#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int UE_CONTEXT_TAG;
    void* RRC_PDU;
    void* MAC_PDU;
} NFAPI_LTE_PDU_T;

typedef struct {
    NFAPI_LTE_PDU_T* array;
    size_t capacity;
    size_t size;
} NFAPDUArray;

NFAPDUArray* createNFAPDUArray(size_t initialCapacity) {
    NFAPDUArray* array = (NFAPDUArray*)malloc(sizeof(NFAPDUArray));
    if (!array) return NULL;
    array->array = (NFAPI_LTE_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_LTE_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }
    array->capacity = initialCapacity;
    array->size = 0;
    return array;
}

void destroyNFAPDUArray(NFAPDUArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->array[i].RRC_PDU);
        free(array->array[i].MAC_PDU);
    }
    free(array->array);
    free(array);
}

int addNFAPDU(NFAPDUArray* array, int UE_CONTEXT_TAG, void* RRC_PDU, void* MAC_PDU) {
    if (array->size == array->capacity) {
        size_t newCapacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_LTE_PDU_T* newArray = realloc(array->array, newCapacity * sizeof(NFAPI_LTE_PDU_T));
        if (!newArray) return -1;
        array->array = newArray;
        array->capacity = newCapacity;
    }
    array->array[array->size].UE_CONTEXT_TAG = UE_CONTEXT_TAG;
    array->array[array->size].RRC_PDU = RRC_PDU;
    array->array[array->size].MAC_PDU = MAC_PDU;
    ++array->size;
    return 0;
}

int updateNFAPDU(NFAPDUArray* array, size_t index, int UE_CONTEXT_TAG, void* RRC_PDU, void* MAC_PDU) {
    if (index >= array->size) return -1;
    free(array->array[index].RRC_PDU);
    free(array->array[index].MAC_PDU);
    array->array[index].UE_CONTEXT_TAG = UE_CONTEXT_TAG;
    array->array[index].RRC_PDU = RRC_PDU;
    array->array[index].MAC_PDU = MAC_PDU;
    return 0;
}

void processNFAPDUs(NFAPDUArray* array, void (*processRRC)(void*), void (*processMAC)(void*)) {
    for (size_t i = 0; i < array->size; ++i) {
        processRRC(array->array[i].RRC_PDU);
        processMAC(array->array[i].MAC_PDU);
    }
}
