#include <time.h>

typedef struct {
    int value;
} record;

record* create_records(long *offsets, int *keys, size_t size) {
    srand(time(NULL));
    record *records = (record *)malloc(size * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = (long)i * sizeof(record);
        keys[i] = rand() % 1000000;
        records[i].value = rand() % 1000;
    }

    return records;
}

void free_records(long *offsets, int *keys, record *records, size_t size) {
    free(records);
    // Optionally, clear offsets and keys if they were dynamically allocated
}

int main() {
    const size_t num_records = 10000000;
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    record *records = create_records(offsets, keys, num_records);
    if (!records) {
        fprintf(stderr, "Failed to create records\n");
        free(keys);
        free(offsets);
        return EXIT_FAILURE;
    }

    // Use the records here

    free_records(offsets, keys, records, num_records);
    return EXIT_SUCCESS;
}
