#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void display_usage() {
    printf("Usage: program_name [-cs] [-o output_file] [--manpage]\n");
    printf("Options:\n");
    printf("  -cs          Count the number of words in each line and print total word count.\n");
    printf("  -o output_file Redirect output to a specified file instead of standard output.\n");
    printf("  --manpage     Display detailed documentation of the program's functionality.\n");
}

void process_file(const char* filename, int count_words) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    long long line_count = 0;
    long long word_count = 0;
    char line[1024];

    while (fgets(line, sizeof(line), file)) {
        line_count++;
        if (count_words) {
            char* token = strtok(line, " ");
            while (token != NULL) {
                word_count++;
                token = strtok(NULL, " ");
            }
        }

        // Progress indicator
        if (line_count % 100 == 0) {
            printf("Processed %lld lines\r", line_count);
            fflush(stdout);
        }
    }

    printf("\nLines: %lld\n", line_count);
    if (count_words) {
        printf("Words: %lld\n", word_count);
    }

    fclose(file);
}

int main(int argc, char* argv[]) {
    int count_words = 0;
    const char* output_file = NULL;
    const char* manpage = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-cs") == 0) {
            count_words = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0 && strlen(argv[i]) > 2) {
            output_file = argv[i] + 3;
        } else if (strcmp(argv[i], "--manpage") == 0) {
            manpage = "help";
        } else {
            display_usage();
            return 1;
        }
    }

    if (manpage != NULL) {
        // Display manpage here
        printf("Manpage content goes here\n");
        return 0;
    }

    const char* input_file = argc > 2 ? argv[2] : NULL;

    if (input_file == NULL) {
        display_usage();
        return 1;
    }

    FILE* output = stdout;
    if (output_file != NULL) {
        output = fopen(output_file, "w");
        if (output == NULL) {
            perror("Error opening output file");
            return 1;
        }
    }

    process_file(input_file, count_words);

    if (output != stdout) {
        fclose(output);
    }

    return 0;
}
