#include <stdio.h>
#include <stdlib.h>

#define MAX_CAPACITY 10000

void read_integers(int **array, int *size) {
    *size = 0;
    int value;
    while (scanf("%d", &value) == 1 && *size < MAX_CAPACITY) {
        (*array)[*size] = value;
        (*size)++;
    }
}

int find_largest(int *array, int size) {
    if (size == 0) return -1; // Assuming no valid input will result in an empty array
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void print_largest(int *array, int size) {
    int largest = find_largest(array, size);
    if (largest != -1) {
        printf("Largest integer: %d\n", largest);
    } else {
        printf("No integers were entered.\n");
    }
}

int main() {
    int *array = malloc(MAX_CAPACITY * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    read_integers(&array, &MAX_CAPACITY);

    print_largest(array, MAX_CAPACITY);

    free(array);
    return 0;
}
```

