bool validate_oauth2_token(const char* json_str) {
    json_object* token_obj = json_tokener_parse(json_str);
    if (!token_obj || !json_is_object(token_obj)) return false;

    const char* access_token = json_object_get_string_ex(token_obj, "access_token");
    const char* token_type = json_object_get_string_ex(token_obj, "token_type");
    int expires_in = 0;
    if (json_object_object_get_ex(token_obj, "expires_in", &json_expires_in)) {
        expires_in = json_object_get_int(json_expires_in);
        if (expires_in <= 0) return false;
    }

    const char* refresh_token = NULL;
    json_object_object_get_ex(token_obj, "refresh_token", (json_object**)&refresh_token);

    bool has_required_fields = access_token && token_type && expires_in > 0;

    json_object_put(token_obj);
    return has_required_fields && strcmp(token_type, "Bearer") == 0;
}

EVP_CIPHER* get_cipher(const char* cipher_mode) {
    if (strcmp(cipher_mode, "ECB") == 0) return EVP_des_ecb();
    else if (strcmp(cipher_mode, "EDE") == 0) return EVP_des_ede3_cbc();
    else if (strcmp(cipher_mode, "CFB") == 0) return EVP_des_cfb8();
    else return NULL;
}

int main() {
    const char* token_json = "{\"access_token\":\"abc123\",\"token_type\":\"Bearer\",\"expires_in\":3600}";
    bool is_valid = validate_oauth2_token(token_json);
    printf("Is valid: %s\n", is_valid ? "true" : "false");

    EVP_CIPHER* cipher = get_cipher("ECB");
    if (cipher) {
        printf("Cipher selected: %s\n", EVP_CIPHER_name(cipher));
    } else {
        printf("Invalid cipher mode.\n");
    }

    return 0;
}
