public class KickstartModifier {

    public static void modifyKickstartConfig(Pokemon pokemon, Map<String, String> params) throws IOException {
        StringBuilder sedCommands = new StringBuilder();
        for (Map.Entry<String, String> entry : params.entrySet()) {
            sedCommands.append("sed -i 's/").append(entry.getKey()).append("/").append(entry.getValue()).append("/' config.kickstart\n");
        }

        ProcessBuilder pb = new ProcessBuilder("bash", "-c", sedCommands.toString());
        Process process = pb.start();
        try {
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new IOException("Error occurred while executing sed commands");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException("Thread interrupted", e);
        }

        Path configPath = Paths.get("config.kickstart");
        String encryptedPassword = encryptPassword(pokemon.getType());
        Files.write(configPath, Files.readAllBytes(configPath).append("\n").append(encryptedPassword).toString().getBytes());

        String weaknesses = getWeaknesses(pokemon.getType());
        System.out.println("Pokemon: " + pokemon.getName() + ", Weaknesses: " + weaknesses);
    }

    private static String encryptPassword(String type) {
        // Placeholder for password encryption logic
        return "encrypted_" + type;
    }

    private static String getWeaknesses(String type) {
        switch (type) {
            case "Fire":
                return "Water, Ground";
            case "Water":
                return "Grass, Electric";
            case "Grass":
                return "Fire, Ice, Flying, Bug";
            // Add more cases as needed
            default:
                return "Unknown";
        }
