typedef struct {
    EVP_CIPHER_CTX *ctx;
    FILE *file;
    int block_size;
} CipherObject;

CipherObject* processFileWithCipher(const char* filePath, const char* option, int encoding) {
    // Initialize OpenSSL
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Allocate memory for cipher object
    CipherObject *cipherObj = (CipherObject*)malloc(sizeof(CipherObject));
    cipherObj->ctx = EVP_CIPHER_CTX_new();
    cipherObj->file = fopen(filePath, "rb");
    cipherObj->block_size = EVP_CIPHER_block_size(EVP_aes_256_cbc()); // Example block size

    if (!cipherObj->ctx || !cipherObj->file) {
        fprintf(stderr, "Failed to allocate memory or open file.\n");
        return NULL;
    }

    // Set up cipher context based on option
    EVP_CIPHER *cipher = NULL;
    if (strcmp(option, "-encrypt") == 0) {
        cipher = EVP_aes_256_cbc();
    } else if (strcmp(option, "-decrypt") == 0) {
        cipher = EVP_aes_256_cbc();
    } else {
        fprintf(stderr, "Unsupported option: %s\n", option);
        free(cipherObj->ctx);
        fclose(cipherObj->file);
        free(cipherObj);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(cipherObj->ctx, cipher, NULL, NULL, NULL)) {
        fprintf(stderr, "Error initializing cipher.\n");
        EVP_CIPHER_CTX_free(cipherObj->ctx);
        fclose(cipherObj->file);
        free(cipherObj);
        return NULL;
    }

    // Read file in chunks and process
    unsigned char *inBuffer = (unsigned char*)malloc(10 * 1024 * 1024); // 10 MB buffer
    unsigned char *outBuffer = (unsigned char*)malloc(cipherObj->block_size + EVP_CIPHER_block_size(cipher));
    int bytesRead, bytesWritten;

    while ((bytesRead = fread(inBuffer, 1, 10 * 1024 * 1024, cipherObj->file)) > 0) {
        if (!EVP_EncryptUpdate(cipherObj->ctx, outBuffer, &bytesWritten, inBuffer, bytesRead)) {
            fprintf(stderr, "Error processing file chunk.\n");
            EVP_CIPHER_CTX_free(cipherObj->ctx);
            fclose(cipherObj->file);
            free(inBuffer);
            free(outBuffer);
            free(cipherObj);
            return NULL;
        }
        // Write processed data (handle output redirection or streaming)
    }

    // Finalize the cipher processing
    if (!EVP_EncryptFinal_ex(cipherObj->ctx, outBuffer, &bytesWritten)) {
        fprintf(stderr, "Error finalizing cipher.\n");
        EVP_CIPHER_CTX_free(cipherObj->ctx);
        fclose(cipherObj->file);
        free(inBuffer);
        free(outBuffer);
        free(cipherObj);
        return NULL;
    }

    // Close file and clean up
    fclose(cipherObj->file);
    free(inBuffer);
    free(outBuffer);

    return cipherObj;
