#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>

typedef struct {
    sem_t *sem;
    int max_access;
} ResourceManager;

int init_resource_manager(ResourceManager *rm, int initial_value, int max_access) {
    rm->sem = (sem_t *)malloc(sizeof(sem_t));
    if (rm->sem == NULL) {
        perror("Failed to allocate memory for semaphore");
        return -1;
    }
    if (sem_init(rm->sem, 0, initial_value) != 0) {
        perror("Failed to initialize semaphore");
        free(rm->sem);
        return -1;
    }
    rm->max_access = max_access;
    return 0;
}

void destroy_resource_manager(ResourceManager *rm) {
    if (sem_destroy(rm->sem) != 0) {
        perror("Failed to destroy semaphore");
    }
    free(rm->sem);
}

int acquire_resource(ResourceManager *rm) {
    if (sem_wait(rm->sem) == -1) {
        perror("Failed to acquire resource");
        return -1;
    }
    // Check if the limit is reached
    if (rm->max_access > 0 && sem_getvalue(rm->sem, NULL) < rm->max_access) {
        printf("Resource acquired successfully\n");
        return 0;
    } else {
        printf("Access limit reached\n");
        sem_post(rm->sem); // Release the semaphore since it's not being used
        return -1;
    }
}

void release_resource(ResourceManager *rm) {
    if (sem_post(rm->sem) == -1) {
        perror("Failed to release resource");
    } else {
        printf("Resource released\n");
    }
}
