#include <forward_list>
#include <algorithm>

template<typename Compare>
void insertAfterOrAtEnd(std::forward_list<int>& lst, int target, int value, Compare comp) {
    auto it = lst.begin();
    auto prev_it = lst.before_begin();

    while (it != lst.end() && !comp(*it, target)) {
        ++prev_it;
        ++it;
    }

    if (it == lst.end()) {
        lst.push_back(value);
    } else {
        lst.insert_after(prev_it, value);
    }
}
