#include <iostream>
#include <boost/program_options.hpp>
#include <sandesh/SandeshClient.h>
#include <sandesh/SandeshTraceBuffer.h>
#include <sandesh/sandesh_types.h>
#include <test/TestUtil.h>

int main(int argc, char* argv[]) {
    namespace po = boost::program_options;

    // Declare the supported options.
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "produce help message")
        ("server", po::value<std::string>(), "Server address")
        ("timeout", po::value<int>(), "Timeout value (in seconds)")
        ("max-retries", po::value<int>(), "Maximum retry attempts");

    // Parse the command line options.
    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("help")) {
        std::cout << desc << "\n";
        return 1;
    }

    std::string server = vm["server"].as<std::string>();
    int timeout = vm["timeout"].as<int>();
    int maxRetries = vm["max-retries"].as<int>();

    // Create a Sandesh client.
    SandeshClient sandeshClient(server, timeout);

    // Set up the custom backoff strategy for retries.
    sandeshClient.SetBackoffStrategy([](int retryCount) {
        return std::pow(2.0, retryCount);
    });

    // Mock the InterfaceTable class.
    auto mockInterfaceTable = std::make_shared<MockInterfaceTable>();
    when(mockInterfaceTable->FindVmUuidFromMetadataIp(_)).thenReturn(boost::optional<std::string>());

    // Configure logging with timestamps and severity levels.
    SandeshTraceBuffer sandeshTraceBuffer("test_sandesh_client", 100);
    Sandesh::InitTrace(&sandeshTraceBuffer);

    // Send multiple GET requests to the server.
    int successfulRequests = 0;
    int failedRequests = 0;
    for (int i = 0; i < maxRetries; ++i) {
        if (sandeshClient.SendGetRequest("path")) {
            successfulRequests++;
        } else {
            failedRequests++;
        }
    }

    // Export logs to a file in a structured format.
    std::ofstream logFile("test_sandesh_client.log");
    sandeshTraceBuffer.Export(logFile);

    std::cout << "Successful requests: " << successfulRequests << "\n";
    std::cout << "Failed requests: " << failedRequests << "\n";

    return 0;
}
```

