#include <iostream>
#include <random>
#include <vector>
#include <functional>

namespace RandomLib {
    class HighPerformanceRandomGenerator {
    public:
        enum DistributionType { Uniform, Normal };

        HighPerformanceRandomGenerator(DistributionType type = Uniform)
            : distributionType(type), threadLocalGenerators(thread::hardware_concurrency()) {
            initializeGenerators();
        }

        ~HighPerformanceRandomGenerator() {
            // Non-trivial destructor to ensure proper resource release
        }

        double generateNumber() {
            switch (distributionType) {
                case Uniform:
                    return uniformDistribution(generator());
                case Normal:
                    return normalDistribution(generator());
            }
            return 0.0; // Should never reach here
        }

    private:
        DistributionType distributionType;
        std::mt19937 generator() const {
            return threadLocalGenerators[std::hash<std::thread::id>{}(std::this_thread::get_id()) % threadLocalGenerators.size()];
        }
        void initializeGenerators() {
            for (auto& gen : threadLocalGenerators) {
                gen = std::mt19937(std::random_device{}());
            }
        }

        std::vector<std::mt19937> threadLocalGenerators;
        std::uniform_real_distribution<> uniformDistribution(0.0, 1.0);
        std::normal_distribution<> normalDistribution(0.0, 1.0);
    };
}

int main() {
    RandomLib::HighPerformanceRandomGenerator rng(RandomLib::HighPerformanceRandomGenerator::Normal);

    for (int i = 0; i < 10; ++i) {
        std::cout << rng.generateNumber() << " ";
    }

    return 0;
}
