using System;
using System.Collections.Generic;
using System.Data.SqlClient;

public class UserProfileBatchInserter
{
    public static int InsertUserProfiles(List<UserProfile> userProfiles, SqlConnection connection, string tableName)
    {
        if (userProfiles == null || userProfiles.Count == 0)
            return 0;

        const int batchSize = 1000;
        int totalInserted = 0;

        using (var transaction = connection.BeginTransaction())
        {
            try
            {
                var sql = $"INSERT INTO {tableName} ({string.Join(", ", UserProfile.GetColumnNames())}) VALUES (@{string.Join(", @", UserProfile.GetParameterNames())})";
                using (var command = new SqlCommand(sql, connection, transaction))
                {
                    foreach (var userProfile in userProfiles)
                    {
                        if (totalInserted % batchSize == 0)
                        {
                            command.Parameters.Clear();
                            command.Prepare();
                        }

                        foreach (var parameterName in UserProfile.GetParameterNames())
                        {
                            var parameterValue = userProfile.GetType().GetProperty(parameterName).GetValue(userProfile);
                            command.Parameters.AddWithValue($"@{parameterName}", parameterValue ?? DBNull.Value);
                        }

                        command.ExecuteNonQuery();
                        totalInserted++;

                        if (totalInserted % batchSize == 0)
                        {
                            transaction.Commit();
                            transaction = connection.BeginTransaction();
                        }
                    }

                    // Insert remaining records
                    if (userProfiles.Count % batchSize != 0)
                    {
                        transaction.Commit();
                    }
                }
            }
            catch (Exception ex)
            {
                transaction.Rollback();
                throw new Exception("Error inserting user profiles", ex);
            }
        }

        return totalInserted;
    }
}

public class UserProfile
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }

    public static string[] GetColumnNames()
    {
        return new[] { "Id", "Name", "Age" };
    }

    public static string[] GetParameterNames()
    {
        return new[] { "Id", "Name", "Age" };
    }
}
