public class GameSettings
{
    public int Width { get; set; }
    public int Height { get; set; }
    public string NetworkAddress { get; set; }
    public int FrameRateLimit { get; set; }
}

public class MultiplayerGameServer
{
    private GameSettings settings;
    private Random random;

    public MultiplayerGameServer(string configPath)
    {
        try
        {
            string json = File.ReadAllText(configPath);
            settings = JsonConvert.DeserializeObject<GameSettings>(json);

            if (settings.Width <= 0 || settings.Height <= 0)
            {
                throw new ArgumentException("Invalid resolution settings.");
            }
            if (string.IsNullOrEmpty(settings.NetworkAddress))
            {
                throw new ArgumentException("Network address cannot be empty.");
            }
            if (settings.FrameRateLimit <= 0)
            {
                throw new ArgumentException("Frame rate limit must be greater than zero.");
            }

            Console.WriteLine($"Game settings loaded: Resolution {settings.Width}x{settings.Height}, Network: {settings.NetworkAddress}, FPS Limit: {settings.FrameRateLimit}");
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Failed to load game settings: {ex.Message}");
            throw;
        }
    }

    public void AdjustFrameRate()
    {
        // Simulate network latency change
        int randomLatency = random.Next(10, 50); // Latency between 10 and 50 ms

        if (randomLatency > settings.FrameRateLimit)
        {
            Console.WriteLine($"Adjusting frame rate due to high network latency: {settings.FrameRateLimit} FPS");
        }
    }

    public void InitializeGameWindows()
    {
        // Code to initialize game windows with resolution from settings
        Console.WriteLine("Initializing game windows with resolution: {0}x{1}", settings.Width, settings.Height);
    }
}

class Program
{
    static void Main(string[] args)
    {
        try
        {
            MultiplayerGameServer server = new MultiplayerGameServer("game_config.json");
            server.InitializeGameWindows();
            while (true)
            {
                server.AdjustFrameRate();
                System.Threading.Thread.Sleep(1000); // Simulate game loop
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
