public class XmlParser
{
    public static async Task<List<XElement>> ParseElementsAsync(XDocument xml, string elementName)
    {
        if (xml == null)
            throw new ArgumentNullException(nameof(xml));

        if (string.IsNullOrEmpty(elementName))
            throw new ArgumentException("Element name cannot be null or empty", nameof(elementName));

        var matches = new List<XElement>();
        foreach (var elem in xml.Descendants())
        {
            string name = elem.Name.LocalName;
            if (MatchesPattern(name, elementName) && !matches.Contains(elem))
            {
                if (matches.Count > 0)
                    throw new InvalidOperationException("Multiple elements found with the given name");

                matches.Add(elem);
            }
        }

        return matches;
    }

    private static bool MatchesPattern(string name, string pattern)
    {
        // Implement wildcard matching logic here
        // For simplicity, this example checks for exact match
        return name == pattern;
    }

    public static async Task<XDocument> LoadAndValidateXmlAsync(string filePath)
    {
        try
        {
            using (var reader = XmlReader.Create(filePath))
            {
                return await XDocument.LoadAsync(reader);
            }
        }
        catch (Exception ex)
        {
            // Log exception and rethrow or handle appropriately
            throw new InvalidOperationException("Failed to load and validate XML document", ex);
        }
    }

    public static async Task<List<XElement>> ParseElementsWithValidationAsync(string filePath, string elementName)
    {
        var xml = await LoadAndValidateXmlAsync(filePath);
        return await ParseElementsAsync(xml, elementName);
    }

    // For thread safety, consider using a lock or other synchronization mechanism if necessary
}

