using System;
using System.Threading.Tasks;

public class ElementUpdater
{
    private readonly IElementService _elementService;
    private readonly ISessionValidator _sessionValidator;
    private readonly ILogger _logger;
    private readonly ICachingProvider _cachingProvider;
    private readonly IRateLimiter _rateLimiter;

    public ElementUpdater(IElementService elementService, ISessionValidator sessionValidator, ILogger logger, ICachingProvider cachingProvider, IRateLimiter rateLimiter)
    {
        _elementService = elementService;
        _sessionValidator = sessionValidator;
        _logger = logger;
        _cachingProvider = cachingProvider;
        _rateLimiter = rateLimiter;
    }

    public async Task<UpdateResponse> UpdateElementAsync(string sessionToken, int pageId, string elementId, string htmlContent)
    {
        if (!_rateLimiter.AllowRequest(sessionToken))
        {
            return new UpdateResponse { Success = false, RefreshPage = false, ErrorMessage = "Rate limit exceeded." };
        }

        var userId = await _sessionValidator.ValidateSessionAsync(sessionToken);

        if (userId == null)
        {
            return new UpdateResponse { Success = false, RefreshPage = false, ErrorMessage = "Invalid session token." };
        }

        if (!await _elementService.UserHasPermissionAsync(userId.Value, pageId, elementId))
        {
            return new UpdateResponse { Success = false, RefreshPage = false, ErrorMessage = "Permission denied." };
        }

        await _cachingProvider.ClearElementCacheAsync(elementId);

        bool updateSuccess = await _elementService.UpdateHtmlContentAsync(elementId, htmlContent);

        if (updateSuccess)
        {
            _logger.LogUpdate(userId.Value, pageId, elementId);
        }

        return new UpdateResponse { Success = updateSuccess, RefreshPage = true };
    }
}

public class UpdateResponse
{
    public bool Success { get; set; }
    public bool RefreshPage { get; set; }
    public string ErrorMessage { get; set; }
}
