async function traverseCatalog(catalog, criteriaFn, options = {}) {
  const { pageSize = 10, page = 1 } = options;
  let results = [];
  let currentPage = 0;

  async function traverse(node) {
    if (node && typeof node === 'object') {
      for (let key in node) {
        if (node.hasOwnProperty(key)) {
          const value = node[key];
          if (typeof value === 'object') {
            await traverse(value);
          } else if (criteriaFn(value, node)) {
            results.push({ ...node, [key]: value });
          }
        }
      }
    }
  }

  try {
    await traverse(catalog);
    const startIndex = (page - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    return results.slice(startIndex, endIndex);
  } catch (error) {
    console.error('Error traversing catalog:', error);
    throw error;
  }
}

// Example usage:
const productCatalog = {
  electronics: {
    smartphones: [
      { name: 'iPhone', price: 999 },
      { name: 'Samsung Galaxy', price: 899 }
    ],
    laptops: [
      { name: 'MacBook Pro', price: 1299 },
      { name: 'Dell XPS', price: 1099 }
    ]
  },
  books: {
    fiction: [
      { title: 'To Kill a Mockingbird', author: 'Harper Lee' },
      { title: '1984', author: 'George Orwell' }
    ],
    nonfiction: [
      { title: 'Sapiens', author: 'Yuval Noah Harari' },
      { title: 'Brief History of Time', author: 'Stephen Hawking' }
    ]
  }
};

const criteria = (product) => product.price > 1000;

(async () => {
  try {
    const products = await traverseCatalog(productCatalog, criteria, { pageSize: 2 });
    console.log(products);
  } catch (error) {
    console.error('Failed to fetch filtered products:', error);
  }
})();
```

