// dynamicLoader.js
(function() {
    const scriptQueue = [];
    let isLoading = false;

    function loadScript(url) {
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = url;
            script.onload = resolve;
            script.onerror = () => reject(new Error(`Failed to load ${url}`));
            document.head.appendChild(script);
        });
    }

    function executeScripts() {
        if (isLoading || !scriptQueue.length) return;

        isLoading = true;
        const nextScriptUrl = scriptQueue.shift();

        loadScript(nextScriptUrl)
            .then(() => {
                console.log(`Successfully loaded ${nextScriptUrl}`);
                executeScripts();
            })
            .catch(error => {
                console.error(error);
                // Implement graceful degradation or fallback mechanism here
                executeScripts();
            })
            .finally(() => {
                isLoading = false;
            });
    }

    export function addScriptToQueue(url) {
        scriptQueue.push(url);
        executeScripts();
    }
})();

// main.js
import { addScriptToQueue } from './dynamicLoader.js';

addScriptToQueue('https://example.com/library1.js');
addScriptToQueue('https://example.com/library2.js');
addScriptToQueue('https://example.com/applicationCode.js');

```
