['```java
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class UniqueStringPairs {

    public static int countUniquePairs(List<String> strings) {
        long startTime = System.nanoTime();
        Trie trie = new Trie();
        Set<String> uniquePairs = new HashSet<>();

        for (String str : strings) {
            if (!str.trim().isEmpty()) {
                if (trie.insert(str)) {
                    uniquePairs.add(str);
                }
            }
        }

        for (int i = 0; i < strings.size(); i++) {
            for (int j = i + 1; j < strings.size(); j++) {
                String s1 = strings.get(i);
                String s2 = strings.get(j);
                if (!s1.contains(s2) && !s2.contains(s1)) {
                    uniquePairs.add(s1 + "," + s2);
                }
            }
        }

        long endTime = System.nanoTime();
        System.out.println("Time taken: " + (endTime - startTime) / 1_000_000.0 + " ms");

        return uniquePairs.size() / 2;
    }

    static class Trie {
        private Node root;

        public Trie() {
            this.root = new Node();
        }

        private static class Node {
            boolean isEndOfWord;
            Node[] children;

            Node() {
                this.isEndOfWord = false;
                this.children = new Node[26];
            }
        }

        private int getIndex(char ch) {
            return ch - 'a';
        }

        public boolean insert(String key) {
            if (key == null || key.isEmpty()) {
                return false;
            }

            Node currentNode = root;
            for (int i = 0; i < key.length(); i++) {
                int index = getIndex(key.charAt(i));
                if (currentNode.children[index] == null) {
                    currentNode.children[index] = new Node();
                }
                currentNode = currentNode.children[index];
            }

            if (!currentNode.isEndOfWord) {
                currentNode.isEndOfWord = true;
                return true;
            } else {
                return false;
            }
        }
    }

    public static void main(String[] args) {
        List<String> strings = List.of("hello", "world", "helloworld", "java", "code");
        System.out.println(countUniquePairs(strings));
    }
}
```']

['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class ConnectionPool {

    private final Selector selector;
    private final int maxConnections;
    private final long connectionTimeoutMillis;
    private final InetSocketAddress[] remoteAddresses;

    public ConnectionPool(InetSocketAddress[] remoteAddresses, int maxConnections, long connectionTimeoutMillis) throws IOException {
        this.selector = Selector.open();
        this.maxConnections = maxConnections;
        this.connectionTimeoutMillis = connectionTimeoutMillis;
        this.remoteAddresses = remoteAddresses;

        for (InetSocketAddress address : remoteAddresses) {
            connectToAddress(address);
        }
    }

    private void connectToAddress(InetSocketAddress address) throws IOException {
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT);
        channel.connect(address);
    }

    public ByteBuffer getConnection() throws InterruptedException {
        selector.select(100);
        Set<SelectionKey> selectedKeys = selector.selectedKeys();
        Iterator<SelectionKey> iter = selectedKeys.iterator();

        while (iter.hasNext()) {
            SelectionKey key = iter.next();
            if (key.isConnectable()) {
                SocketChannel channel = (SocketChannel) key.channel();
                try {
                    channel.finishConnect();
                } catch (IOException e) {
                    channel.close();
                    continue;
                }
                key.interestOps(SelectionKey.OP_READ);
            } else if (key.isReadable()) {
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                SocketChannel channel = (SocketChannel) key.channel();
                int bytesRead = channel.read(buffer);
                if (bytesRead == -1) {
                    channel.close();
                    continue;
                }
                return buffer.flip();
            }
            iter.remove();
        }

        throw new InterruptedException("No connection available");
    }

    public void close() throws IOException {
        selector.close();
    }
}
