<?php

// Define the API endpoint to fetch environment variables
$apiUrl = 'https://api.example.com/env';

try {
    // Fetch environment variables from the third-party API
    $response = file_get_contents($apiUrl);

    if ($response === false) {
        throw new Exception('Failed to fetch environment variables');
    }

    $envVars = json_decode($response, true);

    // Load vendor autoloader
    require 'vendor/autoload.php';

    // Create a configuration class to handle dynamic configurations
    class Config {
        private static $instance;
        private $config;

        private function __construct(array $config) {
            $this->config = $config;
        }

        public static function getInstance(array $config): self {
            if (!self::$instance) {
                self::$instance = new self($config);
            }
            return self::$instance;
        }

        public function get(string $key) {
            return $this->config[$key] ?? null;
        }
    }

    // Initialize the configuration with fetched data
    $appConfig = Config::getInstance($envVars);

