use reqwest::{ClientBuilder, RequestBuilder, Error};
use std::time::Duration;

fn create_request_builder(url: &str, disable_ssl: bool, headers: Option<Vec<(&str, String)>>, timeout: Option<Duration>, body: Option<&[u8]>) -> Result<RequestBuilder, Error> {
    let mut client = ClientBuilder::new();

    if disable_ssl {
        client = client.dangerously_insecure_skip_tls_verification();
    }

    if let Some(headers) = headers {
        for (key, value) in headers {
            client = client.header(key, value);
        }
    }

    if let Some(timeout) = timeout {
        client = client.timeout(timeout);
    }

    if let Some(body) = body {
        client = client.body(reqwest::Body::from(body));
    }

    client.redirect(reqwest::redirect::Policy::follow())
          .build(url)?
}
```

