import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import javax.transaction.Transactional;

public class UserDAO {

    private final Connection connection;

    public UserDAO(Connection connection) {
        this.connection = connection;
    }

    @Transactional
    public boolean updatePassword(String userId, String newPassword) throws Exception {
        if (!validatePassword(newPassword)) {
            throw new IllegalArgumentException("Invalid password strength");
        }

        try (PreparedStatement stmt = connection.prepareStatement(
                "UPDATE users SET password = ? WHERE id = ?")) {

            stmt.setString(1, hashPassword(newPassword));
            stmt.setString(2, userId);

            int affectedRows = stmt.executeUpdate();
            return affectedRows > 0;
        } catch (SQLException e) {
            throw new RuntimeException("Database error while updating password", e);
        }
    }

    private boolean validatePassword(String password) {
        // Implement password strength validation logic
        return password.length() >= 8 && password.matches(".*[A-Za-z].*");
    }

    private String hashPassword(String password) {
        // Implement password hashing logic
        return new String(java.security.MessageDigest.getInstance("SHA-256").digest(password.getBytes()));
    }
}
