['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000
#define TOP_METRICS 10

typedef struct {
    int id;
    double value;
    time_t timestamp;
    int weight;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    pthread_mutex_t mutex;
} TransactionQueue;

typedef struct {
    Transaction metrics[TOP_METRICS];
    pthread_mutex_t mutex;
} MetricList;

void initialize_transaction_queue(TransactionQueue *queue) {
    pthread_mutex_init(&queue->mutex, NULL);
}

void enqueue_transaction(TransactionQueue *queue, Transaction transaction) {
    pthread_mutex_lock(&queue->mutex);
    // Add the transaction to the queue
    pthread_mutex_unlock(&queue->mutex);
}

Transaction dequeue_transaction(TransactionQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    // Remove and return a transaction from the queue
    pthread_mutex_unlock(&queue->mutex);
    return (Transaction){0};
}

void initialize_metric_list(MetricList *list) {
    pthread_mutex_init(&list->mutex, NULL);
}

void update_metric_list(MetricList *list, Transaction transaction) {
    pthread_mutex_lock(&list->mutex);
    // Update the metric list with the new transaction
    pthread_mutex_unlock(&list->mutex);
}

double get_max_weighted_sum(MetricList *list) {
    double max_sum = 0;
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < TOP_METRICS; i++) {
        if (list->metrics[i].value > max_sum) {
            max_sum = list->metrics[i].value;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return max_sum;
}

Transaction process_transaction(TransactionQueue *queue, MetricList *list) {
    Transaction transaction = dequeue_transaction(queue);
    time_t now = time(NULL);

    if (now - transaction.timestamp > 5) {
        return (Transaction){0};
    }

    pthread_mutex_lock(&queue->mutex);
    int count = 0;
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        if ((now - queue->transactions[i].timestamp <= 3) && (now - queue->transactions[i].timestamp > 0)) {
            count++;
        }
    }
    pthread_mutex_unlock(&queue->mutex);

    if (count >= TOP_METRICS) {
        return (Transaction){0};
    }

    transaction.weight = count + 1;
    update_metric_list(list, transaction);
    double max_sum = get_max_weighted_sum(list);

    return (Transaction){max_sum, transaction.id};
}
