async function asyncReduce(array, initialAccumulator, callback, errorHandler) {
  let accumulator = initialAccumulator;

  for (const item of array) {
    try {
      const updatedAccumulator = await callback(accumulator, item);
      accumulator = updatedAccumulator;
    } catch (error) {
      errorHandler.logError(error);
      // Optionally re-throw the error to propagate it up the call stack
      throw error;
    }
  }

  return accumulator;
}

// Example usage:
const array = [1, 2, 3, 4, 5];
const initialAccumulator = 0;

async function reductionCallback(accumulator, item) {
  // Simulate an asynchronous operation, e.g., fetching data from a server
  await new Promise(resolve => setTimeout(resolve, Math.random() * 1000));
  return accumulator + item;
}

class ErrorHandlingService {
  logError(error) {
    console.error('Error:', error);
    // Additional logging logic can be added here (e.g., writing to a file or sending an alert)
  }
}

const errorHandler = new ErrorHandlingService();

