#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    char *id;
    json_object *metadata;
} ResourceItem;

typedef struct {
    int itemCount;
    ResourceItem **items;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filePath);
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char *)malloc(fileSize + 1);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return NULL;
    }

    size_t bytesRead = fread(buffer, 1, fileSize, file);
    buffer[bytesRead] = '\0';

    fclose(file);

    json_object *jsonRoot = json_tokener_parse(buffer);
    if (!jsonRoot) {
        fprintf(stderr, "Invalid JSON format\n");
        free(buffer);
        return NULL;
    }

    json_type rootType = json_object_get_type(jsonRoot);
    if (rootType != json_type_array) {
        fprintf(stderr, "JSON must be an array of objects\n");
        json_object_put(jsonRoot);
        free(buffer);
        return NULL;
    }

    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fprintf(stderr, "Memory allocation failed\n");
        json_object_put(jsonRoot);
        free(buffer);
        return NULL;
    }

    bundle->itemCount = json_object_array_length(jsonRoot);
    bundle->items = (ResourceItem **)malloc(bundle->itemCount * sizeof(ResourceItem *));
    if (!bundle->items) {
        fprintf(stderr, "Memory allocation failed\n");
        json_object_put(jsonRoot);
        free(buffer);
        free(bundle);
        return NULL;
    }

    for (int i = 0; i < bundle->itemCount; i++) {
        json_object *itemObj = json_object_array_get_idx(jsonRoot, i);
        json_type itemType = json_object_get_type(itemObj);
        if (itemType != json_type_object) {
            fprintf(stderr, "Invalid JSON format: item %d is not an object\n", i);
            for (int j = 0; j < i; j++) {
                free(bundle->items[j]->id);
                json_object_put(bundle->items[j]->metadata);
                free(bundle->items[j]);
            }
            free(bundle->items);
            json_object_put(jsonRoot);
            free(buffer);
            free(bundle);
            return NULL;
        }

        const char *id = json_object_get_string(json_object_object_get_ex(itemObj, "id", &itemType));
        if (itemType != json_type_string || id == NULL) {
            fprintf(stderr, "Invalid JSON format: item %d missing or invalid 'id'\n", i);
            for (int j = 0; j < i; j++) {
                free(bundle->items[j]->id);
                json_object_put(bundle->items[j]->metadata);
                free(bundle->items[j]);
            }
            free(bundle->items);
            json_object_put(jsonRoot);
            free(buffer);
            free(bundle);
            return NULL;
        }

        ResourceItem *item = (ResourceItem *)malloc(sizeof(ResourceItem));
        if (!item) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; j++) {
                free(bundle->items[j]->id);
                json_object_put(bundle->items[j]->metadata);
                free(bundle->items[j]);
            }
            free(bundle->items);
            json_object_put(jsonRoot);
            free(buffer);
            free(bundle);
            return NULL;
        }

        item->id = strdup(id);
        item->metadata = json_object_object_get_ex(itemObj, "metadata", &itemType) ? json_object_get(itemObj, "metadata") : NULL;

        bundle->items[i] = item;
    }

    json_object_put(jsonRoot);
    free(buffer);

    return bundle;
}

// Example usage
int main() {
    ResourceBundle *bundle = loadResourceBundle("resources.json");
    if (bundle) {
        printf("Loaded %d items from resource bundle\n", bundle->itemCount);
        for (int i = 0; i < bundle->itemCount; i++) {
            printf("Item %d ID: %s\n", i, bundle->items[i]->id);
            // Process metadata as needed
        }
        // Clean up resources
        for (int i = 0; i < bundle->itemCount; i++) {
            free(bundle->items[i]->id);
            json_object_put(bundle->items[i]->metadata);
            free(bundle->items[i]);
        }
        free(bundle->items);
        free(bundle);
    }
    return 0;
