char* appendSlash(const char* str, size_t limit, char* buffer, size_t bufferSize) {
    if (str == NULL || limit == 0) return NULL;

    // Check if the string exceeds the size limit
    size_t len = strlen(str);
    if (len >= limit) return NULL;

    // If a buffer is provided, use it; otherwise, allocate memory
    char* result;
    if (buffer != NULL && bufferSize > 0) {
        result = buffer;
        if (bufferSize <= len + 1) return NULL; // Not enough space in the buffer
    } else {
        result = malloc(len + 2); // +1 for slash, +1 for null terminator
        if (result == NULL) return NULL; // Memory allocation failed
    }

    // Append a slash to the end of the string
    strcpy(result, str);
    result[len] = '/';
    result[len + 1] = '\0';

    return result;
}

// Example usage and performance measurement
int main() {
    const char* input = "example";
    size_t limit = 50;
    char buffer[100];

    clock_t start, end;
    double cpu_time_used;

    // Measure time for allocating memory
    start = clock();
    char* result = appendSlash(input, limit, NULL, 0);
    if (result != NULL) free(result);
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time to allocate memory: %f seconds\n", cpu_time_used);

    // Measure time for using provided buffer
    start = clock();
    result = appendSlash(input, limit, buffer, sizeof(buffer));
    if (result != NULL) {
        printf("Result with buffer: %s\n", result);
        free(result); // No need to free if buffer was used
    }
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time using provided buffer: %f seconds\n", cpu_time_used);

    return 0;
}
