#define MAX_LINE_LENGTH 2048

void process_file(const char *filename, const char *log_service_url) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';

        // Dynamically allocate memory for the fields
        char *fields[MAX_FIELDS];
        int field_count = 0;
        char *token = strtok(line, "\t");
        while (token != NULL && field_count < MAX_FIELDS) {
            fields[field_count++] = strdup(token);
            token = strtok(NULL, "\t");
        }

        // Validate and calculate the average of the last two numerical fields
        double sum = 0;
        int valid_fields = 0;
        for (int i = field_count - 2; i < field_count; i++) {
            if (fields[i] != NULL && strlen(fields[i]) > 0) {
                char *endptr;
                double value = strtod(fields[i], &endptr);
                if (*endptr == '\0') {
                    sum += value;
                    valid_fields++;
                } else {
                    fprintf(stderr, "Invalid number in field %d: %s\n", i + 1, fields[i]);
                }
            }
        }

        double average = (valid_fields > 0) ? sum / valid_fields : 0;

        // Append the average as an additional field
        char new_field[MAX_LINE_LENGTH];
        snprintf(new_field, sizeof(new_field), "\t%.2f", average);
        strcat(line, new_field);

        // Log the processed line to the external logging service
        log_to_service(log_service_url, line);

        // Free dynamically allocated memory for fields
        for (int i = 0; i < field_count; i++) {
            free(fields[i]);
        }
    }

    fclose(file);
}

void log_to_service(const char *url, const char *data) {
    // Code to send data to the external logging service goes here
}

int main() {
    const char *filename = "input.txt";
    const char *log_service_url = "https://example.com/log";
    process_file(filename, log_service_url);
    return 0;
}
