#include <stdio.h>
#include <stdlib.h>
#include <tiffio.h>
#include <openssl/evp.h>

typedef struct {
    int numExtraSamples;
    TIFFDataType extraSampleTypes[3];
} ExtraSampleInfo;

EVP_CIPHER_CTX* parseTIFFAndEncrypt(const char* tiffFilePath, const char* encryptOption) {
    TIFF* tif = TIFFOpen(tiffFilePath, "r");
    if (!tif) {
        fprintf(stderr, "Error opening TIFF file\n");
        return NULL;
    }

    uint16 bitsPerSample, samplesPerPixel;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);

    ExtraSampleInfo extraSamples;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples.numExtraSamples)) {
        for (int i = 0; i < extraSamples.numExtraSamples && i < 3; ++i) {
            TIFFGetField(tif, TIFFTAG_EXTRASAMPLETYPE + i, &extraSamples.extraSampleTypes[i]);
        }
    }

    if (bitsPerSample != 8 && bitsPerSample != 16 && bitsPerSample != 24 && bitsPerSample != 32) {
        fprintf(stderr, "Unsupported bits per sample: %d\n", bitsPerSample);
        TIFFClose(tif);
        return NULL;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        TIFFClose(tif);
        return NULL;
    }

    const EVP_CIPHER* cipher = EVP_get_cipherbyname(encryptOption);
    if (!cipher) {
        fprintf(stderr, "Unsupported encryption option: %s\n", encryptOption);
        EVP_CIPHER_CTX_free(ctx);
        TIFFClose(tif);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        TIFFClose(tif);
        return NULL;
    }

    TIFFClose(tif);
    return ctx;
}
