char* generate_modified_filename(const char* original_filename) {
    if (original_filename == NULL || strlen(original_filename) == 0) {
        return "default_filename.txt";
    }

    char new_filename[MAX_FILENAME_LENGTH];
    strcpy(new_filename, original_filename);

    // Find the length of the filename without extension
    char* last_dot = strrchr(new_filename, '.');
    if (last_dot != NULL) {
        *last_dot = '\0';
    }

    int filename_length = strlen(new_filename);
    int num_digits_to_append = filename_length % 10 + 1;

    // Generate the new extension based on the first character
    char new_extension[5];
    switch (new_filename[0]) {
        case 'a': strcpy(new_extension, "abc"); break;
        case 'b': strcpy(new_extension, "def"); break;
        default: strcpy(new_extension, "xyz"); break;
    }

    // Construct the new filename
    sprintf(new_filename + filename_length, "_%d.%s", num_digits_to_append, new_extension);

    return new_filename;
}

int main() {
    const char* original_filename = "example.txt";
    char* modified_filename = generate_modified_filename(original_filename);
    printf("Original: %s\nModified: %s\n", original_filename, modified_filename);
    return 0;
}
