#define MAX_KEY_SIZE 32
#define IV_SIZE 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[MAX_KEY_SIZE];
    unsigned char iv[IV_SIZE];
} AESCipher;

int aes_init(AESCipher *cipher, const char *password, const unsigned char *salt, size_t salt_len, int cipher_mode) {
    unsigned char derived_key[MAX_KEY_SIZE] = {0};
    unsigned char temp_key[MAX_KEY_SIZE] = {0};

    // Derive key using PBKDF2
    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, 100000, EVP_sha256(), MAX_KEY_SIZE, derived_key);

    // Copy derived key to cipher struct
    memcpy(cipher->key, derived_key, MAX_KEY_SIZE);

    // Generate random IV if not provided
    if (!RAND_bytes(cipher->iv, IV_SIZE)) {
        return -1;
    }

    // Initialize cipher context based on mode
    switch (cipher_mode) {
        case EVP_CIPH_CBC_MODE:
            cipher->ctx = EVP_CIPHER_CTX_new();
            if (!cipher->ctx || !EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, derived_key, cipher->iv)) {
                return -1;
            }
            break;
        case EVP_CIPH_GCM_MODE:
            // Initialize GCM mode here
            break;
        default:
            return -1;
    }

    return 0;
}

void aes_cleanup(AESCipher *cipher) {
    if (cipher->ctx) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        cipher->ctx = NULL;
    }
    memset(cipher, 0, sizeof(AESCipher));
}
