int create_zip_archive(const char *directory_path, const char *output_file) {
    DIR *dir;
    struct dirent *entry;
    FILE *zip_file = fopen(output_file, "wb");
    gzFile manifest_gz = gzdopen(fileno(zip_file), "w9");

    if (!manifest_gz) {
        fprintf(stderr, "Failed to open output file for writing.\n");
        return 1;
    }

    dir = opendir(directory_path);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", directory_path);
        fclose(zip_file);
        return 1;
    }

    while ((entry = readdir(dir)) != NULL) {
        char file_path[4096];
        snprintf(file_path, sizeof(file_path), "%s/%s", directory_path, entry->d_name);

        if (strstr(entry->d_name, ".jpg") || strstr(entry->d_name, ".jpeg")) {
            FILE *file = fopen(file_path, "rb");
            if (!file) {
                fprintf(stderr, "Failed to open file: %s\n", file_path);
                continue;
            }

            // Write manifest entry
            gzprintf(manifest_gz, "%s\t%s\n", entry->d_name, file_path);

            // Compress and write file data
            int ret;
            unsigned char buffer[1024];
            while ((ret = fread(buffer, 1, sizeof(buffer), file)) > 0) {
                if (gzwrite(manifest_gz, buffer, ret) != ret) {
                    fprintf(stderr, "Error writing to zip archive.\n");
                    fclose(file);
                    gzclose(manifest_gz);
                    return 1;
                }
            }

            fclose(file);
        }
    }

    closedir(dir);
    gzclose(manifest_gz);
    fclose(zip_file);

    return 0;
}
