#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>

typedef struct {
    int success;
    double executionTime;
} CommandResult;

CommandResult runBackgroundCommand(const char* command) {
    CommandResult result = {0};
    pid_t pid;
    struct timespec start, end;

    if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
        perror("clock_gettime");
        return result;
    }

    pid = fork();
    if (pid < 0) {
        perror("fork");
        return result;
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else {
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            result.success = 1;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
            perror("clock_gettime");
        } else {
            result.executionTime = end.tv_sec - start.tv_sec + 
                                   (end.tv_nsec - start.tv_nsec) / 1e9;
        }
    }

    return result;
}

int executeCommands(const char* commands[], int numCommands, int maxRetries) {
    CommandResult results[numCommands];
    for (int i = 0; i < numCommands; ++i) {
        int retries = 0;
        while (retries < maxRetries) {
            results[i] = runBackgroundCommand(commands[i]);
            if (results[i].success) {
                break;
            }
            retries++;
        }
    }

    for (int i = 0; i < numCommands; ++i) {
        if (!results[i].success) {
            printf("Command failed: %s\n", commands[i]);
            return 0;
        }
    }

    return 1;
}

int main() {
    const char* commands[] = {"sleep 2", "ls /nonexistent", "echo Hello"};
    int numCommands = sizeof(commands) / sizeof(commands[0]);
    int maxRetries = 3;

    if (executeCommands(commands, numCommands, maxRetries)) {
        printf("All commands executed successfully.\n");
    } else {
        printf("Some commands failed.\n");
    }

    return 0;
}
```

This code snippet demonstrates a function `executeCommands` that takes an array of command strings and executes them in the background using the `fork` and `wait` system calls. Each command's execution time is tracked, and the function handles multiple retries for failed commands up to three times. The results are stored in a structured format, and the main program flow is not blocked.']

