public class WebAppLauncher
{
    private static readonly object lockObject = new object();

    public Process LaunchWebApplication(string directoryPath, string applicationName)
    {
        if (!Directory.Exists(directoryPath))
        {
            Console.WriteLine("Directory does not exist.");
            return null;
        }

        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            Console.WriteLine("web.config file is missing.");
            return null;
        }

        lock (lockObject)
        {
            try
            {
                Process process = new Process();
                process.StartInfo.FileName = applicationName;
                process.StartInfo.WorkingDirectory = directoryPath;

                try
                {
                    process.Start();
                    Console.WriteLine("Web application launched successfully.");
                    return process;
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Failed to launch web application: {ex.Message}");
                    return null;
                }
            }
            catch (ThreadInterruptedException)
            {
                Console.WriteLine("Operation interrupted by a thread.");
                return null;
            }
        }
    }
}
