import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.*;

public class CommandExecutor {

    private static final long MAX_CPU_TIME = 10 * 60 * 1000; // 10 minutes in milliseconds
    private static final long MAX_MEMORY_USAGE = 256 * 1024 * 1024; // 256MB in bytes

    public static void main(String[] args) {
        try {
            executeCommand("path/to/config/file.properties");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void executeCommand(String configPath) throws Exception {
        Properties properties = loadProperties(configPath);
        String command = properties.getProperty("command");
        String[] commandArgs = properties.getProperty("args").split(",");
        File workingDir = new File(properties.getProperty("workingDir"));
        int maxRetries = Integer.parseInt(properties.getProperty("maxRetries"));

        Path lockFile = Paths.get(workingDir.toString(), "execution.lock");

        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            try (Lock lock = Files.newFileLock(lockFile)) {
                if (!Files.exists(lockFile)) {
                    Files.createFile(lockFile);
                }

                ProcessBuilder processBuilder = new ProcessBuilder(command, commandArgs);
                processBuilder.directory(workingDir);

                Process process = processBuilder.start();
                int exitCode = process.waitFor();

                try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                     BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

                    String line;
                    System.out.println("Output:");
                    while ((line = reader.readLine()) != null) {
                        System.out.println(line);
                    }

                    System.err.println("Error:");
                    while ((line = errorReader.readLine()) != null) {
                        System.err.println(line);
                    }
                }

                if (exitCode == 0) {
                    System.out.println("Command executed successfully.");
                    deleteFile(workingDir, properties.getProperty("deleteFile"));
                    break;
                } else {
                    System.err.println("Command failed with exit code " + exitCode);
                }
            } catch (InterruptedException | IOException e) {
                if (attempt == maxRetries) {
                    throw new RuntimeException("Failed to execute command after multiple attempts", e);
                }
                Thread.sleep(1000); // Wait before retrying
            }
        }
    }

    private static Properties loadProperties(String configPath) throws IOException {
        Properties properties = new Properties();
        try (InputStream input = new FileInputStream(configPath)) {
            properties.load(input);
        }
        return properties;
    }

    private static void deleteFile(File directory, String fileName) {
        Path filePath = Paths.get(directory.toString(), fileName);
        if (Files.exists(filePath)) {
            try {
                Files.delete(filePath);
                System.out.println("File " + fileName + " deleted successfully.");
            } catch (IOException e) {
                System.err.println("Failed to delete file " + fileName);
            }
        }
    }
}
```

