public class CSVProcessor<T>
{
    private readonly string _filePath;
    private readonly Func<string[], T> _transformFunction;

    public CSVProcessor(string filePath, Func<string[], T> transformFunction)
    {
        _filePath = filePath;
        _transformFunction = transformFunction ?? throw new ArgumentNullException(nameof(transformFunction));
    }

    public List<T> ProcessFile()
    {
        var results = new List<T>();
        using (var reader = new StreamReader(_filePath))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                var data = line.Split(',');
                if (data.Length > 0)
                {
                    try
                    {
                        var transformedData = _transformFunction(data);
                        results.Add(transformedData);
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error processing row: {line}. Error: {ex.Message}");
                    }
                }
            }
        }
        return results;
    }
}
