    {
        if (string.IsNullOrEmpty(base64EncodedMessage) || base64EncodedMessage.Length > 1024)
        {
            throw new ArgumentException("Input message must not be empty and should not exceed 1024 characters.");
        }

        try
        {
            using (TripleDES tripleDes = TripleDES.Create())
            {
                tripleDes.Key = key;
                tripleDes.IV = iv;
                tripleDes.Mode = CipherMode.CBC;
                tripleDes.Padding = PaddingMode.PKCS7;

                byte[] decryptedBytes = Convert.FromBase64String(base64EncodedMessage);
                using (MemoryStream msDecrypt = new MemoryStream(decryptedBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, tripleDes.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            string decryptedMessage = srDecrypt.ReadToEnd();

                            if (skipHashForPalindrome && IsPalindrome(decryptedMessage))
                            {
                                return "HASH_SKIPPED";
                            }

                            using (MD5 md5 = MD5.Create())
                            {
                                byte[] hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(decryptedMessage));
                                return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine("Error during decryption or hashing: " + ex.Message);
            throw;
        }
    }

    private static bool IsPalindrome(string message)
    {
        int start = 0;
        int end = message.Length - 1;
        while (start < end)
        {
            if (message[start] != message[end])
                return false;
            start++;
            end--;
        }
        return true;
    }
}
```

This code defines a `MessageDecryptor` class with a static method `DecryptAndHashMessage` that performs the required operations. It uses Triple DES for decryption and MD5 for hashing. The method handles exceptions, checks for palindrome strings, and logs errors for performance monitoring.']

