using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;

public class LogProcessor
{
    private readonly string _filePath;
    private Dictionary<string, byte[]> _hashCache = new Dictionary<string, byte[]>();
    private int _lastProcessedLine = -1;

    public LogProcessor(string filePath)
    {
        _filePath = filePath;
    }

    public void ProcessLogFile()
    {
        try
        {
            using (var reader = new StreamReader(_filePath))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    if (_lastProcessedLine >= 0 && _lastProcessedLine == Int32.Parse(line.Trim()))
                    {
                        // Resume from the last processed line
                        continue;
                    }

                    byte[] hash = GetMd5Hash(line);
                    SaveHashToCache(line, hash);

                    _lastProcessedLine = Int32.Parse(line.Trim());
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error processing log file: " + ex.Message);
        }
    }

    private byte[] GetMd5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            return md5.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
        }
    }

    private void SaveHashToCache(string key, byte[] value)
    {
        if (!_hashCache.ContainsKey(key))
        {
            _hashCache[key] = value;
        }
    }

    public Dictionary<string, byte[]> GetHashCache()
    {
        return _hashCache;
    }
}
