using System;
using System.IO;
using System.Security.Cryptography;

public class AESCBCDecryptor
{
    public static byte[] DecryptWithHMAC(string ciphertextBase64, string keyBase64, string ivBase64, string hmacKeyBase64)
    {
        // Convert base64 strings to bytes
        byte[] ciphertext = Convert.FromBase64String(ciphertextBase64);
        byte[] key = Convert.FromBase64String(keyBase64);
        byte[] iv = Convert.FromBase64String(ivBase64);
        byte[] hmacKey = Convert.FromBase64String(hmacKeyBase64);

        // Create a new instance of the Aes class
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            // Create an ICryptoTransform object for decryption
            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            // Create a MemoryStream to hold the decrypted data
            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                // Create a CryptoStream for decryption
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    // Create a buffer to hold the plaintext
                    byte[] plaintextBuffer = new byte[16]; // 128-bit block size
                    int bytesRead;

                    using (MemoryStream msPlaintext = new MemoryStream())
                    {
                        while ((bytesRead = csDecrypt.Read(plaintextBuffer, 0, plaintextBuffer.Length)) > 0)
                        {
                            msPlaintext.Write(plaintextBuffer, 0, bytesRead);
                        }

                        // Get the decrypted plaintext as a byte array
                        byte[] plaintext = msPlaintext.ToArray();

                        // Verify HMAC integrity
                        if (VerifyHMAC(plaintext, hmacKey))
                        {
                            return plaintext;
                        }
                        else
                        {
                            Console.WriteLine("Data segment is corrupted. Discarding.");
                            return null;
                        }
                    }
                }
            }
        }
    }

    private static bool VerifyHMAC(byte[] data, byte[] key)
    {
        using (HMACSHA256 hmac = new HMACSHA256(key))
        {
            byte[] computedHash = hmac.ComputeHash(data);
            return computedHash.SequenceEqual(data.Skip(data.Length - 32)); // Assuming the last 32 bytes are the HMAC
        }
    }
}
```

