using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.IO.Compression;

public class DataDeserializer
{
    public static object Deserialize(string filePath)
    {
        try
        {
            if (Path.GetExtension(filePath).ToLower() == ".gz")
                return DeserializeFromGzFile(filePath);
            else if (Path.GetExtension(filePath).ToLower() == ".bin")
                return DeserializeFromBinFile(filePath);
            else
                throw new NotSupportedException("Unsupported file format");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error deserializing file: {ex.Message}");
            return null;
        }
    }

    private static object DeserializeFromGzFile(string filePath)
    {
        using (FileStream fileStream = File.OpenRead(filePath))
        using (GZipStream gzipStream = new GZipStream(fileStream, CompressionMode.Decompress))
        using (BinaryFormatter formatter = new BinaryFormatter())
        {
            return formatter.Deserialize(gzipStream);
        }
    }

    private static object DeserializeFromBinFile(string filePath)
    {
        using (FileStream fileStream = File.OpenRead(filePath))
        using (BinaryFormatter formatter = new BinaryFormatter())
        {
            return formatter.Deserialize(fileStream);
        }
    }
}
