public class JavaJSFramework {
    public Object deserialize(byte[] data) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed: " + e.getMessage(), e);
        }
    }

    public void executeJavaScript(String scriptPath) throws ScriptException, FileNotFoundException {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        try (BufferedReader reader = new BufferedReader(new FileReader(scriptPath))) {
            String line;
            StringBuilder scriptBuilder = new StringBuilder();
            while ((line = reader.readLine()) != null) {
                scriptBuilder.append(line).append("\n");
            }
            engine.eval(scriptBuilder.toString());
        } catch (FileNotFoundException e) {
            throw new FileNotFoundException("Script file not found: " + scriptPath);
        }
    }

    public void executeJavaScriptScripts(List<String> scriptPaths) throws ScriptException, FileNotFoundException {
        for (String scriptPath : scriptPaths) {
            try {
                executeJavaScript(scriptPath);
            } catch (ScriptException | FileNotFoundException e) {
                System.err.println("Failed to execute script: " + scriptPath + ". Error: " + e.getMessage());
            }
        }
    }

    public static void main(String[] args) {
        JavaJSFramework framework = new JavaJSFramework();

        // Example usage
