#include <cURL/curl.h>

size_t WriteCallback(void* contents, size_t size, size_t nmemb, std::string* output) {
    size_t totalSize = size * nmemb;
    output->append((char*)contents, totalSize);
    return totalSize;
}

bool isValidNumber(const std::string& str) {
    for (char ch : str) {
        if (!isdigit(ch)) {
            return false;
        }
    }
    return true;
}

double calculateAverage(std::vector<std::string>& fields) {
    double sum = 0.0;
    for (const std::string& field : fields) {
        sum += std::stod(field);
    }
    return sum / fields.size();
}

std::string uploadFile(const std::string& url, const std::string& filePath) {
    CURL* curl;
    CURLcode res;
    std::string readBuffer;

    curl = curl_easy_init();
    if(curl) {
        std::ifstream file(filePath, std::ios::in | std::ios::binary);
        if (!file.is_open()) {
            // Log error
            return "File upload failed: Unable to open file";
        }

        char buffer[1024];
        size_t bytesRead;
        while ((bytesRead = file.read(buffer, sizeof(buffer)).gcount()) > 0) {
            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, buffer);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                // Log error
                return "File upload failed: " + std::string(curl_easy_strerror(res));
            }
        }

        file.close();
        curl_easy_cleanup(curl);

        // Process uploaded file to append average of last two numeric fields
        std::ifstream processedFile(filePath, std::ios::in);
        std::ofstream tempFile("temp.txt", std::ios::out | std::ios::binary);
        std::string line;
        while (std::getline(processedFile, line)) {
            std::vector<std::string> fields = {line.substr(0, line.find_last_of(','))};
            if (isValidNumber(line.substr(line.find_last_of(',') + 1))) {
                double average = calculateAverage(fields);
                tempFile << line << "," << average << "\n";
            } else {
                // Log error
                return "Invalid numeric field in file";
            }
        }

        processedFile.close();
        tempFile.close();

        // Replace original file with processed file
        remove(filePath.c_str());
        rename("temp.txt", filePath.c_str());

        return "Upload successful: Average appended to file";
    }
    return "File upload failed: cURL initialization error";
}

int main() {
    std::string url = "http://example.com/upload";
    std::string filePath = "path/to/your/file.csv";

    std::string result = uploadFile(url, filePath);
    std::cout << result << std::endl;

    return 0;
}
