// Import necessary modules
const { exec } = require('child_process');
const escapeHtml = require('escape-html');

/**
 * Executes a shell command and returns its output to the browser.
 * @param {string} cmd - The shell command to execute.
 * @param {function} callback - Callback function to handle the result or error.
 */
function executeShellCommand(cmd, callback) {
    // Check if the command is empty
    if (!cmd) {
        return callback(new Error('Command cannot be empty'));
    }

    // Execute the command using child_process.exec
    exec(cmd, (error, stdout, stderr) => {
        // Handle any errors that occurred during execution
        if (error) {
            const errorMessage = `Execution failed: ${error.message}`;
            console.error(errorMessage);
            return callback(new Error(errorMessage));
        }

        // Sanitize the output to prevent XSS attacks
        const sanitizedOutput = escapeHtml(stdout);

        // Log successful execution
        console.log(`Command executed successfully: ${cmd}`);

        // Provide the sanitized output as a result
        callback(null, sanitizedOutput);
    });
}

// Example usage:
executeShellCommand('echo Hello World', (err, result) => {
    if (err) {
        console.error(err.message);
    } else {
        console.log(result);
    }
});
