public class GraphDatabase {
    private Map<String, Vertex> vertices;
    private Map<String, Set<Edge>> adjacencyList;

    public void addVertex(Vertex vertex) {
        vertices.put(vertex.getId(), vertex);
        adjacencyList.put(vertex.getId(), new HashSet<>());
    }

    public void removeVertex(String vertexId) {
        vertices.remove(vertexId);
        adjacencyList.values().forEach(edges -> edges.removeIf(edge -> edge.getSource().equals(vertexId) || edge.getTarget().equals(vertexId)));
    }

    public void addEdge(Edge edge) {
        adjacencyList.get(edge.getSource()).add(edge);
        adjacencyList.get(edge.getTarget()).add(edge);
    }

    public void removeEdge(String source, String target) {
        adjacencyList.get(source).removeIf(edge -> edge.getTarget().equals(target));
        adjacencyList.get(target).removeIf(edge -> edge.getSource().equals(source));
    }

    public Vertex getVertex(String vertexId) {
        return vertices.get(vertexId);
    }

    public Set<Edge> getEdges(String vertexId) {
        return adjacencyList.getOrDefault(vertexId, Collections.emptySet());
    }

    public void updateVertexProperty(String vertexId, String propertyKey, Object newValue) {
        Vertex vertex = vertices.get(vertexId);
        if (vertex != null) {
            vertex.setProperty(propertyKey, newValue);
        }
    }

    // Additional methods for handling network partitions and failed node restarts
    // ...
}

