use std::fs::{create_dir_all, set_permissions, Permissions};
use std::io::{self, Write};
use std::os::unix::fs::PermissionsExt;
use std::path::Path;

/// Initializes a workspace directory for a software development project.
///
/// # Arguments
///
/// * `project_root` - A string slice that holds the path to the project root directory.
///
/// # Returns
///
/// * `Result<(), io::Error>` - Returns Ok(()) if the operation is successful, or an error if it fails.
///
/// # Examples
///
/// ```
/// use initialize_workspace;
///
/// fn main() -> Result<(), io::Error> {
///     let project_root = "/path/to/project";
///     initialize_workspace(project_root)?;
///     Ok(())
/// }
/// ```
fn initialize_workspace(project_root: &str) -> io::Result<()> {
    let ws_path = Path::new(&env::var("WS_PATH").unwrap_or_else(|_| format!("{}/workspace", project_root)));

    if !ws_path.exists() {
        create_dir_all(ws_path)?;

        // Set specific permissions
        set_permissions(ws_path, PermissionsExt::from_mode(0o755))?;

        // Log the operation to setup.log
        let log_path = Path::new(&format!("{}/setup.log", project_root));
        let mut file = File::create(log_path)?;
        writeln!(file, "Workspace initialized at: {}", ws_path.display())?;
    }

    Ok(())
}
