    void startMessageQueueProcessing() {
        workerThread = std::thread(&NetworkCommunicationLibrary::processMessages, this);
    }

    void stopMessageQueueProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stopProcessing = true;
        }
        condition.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
