    void initializeSSLContext() {
        // Initialize SSL context with TLS 1.2, TLS 1.3, and AES-256, ChaCha20 ciphers
        sslContext = SSL_CTX_new(TLS_method());
        if (sslContext == nullptr) {
            throw std::runtime_error("Failed to create SSL context");
        }

        // Set cipher list for the SSL context
        const char* cipherList = "TLSv1.2:!aNULL:!MD5:AES256-GCM-SHA384:CHACHA20-POLY1305";
        if (SSL_CTX_set_cipher_list(sslContext, cipherList) != 1) {
            throw std::runtime_error("Failed to set cipher list for SSL context");
        }

        // Set protocol list for the SSL context
        const char* protocolList = "TLSv1.2,TLSv1.3";
        if (SSL_CTX_set_min_proto_version(sslContext, TLS1_2_VERSION) != 1 ||
            SSL_CTX_set_max_proto_version(sslContext, TLS1_3_VERSION) != 1) {
            throw std::runtime_error("Failed to set protocol list for SSL context");
