    void processMessages() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !messageQueue.empty() || stopProcessing; });

            if (stopProcessing && messageQueue.empty()) {
                break;
            }

            Message currentMessage = messageQueue.front();
            messageQueue.pop();

            lock.unlock();

            // Process the message
