// Function to read a file, sort its lines, and extract a sequence number
void processFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return;
    }

    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(line);
    }
    file.close();

    std::sort(lines.begin(), lines.end());

    if (!lines.empty()) {
        // Assuming the last line contains a sequence number
        try {
            int sequenceNumber = std::stoi(lines.back());
            std::cout << "Sequence Number: " << sequenceNumber << std::endl;
        } catch (const std::invalid_argument& e) {
            std::cerr << "Invalid sequence number in file." << std::endl;
        }
    } else {
        std::cerr << "No lines found in the file." << std::endl;
    }
}

