#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Function prototypes
void* custom_malloc(size_t size);
void custom_free(void* ptr);
void init_hash_table();
Record* get_record(int key);
void put_record(int key, Record* rec);
void free_all_memory();
void log_memory_operation(const char* operation);

// Custom memory allocator (simplified version)
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

// Hash table implementation
#define TABLE_SIZE 1024

typedef struct hash_entry {
    int key;
    Record* value;
    struct hash_entry* next;
} HashEntry;

HashEntry* hash_table[TABLE_SIZE] = { NULL };

void init_hash_table() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }
}

Record* get_record(int key) {
    int index = abs(key) % TABLE_SIZE;
    HashEntry* entry = hash_table[index];
    while (entry != NULL) {
        if (entry->key == key) {
            return entry->value;
        }
        entry = entry->next;
    }
    return NULL; // Record not found
}

void put_record(int key, Record* rec) {
    int index = abs(key) % TABLE_SIZE;
    HashEntry* new_entry = (HashEntry*)custom_malloc(sizeof(HashEntry));
    new_entry->key = key;
    new_entry->value = rec;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;
}

// Function to free all allocated memory
void free_all_memory() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashEntry* entry = hash_table[i];
        while (entry != NULL) {
            HashEntry* next = entry->next;
            custom_free(entry);
            entry = next;
        }
    }
}

// Logging function
void log_memory_operation(const char* operation) {
    static clock_t last_time = 0;
    clock_t current_time = clock();
    if (last_time != 0) {
        double elapsed_time = (double)(current_time - last_time) / CLOCKS_PER_SEC;
        printf("Memory %s took %.6f seconds\n", operation, elapsed_time);
    }
    last_time = current_time;
}

// Stress test utility
void stress_test(int num_records) {
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        int key = rand() % num_records;
        Record* rec = (Record*)custom_malloc(sizeof(Record));
        rec->value = rand() % 1000; // Random value between 0 and 999
        put_record(key, rec);
        log_memory_operation("allocation");
    }

    for (int i = 0; i < num_records; ++i) {
        int key = rand() % num_records;
        Record* rec = get_record(key);
        if (!rec) {
            printf("Error: Record not found\n");
        }
        log_memory_operation("deallocation");
    }

    free_all_memory();
}

int main() {
    init_hash_table();
    stress_test(10000000); // Stress test with 10 million records
    return 0;
}
```

This code snippet provides a simplified implementation of the required functionality. It includes a custom memory allocator, a hash table for record storage, and a stress test utility to simulate inserting and retrieving records. The logging mechanism is integrated to measure memory allocation and deallocation times. Note that this is a basic example and may require further optimization and error handling for production use.']

