    MD5Config md5;
    SHA256Config sha256;
    RSAConfig rsa;
    int enabled_algorithms;
} CryptoLibrary;

void init_crypto_library(CryptoLibrary *lib, int enable_algorithms) {
    lib->enabled_algorithms = enable_algorithms;
    // Initialize AES configuration
    if (enable_algorithms & 1) {
        lib->aes.cipher = EVP_aes_256_cbc();
        lib->aes.key_size = 32;
        lib->aes.iv_size = 16;
    }
    // Initialize Camellia configuration
    if (enable_algorithms & 2) {
        lib->camellia.cipher = EVP_camellia_256_ecb();
        lib->camellia.key_size = 32;
        lib->camellia.iv_size = 16;
    }
    // Initialize MD5 configuration
    if (enable_algorithms & 4) {
        lib->md5.ctx = EVP_MD_CTX_create();
    }
    // Initialize SHA-256 configuration
    if (enable_algorithms & 8) {
        lib->sha256.ctx = EVP_MD_CTX_create();
    }
    // Initialize RSA configuration
    if (enable_algorithms & 16) {
        lib->rsa.rsa_key = RSA_new();
        RSA_generate_key_ex(lib->rsa.rsa_key, 2048, BN_value_of(65537), NULL);
    }
}

void cleanup_crypto_library(CryptoLibrary *lib) {
    if (lib->enabled_algorithms & 1) {
        EVP_CIPHER_free(lib->aes.cipher);
