    if (lib->enabled_algorithms & 4) {
        EVP_MD_CTX_destroy(lib->md5.ctx);
    }
    if (lib->enabled_algorithms & 8) {
        EVP_MD_CTX_destroy(lib->sha256.ctx);
    }
    if (lib->enabled_algorithms & 16) {
        RSA_free(lib->rsa.rsa_key);
