#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/crypto.h>
#include <json-c/json.h>

typedef struct {
    char *id;
    json_object *metadata;
} ResourceItem;

typedef struct {
    int itemCount;
    ResourceItem **items;
} ResourceBundle;

enum ErrorCode {
    SUCCESS,
    FILE_IO_ERROR,
    JSON_PARSE_ERROR,
    LOGIC_ERROR
};

ResourceBundle* loadResourceBundle(const char *path, enum ErrorCode *error) {
    FILE *file = fopen(path, "r");
    if (!file) {
        *error = FILE_IO_ERROR;
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *fileContent = (char *)malloc(fileSize + 1);
    if (!fileContent) {
        fclose(file);
        *error = FILE_IO_ERROR;
        return NULL;
    }

    fread(fileContent, 1, fileSize, file);
    fclose(file);
    fileContent[fileSize] = '\0';

    json_object *jsonRoot;
    json_error_t err;
    json_root = json_tokener_parse_ex(json_tokener_new(), fileContent, strlen(fileContent), &err);
    if (!jsonRoot) {
        free(fileContent);
        *error = JSON_PARSE_ERROR;
        return NULL;
    }

    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    bundle->itemCount = json_object_array_length(jsonRoot);
    bundle->items = (ResourceItem **)malloc(bundle->itemCount * sizeof(ResourceItem *));

    for (int i = 0; i < bundle->itemCount; ++i) {
        json_object *jsonItem = json_object_array_get_idx(jsonRoot, i);
        if (!json_object_object_get_ex(jsonItem, "id", (json_object **)&bundle->items[i]->id)) {
            json_object_put(bundle->items[i]);
            free(bundle->items[i]);
            bundle->items[i] = NULL;
            *error = LOGIC_ERROR;
            return NULL;
        }

        if (!json_object_object_get_ex(jsonItem, "metadata", (json_object **)&bundle->items[i]->metadata)) {
            json_object_put(bundle->items[i]);
            free(bundle->items[i]);
            bundle->items[i] = NULL;
            *error = LOGIC_ERROR;
            return NULL;
        }
    }

    free(fileContent);
    json_object_put(jsonRoot);

    *error = SUCCESS;
    return bundle;
}

void freeResourceBundle(ResourceBundle *bundle) {
    for (int i = 0; i < bundle->itemCount; ++i) {
        if (bundle->items[i]) {
            json_object_put(bundle->items[i]->id);
            json_object_put(bundle->items[i]->metadata);
            free(bundle->items[i]);
        }
    }

    free(bundle->items);
    free(bundle);
}

int main() {
    enum ErrorCode errorCode;
    ResourceBundle *bundle = loadResourceBundle("path_to_resource_file.json", &errorCode);

    if (errorCode != SUCCESS) {
        fprintf(stderr, "Error: %d - %s\n", errorCode, strerror(errorCode));
        return 1;
    }

    printf("Number of items in bundle: %d\n", bundle->itemCount);

    // Use the bundle...

    freeResourceBundle(bundle);

    return 0;
}
```

This code provides a function `loadResourceBundle` that reads a JSON file containing resource items and loads them into a dynamically allocated structure. It also includes error handling for file I/O, JSON parsing, and logic errors. The `main` function demonstrates how to use the `loadResourceBundle` function and handle potential errors.']

