#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <json-c/json.h>

typedef struct {
    char *id;
    json_object *metadata;
} ResourceItem;

typedef struct {
    size_t count;
    ResourceItem **items;
} ResourceBundle;

int loadResourceBundle(const char *path, ResourceBundle **bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open resource file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *jsonStr = (char *)malloc(fileSize + 1);
    if (!jsonStr) {
        fclose(file);
        perror("Failed to allocate memory for JSON string");
        return -1;
    }

    fread(jsonStr, 1, fileSize, file);
    jsonStr[fileSize] = '\0';
    fclose(file);

    json_object *root = json_tokener_parse(jsonStr);
    if (!root) {
        free(jsonStr);
        perror("Failed to parse JSON");
        return -1;
    }

    size_t itemCount = json_object_array_length(root);
    ResourceBundle *bundleObj = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (!bundleObj) {
        json_object_put(root);
        free(jsonStr);
        perror("Failed to allocate memory for bundle object");
        return -1;
    }

    bundleObj->count = itemCount;
    bundleObj->items = (ResourceItem **)malloc(itemCount * sizeof(ResourceItem *));
    if (!bundleObj->items) {
        json_object_put(root);
        free(bundleObj);
        free(jsonStr);
        perror("Failed to allocate memory for items array");
        return -1;
    }

    for (size_t i = 0; i < itemCount; ++i) {
        json_object *itemJson = json_object_array_get_idx(root, i);
        if (!json_is_object(itemJson)) {
            fprintf(stderr, "Invalid JSON format at index %zu\n", i);
            json_object_put(root);
            for (size_t j = 0; j < i; ++j) {
                free(bundleObj->items[j]->id);
                json_object_put(bundleObj->items[j]->metadata);
                free(bundleObj->items[j]);
            }
            free(bundleObj->items);
            free(bundleObj);
            free(jsonStr);
            return -1;
        }

        const char *id = json_object_get_string(json_object_object_get_ex(itemJson, "id", NULL));
        if (!id) {
            fprintf(stderr, "Missing 'id' field at index %zu\n", i);
            json_object_put(root);
            for (size_t j = 0; j < i; ++j) {
                free(bundleObj->items[j]->id);
                json_object_put(bundleObj->items[j]->metadata);
                free(bundleObj->items[j]);
            }
            free(bundleObj->items);
            free(bundleObj);
            free(jsonStr);
            return -1;
        }

        json_object *metadataJson = json_object_object_get_ex(itemJson, "metadata", NULL);
        if (!metadataJson || !json_is_object(metadataJson)) {
            fprintf(stderr, "Invalid 'metadata' field at index %zu\n", i);
            json_object_put(root);
            for (size_t j = 0; j < i; ++j) {
                free(bundleObj->items[j]->id);
                json_object_put(bundleObj->items[j]->metadata);
                free(bundleObj->items[j]);
            }
            free(bundleObj->items);
            free(bundleObj);
            free(jsonStr);
            return -1;
        }

        ResourceItem *item = (ResourceItem *)malloc(sizeof(ResourceItem));
        if (!item) {
            json_object_put(root);
            for (size_t j = 0; j < i; ++j) {
                free(bundleObj->items[j]->id);
                json_object_put(bundleObj->items[j]->metadata);
                free(bundleObj->items[j]);
            }
            free(bundleObj->items);
            free(bundleObj);
            free(jsonStr);
            perror("Failed to allocate memory for item");
            return -1;
        }

        item->id = strdup(id);
        item->metadata = metadataJson;

        bundleObj->items[i] = item;
    }

    json_object_put(root);
    *bundle = bundleObj;
    free(jsonStr);
    return 0;
}
