#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <http2.h>
#include <json-c/json.h>

typedef struct {
    char id[64];
    json_object *metadata;
} ResourceItem;

typedef struct {
    ResourceItem **items;
    size_t count;
} ResourceBundle;

BundleResource loadResourceBundle(const char *path) {
    FILE *file = fopen(path, "rb");
    if (!file) {
        return (BundleResource){NULL, 0};
    }

    // Read the entire file into memory
    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = malloc(fileSize);
    if (!buffer) {
        fclose(file);
        return (BundleResource){NULL, 0};
    }

    if (fread(buffer, 1, fileSize, file) != fileSize) {
        free(buffer);
        fclose(file);
        return (BundleResource){NULL, 0};
    }
    fclose(file);

    // Parse the JSON data
    json_object *jsonObj;
    json_error_t error;
    jsonObj = json_tokener_parse_ext(buffer, &error);
    if (!jsonObj) {
        free(buffer);
        return (BundleResource){NULL, 0};
    }

    // Count the number of items in the bundle
    size_t itemCount = json_object_array_length(jsonObj);

    // Allocate memory for the resource bundle
    ResourceItem **items = malloc(itemCount * sizeof(ResourceItem *));
    if (!items) {
        json_object_put(jsonObj);
        free(buffer);
        return (BundleResource){NULL, 0};
    }

    // Populate the resource bundle
    for (size_t i = 0; i < itemCount; ++i) {
        json_object *itemJson = json_object_array_get_idx(jsonObj, i);
        ResourceItem *item = malloc(sizeof(ResourceItem));
        if (!item) {
            free(items);
            json_object_put(jsonObj);
            free(buffer);
            return (BundleResource){NULL, 0};
        }

        // Parse the item ID
        const char *idStr = json_object_get_string(json_object_object_get_ex(itemJson, "id"));
        if (!idStr) {
            free(items);
            for (size_t j = 0; j < i; ++j) {
                free(items[j]);
            }
            json_object_put(jsonObj);
            free(buffer);
            return (BundleResource){NULL, 0};
        }
        strncpy(item->id, idStr, sizeof(item->id) - 1);

        // Parse the metadata
        item->metadata = json_object_object_get_ex(itemJson, "metadata");
        if (!item->metadata) {
            free(items);
            for (size_t j = 0; j < i; ++j) {
                free(items[j]);
            }
            json_object_put(jsonObj);
            free(buffer);
            return (BundleResource){NULL, 0};
        }

        items[i] = item;
    }

    // Free the JSON object
    json_object_put(jsonObj);

    // Return the resource bundle
    BundleResource result = {items, itemCount};
    free(buffer);
    return result;
}

void freeResourceBundle(BundleResource *bundle) {
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->items[i]);
    }
    free(bundle->items);
}
