#include <iostream>
#include <fstream>
#include <string>
#include <json/json.h>
#include <vector>
#include <mutex>

struct ResourceItem {
    std::string id;
    Json::Value metadata;
};

struct ResourceBundle {
    int itemCount;
    std::vector<ResourceItem> items;
};

enum ErrorCode {
    NO_ERROR = 0,
    FILE_IO_ERROR,
    JSON_PARSE_ERROR,
    LOGIC_ERROR
};

ResourceBundle loadResourceBundle(const std::string& filePath) {
    ResourceBundle bundle;
    bundle.itemCount = -1;

    // Open file and read content
    std::ifstream file(filePath);
    if (!file.is_open()) {
        return {FILE_IO_ERROR, {}};
    }

    Json::Value root;
    if (!Json::Reader().parse(file, root)) {
        return {JSON_PARSE_ERROR, {}};
    }

    // Parse JSON objects and store in bundle
    for (const auto& item : root) {
        if (!item.isObject()) {
            continue;
        }
        ResourceItem resItem;
        if (item.get("id", "").isNull() || !item["id"].isString()) {
            return {LOGIC_ERROR, {}};
        }
        resItem.id = item["id"].asString();
        for (const auto& pair : item.get("metadata", Json::Value(Json::objectValue))) {
            if (!pair.isMember("key") || !pair.isMember("value")) {
                continue;
            }
            resItem.metadata[pair["key"].asString()] = pair["value"];
        }
        bundle.items.push_back(resItem);
    }

    bundle.itemCount = static_cast<int>(bundle.items.size());
    return bundle;
}

int main() {
    std::string filePath = "path_to_resource_file.json";
    ResourceBundle bundle = loadResourceBundle(filePath);

    if (bundle.itemCount == -1) {
        switch (bundle.itemCount) {
            case FILE_IO_ERROR:
                std::cerr << "File I/O error occurred." << std::endl;
                break;
            case JSON_PARSE_ERROR:
                std::cerr << "JSON parsing error occurred." << std::endl;
                break;
            case LOGIC_ERROR:
                std::cerr << "Logic error occurred." << std::endl;
                break;
        }
    } else {
        std::cout << "Number of items in the bundle: " << bundle.itemCount << std::endl;
        // Process the bundle as needed
    }

    return 0;
}
