#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LOG_FILE "crypto_log.txt"
#define MAX_PRIMITIVES 10
#define MEMORY_THRESHOLD 512 * 1024 // 512 KB

typedef struct {
    const EVP_CIPHER *cipher;
    int usage_count;
} CipherCache;

typedef struct {
    const EVP_MD *digest;
    int usage_count;
} DigestCache;

CipherCache cipher_cache[MAX_PRIMITIVES];
DigestCache digest_cache[MAX_PRIMITIVES];

int cache_index = 0;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_usage(const char *primitive_name) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s used\n", primitive_name);
        fclose(log_file);
    }
}

int find_primitive_in_cache(void **cache, const EVP_CIPHER *cipher, const EVP_MD *digest) {
    for (int i = 0; i < cache_index; i++) {
        if ((cipher != NULL && cache[i]->cipher == cipher) ||
            (digest != NULL && cache[i]->digest == digest)) {
            return i;
        }
    }
    return -1;
}

void *get_cached_primitive(void **cache, const EVP_CIPHER *cipher, const EVP_MD *digest) {
    int index = find_primitive_in_cache(cache, cipher, digest);
    if (index != -1) {
        pthread_mutex_lock(&cache_mutex);
        cache[index]->usage_count++;
        pthread_mutex_unlock(&cache_mutex);
        return cache[index];
    }
    return NULL;
}

void add_primitive_to_cache(void **cache, const EVP_CIPHER *cipher, const EVP_MD *digest) {
    if (cache_index >= MAX_PRIMITIVES) {
        return; // Cache is full
    }

    pthread_mutex_lock(&cache_mutex);
    int index = cache_index++;
    cache[index].cipher = cipher;
    cache[index].digest = digest;
    cache[index].usage_count = 0;
    pthread_mutex_unlock(&cache_mutex);

    EVP_add_cipher(cipher);
    EVP_add_digest(digest);

    if (cipher != NULL) {
        EVP_add_digest_alias(EVP_md5(), "md5");
        EVP_add_digest_alias(EVP_sha1(), "sha1");
        EVP_add_digest_alias(EVP_sha256(), "sha256");
    }
}

void optimize_performance() {
    // Cache frequently used operations here
    add_primitive_to_cache((void **)cipher_cache, EVP_aes_128_cbc(), NULL);
