    private static final String CONFIG_FILE = "crypto_config.properties";
    private static final Map<String, Object> cryptoPrimitivesCache = new HashMap<>();
    private static final Logger logger = Logger.getLogger(CryptoConfigManager.class.getName());

    public synchronized static void loadStateFromConfig() {
        Properties properties = new Properties();
        try (FileReader reader = new FileReader(CONFIG_FILE)) {
            properties.load(reader);
            loadCryptoPrimitives(properties.getProperty("crypto.primitives"));
            configureLogging(properties.getProperty("logging.level"), properties.getProperty("logging.file"));
        } catch (IOException e) {
            logger.severe("Failed to load configuration file: " + e.getMessage());
        }
    }

    private static synchronized void loadCryptoPrimitives(String primitives) {
        // Clear the cache
        cryptoPrimitivesCache.clear();

        if (primitives != null && !primitives.isEmpty()) {
            for (String primitive : primitives.split(",")) {
                try {
                    Object primitiveInstance = Class.forName(primitive).newInstance();
                    cryptoPrimitivesCache.put(primitive, primitiveInstance);
                    logger.info("Loaded cryptographic primitive: " + primitive);
                } catch (Exception e) {
                    logger.severe("Failed to load cryptographic primitive: " + primitive + ". Error: " + e.getMessage());
                }
            }
        }
    }

    private static synchronized void configureLogging(String level, String file) {
        // Configure logging based on the properties
        logger.setLevel(Level.parse(level));
        try {
            FileHandler fileHandler = new FileHandler(file);
            logger.addHandler(fileHandler);
            logger.info("Logging configured with level: " + level + " and file: " + file);
        } catch (IOException e) {
            logger.severe("Failed to configure logging. Error: " + e.getMessage());
        }
    }

    public static synchronized Object getCryptoPrimitive(String name) {
        return cryptoPrimitivesCache.get(name);
    }

    // Add other methods for managing the state and cryptographic operations
}
