#include <iostream>
#include <fstream>
#include <json/json.h>
#include <string>

struct StreamParameters {
    std::string id;
    std::string format;
    std::string codec;
    int width;
    int height;
    Json::Value metadata;
};

enum ErrorCode {
    SUCCESS,
    FILE_NOT_FOUND,
    JSON_PARSE_ERROR,
    DUPLICATE_ID,
    MISSING_FIELD
};

ErrorCode parseStreamConfig(const std::string& filePath, StreamParameters** params) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        return FILE_NOT_FOUND;
    }

    Json::Value root;
    file >> root;

    *params = new StreamParameters[root.size()];
    for (unsigned int i = 0; i < root.size(); ++i) {
        const Json::Value& stream = root[i];
        if (!stream.isMember("id") || !stream["id"].isString()) {
            return MISSING_FIELD;
        }
        (*params)[i].id = stream["id"].asString();

        if (stream.isMember("format")) {
            (*params)[i].format = stream["format"].asString();
        }
        if (stream.isMember("codec")) {
            (*params)[i].codec = stream["codec"].asString();
        }
        if (stream.isMember("resolution") && stream["resolution"].isObject()) {
            if (stream["resolution"].isMember("width") && stream["resolution"]["width"].isInt() &&
                stream["resolution"].isMember("height") && stream["resolution"]["height"].isInt()) {
                (*params)[i].width = stream["resolution"]["width"].asInt();
                (*params)[i].height = stream["resolution"]["height"].asInt();
            } else {
                return JSON_PARSE_ERROR;
            }
        }
        if (stream.isMember("metadata")) {
            (*params)[i].metadata = stream["metadata"];
        }

        for (unsigned int j = 0; j < i; ++j) {
            if ((*params)[i].id == (*params)[j].id) {
                return DUPLICATE_ID;
            }
        }
    }

    file.close();
    return SUCCESS;
}

int main() {
    StreamParameters* params;
    ErrorCode result = parseStreamConfig("stream_config.json", &params);
    if (result != SUCCESS) {
        std::cerr << "Error: " << result << std::endl;
        return 1;
    }

    // Use the parsed parameters...

    delete[] params;
    return 0;
}
