    std::sort(lines.begin(), lines.end());

    // Extract sequence number from the first line
    if (!lines.empty()) {
        size_t pos = lines[0].find("sequence=");
        if (pos != std::string::npos) {
            size_t endPos = lines[0].find(' ', pos);
            if (endPos == std::string::npos) {
                endPos = lines[0].length();
            }
            std::string sequence = lines[0].substr(pos + 9, endPos - pos - 9);
            try {
                int seqNumber = std::stoi(sequence);
                return seqNumber;
            } catch (...) {
                std::cerr << "Invalid sequence number format: " << sequence << std::endl;
            }
        }
    }

    std::cerr << "No valid sequence number found in file." << std::endl;
    return -1;
}

