import java.util.regex.Pattern;
import java.util.logging.Logger;

public class EmailValidator {

    private static final String EMAIL_PATTERN = "^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$";
    private static final Logger LOGGER = Logger.getLogger(EmailValidator.class.getName());
    private static final int MAX_EMAIL_LENGTH = 256;
    private static final String PALINDROME_PLACEHOLDER = "[PALINDROME]";
    private static boolean skipPalindromeValidation = false;

    public static void validateEmails(String filePath) {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            long startTime = System.currentTimeMillis();

            while ((line = reader.readLine()) != null) {
                String[] emails = line.split("\\s+");

                for (String email : emails) {
                    if (email.length() > MAX_EMAIL_LENGTH) {
                        continue;
                    }

                    if (skipPalindromeValidation && isPalindrome(email)) {
                        System.out.println(PALINDROME_PLACEHOLDER);
                    } else if (isValidEmail(email)) {
                        System.out.println(email);
                    }
                }
            }

            long endTime = System.currentTimeMillis();
            LOGGER.info("Email validation took " + (endTime - startTime) + " ms");
        } catch (IOException e) {
            LOGGER.severe("Error processing file: " + e.getMessage());
        }
    }

    private static boolean isValidEmail(String email) {
        return Pattern.matches(EMAIL_PATTERN, email);
    }

    private static boolean isPalindrome(String str) {
        int left = 0;
        int right = str.length() - 1;

        while (left < right) {
            if (str.charAt(left) != str.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }

        return true;
    }

    public static void setSkipPalindromeValidation(boolean skip) {
        skipPalindromeValidation = skip;
    }

    public static boolean isSkipPalindromeValidation() {
        return skipPalindromeValidation;
    }
}
