// Define the structure for JWT claims
typedef struct {
    char *iss;
    char *sub;
    long exp;
    long nbf;
} JWTClaims;

// Define the structure for JWT header
typedef struct {
    char *alg;
    // Other header fields can be added here
} JWTHeader;

// Function to verify JWT signature and extract claims
bool verifyJWT(const char *jwt, const char *secretKey) {
    // Parse JWT to extract header and payload
    JWTHeader header = parseJWTHeader(jwt);
    JWTClaims claims = parseJWTClaims(jwt);

    // Check for required claims
    if (claims.iss == NULL || claims.sub == NULL || claims.exp <= 0 || claims.nbf < 0) {
        return false;
    }

    // Verify signature based on the algorithm specified in the header
    if (strcmp(header.alg, "HS256") == 0) {
        if (!verifyHMACSignature(jwt, secretKey)) {
            return false;
        }
    } else if (strcmp(header.alg, "RS256") == 0) {
        if (!verifyRSA256Signature(jwt, secretKey)) {
            return false;
        }
    } else if (strcmp(header.alg, "ES256") == 0) {
        if (!verifyECDSA256Signature(jwt, secretKey)) {
            return false;
        }
    } else {
        // Unsupported algorithm
        return false;
    }

    // Check token expiration and not before conditions
    time_t current_time = time(NULL);
    if (current_time >= claims.exp || current_time < claims.nbf) {
        return false;
    }

    // Token is valid
    return true;
}

