struct StreamParameters {
    std::string id;
    std::string format;
    std::string codec;
    int width;
    int height;
    Json::Value metadata;
};

class MultimediaLibrary {
public:
    static StreamParameters* parseConfig(const std::string& filePath, std::string& errorMessage) {
        try {
            // Open the JSON configuration file
            std::ifstream configFile(filePath);
            if (!configFile.is_open()) {
                throw std::runtime_error("Failed to open configuration file");
            }

            // Parse the JSON data from the file
            Json::Value root;
            configFile >> root;

            // Check for valid JSON structure
            if (!root.isArray() || root.size() == 0) {
                throw std::runtime_error("Invalid configuration format");
            }

            // Allocate memory for stream parameters
            StreamParameters* params = new StreamParameters[root.size()];
            bool anyErrors = false;

            // Parse each stream in the JSON file
            for (size_t i = 0; i < root.size(); ++i) {
                const Json::Value& stream = root[i];

                // Validate mandatory fields
                if (!stream.isMember("id") || !stream["id"].isString() ||
                    !stream.isMember("format") || !stream["format"].isString() ||
                    !stream.isMember("codec") || !stream["codec"].isString() ||
                    !stream.isMember("resolution") || !stream["resolution"].isObject() ||
                    !stream["resolution"].isMember("width") || !stream["resolution"]["width"].isUInt() ||
                    !stream["resolution"].isMember("height") || !stream["resolution"]["height"].isUInt()) {
                    anyErrors = true;
                    continue;
                }

                // Populate stream parameters
                params[i].id = stream["id"].asString();
                params[i].format = stream["format"].asString();
                params[i].codec = stream["codec"].asString();
                params[i].width = static_cast<int>(stream["resolution"]["width"].asUInt());
                params[i].height = static_cast<int>(stream["resolution"]["height"].asUInt());
                if (stream.isMember("metadata")) {
                    params[i].metadata = stream["metadata"];
                } else {
                    params[i].metadata.clear();
                }
            }

            // Handle any parsing errors
            if (anyErrors) {
                errorMessage = "Error: Invalid configuration parameters";
                delete[] params;
                return nullptr;
            }

            return params;
        } catch (const std::exception& e) {
            errorMessage = "Error: " + std::string(e.what());
            return nullptr;
        }
    }
};

int main() {
    std::string configFilePath = "path_to_config_file.json";
    std::string errorMessage;
    StreamParameters* params = MultimediaLibrary::parseConfig(configFilePath, errorMessage);

    if (params == nullptr) {
        std::cerr << "Configuration parsing failed: " << errorMessage << std::endl;
        return 1;
    }

    // Process the parsed stream parameters
    for (size_t i = 0; i < 3; ++i) { // Assuming there are 3 streams in the config
        std::cout << "Stream ID: " << params[i].id << ", Format: " << params[i].format 
                  << ", Codec: " << params[i].codec << ", Resolution: " << params[i].width << "x" << params[i].height 
                  << std::endl;
    }

    delete[] params;
    return 0;
}
```']

