    rsa->n = BN_new();
    rsa->e = BN_new();
    RSA_set0_key(rsa, rsa->n, rsa->e, NULL);
    EVP_add_cipher(EVP_RSA_WITH_SHA1());

    pthread_mutex_unlock(&crypto_lock);
}

