import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def md5_hash_large_file(file_path, chunk_size=64*1024, encoding='utf-8', progress_indicator=False):
    hash_md5 = hashlib.md5()
    total_size = os.path.getsize(file_path)
    bytes_read = 0

    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hash_md5.update(data)
            bytes_read += len(data)

            if progress_indicator:
                print(f"Processed {bytes_read}/{total_size} bytes", end='\r')

    return hash_md5.hexdigest()

def verify_checksums(file_paths, checksum_list):
    with ThreadPoolExecutor() as executor:
        futures = {executor.submit(md5_hash_large_file, file_path): file_path for file_path in file_paths}
        results = {}

        for future in as_completed(futures):
            file_path = futures[future]
            try:
                md5_hash = future.result()
                expected_md5 = next(item[1] for item in checksum_list if item[0] == file_path)
                if md5_hash != expected_md5:
                    results[file_path] = f"Checksum mismatch: {md5_hash} (expected: {expected_md5})"
            except Exception as e:
                results[file_path] = str(e)

    return results

# Example usage
file_paths = ['path/to/file1', 'path/to/file2']
checksum_list = [('path/to/file1', 'expected_md5_of_file1'), ('path/to/file2', 'expected_md5_of_file2')]
verification_results = verify_checksums(file_paths, checksum_list)
for file_path, result in verification_results.items():
    print(f"{file_path}: {result}")
