#include <pthread.h>

#define MAX_SESSIONS 10000

typedef struct {
    int ue_id;
    int enb_id;
} NFAPI_LTE_PDU_T;

NFAPI_LTE_PDU_T *sessions[MAX_SESSIONS];
int session_count = 0;

pthread_mutex_t sessions_lock = PTHREAD_MUTEX_INITIALIZER;

void add_session(NFAPI_LTE_PDU_T *session) {
    pthread_mutex_lock(&sessions_lock);
    if (session_count < MAX_SESSIONS) {
        sessions[session_count++] = session;
    } else {
        fprintf(stderr, "Maximum number of sessions reached\n");
    }
    pthread_mutex_unlock(&sessions_lock);
}

void remove_session(int ue_id) {
    pthread_mutex_lock(&sessions_lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->ue_id == ue_id) {
            free(sessions[i]);
            for (; i < session_count - 1; i++) {
                sessions[i] = sessions[i + 1];
            }
            session_count--;
            break;
        }
    }
    pthread_mutex_unlock(&sessions_lock);
}
