#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <memory>
#include <forward_list>
#include <string>
#include <chrono>
#include <sys/time.h>

struct Record {
    int value;
    std::time_t timestamp;
    size_t offset;
    std::string key;
};

class HashTable {
private:
    struct Node {
        Record data;
        Node* next;
        Node(const Record& rec) : data(rec), next(nullptr) {}
    };
    std::vector<Node*> buckets;
    size_t bucket_count;
    std::mutex mtx;

    static size_t hash(const std::string& key, size_t bucket_count) {
        size_t h = 0;
        for (char c : key)
            h = (h * 31 + c) % bucket_count;
        return h;
    }

public:
    HashTable(size_t initial_capacity = 16) : bucket_count(initial_capacity), buckets(bucket_count, nullptr) {}

    ~HashTable() {
        for (size_t i = 0; i < bucket_count; ++i) {
            Node* current = buckets[i];
            while (current) {
                Node* next = current->next;
                delete current;
                current = next;
            }
        }
    }

    void insert(const Record& record) {
        std::lock_guard<std::mutex> lock(mtx);
        size_t index = hash(record.key, bucket_count);
        Node* newNode = new Node(record);
        newNode->next = buckets[index];
        buckets[index] = newNode;
    }

    bool remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        size_t index = hash(key, bucket_count);
        Node* current = buckets[index];
        Node* prev = nullptr;

        while (current) {
            if (current->data.key == key) {
                if (prev)
                    prev->next = current->next;
                else
                    buckets[index] = current->next;
                delete current;
                return true;
            }
            prev = current;
            current = current->next;
        }

        return false;
    }

    // Additional methods for memory logging, stress testing, etc.
};

class MemoryAllocator {
public:
    void* allocate(size_t size) {
        // Custom allocation logic here
        return malloc(size);
    }

    void deallocate(void* ptr) {
        free(ptr);
    }
};

class StressTest {
public:
    static void run() {
        HashTable table;
        MemoryAllocator allocator;

        // Insert 10 million records in random order
        for (size_t i = 0; i < 10000000; ++i) {
            Record rec{rand(), time(nullptr), rand(), "key" + std::to_string(i)};
            table.insert(rec);
        }

        // Delete records and log memory usage
        for (size_t i = 0; i < 10000000; ++i) {
            table.remove("key" + std::to_string(rand() % 10000000));
        }
    }
};

void insertAfterOrAppend(std::forward_list<std::string>& list, const std::string& first, const std::string& second) {
    bool inserted = false;
    for (auto it = list.before_begin(); !inserted && it != list.end(); ++it) {
        if (*it == first) {
            *++it = second;
            inserted = true;
        }
    }
    if (!inserted)
        list.push_back(second);
}

class WebService {
public:
    struct Response {
