    int key;
    struct record *record;
    struct node *next;
} Node;

Node* hash_table[NUM_KEYS];

void initialize_memory() {
    srand(time(NULL));
    for (int i = 0; i < NUM_KEYS; ++i) {
        hash_table[i] = NULL;
    }
}

void allocate_record(int key, int range_min, int range_max) {
    Node *new_node = malloc(sizeof(Node));
    new_node->key = key;
    new_node->record = malloc(RECORD_SIZE);
    for (int i = 0; i < 10; ++i) {
        new_node->record->values[i] = rand() % (range_max - range_min + 1) + range_min;
    }
    time(&new_node->record->timestamp);
    strcpy(new_node->record->metadata, "Record Metadata");
    int index = key % NUM_KEYS;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
}

void free_all_memory() {
    for (int i = 0; i < NUM_KEYS; ++i) {
        Node *current = hash_table[i];
        while (current != NULL) {
            Node *temp = current;
            free(current->record);
            free(temp);
            current = temp->next;
        }
    }
}

