typedef struct record {
    int values[256];
    time_t timestamp;
    char metadata[32];
} Record;

Record* create_record(int range) {
    Record* rec = (Record*)malloc(sizeof(Record));
    for (int i = 0; i < 256; ++i) {
        rec->values[i] = rand() % range + 1;
    }
    time(&rec->timestamp);
    snprintf(rec->metadata, sizeof(rec->metadata), "Metadata");
    return rec;
}

void free_record(Record* rec) {
    free(rec);
}

typedef struct hash_table_entry {
    int key;
    Record* record;
    struct hash_table_entry* next;
} HashTableEntry;

HashTableEntry** create_hash_table() {
    HashTableEntry** table = (HashTableEntry**)calloc(NUM_KEYS, sizeof(HashTableEntry*));
    return table;
}

void insert_record(HashTableEntry** table, int key) {
    Record* rec = create_record(1000);
    HashTableEntry* entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    entry->key = key;
    entry->record = rec;
    entry->next = table[key % NUM_KEYS];
    table[key % NUM_KEYS] = entry;
}

Record* get_record(HashTableEntry** table, int key) {
    HashTableEntry* entry = table[key % NUM_KEYS];
    while (entry != NULL) {
        if (entry->key == key) {
            return entry->record;
        }
        entry = entry->next;
    }
    return NULL;
}

void free_hash_table(HashTableEntry** table) {
    for (int i = 0; i < NUM_KEYS; ++i) {
        HashTableEntry* entry = table[i];
        while (entry != NULL) {
            HashTableEntry* next = entry->next;
            free_record(entry->record);
            free(entry);
            entry = next;
        }
    }
    free(table);
}

void stress_test(HashTableEntry** table, int num_records) {
    clock_t start_time = clock();
    for (int i = 0; i < num_records; ++i) {
        insert_record(table, rand() % NUM_KEYS);
    }
    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Stress test completed in %.2f seconds\n", time_taken);

    for (int i = 0; i < num_records; ++i) {
        get_record(table, rand() % NUM_KEYS);
    }
}

int main() {
    srand(time(NULL));
    HashTableEntry** table = create_hash_table();
    stress_test(table, 1e9); // Simulate insertion and retrieval of one trillion records
    free_hash_table(table);
    return 0;
}
