char* appendSlashToLimitedString(const char* input, size_t limit, char* buffer, size_t bufferSize, struct timespec* timestamp) {
    if (timestamp != NULL) {
        clock_gettime(CLOCK_MONOTONIC, timestamp);
        // Validate timestamp logic here
    }

    if (input == NULL || limit == 0) {
        return NULL;
    }

    size_t inputLen = strlen(input);

    if (bufferSize < inputLen + 2) {
        return NULL; // Not enough space in buffer
    }

    if (inputLen >= limit) {
        return NULL;
    }

    if (buffer != NULL) {
        strcpy(buffer, input);
        buffer[inputLen] = '/';
        buffer[inputLen + 1] = '\0';
        return buffer;
    } else {
        char* newString = malloc(inputLen + 2);
        if (newString == NULL) {
            return NULL; // Memory allocation failed
        }
        strcpy(newString, input);
        newString[inputLen] = '/';
        newString[inputLen + 1] = '\0';
        return newString;
    }
}

int main() {
    const char* testString = "HelloWorld";
    size_t limit = 12;
    char buffer[50];
    struct timespec timestamp;

    char* result = appendSlashToLimitedString(testString, limit, buffer, sizeof(buffer), &timestamp);
    if (result != NULL) {
        printf("Result: %s\n", result);
        free(result); // Free dynamically allocated memory
    } else {
        printf("Operation failed.\n");
    }

    return 0;
}
