// Function to count words in a string
int countWords(const char *str) {
    int count = 0;
    if (str == NULL)
        return 0;

    while (*str) {
        // Skip spaces
        while (*str && (*str == ' ' || *str == '\t' || *str == '\n'))
            str++;

        // If a word starts, increment count
        if (*str) {
            count++;
            // Move to the end of the current word
            while (*str && (*str != ' ' && *str != '\t' && *str != '\n'))
                str++;
        }
    }

    return count;
}

// Function to recursively traverse a DOM tree and identify elements matching a selector
void traverseDOM(Node *node, const char *selector, FILE *outputFile) {
    if (node == NULL)
        return;

    // Check if the current node matches the selector
    if (matchesSelector(node, selector)) {
        if (outputFile != NULL) {
            fprintf(outputFile, "%s\n", node->content);
        } else {
            printf("%s\n", node->content);
        }

        if (commandLineFlags.countWords) {
            int wordCount = countWords(node->content);
            totalWordCount += wordCount;
        }
    }

    // Recursively traverse child nodes
    for (int i = 0; i < node->numChildren; i++) {
        traverseDOM(node->children[i], selector, outputFile);
    }
}

// Function to load a resource bundle from a file and return the number of items in the bundle
int loadResourceBundle(const char *path) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        perror("Error opening resource file");
        return -1;
    }

    int itemCount = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        itemCount++;
    }

    fclose(file);
    return itemCount;
}

// Main function to handle command-line arguments and execute the program
int main(int argc, char *argv[]) {
    // Parse command-line arguments
    parseCommandLineArgs(argc, argv);

    // Load resource bundle if specified
    if (commandLineFlags.resourceBundlePath != NULL) {
        int itemCount = loadResourceBundle(commandLineFlags.resourceBundlePath);
        if (itemCount < 0) {
            return EXIT_FAILURE;
        }
    }

    // Traverse DOM tree and identify elements matching the selector
    traverseDOM(rootNode, commandLineFlags.selector, commandLineFlags.outputFile);

    // Output total word count if requested
    if (commandLineFlags.countWords) {
        printf("Total word count: %d\n", totalWordCount);
    }

    return EXIT_SUCCESS;
}
