#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define N 1024

typedef struct {
    int value;
    long weight;
    char status;
} record;

long* offset_arr;
int* key_arr;
double* weight_arr;
record* records;
int arr_size = N;
int current_size = 0;
pthread_mutex_t mutex;

void init_arrays(int N) {
    pthread_mutex_init(&mutex, NULL);
    offset_arr = (long*)malloc(N * sizeof(long));
    key_arr = (int*)malloc(N * sizeof(int));
    weight_arr = (double*)malloc(N * sizeof(double));
    records = (record*)malloc(N * sizeof(record));

    srand(time(NULL)); // Seed for random number generation
}

void* resize_arrays(void* arg) {
    pthread_mutex_lock(&mutex);
    int new_size = current_size * 2;
    offset_arr = realloc(offset_arr, new_size * sizeof(long));
    key_arr = realloc(key_arr, new_size * sizeof(int));
    weight_arr = realloc(weight_arr, new_size * sizeof(double));
    records = realloc(records, new_size * sizeof(record));

    if (offset_arr == NULL || key_arr == NULL || weight_arr == NULL || records == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        return NULL;
    }

    arr_size = new_size;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void add_record(int value, long weight, char status) {
    if (current_size >= arr_size) {
        resize_arrays(NULL); // Resize arrays in a separate thread
    }
    records[current_size].value = value;
    records[current_size].weight = weight;
    records[current_size].status = status;
    current_size++;
}

void* secure_access_token(void* arg) {
    pthread_mutex_lock(&mutex);
    char* access_token = (char*)malloc(256 * sizeof(char));
    // Simulate fetching OAuth 2.0 access token
    snprintf(access_token, 256, "oauth2_token_%d", rand());

    // Simulate retrieving user information using the access token
    printf("Accessing user info with token: %s\n", access_token);

    free(access_token); // Free the session variable after use
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void cleanup() {
    pthread_mutex_destroy(&mutex);
    free(offset_arr);
    free(key_arr);
    free(weight_arr);
    free(records);
}

int main() {
    init_arrays(N);

    // Simulate adding records
    add_record(1, 2, 'A');
    add_record(3, 4, 'B');

    // Secure access token in a separate thread
    pthread_t token_thread;
    pthread_create(&token_thread, NULL, secure_access_token, NULL);
    pthread_join(token_thread, NULL);

    cleanup();
    return 0;
}
```

