#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <time.h>

#define MAX_INPUT_SIZE 1024

typedef struct record {
    int value;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void find_and_print_largest(int* arr, size_t size) {
    int max_val = INT_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }
    printf("Largest integer: %d\n", max_val);
}

void sort_array(int* arr, size_t size) {
    for (size_t i = 0; i < size - 1; ++i) {
        for (size_t j = 0; j < size - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

void free_all_memory(long* offsets, int* keys, Record* records, int* auxiliary_input) {
    free(offsets);
    free(keys);
    for (size_t i = 0; i < sizeof(records) / sizeof(records[0]); ++i) {
        free(records[i].value); // Assuming each record points to an allocated memory
    }
    free(records);
    free(auxiliary_input);
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <num_records> <range> <max_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_records = strtoul(argv[1], NULL, 10);
    int range = atoi(argv[2]);
    size_t max_size = strtoul(argv[3], NULL, 10);

    if (num_records == 0 || range < 0 || max_size == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return EXIT_FAILURE;
    }

    long* offsets = safe_malloc(num_records * sizeof(*offsets));
    int* keys = safe_malloc(num_records * sizeof(*keys));
    Record* records = (Record*)safe_malloc(num_records * sizeof(Record));

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % range;
        keys[i] = rand() % range;
        records[i].value = rand() % range;
    }

    int* auxiliary_input = safe_malloc(max_size * sizeof(*auxiliary_input));
    size_t input_count = 0;

    printf("Enter integers (max %zu), enter -1 to finish:\n", max_size);
    while (input_count < max_size) {
        int num;
        scanf("%d", &num);
        if (num == -1) break;
        auxiliary_input[input_count++] = num;
    }

    find_and_print_largest(auxiliary_input, input_count);
    sort_array(auxiliary_input, input_count);

    free_all_memory(offsets, keys, records, auxiliary_input);

    return EXIT_SUCCESS;
}
