    long *offsets = (long *)malloc(chunk_size * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }

    int *keys = (int *)malloc(chunk_size * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    record *records = (record *)malloc(chunk_size * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    srand(seed);

    // Initialize records with random numbers
    for (size_t i = 0; i < chunk_size; ++i) {
        records[i].value = rand() % 1000 + 1;
    }

    int max_value = INT_MIN;
    size_t num_elements = 0;

    while (1) {
        size_t elements_read = fread(&records[0], sizeof(record), chunk_size, stdin);
        if (elements_read == 0) break;

        for (size_t i = 0; i < elements_read; ++i) {
            if (records[i].value > max_value) {
                max_value = records[i].value;
            }
        }

        num_elements += elements_read;
    }

    printf("Largest integer in the dataset: %d\n", max_value);

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int seed;
    size_t chunk_size;

    printf("Enter seed for random number generator: ");
    scanf("%d", &seed);
    printf("Enter chunk size for input reading: ");
    scanf("%zu", &chunk_size);

    process_data(seed, chunk_size);

    return 0;
}
