void process_packet_metadata(size_t total_packets) {
    const size_t chunk_size = 1000; // Example chunk size, can be adjusted based on requirements

    // Allocate memory for arrays in chunks
    uint32_t* timestamps = malloc(chunk_size * sizeof(uint32_t));
    if (!timestamps) {
        fprintf(stderr, "Memory allocation failed for timestamps\n");
        return;
    }

    uint16_t* protocol_types = malloc(chunk_size * sizeof(uint16_t));
    if (!protocol_types) {
        fprintf(stderr, "Memory allocation failed for protocol types\n");
        free(timestamps);
        return;
    }

    packet_header* headers = malloc(chunk_size * sizeof(packet_header));
    if (!headers) {
        fprintf(stderr, "Memory allocation failed for packet headers\n");
        free(timestamps);
        free(protocol_types);
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < chunk_size; ++i) {
        timestamps[i] = 0;
        protocol_types[i] = 0;
        headers[i].data = NULL;
        headers[i].data_size = 0;
    }

    size_t packets_processed = 0;

    // Simulate reading packet data in chunks
    while (packets_processed < total_packets) {
        size_t current_chunk_size = chunk_size;
        if (packets_processed + current_chunk_size > total_packets) {
            current_chunk_size = total_packets - packets_processed;
        }

        // Example function to read packet data from external source
        int result = read_packet_data(timestamps, protocol_types, headers, current_chunk_size);
        if (result != 0) {
            fprintf(stderr, "Error reading packet data\n");
            break;
        }

        // Process each packet header
        for (size_t i = 0; i < current_chunk_size; ++i) {
            printf("Timestamp: %u, Protocol Type: %u, Data Size: %zu\n",
                   timestamps[i], protocol_types[i], headers[i].data_size);
        }

        packets_processed += current_chunk_size;
    }

    // Free dynamically allocated memory
    free(timestamps);
    free(protocol_types);
    for (size_t i = 0; i < total_packets; ++i) {
        if (headers[i].data) {
            free(headers[i].data);
        }
    }
    free(headers);
}

