Node* create_node(const char* title, long id) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return NULL; // Handle memory allocation failure

    new_node->title = strdup(title);
    new_node->id = id;
    new_node->relevance = 0.0f;
    new_node->children = NULL;
    new_node->num_children = 0;

    return new_node;
}

void free_node(Node* node) {
    if (node != NULL) {
        free(node->title);
        for (int i = 0; i < node->num_children; ++i) {
            free_node(node->children[i]);
        }
        free(node->children);
        free(node);
    }
}

Node** create_document_index(int N, int max_depth) {
    Node** index = (Node**)malloc(N * sizeof(Node*));
    if (index == NULL) return NULL; // Handle memory allocation failure

    for (int i = 0; i < N; ++i) {
        index[i] = create_node("Document Title", i);
        if (index[i] == NULL) {
            free_document_index(index, i); // Clean up on failure
            return NULL;
        }
    }

    return index;
}

void free_document_index(Node** index, int N) {
    for (int i = 0; i < N; ++i) {
        free_node(index[i]);
    }
    free(index);
}
