void resize_records(Record **records, int old_size, int new_size) {
    Record *new_records = (Record *)realloc(*records, new_size * sizeof(Record));
    if (!new_records) return; // Handle memory allocation failure

    for (int i = old_size; i < new_size; ++i) {
        new_records[i].value = i;
        new_records[i].weight = (long)i * 1000;
        new_records[i].status = 'A';
    }

    *records = new_records;
}

void populate_records(Record *records, int N, char **user_input, int user_count) {
    for (int i = 0; i < N; ++i) {
        records[i].value += (*user_input)[i % user_count];
        records[i].weight *= (long)(time(NULL) % 10);
        records[i].status = 'U';
    }
}

void free_records(Record *records, int N) {
