#include <openssl/ssl.h>
#include <openssl/err.h>

SSL_CTX *create_tls_context(const char *cert_file, const char *key_file) {
    SSL_CTX *ctx = NULL;
    ctx = SSL_CTX_new(TLS_method());
    if (ctx == NULL) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // Load certificate and private key
    if (SSL_CTX_use_certificate_file(ctx, cert_file, SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }
    if (SSL_CTX_use_PrivateKey_file(ctx, key_file, SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Configure TLS 1.2 and 1.3
    SSL_CTX_set_options(ctx, SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1);

    // Set cipher suites (e.g., ECDHE-RSA-AES256-GCM-SHA384)
    if (!SSL_CTX_set_cipher_list(ctx, "HIGH:!aNULL:!MD5")) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Configure session parameters (e.g., session timeout)
    SSL_CTX_set_timeout(ctx, 300);

    return ctx;
}

SSL *create_tls_connection(SSL_CTX *ctx, int socket) {
    SSL *ssl = SSL_new(ctx);
    if (ssl == NULL) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Attach the connection to the SSL context
    SSL_set_fd(ssl, socket);

    // Perform TLS handshake
    int ret = SSL_connect(ssl);
    if (ret != 1) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return NULL;
    }

    return ssl;
}

void close_tls_connection(SSL *ssl, SSL_CTX *ctx) {
    // Perform the TLS shutdown
    SSL_shutdown(ssl);

    // Free the SSL structure
    SSL_free(ssl);

    // Free the SSL context
    SSL_CTX_free(ctx);
}
```

