#include <nlohmann/json.hpp>

struct StreamParameters {
    std::string id;
    std::string format;
    // Add other stream parameters as needed
};

enum ErrorCode {
    NO_ERROR,
    FILE_NOT_FOUND,
    JSON_PARSE_ERROR,
    INVALID_ID,
    MISSING_REQUIRED_FIELD,
    DUPLICATE_IDENTIFIER
};

StreamParameters parseStreamParameters(const std::string& filePath, std::string& errorMessage) {
    StreamParameters params;
    std::ifstream file(filePath);

    if (!file.is_open()) {
        errorMessage = "File not found.";
        return { "", "" };
    }

    nlohmann::json j;
    try {
        file >> j;
    } catch (nlohmann::json::parse_error& e) {
        errorMessage = "JSON parse error: " + std::string(e.what());
        return { "", "" };
    }

    for (const auto& item : j.items()) {
        if (!item.value().is_object()) continue;

        const nlohmann::json& stream = item.value();
        params.id = stream["id"];
        params.format = stream["format"];

        // Validate ID
        if (params.id.empty()) {
            errorMessage = "Invalid or missing ID.";
            return { "", "" };
        }

        // Check for duplicate IDs
        if (item.key() != params.id) {
            errorMessage = "Duplicate identifier.";
            return { "", "" };
        }

        // Add validation for other required fields here

        // Additional stream parameter parsing and validation can be added here
    }

    file.close();
    return params;
}

int main() {
    std::string filePath = "config.json";
    std::string errorMessage;
    StreamParameters params = parseStreamParameters(filePath, errorMessage);

    if (params.id.empty()) {
        std::cout << "Error: " << errorMessage << std::endl;
        return -1;
    }

    std::cout << "Parsed stream parameters:" << std::endl;
    std::cout << "ID: " << params.id << ", Format: " << params.format << std::endl;

    return 0;
}
