#define MAX_UE_SESSIONS 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
    // Additional fields for UE-specific metadata
    time_t timestamp;
    float signal_strength;
    uint8_t CQI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} Array;

Array* create_array() {
    Array* arr = (Array*)malloc(sizeof(Array));
    if (!arr) {
        fprintf(stderr, "Failed to allocate memory for array\n");
        return NULL;
    }
    arr->head = arr->tail = NULL;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_array(Array* arr) {
    Node* current = arr->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int append_element(Array* arr, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&arr->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (arr->tail) {
        arr->tail->next = new_node;
    } else {
        arr->head = new_node;
    }
    arr->tail = new_node;
    arr->size++;
    pthread_mutex_unlock(&arr->lock);
    return 0;
}

int serialize_array(Array* arr, FILE* file) {
    pthread_mutex_lock(&arr->lock);
    if (fwrite(&arr->size, sizeof(size_t), 1, file) != 1) {
        perror("Failed to write array size");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }
    Node* current = arr->head;
    while (current) {
        if (fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            perror("Failed to write array element");
            pthread_mutex_unlock(&arr->lock);
            return -1;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&arr->lock);
    return 0;
}

int deserialize_array(Array* arr, FILE* file) {
    size_t size;
    if (fread(&size, sizeof(size_t), 1, file) != 1) {
        perror("Failed to read array size");
        return -1;
    }
    for (size_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        if (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            perror("Failed to read array element");
            return -1;
        }
        append_element(arr, data);
    }
    return 0;
}

