    fwrite(data, 1, length, output_file);
}

int main(int argc, char **argv) {
    CommandLineArgs args;
    parse_command_line_args(argc, argv, &args);

    FILE *input_file = fopen(args.input_file, "rb");
    if (!input_file) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    FILE *output_file = fopen(args.output_file, "wb");
    if (!output_file) {
        perror("Failed to open output file");
        fclose(input_file);
        return EXIT_FAILURE;
    }

    char buffer[MAX_CHUNK_SIZE];
    size_t bytes_read;

    while ((bytes_read = read_chunk(input_file, buffer, MAX_CHUNK_SIZE)) > 0) {
        process_chunk(buffer, bytes_read);
        write_output(buffer, bytes_read, output_file);
    }

    fclose(input_file);
    fclose(output_file);

    return EXIT_SUCCESS;
}
