void data_processor_destroy(DataProcessor* processor) {
    if (processor->proto_message) {
        delete processor->proto_message;
    }
    if (processor->json_data) {
        json_decref(processor->json_data);
    }
    if (processor->avro_writer) {
        avro_writer_free(processor->avro_writer);
