    private readonly Dictionary<string, ExternalDataSource> externalDataSources;

    public RandomValueGenerator(float min, float max, Dictionary<string, ExternalDataSource> dataSources)
    {
        minValue = min;
        maxValue = max;
        externalDataSources = dataSources;

        if (minValue > maxValue || minValue % 1 != 0 || maxValue % 1 != 0)
        {
            throw new ArgumentException("Invalid range for random value generation.");
        }

        foreach (var dataSource in externalDataSources.Values)
        {
            if (!dataSource.IsAvailable())
            {
                throw new InvalidOperationException("External data source is unavailable.");
            }
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        if (minValue >= maxValue || minValue % 1 != 0 || maxValue % 1 != 0)
        {
            return -1;
        }
        return UnityEngine.Random.Range((int)minValue, (int)maxValue);
    }

    public float GetWeightedRandomFloat(float[] weights)
    {
        if (weights.Sum() != 1.0f)
        {
            throw new ArgumentException("Weights must sum up to 1.0f for weighted random selection.");
        }

        float cumulative = 0.0f;
        float randomValue = randomEngine.NextDouble() * weights.Sum();

        foreach (var weight in weights)
        {
            cumulative += weight;
            if (randomValue < cumulative)
            {
                return UnityEngine.Random.Range(minValue, maxValue);
            }
        }

        return UnityEngine.Random.Range(minValue, maxValue);
    }
