typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    size_t max_size;
    pthread_mutex_t lock;
} CRC_Indication_Array;

CRC_Indication_Array* init_crc_ind_array(size_t max_size) {
    if (max_size == 0) {
        fprintf(stderr, "Invalid max_size. Must be greater than 0.\n");
        return NULL;
    }

    CRC_Indication_Array* array = (CRC_Indication_Array*)malloc(sizeof(CRC_Indication_Array));
    if (!array) {
        perror("Failed to allocate memory for CRC Indication Array.");
        return NULL;
    }

    array->head = NULL;
    array->tail = NULL;
    array->size = 0;
    array->max_size = max_size;

    if (pthread_mutex_init(&array->lock, NULL) != 0) {
        perror("Failed to initialize mutex.");
        free(array);
        return NULL;
    }

    return array;
}

int append_to_array(CRC_Indication_Array* array, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->max_size) {
        fprintf(stderr, "Array is full. Cannot append more elements.\n");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node.");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    new_node->data = data;
    new_node->next = NULL;

    if (array->head == NULL) {
        array->head = new_node;
        array->tail = new_node;
    } else {
        array->tail->next = new_node;
        array->tail = new_node;
    }

    array->size++;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void free_crc_ind_array(CRC_Indication_Array* array) {
    Node* current = array->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&array->lock);
    free(array);
}
