import hashlib
import os
from concurrent.futures import ThreadPoolExecutor
import requests

def calculate_md5(file_path, chunk_size=4096, encoding='utf-8'):
    hash_md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def validate_checksum(file_path, checksum_url, retries=3):
    for _ in range(retries):
        try:
            response = requests.get(checksum_url)
            response.raise_for_status()
            expected_checksum = response.text.strip()
            actual_checksum = calculate_md5(file_path)
            if expected_checksum == actual_checksum:
                return True
        except (requests.RequestException, ValueError) as e:
            print(f"Error fetching or validating checksum: {e}")
    return False

def process_files_in_pipeline(file_paths, checksum_urls):
    with ThreadPoolExecutor() as executor:
        results = list(executor.map(lambda file_path, checksum_url: 
                                      validate_checksum(file_path, checksum_url), 
                                      file_paths, checksum_urls))
    return all(results)

# Example usage
file_paths = ['path/to/large/file1', 'path/to/large/file2']
checksum_urls = ['http://example.com/checksums/file1', 'http://example.com/checksums/file2']
if process_files_in_pipeline(file_paths, checksum_urls):
    print("All files processed and checksums validated successfully.")
else:
    print("Some files processing or checksum validation failed.")
