#define MAX_BUNDLE_SIZE 1024

typedef struct {
    char** items;
    int count;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) {
        perror("Failed to open resource bundle file");
        return NULL;
    }

    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return NULL;
    }
    bundle->items = malloc(MAX_BUNDLE_SIZE * sizeof(char*));
    if (!bundle->items) {
        perror("Failed to allocate memory for resource bundle items");
        free(bundle);
        fclose(file);
        return NULL;
    }
    bundle->count = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (bundle->count >= MAX_BUNDLE_SIZE) {
            fprintf(stderr, "Resource bundle size exceeded\n");
            break;
        }
        bundle->items[bundle->count] = strdup(line);
        bundle->count++;
    }

    fclose(file);
    return bundle;
}

void freeResourceBundle(ResourceBundle* bundle) {
    for (int i = 0; i < bundle->count; i++) {
        free(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}

