            EVP_add_digest(EVP_sha1());
            EVP_add_digest_alias("sha", "sha1");
        }

        ~CryptoRandomGenerator() {
            EVP_cleanup();
        }

        float generateRandomFloat(float min, float max) {
            if (min > max) std::swap(min, max);
            static std::mt19937 gen;
            static std::uniform_real_distribution<> dis(min, max);
            return dis(gen);
        }

        int generateRandomInt(int min, int max) {
            if (min >= max) throw std::invalid_argument("Invalid range for integer generation");
            static std::mt19937 gen;
            static std::uniform_int_distribution<> dis(min, max - 1);
            return dis(gen);
        }
    };
}

// Example usage
int main() {
    CryptoUtils::CryptoRandomGenerator cryptoGen;

    float randomFloat = cryptoGen.generateRandomFloat(0.0f, 1.0f);
    int randomInt = cryptoGen.generateRandomInt(1, 100);

    return 0;
}
```

