namespace CryptoLibrary {

    namespace {
        std::mutex cryptoMutex;
        bool isInitialized = false;

        void loadAlgorithm(const char* name, int type, EVP_PKEY_METHOD* method) {
            if (EVP_add_pkey_method(method)) {
                std::lock_guard<std::mutex> lock(cryptoMutex);
                if (!isInitialized) {
                    std::cout << "Loaded " << name << " algorithm successfully." << std::endl;
                    isInitialized = true;
                }
            } else {
                std::cerr << "Failed to load " << name << " algorithm. Error: " << ERR_error_string(ERR_get_error(), nullptr) << std::endl;
            }
        }

        void validateAndLog(const char* name, int type, EVP_PKEY_METHOD* method) {
            if (method == nullptr) {
                std::cerr << "Invalid " << name << " algorithm. Skipping." << std::endl;
            } else {
                loadAlgorithm(name, type, method);
            }
        }

        void initCryptoLibrary() {
            validateAndLog("AES", EVP_PKEY_RSA, EVP_PKEY_get_default_method());
            validateAndLog("Camellia", EVP_PKEY_RSA, EVP_PKEY_get_default_method());
            validateAndLog("MD5", NID_md5, nullptr);
            validateAndLog("SHA", NID_sha256, nullptr);
            validateAndLog("RSA with SHA1", EVP_PKEY_RSA, EVP_PKEY_get_default_method());

            if (RAND_status() != 1) {
                std::cerr << "OpenSSL random number generator not seeded properly." << std::endl;
            }
        }

        void cleanupCryptoLibrary() {
            EVP_cleanup();
        }
    } // namespace

    class SecureRandomGenerator {
        std::mt19937 generator;

    public:
        SecureRandomGenerator() : generator(std::random_device{}()) {}
        ~SecureRandomGenerator() = default;

        double generateFloat(double min, double max) {
            if (min > max) std::swap(min, max);
            return min + (max - min) * generator();
        }

        int generateInt(int min, int max) {
            if (min > max) std::swap(min, max);
            return min + static_cast<int>(generator() % (max - min + 1));
        }
    };

    void initializeLibrary() {
        initCryptoLibrary();
    }

    void finalizeLibrary() {
        cleanupCryptoLibrary();
    }
} // namespace CryptoLibrary
