public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private IExternalDataSource externalDataSource;

    public RandomValueGenerator(float minValue, float maxValue, IExternalDataSource externalDataSource)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.externalDataSource = externalDataSource ?? throw new ArgumentNullException(nameof(externalDataSource));
    }

    public float GetRandomFloat()
    {
        return Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        if (minValue != Mathf.FloorToInt(minValue) || maxValue != Mathf.CeilToInt(maxValue))
            throw new ArgumentException("Min and max values must be integers.");

        return Random.Range((int)Mathf.FloorToInt(minValue), (int)Mathf.CeilToInt(maxValue) + 1);
    }

    public float GetWeightedRandomFloat(float[] weights)
    {
        if (weights == null || weights.Length == 0)
            throw new ArgumentException("Weights array must not be empty.");

        float totalWeight = 0;
        foreach (var weight in weights)
        {
            if (weight < 0)
                throw new ArgumentException("Weights must be non-negative.");
            totalWeight += weight;
        }

        if (Mathf.Abs(totalWeight - 1.0f) > 0.0001f)
            throw new ArgumentException("Sum of weights must be 1.0f.");

        float randomValue = Random.value * totalWeight;
        float cumulativeWeight = 0;

        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return minValue + (maxValue - minValue) * i / (weights.Length - 1);
        }

        throw new InvalidOperationException("Unexpected error in weighted random float generation.");
    }
}

