    public int FrameRateLimit { get; set; }
    public NetworkSettings Network { get; set; }

    public class NetworkSettings
    {
        public string ServerAddress { get; set; }
        public int Port { get; set; }
        public bool UseSSL { get; set; }
    }
}

public class GameInitializer
{
    private GameConfig config;

    public void LoadConfig(string filePath)
    {
        try
        {
            string json = File.ReadAllText(filePath);
            config = JsonConvert.DeserializeObject<GameConfig>(json);

            if (config == null)
            {
                Debug.LogError("Failed to load configuration.");
                return;
            }

            InitializeGame(config);
        }
        catch (Exception ex)
        {
            Debug.LogError($"Error loading configuration: {ex.Message}");
        }
    }

    private void InitializeGame(GameConfig config)
    {
        // Apply resolution settings
        foreach (var res in config.Resolutions)
        {
            Screen.SetResolution(res.width, res.height, FullScreenMode.Windowed);
        }

        // Set frame rate limit
        Application.targetFrameRate = config.FrameRateLimit;

        // Configure network settings
        if (config.Network.UseSSL)
        {
            Debug.LogWarning("SSL is not yet supported.");
        }
    }
}

public class GameWindowManager : MonoBehaviour
{
    void Start()
    {
        GameInitializer initializer = new GameInitializer();
        initializer.LoadConfig("path/to/config.json");
    }
}
