#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_SESSIONS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    // Add UE-specific metadata fields here
    time_t timestamp;
    float signal_strength;
    int CQI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} NFAPI_CRC_QUEUE_T;

NFAPI_CRC_QUEUE_T* create_queue() {
    NFAPI_CRC_QUEUE_T* queue = (NFAPI_CRC_QUEUE_T*)malloc(sizeof(NFAPI_CRC_QUEUE_T));
    if (!queue) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    queue->head = queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue(NFAPI_CRC_QUEUE_T* queue, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&queue->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&queue->lock);
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (queue->tail) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;

    pthread_mutex_unlock(&queue->lock);
}

void dequeue(NFAPI_CRC_QUEUE_T* queue, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&queue->lock);
    if (queue->head == NULL) {
        fprintf(stderr, "Queue is empty\n");
        pthread_mutex_unlock(&queue->lock);
        return;
    }

    Node* temp = queue->head;
    *data = temp->data;

    queue->head = queue->head->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    free(temp);

    pthread_mutex_unlock(&queue->lock);
}

void destroy_queue(NFAPI_CRC_QUEUE_T* queue) {
    Node* current = queue->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}
