    size_t delimiter_len;
} DelimiterConfig;

typedef struct {
    DelimiterConfig config;
    clock_t start_time;
} ProcessingContext;

char* process_string(const char* input, size_t max_size, const DelimiterConfig* delimiter_config, char* buffer, size_t buffer_size, ProcessingContext* context) {
    if (input == NULL || max_size == 0 || delimiter_config == NULL) {
        return NULL;
    }

    clock_t end_time = clock();
    double elapsed_time = ((double)(end_time - context->start_time)) / CLOCKS_PER_SEC;

    if (elapsed_time >= 1.0) {
        printf("Warning: Operation took %.2f seconds.\n", elapsed_time);
    }

    if (strlen(input) > max_size) {
        return NULL;
    }

    size_t result_len = strlen(input) + delimiter_config->delimiter_len + 1;
    char* result;

    if (buffer != NULL && buffer_size >= result_len) {
        result = buffer;
    } else {
        result = malloc(result_len * sizeof(char));
        if (result == NULL) {
            return NULL;
        }
    }

    snprintf(result, result_len, "%s%s", input, delimiter_config->delimiter);

    return result;
}

int main() {
    DelimiterConfig config = {" / ", 4};
    ProcessingContext context;
    context.start_time = clock();

    const char* input = "Hello";
    size_t max_size = 20;
    char buffer[50];

    char* output = process_string(input, max_size, &config, buffer, sizeof(buffer), &context);
    if (output != NULL) {
        printf("Processed string: %s\n", output);
        free(output); // Only needed if dynamically allocated
    } else {
        printf("Failed to process string.\n");
    }

    return 0;
}
