typedef struct {
    double** data;
    size_t rows, cols;
} DynamicMatrix;

DynamicMatrix* create_matrix(size_t rows, size_t cols) {
    DynamicMatrix* matrix = (DynamicMatrix*)malloc(sizeof(DynamicMatrix));
    if (!matrix) return NULL;

    matrix->rows = rows;
    matrix->cols = cols;

    matrix->data = (double**)calloc(rows, sizeof(double*));
    if (!matrix->data) {
        free(matrix);
        return NULL;
    }

    for (size_t i = 0; i < rows; ++i) {
        matrix->data[i] = (double*)calloc(cols, sizeof(double));
        if (!matrix->data[i]) {
            for (size_t j = 0; j < i; ++j) free(matrix->data[j]);
            free(matrix->data);
            free(matrix);
            return NULL;
        }
    }

    return matrix;
}

void destroy_matrix(DynamicMatrix* matrix) {
    if (!matrix) return;

    for (size_t i = 0; i < matrix->rows; ++i) free(matrix->data[i]);
    free(matrix->data);
    free(matrix);
}

void initialize_matrix(DynamicMatrix* matrix, double (*init_value_func)(size_t row, size_t col)) {
    if (!matrix || !init_value_func) return;

    for (size_t i = 0; i < matrix->rows; ++i) {
        for (size_t j = 0; j < matrix->cols; ++j) {
            matrix->data[i][j] = init_value_func(i, j);
        }
    }
}

void add_matrices(DynamicMatrix* result, const DynamicMatrix* mat1, const DynamicMatrix* mat2) {
    if (!result || !mat1 || !mat2 || (mat1->rows != mat2->rows) || (mat1->cols != mat2->cols)) return;

    for (size_t i = 0; i < result->rows; ++i) {
        for (size_t j = 0; j < result->cols; ++j) {
            result->data[i][j] = mat1->data[i][j] + mat2->data[i][j];
        }
    }
}

