std::pair<std::vector<NetworkStream>, std::string> parseConfigFile(const std::string& filePath) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        return { {}, "Error opening file" };
    }

    nlohmann::json jsonData;
    try {
        file >> jsonData;
    } catch (nlohmann::json::parse_error& e) {
        return { {}, "JSON parsing error: " + std::string(e.what()) };
    }

    if (!jsonData.is_array()) {
        return { {}, "Configuration is not an array of JSON objects" };
    }

    std::vector<NetworkStream> streams;
    for (const auto& jsonStream : jsonData) {
        NetworkStream stream;

