#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int count;
    pthread_mutex_t mutex;
} NFAPI_CRC_Queue;

NFAPI_CRC_Queue* create_queue() {
    NFAPI_CRC_Queue* queue = (NFAPI_CRC_Queue*)malloc(sizeof(NFAPI_CRC_Queue));
    if (!queue) return NULL;
    queue->head = queue->tail = NULL;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    return queue;
}

void destroy_queue(NFAPI_CRC_Queue* queue) {
    Node* current = queue->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

int enqueue(NFAPI_CRC_Queue* queue, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&queue->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Memory allocation failed
    }
    newNode->data = data;
    newNode->next = NULL;

    if (queue->tail) {
        queue->tail->next = newNode;
    } else {
        queue->head = newNode;
    }
    queue->tail = newNode;
    queue->count++;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int dequeue(NFAPI_CRC_Queue* queue, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&queue->mutex);
    if (!queue->head) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Queue is empty
    }
    Node* temp = queue->head;
    *data = temp->data;

    queue->head = temp->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    free(temp);
    queue->count--;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int main() {
    NFAPI_CRC_Queue* queue = create_queue();
    if (!queue) {
        printf("Failed to create queue\n");
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 1000;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu.CRCFLAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG

        if (enqueue(queue, pdu) != 0) {
            printf("Failed to enqueue element\n");
            break;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T data;
    while (dequeue(queue, &data) == 0) {
        printf("Dequeued: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG, data.CRCFLAG);
    }

    destroy_queue(queue);
    return 0;
}
