#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define NR_PHY_RX_CONFIG_T struct phy_rx_config
NR_PHY_RX_CONFIG_T {
    int RX_ANTENNA_PORT_ID;
    int SCH_INFO;
    int PHY_RX_PARAMS;
};

typedef struct {
    NR_PHY_RX_CONFIG_T *array;
    size_t capacity;
    size_t size;
    FILE *log_file;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity, const char *log_filename) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) {
        perror("Failed to allocate memory for DynamicArray");
        return NULL;
    }

    da->array = malloc(initial_capacity * sizeof(NR_PHY_RX_CONFIG_T));
    if (!da->array) {
        perror("Failed to allocate memory for array");
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    da->log_file = fopen(log_filename, "w");
    if (!da->log_file) {
        perror("Failed to open log file");
        free(da->array);
        free(da);
        return NULL;
    }

    pthread_mutex_init(&da->lock, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da->array) {
        free(da->array);
    }
    if (da->log_file) {
        fclose(da->log_file);
    }
    pthread_mutex_destroy(&da->lock);
    free(da);
}

int add_to_array(DynamicArray *da, NR_PHY_RX_CONFIG_T config) {
    pthread_mutex_lock(&da->lock);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        NR_PHY_RX_CONFIG_T *new_array = realloc(da->array, new_capacity * sizeof(NR_PHY_RX_CONFIG_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            fprintf(stderr, "Failed to reallocate memory for array\n");
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size++] = config;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

void log_message(DynamicArray *da, const char *message) {
    if (da->log_file) {
        fprintf(da->log_file, "%s\n", message);
    }
}
