// Define the structure for NFAPI_CRC_INDICATION_PDU_T
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    float signal_strength;
    int CQI;
};

// Define a class to manage the array of NFAPI_CRC_INDICATION_PDU_T structures
class NFAPICRCManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::mutex mutex;

public:
    // Constructor with configurable maximum size
    explicit NFAPICRCManager(size_t max_size) : data(max_size) {}

    // Append a new element to the array
    bool append(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mutex);
        if (data.size() == 0) return false; // Check if the array is full
        data.push_back(pdu);
        return true;
    }

    // Get an element at a specific index
    NFAPI_CRC_INDICATION_PDU_T get(size_t index) {
        std::lock_guard<std::mutex> lock(mutex);
        if (index >= data.size()) throw std::out_of_range("Index out of range");
        return data[index];
    }

    // Serialize the array into a binary file
    void serialize(const std::string& filename) const {
        std::ofstream ofs(filename, std::ios::binary);
        for (const auto& pdu : data) {
            ofs.write(reinterpret_cast<const char*>(&pdu), sizeof(pdu));
        }
    }

    // Deserialize the array from a binary file
    void deserialize(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::binary);
        NFAPI_CRC_INDICATION_PDU_T pdu;
        while (ifs.read(reinterpret_cast<char*>(&pdu), sizeof(pdu))) {
            append(pdu);
        }
    }

    // Get the size of the array
    size_t size() const {
        return data.size();
    }
};

// Example usage
int main() {
    NFAPICRCManager manager(1000000); // Create a manager with a maximum size of 1 million

    // Append some data
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, time(nullptr), 4.5, 6};
    for (int i = 0; i < 1000000; ++i) {
        manager.append(pdu);
    }

    // Get and print an element
    NFAPI_CRC_INDICATION_PDU_T retrieved_pdu = manager.get(500000);
    std::cout << "Retrieved PDU: RX_UE_INFORMATION_TAG=" << retrieved_pdu.RX_UE_INFORMATION_TAG 
              << ", RNTI=" << retrieved_pdu.RNTI << ", CRC_INDICATION_REL8_TAG=" << retrieved_pdu.CRC_INDICATION_REL8_TAG 
              << ", timestamp=" << retrieved_pdu.timestamp << ", signal_strength=" << retrieved_pdu.signal_strength 
              << ", CQI=" << retrieved_pdu.CQI << std::endl;

    // Serialize and deserialize
    manager.serialize("data.bin");
    NFAPICRCManager loaded_manager(1000000);
    loaded_manager.deserialize("data.bin");

    return 0;
}
