#include <pthread.h>

typedef struct {
    char *message;
    size_t length;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} LogArray;

LogArray* log_array_init(size_t initial_capacity) {
    LogArray *array = (LogArray*)malloc(sizeof(LogArray));
    array->entries = (LogEntry**)malloc(initial_capacity * sizeof(LogEntry*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void log_array_add(LogArray *array, char *message, size_t length) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        array->entries = realloc(array->entries, 2 * array->capacity * sizeof(LogEntry*));
        array->capacity *= 2;
    }
    LogEntry *entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->message = malloc(length);
    memcpy(entry->message, message, length);
    entry->length = length;
    array->entries[array->size++] = entry;
    pthread_mutex_unlock(&array->lock);
}

