#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SESSIONS 10000

typedef struct {
    // Define the fields of NFAPI_LTE_PDU_T here
    int ue_id;
    int enb_id;
} NFAPI_LTE_PDU_T;

NFAPI_LTE_PDU_T *session_array = NULL;
int session_count = 0;
pthread_mutex_t mutex;

void initialize_session_manager() {
    pthread_mutex_init(&mutex, NULL);
    session_array = (NFAPI_LTE_PDU_T *)calloc(MAX_SESSIONS, sizeof(NFAPI_LTE_PDU_T));
    if (!session_array) {
        fprintf(stderr, "Failed to allocate memory for session array\n");
        exit(EXIT_FAILURE);
    }
}

void add_session(int ue_id, int enb_id) {
    pthread_mutex_lock(&mutex);
    if (session_count >= MAX_SESSIONS) {
        printf("Session limit reached. Unable to add new session.\n");
    } else {
        session_array[session_count].ue_id = ue_id;
        session_array[session_count].enb_id = enb_id;
        session_count++;
    }
    pthread_mutex_unlock(&mutex);
}

void remove_session(int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= session_count) {
        printf("Invalid session index\n");
    } else {
        for (; index < session_count - 1; index++) {
            session_array[index] = session_array[index + 1];
        }
        session_count--;
    }
    pthread_mutex_unlock(&mutex);
}

void *process_sessions(void *arg) {
    int start_index = *(int *)arg;
    int end_index = (start_index + MAX_SESSIONS / 4 > session_count) ? session_count : start_index + MAX_SESSIONS / 4;

    for (int i = start_index; i < end_index; i++) {
        // Process each session
        printf("Processing session with UE ID: %d, ENB ID: %d\n", session_array[i].ue_id, session_array[i].enb_id);
    }

    free(arg);
    return NULL;
}

void *monitor_memory(void *arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        printf("Current memory usage: %zu bytes\n", session_count * sizeof(NFAPI_LTE_PDU_T));
        pthread_mutex_unlock(&mutex);
        sleep(5); // Check every 5 seconds
    }
}

int main() {
    initialize_session_manager();

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_memory, NULL);

    int num_threads = 4;
    pthread_t threads[num_threads];
    int thread_ids[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, process_sessions, &thread_ids[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_join(monitor_thread, NULL);

    free(session_array);
    pthread_mutex_destroy(&mutex);
    return 0;
}
