#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define fields for NFAPI_LTE_PDU_T structure
} NFAPI_LTE_PDU_T;

typedef struct {
    NFAPI_LTE_PDU_T **sessions;
    size_t count;
    size_t max_count;
    pthread_mutex_t lock;
} SessionManager;

SessionManager *session_manager_init(size_t initial_capacity, size_t max_capacity) {
    SessionManager *manager = (SessionManager *)malloc(sizeof(SessionManager));
    if (!manager) {
        perror("Failed to allocate memory for SessionManager");
        return NULL;
    }
    manager->sessions = (NFAPI_LTE_PDU_T **)calloc(initial_capacity, sizeof(NFAPI_LTE_PDU_T *));
    if (!manager->sessions) {
        perror("Failed to allocate memory for sessions array");
        free(manager);
        return NULL;
    }
    manager->count = 0;
    manager->max_count = initial_capacity < max_capacity ? initial_capacity : max_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void session_manager_destroy(SessionManager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->sessions[i]);
        }
        free(manager->sessions);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int session_manager_add_session(SessionManager *manager, NFAPI_LTE_PDU_T *session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->max_count) {
        manager->sessions = reallocarray(manager->sessions, manager->max_count * 2, sizeof(NFAPI_LTE_PDU_T *));
        if (!manager->sessions) {
            perror("Failed to reallocate memory for sessions array");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->max_count *= 2;
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
