#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char ip[16];
    int port;
    int status;
    time_t last_active;
} Device;

typedef struct Node {
    Device data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
} DeviceList;

void initDeviceList(DeviceList* list) {
    list->head = NULL;
}

Node* createNode(Device device) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = device;
    newNode->next = NULL;
    return newNode;
}

void addDevice(DeviceList* list, Device device) {
    Node* newNode = createNode(device);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void removeDevice(DeviceList* list, const char* ip, int port) {
    Node* temp = list->head;
    Node* prev = NULL;

    while (temp != NULL && 
           (strcmp(temp->data.ip, ip) != 0 || temp->data.port != port)) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // Device not found

    if (prev == NULL) {
        list->head = temp->next;
    } else {
        prev->next = temp->next;
    }
    free(temp);
}

void updateDeviceStatus(DeviceList* list, const char* ip, int port, int status) {
    Node* temp = list->head;

    while (temp != NULL && 
           (strcmp(temp->data.ip, ip) != 0 || temp->data.port != port)) {
        temp = temp->next;
    }

    if (temp != NULL) {
        temp->data.status = status;
        time(&temp->data.last_active);
    }
}

Node* getMostRecentlyActiveDevice(DeviceList* list) {
    Node* mostActive = NULL;

    Node* temp = list->head;

    while (temp != NULL) {
        if (mostActive == NULL || temp->data.last_active > mostActive->data.last_active) {
            mostActive = temp;
        }
        temp = temp->next;
    }

    return mostActive;
}

void cleanupInactiveDevices(DeviceList* list, time_t threshold) {
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (time(NULL) - current->data.last_active > threshold) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            Node* next = current->next;
            free(current);
            current = next;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void serializeDeviceList(DeviceList* list, FILE* file) {
    Node* temp = list->head;

    while (temp != NULL) {
        fwrite(&temp->data, sizeof(Device), 1, file);
        temp = temp->next;
    }
}

void deserializeDeviceList(DeviceList* list, FILE* file) {
    Device device;
    while (fread(&device, sizeof(Device), 1, file) == 1) {
        addDevice(list, device);
    }
}
