#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

// Define log levels
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

// Global configuration settings
LogLevel current_log_level = LOG_ERROR;
int rate_limit_interval_ms = 1000; // 1 second
time_t last_log_time = 0;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to safely allocate memory
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// External logging service integration function
void external_log(const char* message) {
    // Simulate sending a log message to an external service
    printf("External Log: %s\n", message);
}

// Function to format and log messages
void log_message(LogLevel level, const char* format, ...) {
    if (level > current_log_level || time(NULL) - last_log_time < rate_limit_interval_ms / 1000.0) {
        return;
    }

    va_list args;
    va_start(args, format);

    // Buffer to hold the formatted message
    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    // Prepend timestamp and log level to the message
    time_t now = time(NULL);
    struct tm* local_time = localtime(&now);
    char time_str[30];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", local_time);

    snprintf(buffer, sizeof(buffer), "[%s] [%s] %s\n", time_str, (level == LOG_DEBUG ? "DEBUG" : 
        (level == LOG_INFO ? "INFO" : (level == LOG_WARNING ? "WARNING" : "ERROR"))), buffer);

    // Lock the log to ensure thread safety
    pthread_mutex_lock(&log_lock);

    // Log to external service
    external_log(buffer);

    // Update last log time and unlock
    last_log_time = now;
    pthread_mutex_unlock(&log_lock);
}

// Example usage
int main() {
    log_message(LOG_INFO, "This is an informational message.");
    log_message(LOG_ERROR, "This is an error message.");

    return 0;
}
```

