#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 100

typedef struct {
    char *log_entries[MAX_LOG_ENTRIES];
    int count;
    pthread_mutex_t lock;
} Logger;

void init_logger(Logger *logger) {
    logger->count = 0;
    pthread_mutex_init(&logger->lock, NULL);
}

void log_message(Logger *logger, const char *function_name, const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    // Create a buffer for the log entry
    size_t buf_size = strlen(function_name) + strlen(timestamp) + 30; // Extra space for format specifiers and null terminator
    char *log_entry = (char *)malloc(buf_size);
    if (!log_entry) {
        fprintf(stderr, "Memory allocation failed\n");
        va_end(args);
        return;
    }

    // Format the log entry
    snprintf(log_entry, buf_size, "%s [%s] ", timestamp, function_name);
    vsnprintf(log_entry + strlen(log_entry), buf_size - strlen(log_entry), format, args);

    pthread_mutex_lock(&logger->lock);

    if (logger->count >= MAX_LOG_ENTRIES) {
        // Log buffer is full, free the oldest entry
        free(logger->log_entries[0]);
        memmove(logger->log_entries, logger->log_entries + 1, (MAX_LOG_ENTRIES - 1) * sizeof(char *));
        logger->count--;
    }

    // Add new log entry
    logger->log_entries[logger->count] = log_entry;
    logger->count++;

    pthread_mutex_unlock(&logger->lock);

    va_end(args);
}

void destroy_logger(Logger *logger) {
    for (int i = 0; i < logger->count; i++) {
        free(logger->log_entries[i]);
    }
    pthread_mutex_destroy(&logger->lock);
}
