#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 1000
#define MODULE_ID_LENGTH 20

typedef struct LogEntry {
    time_t timestamp;
    char function_name[50];
    char module_id[MODULE_ID_LENGTH];
    char message[2048];
} LogEntry;

LogEntry log_buffer[MAX_LOG_ENTRIES];
int log_count = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* function_name, const char* module_id, const char* format, ...) {
    va_list args;
    pthread_mutex_lock(&log_mutex);

    if (log_count >= MAX_LOG_ENTRIES) {
        // Handle buffer overflow gracefully
        printf("Log buffer is full. Discarding message.\n");
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    LogEntry* entry = &log_buffer[log_count++];
    time_t current_time = time(NULL);
    strftime(entry->timestamp, sizeof(time_t), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
    strncpy(entry->function_name, function_name, sizeof(entry->function_name) - 1);
    strncpy(entry->module_id, module_id, MODULE_ID_LENGTH - 1);

    va_start(args, format);
    vsnprintf(entry->message, sizeof(entry->message), format, args);
    va_end(args);

    pthread_mutex_unlock(&log_mutex);
}

void* log_thread_function(void* arg) {
    // Simulate high-throughput logging
    for (int i = 0; i < 1000; ++i) {
        log_message("simulate_log_function", "ModuleA", "Log entry %d", i);
    }
    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    // Create threads to simulate concurrent logging
    pthread_create(&thread1, NULL, log_thread_function, NULL);
    pthread_create(&thread2, NULL, log_thread_function, NULL);

    // Wait for threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
```

