namespace CryptoRandom {

class RandomGenerator {
public:
    explicit RandomGenerator(uint32_t seed = std::random_device{}())
        : gen(seed) {}

    ~RandomGenerator() {
        EVP_cleanup();
    }

    double getRandomFloat(double min, double max) {
        if (min > max) std::swap(min, max);
        return dist_float(gen);
    }

    int getRandomInt(int min, int max) {
        if (min > max) std::swap(min, max);
        return dist_int(gen);
    }

private:
    std::mt19937 gen;
    std::uniform_real_distribution<double> dist_float;
    std::uniform_int_distribution<int> dist_int;
};

