#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>

typedef struct {
    char *buffer;
    size_t allocated_size;
    size_t used_size;
} LogBuffer;

LogBuffer* create_log_buffer(size_t initial_size) {
    LogBuffer *log = (LogBuffer*)malloc(sizeof(LogBuffer));
    log->buffer = (char*)malloc(initial_size);
    log->allocated_size = initial_size;
    log->used_size = 0;
    return log;
}

void destroy_log_buffer(LogBuffer *log) {
    free(log->buffer);
    free(log);
}

int append_to_log(LogBuffer *log, const char *format, ...) {
    va_list args;
    va_start(args, format);

    if (log->used_size + vsnprintf(NULL, 0, format, args) + 1 > log->allocated_size / 2) {
        size_t new_size = log->allocated_size * 2;
        char *new_buffer = realloc(log->buffer, new_size);
        if (!new_buffer) return -1;
        log->buffer = new_buffer;
        log->allocated_size = new_size;
    }

    vsnprintf(log->buffer + log->used_size, log->allocated_size - log->used_size, format, args);
    log->used_size += vsnprintf(NULL, 0, format, args) + 1;

    va_end(args);

    if (log->used_size > log->allocated_size / 2) {
        // Flush to file
        FILE *file = fopen("log.txt", "a");
        if (file) {
            fwrite(log->buffer, 1, log->used_size, file);
            fclose(file);
            log->used_size = 0;
        }
    }

    return 0;
}
