typedef struct Matrix {
    double** data;
    int rows;
    int cols;
} Matrix;

Matrix* create_matrix(int rows, int cols) {
    Matrix* mat = (Matrix*)malloc(sizeof(Matrix));
    mat->rows = rows;
    mat->cols = cols;
    mat->data = (double**)malloc(rows * sizeof(double*));
    for (int i = 0; i < rows; i++) {
        mat->data[i] = (double*)malloc(cols * sizeof(double));
    }
    return mat;
}

void destroy_matrix(Matrix* mat) {
    for (int i = 0; i < mat->rows; i++) {
        free(mat->data[i]);
    }
    free(mat->data);
    free(mat);
}

void init_matrix(Matrix* mat, double (*init_value_func)(int, int)) {
    for (int i = 0; i < mat->rows; i++) {
        for (int j = 0; j < mat->cols; j++) {
            mat->data[i][j] = init_value_func(i, j);
        }
    }
}

double default_init(int row, int col) {
    return row * col;
}

int main() {
    Matrix* my_matrix = create_matrix(3, 4);
    init_matrix(my_matrix, default_init);

    for (int i = 0; i < my_matrix->rows; i++) {
        for (int j = 0; j < my_matrix->cols; j++) {
            printf("%.2f ", my_matrix->data[i][j]);
        }
        printf("\n");
    }

    destroy_matrix(my_matrix);
    return 0;
}
