DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    array->entries = malloc(initial_capacity * sizeof(LogEntry));
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void free_dynamic_array(DynamicArray* array) {
    free(array->entries);
    free(array);
}

int add_log_entry(DynamicArray* array, LogEntry entry) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        array->entries = realloc(array->entries, new_capacity * sizeof(LogEntry));
        array->capacity = new_capacity;
    }
    array->entries[array->size++] = entry;
    return 0;
}

void set_random_log_values(DynamicArray* array, int min_value, int max_value) {
    srand(time(NULL));
    for (size_t i = 0; i < array->size; i++) {
        array->entries[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
