    let lastMetrics = null;

    async function update() {
        const currentMetrics = await fetch_performance_metrics(url, apiKey);
        if (currentMetrics && JSON.stringify(currentMetrics) !== JSON.stringify(lastMetrics)) {
            lastMetrics = currentMetrics;
            // Render the metrics in the canvas
            ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
            ctx.fillText(JSON.stringify(currentMetrics), 10, 20);
        }
        setTimeout(update, interval);
    }

    update();
}

