#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    long* offset;
    int* key;
} Record;

void manage_memory(long N, int min_value, int max_value) {
    // Memory pool for offsets and keys
    long* offsets = (long*)calloc(N * sizeof(long), 1);
    int* keys = (int*)calloc(N * sizeof(int), 1);

    // Memory pool for records
    Record* records = (Record*)malloc(N * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    srand(time(NULL)); // Seed for random number generation

    // Populate the records with random numbers and associated pointers
    for (long i = 0; i < N; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    // Example usage: Accessing and printing some records
    for (long i = 0; i < N; ++i) {
        printf("Record %ld: Value=%d, Offset=%ld, Key=%d\n", i, records[i].value, *records[i].offset, *records[i].key);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long N = 10; // Example size
    int min_value = 1;
    int max_value = 100;

    manage_memory(N, min_value, max_value);

    return 0;
}
