#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000

typedef struct {
    int value;
    long* offset;
    int* key;
} record;

typedef struct {
    record records[MAX_RECORDS];
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    size_t used;
    size_t capacity;
    size_t memory_limit;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity, size_t memory_limit) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->records = malloc(initial_capacity * sizeof(record));
    pool->offsets = malloc(initial_capacity * sizeof(long));
    pool->keys = malloc(initial_capacity * sizeof(int));

    if (pool->records == NULL || pool->offsets == NULL || pool->keys == NULL) {
        free(pool);
        return NULL;
    }

    pool->used = 0;
    pool->capacity = initial_capacity;
    pool->memory_limit = memory_limit;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool == NULL) return;

    free(pool->records);
    free(pool->offsets);
    free(pool->keys);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int allocate_record(MemoryPool* pool, long offset, int key, int value) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used >= pool->capacity || pool->used * sizeof(record) > pool->memory_limit) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Memory allocation failed
    }

    record* rec = &pool->records[pool->used];
    rec->offset = &pool->offsets[pool->used];
    rec->key = &pool->keys[pool->used];
    *rec->offset = offset;
    *rec->key = key;
    rec->value = value;

    pool->used++;
    pthread_mutex_unlock(&pool->lock);
    return 0; // Allocation successful
}

void* populate_records(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;
    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        long offset = rand() % 1000000L;
        int key = rand() % 1000;
        int value = rand() % 100;

        if (allocate_record(pool, offset, key, value) != 0) {
            break; // Stop populating records if allocation fails
        }
    }

    return NULL;
}

int main() {
    MemoryPool* pool = create_memory_pool(100, 1024 * 1024); // Initial capacity of 100 and memory limit of 1MB

    pthread_t thread;
    if (pthread_create(&thread, NULL, populate_records, pool) != 0) {
        destroy_memory_pool(pool);
        return -1; // Thread creation failed
    }

    pthread_join(thread, NULL);

    destroy_memory_pool(pool);
    return 0;
}
