<?php

class AppLogger {
    private $logFile;
    private $maxMemoryUsage = 1024 * 1024; // 1MB limit per log session

    public function __construct($logFile) {
        $this->logFile = $logFile;
        ini_set('memory_limit', '2M'); // Increase PHP memory limit
    }

    public function log(...$args) {
        if (memory_get_usage() > $this->maxMemoryUsage) {
            return false; // Limit reached, ignore the log entry
        }
        $message = date('Y-m-d H:i:s') . ' [' . __FUNCTION__ . '] ';
        foreach ($args as $arg) {
            $message .= $arg . ' ';
        }
        error_log($message, 3, $this->logFile);
    }

    public function shutdown() {
        // Perform any necessary cleanup
        gc_collect_cycles();
    }
}

class AppAuthenticator {
    private $oauthClient;

    public function __construct($clientId, $clientSecret) {
        $this->oauthClient = new OAuth2\Client($clientId, $clientSecret);
    }

    public function authenticateUser($code) {
        try {
            $token = $this->oauthClient->getAccessToken('authorization_code', [
                'code' => $code
            ]);
            $_SESSION['access_token'] = $token['access_token'];
            return true;
        } catch (\Exception $e) {
            error_log('Authentication failed: ' . $e->getMessage());
            return false;
        }
    }

    public function getUserInfo() {
        if (isset($_SESSION['access_token'])) {
            try {
                $user = $this->oauthClient->fetchResource([
                    'url' => 'https://api.example.com/user',
                    'method' => 'GET'
                ], $_SESSION['access_token']);
                return json_decode($user, true);
            } catch (\Exception $e) {
                error_log('Failed to retrieve user info: ' . $e->getMessage());
                return null;
            }
        }
        return null;
    }
}

class BibleBookExtractor {
    private static $bookNames = [
        'Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy',
        'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel',
        // Add more book names as needed
    ];

    public static function extractBooks($text) {
        $books = [];
        foreach (self::$bookNames as $book) {
            preg_match_all('/\b' . preg_quote($book, '/') . '\b/iu', $text, $matches);
            $books[$book] = count($matches[0]);
        }
        return $books;
    }
}

function setupAndLogApp() {
    error_reporting(E_ALL);
    ini_set('display_errors', 1);

    $appLogger = new AppLogger('/var/log/app.log');
    register_shutdown_function([$appLogger, 'shutdown']);

    $authenticator = new AppAuthenticator('client_id', 'client_secret');
    if (!$authenticator->authenticateUser($_GET['code'])) {
        $appLogger->log('Authentication failed for code: ', $_GET['code']);
        return;
    }

    $userInfo = $authenticator->getUserInfo();
    if ($userInfo === null) {
        $appLogger->log('Failed to retrieve user info');
        return;
    }

    $text = "The Old Testament begins with Genesis and ends with Revelation.";
    $books = BibleBookExtractor::extractBooks($text);
    foreach ($books as $book => $count) {
        $appLogger->log("Found $count occurrence(s) of the book '$book'.");
    }
}

setupAndLogApp();
?>
