typedef struct Matrix {
    double **data;
    int rows;
    int cols;
    size_t allocated_size;
} Matrix;

Matrix* create_matrix(int rows, int cols, size_t initial_size) {
    Matrix *matrix = (Matrix*)malloc(sizeof(Matrix));
    matrix->rows = rows;
    matrix->cols = cols;
    matrix->allocated_size = initial_size;

    // Allocate memory for the data array
    matrix->data = (double**)malloc(rows * sizeof(double*));
    for (int i = 0; i < rows; ++i) {
        matrix->data[i] = (double*)malloc(cols * sizeof(double));
    }

    return matrix;
}

void init_matrix(Matrix *matrix, void (*init_value_func)(Matrix*, int, int)) {
    for (int i = 0; i < matrix->rows; ++i) {
        for (int j = 0; j < matrix->cols; ++j) {
            init_value_func(matrix, i, j);
        }
    }
}

void destroy_matrix(Matrix *matrix) {
    for (int i = 0; i < matrix->rows; ++i) {
        free(matrix->data[i]);
    }
    free(matrix->data);
    free(matrix);
}

void resize_matrix(Matrix **matrix, int new_rows, int new_cols) {
    Matrix *new_matrix = create_matrix(new_rows, new_cols, (*matrix)->allocated_size);
    for (int i = 0; i < (*matrix)->rows && i < new_matrix->rows; ++i) {
        for (int j = 0; j < (*matrix)->cols && j < new_matrix->cols; ++j) {
            new_matrix->data[i][j] = (*matrix)->data[i][j];
        }
    }
    destroy_matrix(*matrix);
    *matrix = new_matrix;
}

void elementwise_add(Matrix *result, Matrix *a, Matrix *b) {
    for (int i = 0; i < a->rows && i < b->rows && i < result->rows; ++i) {
        for (int j = 0; j < a->cols && j < b->cols && j < result->cols; ++j) {
            result->data[i][j] = a->data[i][j] + b->data[i][j];
        }
    }
}
