#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 1024
#define SESSION_TIMEOUT 3600 // 1 hour

typedef struct {
    char session_id[32];
    time_t last_activity;
    int auth_level;
} Session;

Session sessions[MAX_SESSIONS];
int next_session_index = 0;
pthread_mutex_t sessions_lock;

void initialize_sessions() {
    pthread_mutex_init(&sessions_lock, NULL);
}

Session* create_session(const char* user_id, int auth_level) {
    Session* new_session = &sessions[next_session_index % MAX_SESSIONS];
    snprintf(new_session->session_id, sizeof(new_session->session_id), "session_%d", next_session_index++);
    new_session->last_activity = time(NULL);
    new_session->auth_level = auth_level;
    return new_session;
}

void update_session(Session* session) {
    pthread_mutex_lock(&sessions_lock);
    if (session) {
        session->last_activity = time(NULL);
    }
    pthread_mutex_unlock(&sessions_lock);
}

int validate_session(const char* session_id, int required_auth_level) {
    pthread_mutex_lock(&sessions_lock);
    for (int i = 0; i < next_session_index; ++i) {
        if (strcmp(sessions[i].session_id, session_id) == 0 && time(NULL) - sessions[i].last_activity < SESSION_TIMEOUT && sessions[i].auth_level >= required_auth_level) {
            pthread_mutex_unlock(&sessions_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&sessions_lock);
    return 0;
}

void expire_sessions() {
    time_t now = time(NULL);
    for (int i = 0; i < next_session_index; ++i) {
        if (now - sessions[i].last_activity > SESSION_TIMEOUT) {
            memset(&sessions[i], 0, sizeof(Session));
        }
    }
}

void* session_manager_thread(void* arg) {
    while (1) {
        expire_sessions();
        sleep(60); // Check every minute
    }
    return NULL;
}

int main() {
    initialize_sessions();
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, session_manager_thread, NULL);

    // Example usage
    Session* user_session = create_session("user123", 2);
    update_session(user_session);
    if (validate_session(user_session->session_id, 2)) {
        printf("Session is valid.\n");
    } else {
        printf("Session is invalid.\n");
    }

    pthread_join(thread_id, NULL);
    return 0;
}
```

