#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct DynamicArray {
    void** data;
    size_t* sizes;
    size_t dim_count;
    size_t allocated_size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t* dims, size_t dim_count) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->sizes = (size_t*)calloc(dim_count + 1, sizeof(size_t));
    array->data = (void**)malloc(dims[0] * sizeof(void*));
    if (!array->data || !array->sizes) {
        free(array);
        return NULL;
    }

    array->dim_count = dim_count;
    array->allocated_size = dims[0];
    for (size_t i = 1; i <= dim_count; ++i) {
        array->sizes[i] = dims[i - 1];
    }
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (!array) return;

    for (size_t i = 0; i < array->allocated_size; ++i) {
        free(array->data[i]);
    }
    free(array->data);
    free(array->sizes);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void* allocate_element(DynamicArray* array, size_t index) {
    if (index >= array->allocated_size) {
        size_t new_size = array->allocated_size * 2;
        void** new_data = (void**)realloc(array->data, new_size * sizeof(void*));
        if (!new_data) return NULL;

        array->data = new_data;
        array->allocated_size = new_size;
    }

    return array->data[index] = malloc(sizeof(int)); // Example allocation
}

void init_array_elements(DynamicArray* array, void (*init_func)(size_t)) {
    for (size_t i = 0; i < array->sizes[array->dim_count]; ++i) {
        pthread_mutex_lock(&array->lock);
        void* element = allocate_element(array, i);
        if (!element) {
            pthread_mutex_unlock(&array->lock);
            break;
        }

        init_func(i);
        pthread_mutex_unlock(&array->lock);
    }
}

void in_place_operation(DynamicArray* array, void (*op)(void*, size_t)) {
    for (size_t i = 0; i < array->sizes[array->dim_count]; ++i) {
        pthread_mutex_lock(&array->lock);
        op(array->data[i], i);
        pthread_mutex_unlock(&array->lock);
    }
}

// Example usage
void init_func(size_t index) {
    int* value = (int*)malloc(sizeof(int));
    *value = (int)index; // Initialize element with its index
}

void operation(void* data, size_t index) {
    int* value = (int*)data;
    *value += 10; // Example in-place operation
}

int main() {
    size_t dims[] = {3};
    DynamicArray* array = create_dynamic_array(dims, sizeof(dims)/sizeof(dims[0]));

    if (array) {
        init_array_elements(array, init_func);

        printf("Initial values:\n");
        for (size_t i = 0; i < array->sizes[array->dim_count]; ++i) {
            int* value = (int*)array->data[i];
            printf("%d ", *value);
        }
        printf("\n");

        in_place_operation(array, operation);

        printf("After operation:\n");
        for (size_t i = 0; i < array->sizes[array->dim_count]; ++i) {
            int* value = (int*)array->data[i];
            printf("%d ", *value);
        }
        printf("\n");

        destroy_dynamic_array(array);
    }

    return 0;
}
