#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct MultiDimArray {
    int dimensions;
    size_t *sizes;
    void **data;
    pthread_mutex_t lock;
} MultiDimArray;

MultiDimArray* create_multi_dim_array(int dimensions, size_t *sizes) {
    MultiDimArray *array = malloc(sizeof(MultiDimArray));
    array->dimensions = dimensions;
    array->sizes = malloc(dimensions * sizeof(size_t));
    array->data = malloc(sizes[0] * sizeof(void *));
    pthread_mutex_init(&array->lock, NULL);

    for (int i = 1; i < dimensions; i++) {
        size_t total_size = sizes[i - 1] * sizes[i];
        void **new_data = realloc(array->data, total_size * sizeof(void *));
        array->data = new_data;
        array->sizes[i] = sizes[i];
    }

    return array;
}

void destroy_multi_dim_array(MultiDimArray *array) {
    for (int i = 0; i < array->dimensions - 1; i++) {
        size_t total_size = array->sizes[i] * array->sizes[i + 1];
        free(array->data);
    }
    free(array->sizes);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void init_multi_dim_array(MultiDimArray *array, void (*init_value_func)(int)) {
    for (size_t i = 0; i < array->sizes[0]; i++) {
        array->data[i] = malloc(sizeof(int));
        *(*(int**)array->data + i) = init_value_func(i);
    }
}

void in_place_operation(MultiDimArray *array, void (*operation)(int, int*), int *result) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->sizes[0]; i++) {
        operation(i, *(int**)array->data + i);
        *result += *(*(int**)array->data + i);
    }
    pthread_mutex_unlock(&array->lock);
}

void log_memory_usage(MultiDimArray *array) {
    size_t total_size = 0;
    for (int i = 0; i < array->dimensions - 1; i++) {
        total_size += array->sizes[i] * array->sizes[i + 1];
    }
    printf("Total Memory Usage: %zu bytes\n", total_size);
}
