#include <stdlib.h>
#include <stdio.h>

typedef struct TreeNode {
    void* data;
    struct TreeNode** children;
    int num_children;
    int max_children;
} TreeNode;

typedef struct Tree {
    TreeNode* root;
    size_t allocated_memory;
    size_t total_allocated;
    size_t node_size;
    size_t max_node_size;
    void (*node_init_func)(void*);
} Tree;

TreeNode* create_node(Tree* tree) {
    if (tree->allocated_memory == 0 || tree->total_allocated >= tree->max_node_size) {
        // Resize memory pool
        TreeNode** new_children = realloc(tree->root->children, tree->num_children * sizeof(TreeNode*) * 2);
        if (!new_children) return NULL;
        tree->root->children = new_children;
        tree->max_node_size *= 2;
    }

    TreeNode* node = (TreeNode*)malloc(tree->node_size);
    if (!node) return NULL;

    // Initialize node using user-defined function
    tree->node_init_func(node);

    tree->total_allocated += tree->node_size;
    tree->allocated_memory -= tree->node_size;

    tree->root->children[tree->num_children++] = node;
    return node;
}

void initialize_tree(Tree* tree, size_t initial_size, void (*node_init_func)(void*)) {
    tree->node_size = sizeof(TreeNode);
    tree->max_node_size = 1024; // Initial capacity for child nodes
    tree->allocated_memory = initial_size * tree->node_size;
    tree->total_allocated = 0;
    tree->root = (TreeNode*)malloc(tree->node_size);
    if (!tree->root) return;

    tree->root->children = (TreeNode**)calloc(tree->max_node_size, sizeof(TreeNode*));
    if (!tree->root->children) {
        free(tree->root);
        return;
    }

    tree->root->num_children = 0;
    tree->node_init_func = node_init_func;
}

void destroy_tree(Tree* tree) {
    for (int i = 0; i < tree->root->num_children; ++i) {
        destroy_tree(tree->root->children[i]);
    }
    free(tree->root->children);
    free(tree->root);
}
