record* processFile(const char* filename, long** offsetArray, int** keyArray, int* uniqueKeyCount) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return NULL;
    }

    // Dynamically allocate memory for arrays and record structure
    *offsetArray = (long*)malloc(sizeof(long));
    *keyArray = (int*)malloc(sizeof(int));
    record* records = (record*)malloc(sizeof(record));

    if (!(*offsetArray) || !(*keyArray) || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return NULL;
    }

    // Read file and populate arrays
    while (fscanf(file, "%ld %d", offsetArray, keyArray) != EOF) {
        // Resize arrays as needed
        *offsetArray = realloc(*offsetArray, (*uniqueKeyCount + 1) * sizeof(long));
        *keyArray = realloc(*keyArray, (*uniqueKeyCount + 1) * sizeof(int));
        if (!*offsetArray || !*keyArray) {
            fprintf(stderr, "Memory reallocation failed\n");
            free(records);
            fclose(file);
            return NULL;
        }

        // Add new key and offset
        (*keyArray)[*uniqueKeyCount] = **keyArray;
        (*offsetArray)[*uniqueKeyCount] = **offsetArray;
        (*uniqueKeyCount)++;
    }

    fclose(file);

    // Initialize record values with random numbers
    srand(time(NULL));
    for (int i = 0; i < *uniqueKeyCount; i++) {
        records[i].value = rand() % 1000 + 1; // Random number between 1 and 1000
    }

    return records;
}

// Example usage
int main() {
    long* offsets = NULL;
    int* keys = NULL;
    int uniqueKeys = 0;

    record* records = processFile("input.txt", &offsets, &keys, &uniqueKeys);

    if (records) {
        // Use the records array...
        free(records);
    }

    if (offsets) {
        free(offsets);
    }

    if (keys) {
        free(keys);
    }

    return 0;
}
