typedef struct {
    int *data;
    size_t capacity;
    size_t size;
} key_record;

typedef struct {
    int *data;
    size_t size;
    pthread_mutex_t mutex;
} record;

offset_record* create_offset_record(size_t max_offsets) {
    if (max_offsets == 0 || max_offsets < 0) return NULL;

    offset_record *rec = malloc(sizeof(offset_record));
    if (!rec) return NULL;

    rec->data = calloc(max_offsets, sizeof(long));
    if (!rec->data) {
        free(rec);
        return NULL;
    }

    rec->capacity = max_offsets;
    rec->size = 0;

    return rec;
}

key_record* create_key_record(size_t max_keys) {
    if (max_keys == 0 || max_keys < 0) return NULL;

    key_record *rec = malloc(sizeof(key_record));
    if (!rec) return NULL;

    rec->data = calloc(max_keys, sizeof(int));
    if (!rec->data) {
        free(rec);
        return NULL;
    }

    rec->capacity = max_keys;
    rec->size = 0;

    return rec;
}

record* create_record(size_t size) {
    record *rec = malloc(sizeof(record));
    if (!rec) return NULL;

    rec->data = calloc(size, sizeof(int));
    if (!rec->data) {
        free(rec);
        return NULL;
    }

    rec->size = size;
    pthread_mutex_init(&rec->mutex, NULL);

    // Initialize with random numbers
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        rec->data[i] = rand() % (MAX_RANDOM_VALUE + 1);
    }

    return rec;
}

void destroy_offset_record(offset_record *rec) {
    if (!rec) return;
    free(rec->data);
    free(rec);
}

void destroy_key_record(key_record *rec) {
    if (!rec) return;
    free(rec->data);
    free(rec);
}

void destroy_record(record *rec) {
    if (!rec) return;
    pthread_mutex_destroy(&rec->mutex);
    free(rec->data);
    free(rec);
}
