typedef struct record {
    int value;
    char *buffer;
} Record;

int hash_function(int key, int table_size) {
    return key % table_size;
}

void insert_record(Record **hash_table, int key, int value, int buffer_size, int table_size) {
    int index = hash_function(key, table_size);
    while (hash_table[index] != NULL && hash_table[index]->value != -1) {
        if (hash_table[index]->key == key) {
            // Update existing record
            free(hash_table[index]->buffer);
            hash_table[index]->value = value;
            hash_table[index]->buffer = (char *)malloc(buffer_size * sizeof(char));
            // Populate buffer with random string
            for (int i = 0; i < buffer_size - 1; i++) {
                hash_table[index]->buffer[i] = 'a' + rand() % 26;
            }
            hash_table[index]->buffer[buffer_size - 1] = '\0';
            return;
        }
        index = (index + 1) % table_size;
    }

    // Insert new record
    hash_table[index] = (Record *)malloc(sizeof(Record));
    hash_table[index]->key = key;
    hash_table[index]->value = value;
    hash_table[index]->buffer = (char *)malloc(buffer_size * sizeof(char));
    for (int i = 0; i < buffer_size - 1; i++) {
        hash_table[index]->buffer[i] = 'a' + rand() % 26;
    }
    hash_table[index]->buffer[buffer_size - 1] = '\0';
}

Record *search_record(Record **hash_table, int key, int table_size) {
    int index = hash_function(key, table_size);
    while (hash_table[index] != NULL) {
        if (hash_table[index]->key == key && hash_table[index]->value != -1) {
            return hash_table[index];
        }
        index = (index + 1) % table_size;
    }
    return NULL;
}

void delete_record(Record **hash_table, int key, int table_size) {
    int index = hash_function(key, table_size);
    while (hash_table[index] != NULL) {
        if (hash_table[index]->key == key && hash_table[index]->value != -1) {
            free(hash_table[index]->buffer);
            hash_table[index]->value = -1;
            return;
        }
        index = (index + 1) % table_size;
    }
}

void clean_up(Record **hash_table, int array_size, int table_size) {
    for (int i = 0; i < array_size; i++) {
        free(hash_table[i]->buffer);
        free(hash_table[i]);
    }
    free(hash_table);
}

Record **init_arrays(int long_array_size, int int_array_size, int record_buffer_size, int hash_table_size) {
    srand(time(NULL));

    Record **hash_table = (Record **)calloc(hash_table_size, sizeof(Record *));
    for (int i = 0; i < hash_table_size; i++) {
        hash_table[i] = NULL;
    }

    long *long_array = (long *)malloc(long_array_size * sizeof(long));
    int *int_array = (int *)malloc(int_array_size * sizeof(int));

    Record *record_array = (Record *)malloc(record_buffer_size * sizeof(Record));

    for (int i = 0; i < record_buffer_size; i++) {
        insert_record(hash_table, rand() % hash_table_size, rand() % 100, record_buffer_size, hash_table_size);
    }

    free(long_array);
    free(int_array);
    return hash_table;
}
