#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1024

typedef struct {
    long value;
} offset_record;

typedef struct {
    int key;
} key_record;

typedef struct {
    int id;
    time_t age;
    int *data;
    size_t data_size;
    int weighted_sum;
} record;

typedef struct {
    record **records;
    size_t count;
    pthread_mutex_t lock;
} transaction_set;

void initialize_transaction_set(transaction_set *set, size_t initial_capacity) {
    set->records = (record **)malloc(initial_capacity * sizeof(record *));
    if (!set->records) {
        fprintf(stderr, "Failed to allocate memory for transaction records\n");
        exit(EXIT_FAILURE);
    }
    set->count = 0;
    pthread_mutex_init(&set->lock, NULL);
}

void destroy_transaction_set(transaction_set *set) {
    for (size_t i = 0; i < set->count; ++i) {
        free(set->records[i]->data);
        free(set->records[i]);
    }
    free(set->records);
    pthread_mutex_destroy(&set->lock);
}

record *create_record(int id, size_t data_size, int min_value, int max_value) {
    record *new_record = (record *)malloc(sizeof(record));
    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        exit(EXIT_FAILURE);
    }
    new_record->id = id;
    new_record->age = time(NULL);
    new_record->data_size = data_size;
    new_record->data = (int *)malloc(data_size * sizeof(int));
    if (!new_record->data) {
        fprintf(stderr, "Failed to allocate memory for record data\n");
        free(new_record);
        exit(EXIT_FAILURE);
    }
    srand(time(NULL) ^ id); // Seed for random number generation
    for (size_t i = 0; i < data_size; ++i) {
        new_record->data[i] = min_value + rand() % (max_value - min_value + 1);
    }
    new_record->weighted_sum = 0;
    return new_record;
}

void add_record(transaction_set *set, record *record) {
    pthread_mutex_lock(&set->lock);
    if (set->count >= MAX_RECORDS) {
        fprintf(stderr, "Transaction set is full\n");
        exit(EXIT_FAILURE);
    }
    set->records[set->count++] = record;
    pthread_mutex_unlock(&set->lock);
}

int filter_transactions(transaction_set *set, int min_age, int max_past_3_seconds) {
    pthread_mutex_lock(&set->lock);
    int max_weighted_sum = INT_MIN;
    for (size_t i = 0; i < set->count; ++i) {
        if (time(NULL) - set->records[i]->age > min_age &&
            time(NULL) - set->records[i]->age <= min_age + max_past_3_seconds) {
            int current_sum = 0;
            for (size_t j = 0; j < set->records[i]->data_size; ++j) {
                current_sum += set->records[i]->data[j];
            }
            if (current_sum > max_weighted_sum) {
                max_weighted_sum = current_sum;
            }
        }
    }
    pthread_mutex_unlock(&set->lock);
    return max_weighted_sum;
}

int main() {
    // Example usage
    transaction_set set;
    initialize_transaction_set(&set, 10);

    record *record1 = create_record(1, 10, 0, 100);
    record *record2 = create_record(2, 15, 10, 200);

    add_record(&set, record1);
    add_record(&set, record2);

    int max_weighted_sum = filter_transactions(&set, 0, 5);
    printf("Max weighted sum: %d\n", max_weighted_sum);

    destroy_transaction_set(&set);

    return 0;
}
