#define INITIAL_CAPACITY 16
#define MAX_STRING_LENGTH 256

typedef struct Record {
    int key;
    char value[MAX_STRING_LENGTH];
} Record;

typedef struct HashTableNode {
    Record record;
    struct HashTableNode* next;
} HashTableNode;

typedef struct HashTable {
    HashTableNode** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

unsigned long hash_function(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

HashTable* create_hash_table() {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }
    table->buckets = calloc(INITIAL_CAPACITY, sizeof(HashTableNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void insert_record(HashTable* table, int key, const char* value) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key, table->capacity);
    HashTableNode* new_node = malloc(sizeof(HashTableNode));
    if (!new_node) {
        pthread_mutex_unlock(&table->mutex);
        return;
    }
    new_node->record.key = key;
    strncpy(new_node->record.value, value, MAX_STRING_LENGTH - 1);
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->size++;
    pthread_mutex_unlock(&table->mutex);
}

Record* lookup_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key, table->capacity);
    HashTableNode* node = table->buckets[index];
    while (node) {
        if (node->record.key == key) {
            pthread_mutex_unlock(&table->mutex);
            return &node->record;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

void delete_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key, table->capacity);
    HashTableNode* current = table->buckets[index];
    HashTableNode* previous = NULL;
    while (current) {
        if (current->record.key == key) {
            if (previous) {
                previous->next = current->next;
            } else {
                table->buckets[index] = current->next;
            }
            free(current);
            table->size--;
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&table->mutex);
}

void resize_hash_table(HashTable* table) {
    // Implement resizing logic here
}

void iterate_records_by_integer_value(HashTable* table) {
    pthread_mutex_lock(&table->mutex);
    // Implement iteration by integer value logic here
    pthread_mutex_unlock(&table->mutex);
}

void iterate_records_lexicographically(HashTable* table) {
    pthread_mutex_lock(&table->mutex);
    // Implement lexicographical iteration logic here
    pthread_mutex_unlock(&table->mutex);
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; i++) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            HashTableNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&table->mutex);
    free(table->buckets);
    free(table);
}
