#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    long value;
} offset_record;

typedef struct {
    int value;
} key_record;

typedef struct {
    int value;
} record;

struct transaction {
    int id;
    time_t timestamp;
    int weighted_sum;
};

struct metrics {
    int max_weighted_sum_id;
    int max_weighted_sum;
};

struct data_manager {
    offset_record *offsets;
    key_record *keys;
    record *records;
    struct transaction transactions[MAX_RECORDS];
    struct metrics metrics;
    pthread_mutex_t lock;
    int offset_count;
    int key_count;
    int record_count;
    time_t last_log_time;
};

void init_data_manager(struct data_manager *dm, int max_offsets, int max_keys, int min_value, int max_value) {
    dm->offsets = (offset_record *)malloc(max_offsets * sizeof(offset_record));
    dm->keys = (key_record *)malloc(max_keys * sizeof(key_record));
    dm->records = (record *)malloc(MAX_RECORDS * sizeof(record));
    pthread_mutex_init(&dm->lock, NULL);
    for (int i = 0; i < MAX_RECORDS; i++) {
        dm->records[i].value = min_value + rand() % (max_value - min_value + 1);
    }
}

void free_data_manager(struct data_manager *dm) {
    free(dm->offsets);
    free(dm->keys);
    pthread_mutex_destroy(&dm->lock);
}

void purge_old_records(struct data_manager *dm, time_t age_threshold) {
    time_t current_time = time(NULL);
    for (int i = 0; i < dm->key_count; i++) {
        if (current_time - dm->keys[i].timestamp > age_threshold) {
            memmove(&dm->keys[i], &dm->keys[i + 1], --dm->key_count * sizeof(key_record));
            i--;
        }
    }
}

void log_event(const char *message) {
    time_t now = time(NULL);
    if (now - dm->last_log_time > 3600) { // Log every hour
        dm->last_log_time = now;
        FILE *log_file = fopen("data_manager.log", "a");
        fprintf(log_file, "[%s] %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

int filter_transactions(struct data_manager *dm) {
    pthread_mutex_lock(&dm->lock);
    int max_weighted_sum = 0;
    int max_weighted_sum_id = -1;
    for (int i = 0; i < dm->record_count; i++) {
        time_t now = time(NULL);
        struct transaction *t = &dm->transactions[i];
        t->weighted_sum = dm->records[i].value + dm->offsets[t->id % dm->offset_count].value;
        if (now - t->timestamp > 3) {
            memmove(&dm->transactions[i], &dm->transactions[i + 1], --dm->record_count * sizeof(struct transaction));
            i--;
        } else {
            if (t->weighted_sum > max_weighted_sum) {
                max_weighted_sum = t->weighted_sum;
                max_weighted_sum_id = t->id;
            }
        }
    }
    dm->metrics.max_weighted_sum_id = max_weighted_sum_id;
    dm->metrics.max_weighted_sum = max_weighted_sum;
    pthread_mutex_unlock(&dm->lock);
    return max_weighted_sum_id;
}

int main() {
    struct data_manager dm;
    init_data_manager(&dm, 100, 50, -100, 100);
    log_event("Data manager initialized");
    filter_transactions(&dm);
    free_data_manager(&dm);
    return 0;
}
```

This code snippet provides a basic structure for a `data_manager` that handles memory allocation, transaction filtering, and logging. It includes functions to initialize, free, purge old records, log events, and filter transactions based on specified criteria. The code uses mutex locks to ensure thread safety during concurrent access.']

