#define DEFAULT_OFFSETS 1024
#define DEFAULT_KEYS 1024

typedef struct {
    long* offsets;
    int offsets_size;
    int offsets_capacity;
    pthread_mutex_t offset_lock;
} OffsetManager;

typedef struct {
    int* keys;
    int keys_size;
    int keys_capacity;
    pthread_mutex_t key_lock;
} KeyManager;

typedef struct {
    int value;
} Record;

OffsetManager* create_offset_manager(int max_offsets) {
    if (max_offsets <= 0) max_offsets = DEFAULT_OFFSETS;
    OffsetManager* manager = malloc(sizeof(OffsetManager));
    if (!manager) return NULL;

    manager->offsets = malloc(max_offsets * sizeof(long));
    if (!manager->offsets) {
        free(manager);
        return NULL;
    }
    manager->offsets_size = 0;
    manager->offsets_capacity = max_offsets;
    pthread_mutex_init(&manager->offset_lock, NULL);

    return manager;
}

KeyManager* create_key_manager(int max_keys) {
    if (max_keys <= 0) max_keys = DEFAULT_KEYS;
    KeyManager* manager = malloc(sizeof(KeyManager));
    if (!manager) return NULL;

    manager->keys = malloc(max_keys * sizeof(int));
    if (!manager->keys) {
        free(manager);
        return NULL;
    }
    manager->keys_size = 0;
    manager->keys_capacity = max_keys;
    pthread_mutex_init(&manager->key_lock, NULL);

    return manager;
}

void destroy_offset_manager(OffsetManager* manager) {
    if (!manager) return;
    pthread_mutex_destroy(&manager->offset_lock);
    free(manager->offsets);
    free(manager);
}

void destroy_key_manager(KeyManager* manager) {
    if (!manager) return;
    pthread_mutex_destroy(&manager->key_lock);
    free(manager->keys);
    free(manager);
}

int add_offset(OffsetManager* manager, long offset) {
    pthread_mutex_lock(&manager->offset_lock);

    if (manager->offsets_size >= manager->offsets_capacity) {
        int new_capacity = manager->offsets_capacity * 2;
        long* new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
        if (!new_offsets) {
            pthread_mutex_unlock(&manager->offset_lock);
            return -1;
        }
        manager->offsets = new_offsets;
        manager->offsets_capacity = new_capacity;
    }

    manager->offsets[manager->offsets_size++] = offset;

    pthread_mutex_unlock(&manager->offset_lock);
    return 0;
}

int add_key(KeyManager* manager, int key) {
    pthread_mutex_lock(&manager->key_lock);

    if (manager->keys_size >= manager->keys_capacity) {
        int new_capacity = manager->keys_capacity * 2;
        int* new_keys = realloc(manager->keys, new_capacity * sizeof(int));
        if (!new_keys) {
            pthread_mutex_unlock(&manager->key_lock);
            return -1;
        }
        manager->keys = new_keys;
        manager->keys_capacity = new_capacity;
    }

    manager->keys[manager->keys_size++] = key;

    pthread_mutex_unlock(&manager->key_lock);
    return 0;
}

Record* create_records(int count, int min_value, int max_value) {
    Record* records = malloc(count * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

void free_records(Record* records, int count) {
    if (!records) return;
    free(records);
}
