    xmlNodePtr node = root_element->children;
    while (node != NULL) {
        if (strcmp((const char*)node->name, element_name) == 0) {
            xmlFreeDoc(doc);
            return node;
        }
        node = node->next;
    }
    xmlFreeDoc(doc);
    fprintf(stderr, "Element not found\n");
