#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    float humidity;
    time_t timestamp;
} Record;

// Function prototype for adding calibration parameters
void addCalibrationParameters(float *params, int count);

// Function prototype for validating calibration parameters
int validateCalibrationParameters(float *params, int count, float maxAdjustment);

// Function prototype for applying calibration to temperature readings
float applyCalibration(float temperature, float calibrationParam);

// Function prototype for checking sensor data quality
void checkDataQuality(Record *records, int count);

// Function prototype for dynamic reconfiguration
void updateCalibrationParameters(float *newParams, int count);

// Main function to process sensor logs
Record* processSensorLogs(int numFiles, const char **fileNames) {
    // Dynamically allocate memory for arrays
    double *temperatures = (double *)malloc(numFiles * sizeof(double));
    char *sensorIds = (char *)malloc(numFiles * sizeof(char));
    Record *records = (Record *)malloc(numFiles * sizeof(Record));
    float *calibrationParams = (float *)malloc(numFiles * sizeof(float));

    if (!temperatures || !sensorIds || !records || !calibrationParams) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize pthreads for concurrency
    pthread_t threads[200];
    int threadCount = 0;

    for (int i = 0; i < numFiles; ++i) {
        FILE *file = fopen(fileNames[i], "r");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        // Read data from the file
        fscanf(file, "%lf %c", &temperatures[i], &sensorIds[i]);

        // Validate sensor ID and temperature reading
        if (strlen(sensorIds[i]) != 1 || temperatures[i] < -50.0 || temperatures[i] > 50.0) {
            fprintf(stderr, "Invalid data in file %s\n", fileNames[i]);
            fclose(file);
            continue;
        }

        // Generate random humidity level and ensure no two consecutive records have the same value
        static float lastHumidity = -1.0;
        while (1) {
            records[i].humidity = 45.0 + rand() % 21; // Random between 45% and 65%
            if (lastHumidity == -1 || records[i].humidity != lastHumidity)
                break;
        }
        records[i].timestamp = time(NULL);
        lastHumidity = records[i].humidity;

        // Apply calibration to temperature readings
        if (!validateCalibrationParameters(&calibrationParams[i], 1, 2.0)) {
            fprintf(stderr, "Invalid calibration parameter in file %s\n", fileNames[i]);
            fclose(file);
            continue;
        }
        temperatures[i] = applyCalibration(temperatures[i], calibrationParams[i]);

        // Start a thread for data quality check
        if (pthread_create(&threads[threadCount++], NULL, (void *(*)(void *))checkDataQuality, &records[i]) != 0) {
            perror("Failed to create thread");
        }

        fclose(file);
    }

    // Wait for all threads to finish
    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up dynamically allocated memory
    free(temperatures);
    free(sensorIds);
    free(calibrationParams);

    return records;
}
