#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    int *key_ref;
} record;

typedef struct bucket_node {
    record *rec;
    struct bucket_node *next;
} bucket_node;

typedef struct {
    bucket_node **buckets;
    size_t size;
    size_t count;
    double load_factor_threshold;
    pthread_mutex_t lock;
} hash_table;

hash_table* create_hash_table(size_t initial_size, double load_factor_threshold);
void destroy_hash_table(hash_table *ht);
record* insert_record(hash_table *ht, int key, long offset);
record* find_record_by_key(hash_table *ht, int key);
int remove_record_by_key(hash_table *ht, int key);
void iterate_records(hash_table *ht, void (*callback)(record*));

hash_table* create_hash_table(size_t initial_size, double load_factor_threshold) {
    hash_table *ht = (hash_table*)malloc(sizeof(hash_table));
    ht->buckets = (bucket_node**)calloc(initial_size, sizeof(bucket_node*));
    ht->size = initial_size;
    ht->count = 0;
    ht->load_factor_threshold = load_factor_threshold;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(hash_table *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        bucket_node *node = ht->buckets[i];
        while (node != NULL) {
            bucket_node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

record* insert_record(hash_table *ht, int key, long offset) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key) % ht->size;
    bucket_node *node = ht->buckets[index];
    while (node != NULL) {
        if (*(node->rec->key_ref) == key) {
            pthread_mutex_unlock(&ht->lock);
            return node->rec;
        }
        node = node->next;
    }
    record *new_rec = (record*)malloc(sizeof(record));
    new_rec->value = offset;
    new_rec->key_ref = &key;
    bucket_node *new_node = (bucket_node*)malloc(sizeof(bucket_node));
    new_node->rec = new_rec;
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;
    ht->count++;
    double load_factor = (double)ht->count / ht->size;
    if (load_factor > ht->load_factor_threshold) {
        resize_hash_table(ht);
    }
    pthread_mutex_unlock(&ht->lock);
    return new_rec;
}

record* find_record_by_key(hash_table *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key) % ht->size;
    bucket_node *node = ht->buckets[index];
    while (node != NULL) {
        if (*(node->rec->key_ref) == key) {
            record *found_rec = node->rec;
            pthread_mutex_unlock(&ht->lock);
            return found_rec;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

int remove_record_by_key(hash_table *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key) % ht->size;
    bucket_node **node_ptr = &ht->buckets[index];
    while (*node_ptr != NULL) {
        if (*((*node_ptr)->rec->key_ref) == key) {
            bucket_node *temp = *node_ptr;
            *node_ptr = (*node_ptr)->next;
            free(temp);
            ht->count--;
            pthread_mutex_unlock(&ht->lock);
            return 1;
        }
        node_ptr = &((*node_ptr)->next);
    }
    pthread_mutex_unlock(&ht->lock);
    return 0;
}

void iterate_records(hash_table *ht, void (*callback)(record*)) {
    pthread_mutex_lock(&ht->lock);
    for (size_t i = 0; i < ht->size; ++i) {
        bucket_node *node = ht->buckets[i];
        while (node != NULL) {
            callback(node->rec);
            node = node->next;
        }
    }
    pthread_mutex_unlock(&ht->lock);
}

void resize_hash_table(hash_table *ht) {
    size_t new_size = ht->size * 2;
    bucket_node **new_buckets = (bucket_node**)calloc(new_size, sizeof(bucket_node*));
    for (size_t i = 0; i < ht->size; ++i) {
        bucket_node *node = ht->buckets[i];
        while (node != NULL) {
            size_t new_index = hash_function(*(node->rec->key_ref)) % new_size;
            bucket_node *next = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next;
        }
    }
    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->size = new_size;
}
