#include <stdlib.h>
#include <string.h>
#include <pthread.h>

struct cache_node {
    char *key;
    int node_id;
    double last_access_time;
};

struct shared_state {
    struct cache_node **nodes;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

void initialize_cache(struct shared_state *state, size_t max_nodes) {
    if (max_nodes <= 0) {
        max_nodes = 10; // Default value
    }
    state->capacity = max_nodes;
    state->size = 0;
    state->nodes = (struct cache_node **)malloc(max_nodes * sizeof(struct cache_node *));
    pthread_mutex_init(&state->lock, NULL);
}

void evict_lru_node(struct shared_state *state) {
    if (state->size == 0) return;

    int lru_index = 0;
    double lru_time = state->nodes[0]->last_access_time;

    for (size_t i = 1; i < state->size; ++i) {
        if (state->nodes[i]->last_access_time < lru_time) {
            lru_index = i;
            lru_time = state->nodes[i]->last_access_time;
        }
    }

    free(state->nodes[lru_index]->key);
    free(state->nodes[lru_index]);
    for (size_t i = lru_index; i < state->size - 1; ++i) {
        state->nodes[i] = state->nodes[i + 1];
    }
    state->size--;
}

void resize_cache(struct shared_state *state, size_t new_capacity) {
    if (new_capacity <= state->capacity) return;

    struct cache_node **new_nodes = (struct cache_node **)realloc(state->nodes, new_capacity * sizeof(struct cache_node *));
    if (!new_nodes) {
        // Handle allocation failure
        return;
    }
    state->nodes = new_nodes;
    state->capacity = new_capacity;
}

void add_cache_node(struct shared_state *state, char *key, int node_id) {
    pthread_mutex_lock(&state->lock);
    if (state->size == state->capacity) {
        resize_cache(state, state->capacity * 2); // Double the capacity on resize
    }
    struct cache_node *new_node = (struct cache_node *)malloc(sizeof(struct cache_node));
    new_node->key = strdup(key);
    new_node->node_id = node_id;
    new_node->last_access_time = 0.0; // Initialize last access time
    state->nodes[state->size++] = new_node;
    pthread_mutex_unlock(&state->lock);
}

void free_cache(struct shared_state *state) {
    for (size_t i = 0; i < state->size; ++i) {
        free(state->nodes[i]->key);
        free(state->nodes[i]);
    }
    free(state->nodes);
    pthread_mutex_destroy(&state->lock);
}
```

This code provides a basic implementation of the cache management function with thread safety and LRU eviction policy. Additional features such as serialization, configuration management, and concurrent access optimization can be added based on specific requirements.']

