record* create_records(int N, long* offsets, int* keys, double* weights, unsigned char* flags, char* statuses) {
    record* records = (record*)malloc(N * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < N; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].weight = offsets[i];
        records[i].status = statuses[i];
        records[i].buffer = (unsigned char*)malloc(1);
        if (!records[i].buffer) {
            for (int j = 0; j < i; j++) free(records[j].buffer);
            free(records);
            return NULL;
        }
        *records[i].buffer = flags[i];
        records[i].value_ptr = (double*)malloc(sizeof(double));
        if (!records[i].value_ptr) {
            for (int j = 0; j <= i; j++) {
                free(records[j].buffer);
                free(records[j].value_ptr);
