    for (i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % num_records * 10 + 1; // Generate a random number
        } while (used_keys[key / 10] & (1 << (key % 10))); // Ensure uniqueness
        keys[i] = key;
        used_keys[key / 10] |= 1 << (key % 10);
    }
    free(used_keys);

    // Allocate memory for records array
    records = malloc(num_records * sizeof(record));
