    for (i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Free all allocated memory
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
