long* allocate_offsets(int size) {
    if (size <= 0 || size > INT_MAX / sizeof(long)) {
        return NULL; // Handle invalid input and potential overflow
    }
    return (long*)calloc(size, sizeof(long));
}

int* allocate_keys(int size, int min_key, int max_key) {
    if (size <= 0 || size > INT_MAX / sizeof(int)) {
        return NULL; // Handle invalid input and potential overflow
    }
    int* keys = (int*)calloc(size, sizeof(int));
    if (!keys) {
        return NULL;
    }
    srand(time(NULL)); // Seed for random number generation
    int count = 0;
    while (count < size) {
        int key = min_key + rand() % (max_key - min_key + 1);
        int i;
        for (i = 0; i < count; ++i) {
            if (keys[i] == key) {
                break; // Duplicate found, generate a new one
            }
        }
        if (i == count) { // Unique key found
            keys[count++] = key;
        }
    }
    return keys;
}

record* allocate_records(int size) {
    if (size <= 0 || size > INT_MAX / sizeof(record)) {
        return NULL; // Handle invalid input and potential overflow
    }
    record* records = (record*)calloc(size, sizeof(record));
    if (!records) {
        return NULL;
    }
    return records;
}

void generate_keys(record* records, int size, int min_key, int max_key) {
    for (int i = 0; i < size; ++i) {
        int key = min_key + rand() % (max_key - min_key + 1);
        while (i > 0 && records[i-1].key >= key) { // Ensure uniqueness
            key = min_key + rand() % (max_key - min_key + 1);
        }
        records[i].key = key;
    }
}

void sort_records(record* records, int size) {
    qsort(records, size, sizeof(record), (int (*)(const void*, const void*))compare_offsets);
}

long find_offset_by_key(record* records, int size, int key) {
    for (int i = 0; i < size; ++i) {
        if (records[i].key == key) {
            return records[i].offset;
        }
    }
    return -1L; // Return special value indicating absence of key
}

void add_record(record** records, int* size, int active_size, long offset, int key) {
    if (*size <= active_size) { // Resize array if needed
        *records = realloc(*records, (*size + 1) * sizeof(record));
        if (!*records) {
            return; // Handle memory allocation failure
        }
        ++(*size);
    }
    (*records)[active_size].offset = offset;
    (*records)[active_size].key = key;
}

int compare_offsets(const void* a, const void* b) {
    return ((record*)a)->offset - ((record*)b)->offset;
}
