    for (size_t i = 0; i < size; ++i) {
        array[i] = (double*)malloc(sizeof(double));
    }
    return array;
}

char*** allocate_char_array(size_t size, size_t max_str_len) {
    char*** array = (char***)malloc(size * sizeof(char**));
    for (size_t i = 0; i < size; ++i) {
        array[i] = (char**)malloc(max_str_len * sizeof(char*));
        for (size_t j = 0; j < max_str_len; ++j) {
            array[i][j] = (char*)malloc((max_str_len + 1) * sizeof(char));
        }
    }
    return array;
}

data_point** allocate_data_point_array(size_t initial_size, size_t* current_size, size_t max_str_len) {
    data_point** array = (data_point**)malloc(initial_size * sizeof(data_point*));
    for (size_t i = 0; i < initial_size; ++i) {
        array[i] = (data_point*)malloc(sizeof(data_point));
        array[i]->str = (char*)malloc((max_str_len + 1) * sizeof(char));
    }
    *current_size = initial_size;
    return array;
}

void resize_data_point_array(data_point*** array, size_t* current_size, size_t new_size, size_t max_str_len) {
    data_point** temp = (data_point**)realloc(*array, new_size * sizeof(data_point*));
    if (temp == NULL) {
        // Handle memory allocation failure
        return;
    }
    *array = temp;
    for (size_t i = *current_size; i < new_size; ++i) {
        (*array)[i] = (data_point*)malloc(sizeof(data_point));
        (*array)[i]->str = (char*)malloc((max_str_len + 1) * sizeof(char));
    }
    *current_size = new_size;
}

void free_all_memory(double** double_array, char*** char_array, data_point** data_point_array, size_t size, size_t max_str_len) {
    for (size_t i = 0; i < size; ++i) {
        free(double_array[i]);
        for (size_t j = 0; j < max_str_len; ++j) {
            free(char_array[i][j]);
        }
        free(char_array[i]);
        free(data_point_array[i]->str);
        free(data_point_array[i]);
    }
    free(double_array);
    free(char_array);
    free(data_point_array);
}

// Example usage
int main() {
    size_t initial_size = 10;
    size_t max_str_len = 256;
    size_t current_size;

    double** double_arr = allocate_double_array(initial_size);
    char*** char_arr = allocate_char_array(initial_size, max_str_len);
    data_point** data_point_arr = allocate_data_point_array(initial_size, &current_size, max_str_len);

    // Use the arrays...

    resize_data_point_array(&data_point_arr, &current_size, 20, max_str_len);

    // Free all allocated memory
    free_all_memory(double_arr, char_arr, data_point_arr, current_size, max_str_len);

    return 0;
}
