        mat->data[i] = (double*)malloc(cols * sizeof(double));
        if (!mat->data[i]) {
            perror("Failed to allocate memory for matrix row.");
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(mat->data[j]);
            }
            free(mat->data);
            free(mat);
            return NULL;
        }
    }

    // Initialize matrix elements using the user-defined function
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            mat->data[row][col] = init_value_func(row, col);
        }
    }

    return mat;
}

void free_matrix(Matrix* mat) {
    if (!mat) {
        return;
    }

    for (int i = 0; i < mat->rows; ++i) {
        free(mat->data[i]);
    }
    free(mat->data);
    free(mat);
}

// Additional functions like element-wise addition, dynamic resizing,
// logging, and profiling can be added here.
