record* create_records(int N, int M, int min_value, int max_value) {
    record* records = (record*)malloc(N * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < N; ++i) {
        records[i].id = rand() % (max_value - min_value + 1) + min_value;
        records[i].weight = rand();
        records[i].status = 'A' + rand() % 26;
        records[i].buffer = (unsigned char*)malloc(M * sizeof(unsigned char));
        if (!records[i].buffer) {
            for (int j = 0; j < i; ++j) free(records[j].buffer);
            free(records);
            return NULL;
        }
        memset(records[i].buffer, '0', M);
        records[i].value = (double*)malloc(sizeof(double));
        if (!records[i].value) {
            for (int j = 0; j <= i; ++j) {
                free(records[j].buffer);
                free(records[j].value);
            }
            free(records);
            return NULL;
        }
        *records[i].value = ((double)rand() / RAND_MAX) * 100.0;
    }

    return records;
}

void destroy_records(record* records, int N, int M) {
    for (int i = 0; i < N; ++i) {
        free(records[i].buffer);
        free(records[i].value);
    }
    free(records);
}

// Additional memory management and synchronization code here...

int main() {
    srand(time(NULL));
    int N = 10, M = 20;
    record* records = create_records(N, M, 10, 50);
    if (records) {
        // Process records...
        destroy_records(records, N, M);
    }
    return 0;
}
