typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicCollection;

DynamicCollection* create_collection(size_t initial_capacity) {
    DynamicCollection *collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_collection(DynamicCollection *collection) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; ++i) {
        // Free any dynamically allocated memory within records if necessary
    }
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void add_record(DynamicCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return; // Handle memory allocation failure
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    collection->records[collection->size].key = key;
    collection->records[collection->size].offset = offset;
    ++collection->size;
    pthread_mutex_unlock(&collection->mutex);
}

Record* get_record(const DynamicCollection *collection, size_t index) {
    if (index >= collection->size) return NULL;
    return &collection->records[index];
}

size_t get_collection_size(const DynamicCollection *collection) {
    return collection->size;
}
```

