#define MAX_PACKETS 1000

typedef struct {
    uint32_t id;
    time_t timestamp;
    uint8_t flags;
    uint8_t* payload;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    size_t count;
    pthread_mutex_t lock;
} PacketManager;

PacketManager packet_manager;

void init_packet_manager() {
    pthread_mutex_init(&packet_manager.lock, NULL);
    packet_manager.count = 0;
}

Packet* allocate_packet(size_t payload_size) {
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        return NULL;
    }
    packet->id = generate_unique_id();
    packet->timestamp = time(NULL);
    packet->flags = 0;
    packet->payload = (uint8_t*)malloc(payload_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }
    return packet;
}

void free_packet(Packet* packet) {
    free(packet->payload);
    free(packet);
}

uint32_t generate_unique_id() {
    // Implement a hash-based generation scheme
    static uint32_t current_id = 0;
    return ++current_id;
}

int add_packet(Packet* packet) {
    pthread_mutex_lock(&packet_manager.lock);
    if (packet_manager.count >= MAX_PACKETS) {
        pthread_mutex_unlock(&packet_manager.lock);
        return -1;
    }
    packet_manager.packets[packet_manager.count++] = *packet;
    pthread_mutex_unlock(&packet_manager.lock);
    return 0;
}

Packet* get_packet(int index) {
    if (index < 0 || index >= packet_manager.count) {
        return NULL;
    }
    return &packet_manager.packets[index];
}

int get_packet_count() {
    return packet_manager.count;
}

void free_all_packets() {
    pthread_mutex_lock(&packet_manager.lock);
    for (size_t i = 0; i < packet_manager.count; ++i) {
        free_packet(&packet_manager.packets[i]);
    }
    packet_manager.count = 0;
    pthread_mutex_unlock(&packet_manager.lock);
}

