#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct {
    char username[50];
    int user_id;
} user_profile;

user_profile** profiles = NULL;
int max_profiles = 0;
int current_profiles = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;
int log_level = LOG_LEVEL_INFO;

void init_logging(const char* filename, int level) {
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    log_level = level;
}

void log_message(int level, const char* format, ...) {
    if (level < log_level) return;

    time_t now = time(NULL);
    char* timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = '\0';

    va_list args;
    va_start(args, format);
    fprintf(log_file, "[%s] ", timestamp);
    vfprintf(log_file, format, args);
    va_end(args);

    if (level == LOG_LEVEL_ERROR) {
        fprintf(stderr, "[%s] Error: ", timestamp);
        vfprintf(stderr, format, args);
        va_end(args);
    }
}

void* allocate_profiles(int new_capacity) {
    user_profile** new_profiles = realloc(profiles, new_capacity * sizeof(user_profile*));
    if (new_profiles == NULL) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for profiles");
        return NULL;
    }
    memset(new_profiles + current_profiles, 0, (new_capacity - current_profiles) * sizeof(user_profile*));
    profiles = new_profiles;
    max_profiles = new_capacity;
    return new_profiles;
}

int create_profile(const char* username, int user_id) {
    pthread_mutex_lock(&mutex);

    if (current_profiles >= max_profiles) {
        user_profile** new_profiles = allocate_profiles(max_profiles + 10);
        if (new_profiles == NULL) {
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    profiles[current_profiles] = malloc(sizeof(user_profile));
    if (profiles[current_profiles] == NULL) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for user profile");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    strncpy(profiles[current_profiles]->username, username, sizeof(profiles[current_profiles]->username) - 1);
    profiles[current_profiles]->user_id = user_id;
    current_profiles++;

    log_message(LOG_LEVEL_INFO, "Created profile: %s (%d)", username, user_id);

    pthread_mutex_unlock(&mutex);
    return 0;
}

int delete_profile(int user_id) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < current_profiles; i++) {
        if (profiles[i]->user_id == user_id) {
            free(profiles[i]);
            profiles[i] = NULL;
            memmove(profiles + i, profiles + i + 1, --current_profiles * sizeof(user_profile*));
            log_message(LOG_LEVEL_INFO, "Deleted profile: %d", user_id);
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    log_message(LOG_LEVEL_ERROR, "Profile with ID %d not found", user_id);
    pthread_mutex_unlock(&mutex);
    return -1;
}

void free_profiles() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < current_profiles; i++) {
        if (profiles[i] != NULL) {
            free(profiles[i]);
        }
    }

    free(profiles);
    profiles = NULL;
    max_profiles = 0;
    current_profiles = 0;

    pthread_mutex_unlock(&mutex);
}

void* database_update(void* arg) {
    int user_id = *(int*)arg;
    char status[50] = "Active";
    char last_modified_ip[] = "192.168.1.1";
    time_t now = time(NULL);

    // Simulate database update
    printf("Updating database for user %d with status: %s, IP: %s, Last Modified: %s\n",
           user_id, status, last_modified_ip, ctime(&now));

    free(arg);
    return NULL;
}

int main() {
    init_logging("application.log", LOG_LEVEL_INFO);

    if (create_profile("john_doe", 1001) != 0) {
        log_message(LOG_LEVEL_ERROR, "Failed to create profile for john_doe");
    }

    if (delete_profile(1001) != 0) {
        log_message(LOG_LEVEL_ERROR, "Failed to delete profile with ID 1001");
    }

    free_profiles();

    return 0;
}
