# Define a custom metric collector
class CustomMetricCollector:
    def __init__(self):
        self.metrics = {}

    def record_metric(self, key, value):
        if key not in self.metrics:
            self.metrics[key] = []
        self.metrics[key].append(value)

    def get_metrics(self, key):
        return self.metrics.get(key, [])

# Initialize the metric collector
metric_collector = CustomMetricCollector()

# Define a thread-safe mechanism for limiting metrics
class MetricBuffer:
    def __init__(self, max_entries=5000):
        self.buffer = []
        self.max_entries = max_entries

    def add_metric(self, metric):
        if len(self.buffer) >= self.max_entries:
            self.buffer.pop(0)
        self.buffer.append(metric)

# Initialize the metric buffer
metric_buffer = MetricBuffer()

# Define a mechanism for caching user information
