# Implement a fallback mechanism for Redis failures
def redis_fallback(function):
    def wrapper(*args, **kwargs):
        try:
            return function(*args, **kwargs)
        except redis.ConnectionError:
            print("Redis connection error. Using fallback.")
            # Fallback logic here
    return wrapper

@redis_fallback
def get_user_info(token):
    if token in user_cache:
        return user_cache[token]
    else:
        user_info = redis_client.get(token)
        user_cache[token] = user_info
        return user_info

# Define a caching strategy for minimizing database load
