    oauth_client = providers.Factory(OAuthClient, config=config.provided.oauth)

    @providers.Singleton
    def user_service(self, oauth_client=oauth_client):
        return UserService(oauth_client)

service_container = ServiceContainer()

# Define a mechanism for periodically archiving old metric data
def archive_metrics():
    while True:
        for key, values in metric_collector.metrics.items():
            # Archive logic here
            pass
        time.sleep(3600)  # Run once per hour

# Start the monitoring and archiving threads
