#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_CACHE_SIZE 1024

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    record *cache[MAX_CACHE_SIZE];
    int count;
} lru_cache;

lru_cache *create_lru_cache() {
    lru_cache *c = (lru_cache *)malloc(sizeof(lru_cache));
    c->count = 0;
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        c->cache[i] = NULL;
    }
    return c;
}

void add_to_lru_cache(lru_cache *c, record *r) {
    if (c->count >= MAX_CACHE_SIZE) {
        free(c->cache[0]);
        memmove(c->cache, c->cache + 1, sizeof(record *) * (MAX_CACHE_SIZE - 1));
        c->count--;
    }
    c->cache[c->count++] = r;
}

record *get_from_lru_cache(lru_cache *c, int key) {
    for (int i = 0; i < c->count; i++) {
        if (c->cache[i]->key == key) {
            record *r = c->cache[i];
            memmove(c->cache + i, c->cache + i + 1, sizeof(record *) * (c->count - i - 1));
            c->cache[--c->count] = r;
            return r;
        }
    }
    return NULL;
}

void free_lru_cache(lru_cache *c) {
    for (int i = 0; i < c->count; i++) {
        free(c->cache[i]);
    }
    free(c);
}

record *create_record(long offset, int key) {
    record *r = (record *)malloc(sizeof(record));
    r->offset = offset;
    r->key = key;
    return r;
}

void free_record(record *r) {
    free(r);
}

record **create_records(int size, lru_cache *cache) {
    record **records = (record **)malloc(size * sizeof(record *));
    for (int i = 0; i < size; i++) {
        records[i] = create_record(rand(), rand() % 1000);
        add_to_lru_cache(cache, records[i]);
    }
    return records;
}

void free_records(record **records, int size) {
    for (int i = 0; i < size; i++) {
        free_record(records[i]);
    }
    free(records);
}

int main() {
    srand(time(NULL));
    lru_cache *cache = create_lru_cache();

    int size = 10;
    record **records = create_records(size, cache);

    // Additional operations like searching, sorting, and adding new records

    free_records(records, size);
    free_lru_cache(cache);

    return 0;
}
