std::vector<std::vector<double>> init_matrix(int rows, int cols, std::function<double(int, int)> init_value_func) {
    std::vector<std::vector<double>> matrix(rows, std::vector<double>(cols));
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            matrix[i][j] = init_value_func(i, j);
        }
    }
    return matrix;
}

// Function to generate unique keys with retry mechanism
std::vector<int> generate_keys(int N, const std::function<bool(int)>& is_unique) {
    std::vector<int> keys(N);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1000); // Adjust range as needed

    for (int i = 0; i < N;) {
        int key = dis(gen);
        if (is_unique(key)) {
            keys[i++] = key;
        }
    }

    return keys;
}

// Class to handle random number generation and cryptographic primitives
namespace crypto_utils {
    class RandomNumberGenerator {
    public:
        RandomNumberGenerator(int min, int max) : gen(std::random_device()()), dis(min, max) {}

        double random_double(double min_val, double max_val) {
            if (min_val > max_val) std::swap(min_val, max_val);
            return dis(gen);
        }

        int random_int(int min_val, int max_val) {
            if (min_val > max_val) std::swap(min_val, max_val);
            return dis(gen);
        }

    private:
        std::mt19937 gen;
        std::uniform_int_distribution<> dis;
    };
}

// Function to sort records by offset
void custom_sort(std::vector<record>& records) {
    std::stable_sort(records.begin(), records.end(), [](const record& a, const record& b) {
        return a.offset < b.offset;
    });
}

// Search function for a key in records
long search_record(const std::vector<record>& records, int key) {
    auto it = std::find_if(records.begin(), records.end(), [key](const record& r) { return r.key == key; });
    if (it != records.end()) return it->offset;
    return -1; // Special value for non-existent keys
}

// Class to manage a dynamic array of records with efficient additions
class RecordManager {
public:
    RecordManager(int initial_capacity = 10) : capacity(initial_capacity), size(0), data(new record[capacity]) {}

    ~RecordManager() { delete[] data; }

    void add_record(long offset, int key) {
        if (size == capacity) expand();
        data[size++] = {offset, key};
    }

private:
    void expand() {
        capacity *= 2;
        record* new_data = new record[capacity];
        std::copy(data, data + size, new_data);
        delete[] data;
        data = new_data;
    }

    int capacity;
    int size;
    record* data;
};

// Class to handle cryptographic primitives
class CryptoPrimitives {
public:
    CryptoPrimitives() {
        EVP_add_cipher(EVP_aes_256_cbc());
        EVP_add_cipher(EVP_camellia_256_cbc());
        MD5_Init(&md5_ctx);
        SHA1_Init(&sha1_ctx);
        RSA_generate_key_ex(&rsa, 2048, BN_value_one(), nullptr);
    }

    ~CryptoPrimitives() {
        EVP_cleanup();
        MD5_Final(md5_out, &md5_ctx);
        SHA1_Final(sha1_out, &sha1_ctx);
        RSA_free(rsa);
    }

private:
    EVP_CIPHER_CTX md5_ctx;
    unsigned char md5_out[MD5_DIGEST_LENGTH];
    EVP_CIPHER_CTX sha1_ctx;
    unsigned char sha1_out[SHA_DIGEST_LENGTH];
    RSA* rsa;
};

