#include <pthread.h>
#include <time.h>

typedef struct {
    // Define the fields for NFAPI_CRC_INDICATION_PDU_T structure
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(int initial_capacity) {
    if (initial_capacity <= 0) {
        fprintf(stderr, "Invalid capacity. Capacity must be greater than 0.\n");
        return NULL;
    }

    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Memory allocation failed for DynamicArray structure.");
        return NULL;
    }

    array->head = array->tail = NULL;
    array->size = 0;

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    if (pthread_mutex_init(&array->lock, &attr) != 0) {
        perror("Failed to initialize mutex.");
        free(array);
        return NULL;
    }

    // Optionally, pre-allocate nodes here if needed

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int append_to_dynamic_array(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&array->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed for new node.");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    new_node->data = new_data;
    new_node->next = NULL;

    if (array->head == NULL) {
        array->head = array->tail = new_node;
    } else {
        array->tail->next = new_node;
        array->tail = new_node;
    }
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

