    }
    key_record *new_keys = realloc(*keys, new_size * sizeof(key_record));
    if (new_keys) {
        *keys = new_keys;
    }
    record *new_records = realloc(*records, new_size * sizeof(record));
    if (new_records) {
        *records = new_records;
    }
}

void free_memory(offset_record *offsets, key_record *keys, record *records) {
