    if (!file) {
        perror("Failed to open file");
        return;
    }

    offset_record *offsets = NULL;
    key_record *keys = NULL;
    record *records = NULL;
    int size = 100; // Initial size
    allocate_memory(&offsets, &keys, &records, size);

    int line_number = 0;
    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        line_number++;
        // Dynamically resize memory as needed
        if (line_number >= size) {
            resize_memory(&offsets, &keys, &records, size, size * 2);
            size *= 2;
        }

        // Process each field in the row
        char *token = strtok(buffer, "\t");
        int field_index = 0;
        while (token) {
            if (field_index == 0) {
                offsets[line_number - 1].values = malloc(1 * sizeof(long));
                offsets[line_number - 1].count = 1;
                offsets[line_number - 1].values[0] = atol(token);
            } else if (field_index < 2 && validate_numeric_field(token)) {
                records[line_number - 1].values[field_index] = atoi(token);
            }
            token = strtok(NULL, "\t");
            field_index++;
        }

        // Compute the average of the last two numerical fields
        if (field_index >= 2) {
            int sum = records[line_number - 1].values[0] + records[line_number - 1].values[1];
            records[line_number - 1].average = sum / 2;
        }
    }

    fclose(file);
    // Free allocated memory
    free_memory(offsets, keys, records);
}

int main() {
    process_file("data.txt", MIN_VALUE, MAX_VALUE);
    return 0;
