int resolve_hostname(const char *hostname) {
    int status;
    struct addrinfo hints, *res, *p;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);
    }

    freeaddrinfo(res); // free the linked list

    return 0;
}

void *dns_worker(void *arg) {
    const char *hostname = (const char *)arg;

    if (resolve_hostname(hostname) != 0) {
        fprintf(stderr, "Failed to resolve %s\n", hostname);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    pthread_t threads[argc - 1];
    load_config();

    for (int i = 1; i < argc; ++i) {
        if (pthread_create(&threads[i - 1], NULL, dns_worker, argv[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
