#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_LEN 16
#define CACHE_SIZE 100
#define MAX_CONCURRENT_QUERIES 10

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    char ip[MAX_IP_LEN];
    time_t last_resolved;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int concurrent_queries = 0;
pthread_mutex_t query_lock = PTHREAD_MUTEX_INITIALIZER;

void* dns_resolver(void* arg) {
    char* hostname = (char*)arg;
    struct addrinfo hints, *res, *p;
    int status;

    if (concurrent_queries >= MAX_CONCURRENT_QUERIES) {
        printf("Too many concurrent DNS queries. Please try again later.\n");
        return NULL;
    }

    pthread_mutex_lock(&query_lock);
    concurrent_queries++;
    pthread_mutex_unlock(&query_lock);

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        pthread_mutex_lock(&query_lock);
        concurrent_queries--;
        pthread_mutex_unlock(&query_lock);
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("Resolved IP: %s\n", ipstr);

        pthread_mutex_lock(&cache_lock);
        int found = 0;
        for (int i = 0; i < cache_count; i++) {
            if (strcmp(hostname, cache[i].hostname) == 0) {
                strcpy(cache[i].ip, ipstr);
                cache[i].last_resolved = time(NULL);
                found = 1;
                break;
            }
        }

        if (!found && cache_count < CACHE_SIZE) {
            strcpy(cache[cache_count].hostname, hostname);
            strcpy(cache[cache_count].ip, ipstr);
            cache[cache_count].last_resolved = time(NULL);
            cache_count++;
        }
        pthread_mutex_unlock(&cache_lock);

        break;
    }

    freeaddrinfo(res); // free the linked list

    pthread_mutex_lock(&query_lock);
    concurrent_queries--;
    pthread_mutex_unlock(&query_lock);

    return NULL;
}

int main() {
    char hostname[MAX_HOSTNAME_LEN];
    pthread_t threads[MAX_CONCURRENT_QUERIES];

    printf("Enter hostname to resolve: ");
    fgets(hostname, MAX_HOSTNAME_LEN, stdin);
    hostname[strcspn(hostname, "\n")] = 0; // Remove newline character

    if (pthread_create(&threads[0], NULL, dns_resolver, hostname) != 0) {
        perror("pthread_create");
        return 1;
    }

    pthread_join(threads[0], NULL);

    return 0;
}
```

This code provides a basic implementation of a DNS resolver with caching and concurrency control. It uses the `getaddrinfo` function from the standard C library to perform DNS queries, and it includes a simple cache mechanism to store resolved IP addresses. The `dns_resolver` function handles concurrent requests by limiting the number of simultaneous queries. The main function demonstrates how to use this resolver with user input.']

