// Define constants for HTTP status codes and maximum buffer size
#define OK 200
#define FORBIDDEN 403
#define NOT_FOUND 404

// Struct to hold request data
typedef struct {
    int client_socket;
    char* url;
    char** trusted_ips;
    int num_trusted_ips;
} RequestData;

// Function prototypes
void handle_request(void*);
int validate_ip(char*, char**);
void log_request(RequestData, int);

int main(int argc, char* argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <port> <trusted_ip1> [<trusted_ip2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int port = atoi(argv[1]);
    int num_trusted_ips = argc - 2;
    char** trusted_ips = &argv[2];

    // Set up signal handling for graceful termination
    struct sigaction sa;
    sa.sa_handler = &handle_request;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Set up listening socket
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(port);
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        return EXIT_FAILURE;
    }
    listen(server_socket, SOMAXCONN);

    // Main loop to handle incoming connections
    while (1) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            perror("accept");
            continue;
        }

        RequestData* data = malloc(sizeof(RequestData));
        data->client_socket = client_socket;
        data->url = read_request(client_socket); // Function to read HTTP request
        data->trusted_ips = trusted_ips;
        data->num_trusted_ips = num_trusted_ips;

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, &handle_request, data) != 0) {
            perror("pthread_create");
            free(data);
            close(client_socket);
        }
    }

    close(server_socket);
    return EXIT_SUCCESS;
}

void handle_request(void* arg) {
    RequestData* data = (RequestData*)arg;

    if (!validate_ip(inet_ntoa(((struct sockaddr_in*)getpeername(data->client_socket, NULL, 0))->sin_addr), data->trusted_ips)) {
        send_response(data->client_socket, FORBIDDEN);
        free_request_data(data);
        return;
    }

    int status_code = process_request(data->url); // Function to process request
    send_response(data->client_socket, status_code);

    log_request(*data, status_code);
    free_request_data(data);
}

int validate_ip(char* client_ip, char** trusted_ips) {
    for (int i = 0; i < num_trusted_ips; ++i) {
        if (strcmp(client_ip, trusted_ips[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

void log_request(RequestData data, int status_code) {
    char* log_message = generate_log_message(data.url, client_ip, status_code); // Function to generate log message
    write_log(log_message); // Function to write log to file
    free(log_message);
}

