void* process_directory(void *arg) {
    Config *config = (Config *)arg;
    DIR *dir;
    struct dirent *ent;

    if ((dir = opendir(config->directory)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char full_path[MAX_PATH_LENGTH];
            snprintf(full_path, sizeof(full_path), "%s/%s", config->directory, ent->d_name);
            if (stat(full_path, &st) == 0 && S_ISREG(st.st_mode)) {
                process_log_file(full_path);
            }
        }
        closedir(dir);
    } else {
        log_message(LOG_LEVEL_ERROR, "Could not open directory: %s", config->directory);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
