    // Parse command line options and configuration file to populate the config structure
    // ...

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_directory, &config) != 0) {
        log_message(LOG_LEVEL_CRITICAL, "Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    // Clean up resources and exit

    return EXIT_SUCCESS;
}
