Record* initialize_records(size_t num_records, long* offsets, int* keys, size_t offset_size, size_t key_size) {
    srand(time(NULL));
    Record* head = NULL;
    Record* tail = NULL;

    for (size_t i = 0; i < num_records; ++i) {
        Record* new_record = (Record*)aligned_alloc(CACHE_LINE_SIZE, sizeof(Record));
        if (!new_record) {
            // Handle memory allocation failure
            while (head != NULL) {
                Record* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_record->value = rand() % INT_MAX; // Ensure value does not overflow int
        new_record->prev = tail;
        new_record->next = NULL;

        if (tail != NULL) {
            tail->next = new_record;
        } else {
            head = new_record;
        }
        tail = new_record;
    }

    return head;
}

void free_records(Record* head) {
    while (head != NULL) {
        Record* temp = head;
        head = head->next;
        free(temp);
    }
}
