#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct record {
    int value;
    struct record *prev, *next;
} Record;

typedef struct list {
    Record **records;
    long *offsets;
    int *keys;
    size_t capacity, size;
    size_t allocated_capacity;
} List;

List* create_list() {
    List *list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->records = (Record**)calloc(INITIAL_CAPACITY, sizeof(Record*));
    list->offsets = (long*)calloc(INITIAL_CAPACITY, sizeof(long));
    list->keys = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->allocated_capacity = INITIAL_CAPACITY * sizeof(Record*);

    return list;
}

void free_list(List *list) {
    for (size_t i = 0; i < list->size; ++i) {
        Record *record = list->records[i];
        if (record) {
            free(record);
        }
    }
    free(list->records);
    free(list->offsets);
    free(list->keys);
    free(list);
}

void add_record(List *list, int value, long offset, int key) {
    if (list->size == list->capacity) {
        list->allocated_capacity *= 2;
        list->records = (Record**)realloc(list->records, list->allocated_capacity);
        list->offsets = (long*)realloc(list->offsets, list->allocated_capacity * sizeof(long));
        list->keys = (int*)realloc(list->keys, list->allocated_capacity * sizeof(int));
    }

    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return;

    new_record->value = value;
    new_record->prev = NULL;
    new_record->next = list->records[0];
    if (list->records[0]) {
        list->records[0]->prev = new_record;
    }
    list->records[list->size] = new_record;

    list->offsets[list->size] = offset;
    list->keys[list->size] = key;
    ++list->size;
}

// Additional functions for loading external data, error handling, and synchronization can be implemented here.
