void* file_operation_thread(void *arg) {
    FileOperation *op = (FileOperation *) arg;
    if (!is_allowed_path(op->path)) {
        fprintf(stderr, "Access denied to %s\n", op->path);
        free(op);
        pthread_exit(NULL);
    }
    // Perform the file operation
    // Example: Listing directory contents
    if (strcmp(op->operation, "list") == 0) {
        DIR *dir = opendir(op->path);
        struct dirent *ent;
        while ((ent = readdir(dir)) != NULL) {
            printf("%s\n", ent->d_name);
        }
        closedir(dir);
