        FILE *file = fopen(op->path, "r");
        if (file == NULL) perror("Error opening file");
        else {
            char buffer[128];
            while (fgets(buffer, sizeof(buffer), file)) printf("%s", buffer);
            fclose(file);
        }
    } else if (strcmp(op->operation, "write") == 0) {
        FILE *file = fopen(op->path, "w");
        if (file == NULL) perror("Error opening file");
        else {
            fprintf(file, "Hello, world!\n");
            fclose(file);
        }
    }
    free(op);
    pthread_exit(NULL);
}

int resolve_hostname(const char *hostname, u_char *ip_addr) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            memcpy(ip_addr, &ipv4->sin_addr.s_addr, sizeof(struct in_addr));
            break;
        }
    }

    freeaddrinfo(res);
    return 0;
}

int main() {
    // Example usage
    pthread_t threads[MAX_CONCURRENT_OPS];
    FileOperation ops[MAX_CONCURRENT_OPS];

    // Set up operations and create threads
    for (int i = 0; i < MAX_CONCURRENT_OPS; i++) {
        ops[i].operation = "list";
        ops[i].path = "/safe/dir1/subdir";
        pthread_create(&threads[i], NULL, file_operation_thread, &ops[i]);
    }

    // Join threads
    for (int i = 0; i < MAX_CONCURRENT_OPS; i++) {
        pthread_join(threads[i], NULL);
    }

    u_char ip_addr[4];
    if (resolve_hostname("example.com", ip_addr) == 0) {
        printf("IP address: %d.%d.%d.%d\n",
               ip_addr[0], ip_addr[1], ip_addr[2], ip_addr[3]);
    }

    return 0;
}
