#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKETS 1000

typedef struct {
    int packet_id;
    char timestamp[20];
    unsigned flags;
    char payload[MAX_PACKET_SIZE];
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *pm) {
    pm->count = 0;
    pthread_mutex_init(&pm->lock, NULL);
}

int allocate_packet(PacketManager *pm) {
    pthread_mutex_lock(&pm->lock);
    if (pm->count < MAX_PACKETS) {
        int index = pm->count++;
        pthread_mutex_unlock(&pm->lock);
        return index;
    }
    pthread_mutex_unlock(&pm->lock);
    return -1; // No more packets available
}

void free_packet(PacketManager *pm, int index) {
    pthread_mutex_lock(&pm->lock);
    if (index >= 0 && index < pm->count) {
        pm->count--;
        pthread_mutex_unlock(&pm->lock);
    }
    pthread_mutex_unlock(&pm->lock);
}

int get_packet_count(PacketManager *pm) {
    int count;
    pthread_mutex_lock(&pm->lock);
    count = pm->count;
    pthread_mutex_unlock(&pm->lock);
    return count;
}

Packet* get_packet(PacketManager *pm, int index) {
    Packet *packet = NULL;
    pthread_mutex_lock(&pm->lock);
    if (index >= 0 && index < pm->count) {
        packet = &pm->packets[index];
    }
    pthread_mutex_unlock(&pm->lock);
    return packet;
}
```

