MemoryPool offset_pool;
MemoryPool key_pool;

void init_memory_pools(size_t initial_size) {
    offset_pool.data = (long*)malloc(initial_size * sizeof(long));
    offset_pool.capacity = initial_size;
    offset_pool.size = 0;

    key_pool.data = (int*)malloc(initial_size * sizeof(int));
    key_pool.capacity = initial_size;
    key_pool.size = 0;
}

void* pool_malloc(MemoryPool* pool, size_t size) {
    if (pool->size + size > pool->capacity) {
        long new_capacity = pool->capacity == 0 ? INITIAL_POOL_SIZE : pool->capacity * 2;
        while (new_capacity < pool->size + size) {
            new_capacity *= 2;
        }

        long* new_data = (long*)realloc(pool->data, new_capacity * sizeof(long));
        if (new_data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        pool->data = new_data;
        pool->capacity = new_capacity;
    }

    long* ptr = &pool->data[pool->size];
    pool->size += size / sizeof(long);
    return ptr;
}

void pool_free(MemoryPool* pool, void* ptr) {
    // No-op in this simple example
}

