    for (size_t i = 0; i < max_offsets; i++) {
        (*offsets)[i].value = rand() % (max_value - min_value + 1) + min_value;
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    for (size_t i = 0; i < max_keys; i++) {
        (*keys)[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return 0;
}

void cleanup_structures(struct offset_record** offsets, struct key_record** keys, struct record** records) {
    free(*offsets);
    pool_free(&offset_pool, *offsets);
    free(*keys);
    pool_free(&key_pool, *keys);
    free(*records);
