struct memory_pool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_count;
    pthread_mutex_t lock;
};

void init_memory_pool(struct memory_pool* mp, size_t block_size, size_t initial_blocks) {
    mp->block_size = block_size;
    mp->num_blocks = initial_blocks;
    mp->free_count = initial_blocks;
    mp->pool = malloc(initial_blocks * block_size);
    pthread_mutex_init(&mp->lock, NULL);
}

void* memory_pool_alloc(struct memory_pool* mp) {
    void* block;
    pthread_mutex_lock(&mp->lock);
    if (mp->free_count == 0) {
        // Resize pool or handle allocation failure
    }
    block = mp->pool + (mp->num_blocks - mp->free_count) * mp->block_size;
    mp->free_count--;
    pthread_mutex_unlock(&mp->lock);
    return block;
}

void memory_pool_free(struct memory_pool* mp, void* block) {
    pthread_mutex_lock(&mp->lock);
    // Insert block back into pool
    mp->free_count++;
    pthread_mutex_unlock(&mp->lock);
}

struct profiling_info {
