    init_memory_pool(&offset_pool, sizeof(offset_record), max_offsets);
    init_memory_pool(&key_pool, sizeof(key_record), max_keys);

    offset_record* offsets = (offset_record*)memory_pool_alloc(&offset_pool);
    key_record* keys = (key_record*)memory_pool_alloc(&key_pool);

    record* records = (record*)malloc(max_records * sizeof(record));
    for (int i = 0; i < max_records; i++) {
        records[i].data = rand() % (max_value - min_value + 1) + min_value;
    }

    // Implement dynamic resizing, thread safety, and profiling

    // Clean up
    free(records);
    memory_pool_free(&offset_pool, offsets);
    memory_pool_free(&key_pool, keys);

    return 0;
}

int main() {
