typedef struct Node {
    int value;
    char* str;
    struct Node* next;
} Node;

Node* create_node(int value, const char* str) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->value = value;
    new_node->str = strdup(str);
    if (!(new_node->str)) {
        free(new_node);
        return NULL;
    }
    new_node->next = NULL;

    return new_node;
}

void free_node(Node* node) {
    free(node->str);
    free(node);
}

Node** create_linked_list(int count, const int values[], const char* strs[]) {
    if (count <= 0 || !values || !strs) return NULL;

    Node** head = (Node**)malloc(count * sizeof(Node*));
    if (!head) return NULL;

    for (int i = 0; i < count; i++) {
        head[i] = create_node(values[i], strs[i]);
        if (!head[i]) {
            // Cleanup on failure
            for (int j = 0; j < i; j++) {
                free_node(head[j]);
            }
            free(head);
            return NULL;
        }
    }

    // Link nodes in the list
    for (int i = 0; i < count - 1; i++) {
        head[i]->next = head[i + 1];
    }
    head[count - 1]->next = NULL;

    return head;
}

void free_linked_list(Node** head, int count) {
    if (!head) return;

    for (int i = 0; i < count; i++) {
        free_node(head[i]);
    }

    free(head);
}
