#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    int value;
    char* str;
    struct Node* next;
} Node;

Node* create_node(int value, const char* str) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->value = value;
    new_node->str = strdup(str);
    new_node->next = NULL;
    return new_node;
}

void free_node(Node* node) {
    if (!node) return;
    free(node->str);
    free(node);
}

typedef struct LinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_linked_list(LinkedList* list) {
    if (!list) return;
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void insert_head(LinkedList* list, int value, const char* str) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = create_node(value, str);
    if (new_node) {
        new_node->next = list->head;
        list->head = new_node;
        if (!list->tail) list->tail = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void insert_tail(LinkedList* list, int value, const char* str) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = create_node(value, str);
    if (new_node) {
        if (!list->head) {
            list->head = list->tail = new_node;
        } else {
            list->tail->next = new_node;
            list->tail = new_node;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void delete_head(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    if (list->head) {
        Node* old_head = list->head;
        list->head = list->head->next;
        if (!list->head) list->tail = NULL;
        free_node(old_head);
    }
    pthread_mutex_unlock(&list->mutex);
}

void delete_tail(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    if (list->tail) {
        Node* current = list->head;
        Node* prev = NULL;
        while (current != list->tail) {
            prev = current;
            current = current->next;
        }
        if (!prev) {
            free_node(list->head);
            list->head = list->tail = NULL;
        } else {
            free_node(prev->next);
            prev->next = NULL;
            list->tail = prev;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}
