            exit(EXIT_FAILURE);
        }
        pool->data = new_data;
        pool->capacity = new_capacity;
    }
    ptr = ((char *)pool->data) + pool->size;
    pool->size += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

