#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EMAIL_LENGTH 256

typedef struct {
    long offset;
} offset_record;

typedef struct {
    int key;
} key_record;

typedef struct {
    offset_record *offsets;
    key_record *keys;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} record_array;

record_array* create_record_array(size_t initial_capacity) {
    record_array *array = malloc(sizeof(record_array));
    array->offsets = malloc(initial_capacity * sizeof(offset_record));
    array->keys = malloc(initial_capacity * sizeof(key_record));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void resize_record_array(record_array *array, size_t new_capacity) {
    pthread_mutex_lock(&array->mutex);
    offset_record *new_offsets = realloc(array->offsets, new_capacity * sizeof(offset_record));
    key_record *new_keys = realloc(array->keys, new_capacity * sizeof(key_record));
    if (new_offsets && new_keys) {
        array->offsets = new_offsets;
        array->keys = new_keys;
        array->capacity = new_capacity;
    }
    pthread_mutex_unlock(&array->mutex);
}

void add_record(record_array *array, long offset, int key) {
    if (array->count == array->capacity) {
        resize_record_array(array, array->capacity * 2);
    }
    pthread_mutex_lock(&array->mutex);
    array->offsets[array->count].offset = offset;
    array->keys[array->count].key = key;
    array->count++;
    pthread_mutex_unlock(&array->mutex);
}

void destroy_record_array(record_array *array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->offsets);
    free(array->keys);
    free(array);
}
