#define MAX_RESIZE_FACTOR 2

typedef struct {
    int value;
    long weight;
    char status;
} record;

typedef struct {
    pthread_mutex_t lock;
    void* memory_pool;
    size_t pool_size;
    size_t pool_capacity;
} memory_manager;

memory_manager manager = { PTHREAD_MUTEX_INITIALIZER, NULL, 0, 0 };

void initialize_memory_manager(size_t initial_size) {
    manager.pool_capacity = initial_size * sizeof(record);
    manager.memory_pool = malloc(manager.pool_capacity);
    if (manager.memory_pool == NULL) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
}

void* resize_memory_pool(size_t new_size) {
    pthread_mutex_lock(&manager.lock);
    size_t old_size = manager.pool_size;
    manager.pool_capacity = new_size * sizeof(record);
    void* new_memory_pool = realloc(manager.memory_pool, manager.pool_capacity);
    if (new_memory_pool == NULL) {
        perror("Failed to resize memory pool");
        free(new_memory_pool);
        pthread_mutex_unlock(&manager.lock);
        return NULL;
    }
    manager.memory_pool = new_memory_pool;
    memset((char*)manager.memory_pool + old_size, 0, manager.pool_capacity - old_size);
    pthread_mutex_unlock(&manager.lock);
    return manager.memory_pool;
}

record* allocate_record(size_t N) {
    if (N > manager.pool_capacity / sizeof(record)) {
        size_t new_size = manager.pool_capacity == 0 ? 1 : manager.pool_capacity * MAX_RESIZE_FACTOR;
        while (new_size < N * sizeof(record)) {
            new_size *= MAX_RESIZE_FACTOR;
        }
        resize_memory_pool(new_size);
    }
    return (record*)manager.memory_pool + manager.pool_size / sizeof(record);
}

void* complex_generation_algorithm(size_t N) {
    record* records = allocate_record(N);
    for (size_t i = 0; i < N; ++i) {
        records[i].value = rand() % 100;
        records[i].weight = time(NULL) + rand() % 1000;
        records[i].status = (rand() % 2 == 0) ? 'A' : 'B';
    }
    return records;
}

void* distributed_memory_management(void* arg) {
    size_t N = *(size_t*)arg;
    if (N <= 0) {
        fprintf(stderr, "Invalid value for N: %zu\n", N);
        return NULL;
    }

    record* records = complex_generation_algorithm(N);
    // Perform further processing with records

    free(records);
    return NULL;
}

int main() {
    srand(time(NULL));

    initialize_memory_manager(10);

    size_t thread_N = 20;
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, distributed_memory_management, &thread_N) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread_id, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
