Item* build_balanced_tree(double value, int depth, int max_depth) {
    if (depth > max_depth) {
        return NULL;
    }
    Item* item = (Item*)malloc(sizeof(Item));
    if (item == NULL) {
        return NULL;
    }
    item->value = value;
    item->left = build_balanced_tree(value - 1, depth + 1, max_depth); // Adjust the logic to ensure balance
    item->right = build_balanced_tree(value + 1, depth + 1, max_depth);
    return item;
}
