int init_data_structures(int offset_count, int key_count, int record_count, int linked_list_count, int record_value_range) {
    if (offset_count < 0 || key_count < 0 || record_count < 0 || linked_list_count < 0 || record_value_range < 0) {
        fprintf(stderr, "Invalid input size.\n");
        return -1;
    }

    // Allocate memory for offsets
    long* offsets = (long*)malloc(offset_count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets.");
        return -1;
    }

    // Allocate memory for keys
    int* keys = (int*)malloc(key_count * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys.");
        free(offsets);
        return -1;
    }

    // Initialize records with unique values within the specified range
    Record* records = (Record*)malloc(record_count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        free(offsets);
        free(keys);
        return -1;
    }
    for (int i = 0; i < record_count; ++i) {
        records[i].value = i % record_value_range;
    }

    // Initialize linked list with unique values
    Node* head = NULL;
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < linked_list_count; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory for a node.");
            // Free previously allocated structures
            free(offsets);
            free(keys);
            free(records);
            // Free nodes in the linked list
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_destroy(&lock);
            return -1;
        }

        new_node->value = i;
        new_node->next = head;
        head = new_node;
    }

    // Clean up and return success
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&lock);
    return 0;
}
