// Function to safely allocate memory with error handling
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to initialize the data structures
int initialize_data_structures(int array_size, int linked_list_length, int hash_table_capacity, int tree_depth, int queue_size) {
    if (array_size <= 0 || linked_list_length > 10000 || !is_power_of_two(hash_table_capacity) || hash_table_capacity > 1024 || tree_depth > 20 || queue_size != 1000) {
        fprintf(stderr, "Invalid input size\n");
        return -1;
    }

    // Initialize array
    double* double_array = safe_malloc(array_size * sizeof(double));

    // Initialize linked list
    node** linked_list = (node**)safe_malloc(linked_list_length * sizeof(node*));
    for (int i = 0; i < linked_list_length; i++) {
        linked_list[i] = (node*)safe_malloc(sizeof(node));
        linked_list[i]->value = 0.0;
    }

    // Initialize hash table
    entry** hash_table = (entry**)safe_malloc(hash_table_capacity * sizeof(entry*));
    for (int i = 0; i < hash_table_capacity; i++) {
        hash_table[i] = NULL;
    }

    // Initialize tree (balanced binary search tree)
    item* root = NULL;

    // Initialize queue
    queue_node* queue_head = NULL;
    queue_node* queue_tail = NULL;

    // Example of inserting an element into the queue
    if (queue_size > 0) {
        queue_node* new_node = (queue_node*)safe_malloc(sizeof(queue_node));
        new_node->data = safe_malloc(sizeof(double));
        *((double*)new_node->data) = 3.14;
        new_node->next = NULL;

        if (queue_head == NULL) {
            queue_head = new_node;
        } else {
            queue_tail->next = new_node;
        }
        queue_tail = new_node;
    }

    // Clean up allocated memory
    free(double_array);
    for (int i = 0; i < linked_list_length; i++) {
        free(linked_list[i]);
    }
    free(linked_list);
    for (int i = 0; i < hash_table_capacity; i++) {
        while (hash_table[i] != NULL) {
            entry* temp = hash_table[i];
            hash_table[i] = temp->next;
            free(temp->key);
            free(temp);
        }
    }
    free(hash_table);

    // Clean up queue nodes
    while (queue_head != NULL) {
        queue_node* temp = queue_head;
        queue_head = queue_head->next;
        free(temp->data);
        free(temp);
    }

    return 0;
}

// Helper function to check if a number is a power of two
int is_power_of_two(int n) {
    return (n != 0) && ((n & (n - 1)) == 0);
}
