} dynamic_array;

void init_dynamic_array(dynamic_array *arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->offsets = (offset_record *)malloc(initial_capacity * sizeof(offset_record));
    arr->keys = (key_record *)malloc(initial_capacity * sizeof(key_record));
    pthread_mutex_init(&arr->mutex, NULL);
}

void resize_dynamic_array(dynamic_array *arr) {
    size_t new_capacity = arr->capacity * 2;
    arr->offsets = (offset_record *)realloc(arr->offsets, new_capacity * sizeof(offset_record));
    arr->keys = (key_record *)realloc(arr->keys, new_capacity * sizeof(key_record));
    arr->capacity = new_capacity;
}

void add_to_dynamic_array(dynamic_array *arr, long offset, int key) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= arr->capacity) {
        resize_dynamic_array(arr);
    }
    arr->offsets[arr->size].offset = offset;
    arr->keys[arr->size].key = key;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

void free_dynamic_array(dynamic_array *arr) {
    pthread_mutex_destroy(&arr->mutex);
    free(arr->offsets);
    free(arr->keys);
}

