using UnityEngine;

public class RandomValueGenerator : MonoBehaviour
{
    private long[] offsetValues;
    private Dictionary<int, record> keyRecords;

    public void Initialize(long[] offsets, Dictionary<int, record> records)
    {
        if (offsets == null || records == null)
            throw new ArgumentNullException("Offset values and/or records cannot be null.");

        offsetValues = offsets;
        keyRecords = records;

        foreach (var record in keyRecords.Values)
        {
            record.value = GetRandomInt(0, 100); // Example range
        }
    }

    public int GetRandomInt(int min, int max)
    {
        if (min >= max)
            throw new ArgumentException("Min value must be less than max value.");

        return UnityEngine.Random.Range(min, max + 1);
    }

    public float GetWeightedRandomFloat(float[] weights)
    {
        if (weights == null || weights.Length == 0)
            throw new ArgumentException("Weights array cannot be null or empty.");

        float totalWeight = 0.0f;
        for (int i = 0; i < weights.Length; i++)
        {
            totalWeight += weights[i];
        }

        if (Mathf.Abs(totalWeight - 1.0f) > 0.0001f)
            throw new ArgumentException("Weights must sum up to 1.0.");

        float randomValue = UnityEngine.Random.value;
        float cumulativeWeight = 0.0f;

        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return i;
        }

        throw new InvalidOperationException("Failed to select a weighted random value.");
    }
}
