#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024
#define MAX_WORDS 10000
#define MAX_STOP_WORDS 100

typedef struct {
    char *word;
    int count;
} WordCount;

int compare_word_count(const void *a, const void *b) {
    return ((WordCount *)b)->count - ((WordCount *)a)->count;
}

void process_file(const char *filename, char **stop_words, int num_stop_words, const char *output_dir, int log_level) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    WordCount word_counts[MAX_WORDS] = {0};
    char line[MAX_LINE_LENGTH];
    int line_count = 0;
    int word_count = 0;

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        line_count++;
        char *token = strtok(line, " ");
        while (token) {
            if (!isalpha(token[0])) {
                token++;
                continue;
            }

            for (int i = 0; token[i]; i++) {
                token[i] = tolower(token[i]);
            }

            int is_stop_word = 0;
            for (int i = 0; i < num_stop_words; i++) {
                if (strcmp(token, stop_words[i]) == 0) {
                    is_stop_word = 1;
                    break;
                }
            }

            if (is_stop_word) {
                token = strtok(NULL, " ");
                continue;
            }

            int found = 0;
            for (int i = 0; i < word_count; i++) {
                if (strcmp(word_counts[i].word, token) == 0) {
                    word_counts[i].count++;
                    found = 1;
                    break;
                }
            }

            if (!found) {
                if (word_count >= MAX_WORDS) {
                    fprintf(stderr, "Too many unique words\n");
                    fclose(file);
                    return;
                }
                word_counts[word_count].word = strdup(token);
                word_counts[word_count].count = 1;
                word_count++;
            }

            token = strtok(NULL, " ");
        }
    }

    fclose(file);

    qsort(word_counts, word_count, sizeof(WordCount), compare_word_count);

    FILE *report_file = fopen("report.txt", "w");
    if (!report_file) {
        perror("Error opening report file");
        return;
    }

    fprintf(report_file, "Line count: %d\n", line_count);
    fprintf(report_file, "Unique word count: %d\n", word_count);
    for (int i = 0; i < 10 && i < word_count; i++) {
        fprintf(report_file, "%s: %d\n", word_counts[i].word, word_counts[i].count);
    }

    fclose(report_file);

    printf("Report generated successfully in report.txt\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] <input-file>\n", argv[0]);
        return 1;
    }

    const char *filename = NULL;
    char **stop_words = malloc(MAX_STOP_WORDS * sizeof(char *));
    int num_stop_words = 0;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            stop_words[num_stop_words] = argv[++i];
            num_stop_words++;
        } else if (filename == NULL) {
            filename = argv[i];
        }
    }

    if (filename == NULL) {
        fprintf(stderr, "No input file specified\n");
        free(stop_words);
        return 1;
    }

    process_file(filename, stop_words, num_stop_words, "output", 0);

    for (int i = 0; i < num_stop_words; i++) {
        free(stop_words[i]);
    }
    free(stop_words);

    return 0;
}
```

