#define MAX_THREADS 10

typedef struct {
    char *filename;
    int line_count;
    pthread_mutex_t mutex;
} FileData;

FileData file_data = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void* process_file(void* arg) {
    FILE *file = fopen(((FileData*)arg)->filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return NULL;
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        pthread_mutex_lock(&file_data.mutex);
        file_data.line_count++;
        pthread_mutex_unlock(&file_data.mutex);
    }

    fclose(file);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] [input_file]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Parse command line arguments
    // ...

    if (optind == argc) {
        // Read from stdin
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), stdin)) {
            pthread_mutex_lock(&file_data.mutex);
            file_data.line_count++;
            pthread_mutex_unlock(&file_data.mutex);
        }
    } else {
        FileData file_data_thread = {argv[optind], 0, PTHREAD_MUTEX_INITIALIZER};
        pthread_t thread;
        if (pthread_create(&thread, NULL, process_file, &file_data_thread) != 0) {
            perror("Error creating thread");
            exit(EXIT_FAILURE);
        }

        // Wait for thread to finish
        pthread_join(thread, NULL);
    }

    printf("Number of lines: %d\n", file_data.line_count);

    return 0;
}
