typedef struct {
    int key;
    long offset;
} Record;

Record* create_records(int num_records, long min_offset, long max_offset) {
    if (num_records > MAX_RECORDS || min_offset >= max_offset) {
        return NULL; // Invalid input
    }

    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (records == NULL) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    long used_offsets[MAX_RECORDS] = {0};
    int unique_count = 0;

    while (unique_count < num_records) {
        long offset = min_offset + rand() % (max_offset - min_offset);
        if (!used_offsets[offset]) {
            records[unique_count].key = unique_count;
            records[unique_count].offset = offset;
            used_offsets[offset] = 1;
            unique_count++;
        }
    }

    return records;
}

void free_records(Record *records) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    int num_records = 500000;
    long min_offset = 1000;
    long max_offset = 999999;

    Record *records = create_records(num_records, min_offset, max_offset);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return EXIT_FAILURE;
    }

    // Example iteration over records
    for (int i = 0; i < num_records; i++) {
        printf("Key: %d, Offset: %ld\n", records[i].key, records[i].offset);
    }

    free_records(records);

    return EXIT_SUCCESS;
}
