#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure with additional fields
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
    uint64_t timestamp;
    int signal_strength;
    int CQI;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with random values and additional metadata
Node* create_node() {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }
    // Initialize with random values and set current time as timestamp
    srand(time(NULL));
    newNode->data.RX_UE_INFORMATION_TAG = rand();
    newNode->data.RNTI = (uint16_t)rand();
    newNode->data.CRCFLAG = (uint8_t)rand() % 2;
    newNode->data.timestamp = time(NULL);
    newNode->data.signal_strength = rand() % 100;
    newNode->data.CQI = rand() % 30;
    newNode->next = NULL;
    return newNode;
}

// Function to append a new node to the linked list
void append_node(Node** head, int max_size) {
    if (*head == NULL) {
        *head = create_node();
    } else {
        Node* temp = *head;
        while (temp->next != NULL && (*head)->data.RX_UE_INFORMATION_TAG < temp->data.RX_UE_INFORMATION_TAG) {
            temp = temp->next;
        }
        if ((*head)->data.RX_UE_INFORMATION_TAG == temp->data.RX_UE_INFORMATION_TAG) {
            printf("Duplicate RX_UE_INFORMATION_TAG, not appending.\n");
            return;
        }
        Node* newNode = create_node();
        newNode->next = temp->next;
        temp->next = newNode;
    }
}

// Function to serialize the linked list into a binary file
void serialize_list(Node* head, const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    Node* temp = head;
    while (temp != NULL) {
        fwrite(&temp->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
        temp = temp->next;
    }
    fclose(fp);
}

// Function to deserialize the binary file into a linked list
Node* deserialize_list(const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("Failed to open file for reading");
        return NULL;
    }
    Node* head = NULL;
    while (!feof(fp)) {
        NFAPI_CRC_INDICATION_PDU_T data;
        size_t result = fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
        if (result == 0 && !feof(fp)) {
            perror("Failed to read from file");
            break;
        }
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            perror("Failed to allocate memory for new node");
            break;
        }
        newNode->data = data;
        newNode->next = head;
        head = newNode;
    }
    fclose(fp);
    return head;
}

