#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define DEFAULT_DELIMITER "/"
#define MAX_SIZE_LIMIT 1024

typedef struct {
    char *buffer;
    size_t size;
} ExternalBuffer;

char* process_string(const char *input, size_t max_size, const char *delimiter, ExternalBuffer *ext_buf) {
    if (input == NULL || delimiter == NULL) {
        return NULL;
    }

    // Validate the input string length
    size_t input_length = strlen(input);
    if (input_length >= max_size) {
        return NULL;
    }

    char *result;
    size_t result_length = input_length + strlen(delimiter);

    if (ext_buf != NULL && ext_buf->buffer != NULL && ext_buf->size >= result_length) {
        // Use the provided external buffer
        strcpy(ext_buf->buffer, input);
        strcat(ext_buf->buffer, delimiter);
        return ext_buf->buffer;
    } else {
        // Allocate memory for the result string
        result = malloc(result_length + 1);
        if (result == NULL) {
            return NULL; // Memory allocation failed
        }
        strcpy(result, input);
        strcat(result, delimiter);
        return result;
    }
}

int main() {
    const char *input = "example";
    size_t max_size = MAX_SIZE_LIMIT;
    const char *delimiter = DEFAULT_DELIMITER;

    ExternalBuffer ext_buf = {NULL, 0};
    char *result = process_string(input, max_size, delimiter, &ext_buf);

    if (result != NULL) {
        printf("Processed string: %s\n", result);
        free(result); // Free allocated memory if using dynamic allocation
    } else {
        printf("Failed to process string.\n");
    }

    return 0;
}
