    double latency;
    float throughput;
} client_profile;

// Function to allocate memory for connection records
connection_record* allocate_connection(int id, int num_packets) {
    connection_record *record = (connection_record*)malloc(sizeof(connection_record));
    if (!record) {
        perror("Failed to allocate memory for connection record");
        exit(EXIT_FAILURE);
    }
    record->connection_id = id;
    record->packets = (packet_record**)calloc(num_packets, sizeof(packet_record*));
    if (!record->packets) {
        perror("Failed to allocate memory for packets array");
        free(record);
        exit(EXIT_FAILURE);
    }
    return record;
}

// Function to allocate memory for packet records
packet_record* allocate_packet(unsigned long size, char type, uint64_t sequence_number) {
    packet_record *packet = (packet_record*)malloc(sizeof(packet_record));
    if (!packet) {
        perror("Failed to allocate memory for packet record");
        exit(EXIT_FAILURE);
    }
    packet->size = size;
    packet->type = type;
    packet->sequence_numbers = (uint64_t*)calloc(1, sizeof(uint64_t));
    if (!packet->sequence_numbers) {
        perror("Failed to allocate memory for sequence numbers array");
        free(packet);
        exit(EXIT_FAILURE);
    }
    *packet->sequence_numbers = sequence_number;
    return packet;
}

// Function to deallocate memory for connection records
void deallocate_connection(connection_record *record, int num_packets) {
    for (int i = 0; i < num_packets; ++i) {
        free(record->packets[i]->sequence_numbers);
        free(record->packets[i]);
    }
    free(record->packets);
    free(record);
}

// Function to deallocate memory for packet records
void deallocate_packet(packet_record *packet) {
    free(packet->sequence_numbers);
    free(packet);
}
