#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2
#define NOT_FOUND -1.0f

typedef struct {
    char* name;
    int priority;
    float value;
} item;

item** items = NULL;
int active_size = 0;
int capacity = 0;

void init_items() {
    capacity = INITIAL_CAPACITY;
    items = (item**)malloc(capacity * sizeof(item*));
    if (!items) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

void add_item(const char* name, int priority, float value) {
    if (active_size >= capacity - 1) {
        capacity *= GROWTH_FACTOR;
        items = (item**)realloc(items, capacity * sizeof(item*));
        if (!items) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
    }
    item** new_item = &items[active_size++];
    *new_item = (item*)malloc(sizeof(item));
    (*new_item)->name = strdup(name);
    (*new_item)->priority = priority;
    (*new_item)->value = value;
}

void sort_items() {
    // Simple bubble sort for demonstration purposes
    for (int i = 0; i < active_size - 1; ++i) {
        for (int j = 0; j < active_size - i - 1; ++j) {
            if (items[j]->priority < items[j + 1]->priority) {
                item* temp = items[j];
                items[j] = items[j + 1];
                items[j + 1] = temp;
            }
        }
    }
}

float search_item(const char* name) {
    for (int i = 0; i < active_size; ++i) {
        if (strcmp(items[i]->name, name) == 0) {
            return items[i]->value;
        }
    }
    return NOT_FOUND;
}

void update_item_value(const char* name, float new_value) {
    for (int i = 0; i < active_size; ++i) {
        if (strcmp(items[i]->name, name) == 0) {
            items[i]->value = new_value;
            break;
        }
    }
}

void remove_item(const char* name) {
    for (int i = 0; i < active_size; ++i) {
        if (strcmp(items[i]->name, name) == 0) {
            free(items[i]);
            for (int j = i; j < active_size - 1; ++j) {
                items[j] = items[j + 1];
            }
            --active_size;
            break;
        }
    }
}

void cleanup() {
    for (int i = 0; i < active_size; ++i) {
        free(items[i]->name);
        free(items[i]);
    }
    free(items);
}

