        if (strcmp(items[i]->name, name) == 0) {
            return items[i]->value;
        }
    }
    return -1.0f; // Special value indicating absence
}

void update_item(const char* name, float new_value) {
    for (int i = 0; i < active_size; ++i) {
        if (strcmp(items[i]->name, name) == 0) {
            items[i]->value = new_value;
            return;
        }
    }
}

void remove_item(const char* name) {
    int found = -1;
    for (int i = 0; i < active_size; ++i) {
        if (strcmp(items[i]->name, name) == 0) {
            found = i;
            break;
        }
    }
    if (found != -1) {
        free(items[found]->name);
        free(items[found]);
        for (int i = found; i < active_size - 1; ++i) {
            items[i] = items[i + 1];
        }
        --active_size;
    }
}

void append_item(const char* name, int priority, float value) {
    if (active_size >= total_size) resize_items();
    item* newItem = (item*)malloc(sizeof(item));
    if (!newItem) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    newItem->name = strdup(name);
    newItem->priority = priority;
    newItem->value = value;
    items[active_size++] = newItem;
}

void free_items() {
    for (int i = 0; i < active_size; ++i) {
        free(items[i]->name);
        free(items[i]);
    }
    free(items);
}
