item* create_and_populate_items(int count, int min_priority, int max_priority, double min_score, double max_score, const char *prefix) {
    if (count <= 0 || min_priority >= max_priority || min_score >= max_score) return NULL;

    srand(time(NULL));
    item *items = malloc(count * sizeof(item));
    if (!items) {
        perror("Failed to allocate memory for items");
        return NULL;
    }

    const char *suffixes[] = {"A", "B", "C", "D", "E"};
    int suffix_count = sizeof(suffixes) / sizeof(suffixes[0]);

    for (int i = 0; i < count; ++i) {
        items[i].timestamp = time(NULL);
        items[i].priority = min_priority + rand() % (max_priority - min_priority + 1);
        items[i].score = min_score + (double)(rand()) / RAND_MAX * (max_score - min_score);

        int suffix_index = rand() % suffix_count;
        items[i].message = malloc((strlen(prefix) + strlen(suffixes[suffix_index]) + 2) * sizeof(char));
        if (!items[i].message) {
            perror("Failed to allocate memory for message");
            for (int j = 0; j < i; ++j) free(items[j].message);
            free(items);
            return NULL;
        }
        snprintf(items[i].message, MAX_MESSAGE_LENGTH, "%s%s", prefix, suffixes[suffix_index]);
    }

    // Integrity check
    for (int i = 0; i < count; ++i) {
        if (!items[i].message || items[i].timestamp == 0 || items[i].priority <= 0 || items[i].score <= 0) {
            fprintf(stderr, "Memory integrity check failed at index %d\n", i);
            for (int j = 0; j < i; ++j) free(items[j].message);
            free(items);
            return NULL;
        }
    }

    return items;
}

void free_items(item *items, int count) {
    if (!items || count <= 0) return;

    for (int i = 0; i < count; ++i) {
        free(items[i].message);
    }
    free(items);
}
