void initializeData(long** offsets, int* keys, Record** records, size_t numRecords, size_t minStrLen, size_t maxStrLen) {
    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Null pointer provided.\n");
        return;
    }

    *offsets = malloc(numRecords * sizeof(long));
    *keys = malloc(numRecords * sizeof(int));
    *records = malloc(numRecords * sizeof(Record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < numRecords; ++i) {
        (*offsets)[i] = i * 10; // Example offset logic
        (*keys)[i] = rand() % numRecords; // Example key logic

        (*records)[i].id = (int)i;
        (*records)[i].data = malloc((maxStrLen + 1) * sizeof(char));
        if (!(*records)[i].data) {
            fprintf(stderr, "Error: Memory allocation failed for record %zu.\n", i);
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j].data);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            return;
        }

        if (generateRandomString((*records)[i].data, rand() % (maxStrLen - minStrLen + 1) + minStrLen)) {
            fprintf(stderr, "Error: Failed to generate random string for record %zu.\n", i);
            // Free previously allocated memory
            for (size_t j = 0; j <= i; ++j) {
                free((*records)[j].data);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            return;
        }
    }

    printf("Data initialized successfully.\n");
}

void freeAllMemory(long* offsets, int* keys, Record* records, size_t numRecords) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) {
        for (size_t i = 0; i < numRecords; ++i) {
            if (records[i].data) free(records[i].data);
        }
        free(records);
    }
}

int main() {
    size_t numRecords = 5;
    size_t minStrLen = 3;
    size_t maxStrLen = 10;

    long* offsets;
    int* keys;
    Record* records;

    initializeData(&offsets, &keys, &records, numRecords, minStrLen, maxStrLen);

    // Use the data...

    freeAllMemory(offsets, keys, records, numRecords);

    return 0;
}
