#define MAX_STRING_LEN 20

typedef struct {
    int value;
    char* string;
} Record;

void generate_random_string(char** str, int min_len, int max_len) {
    *str = (char*)malloc((max_len + 1) * sizeof(char));
    if (*str == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < min_len; ++i) {
        int random_char = 'a' + rand() % ('z' - 'a' + 1);
        (*str)[i] = random_char;
    }
    for (int i = min_len; i < max_len; ++i) {
        int random_char = '0' + rand() % ('9' - '0' + 1);
        (*str)[i] = random_char;
    }
    (*str)[max_len] = '\0';
}

void manage_memory(long** offsets, int** keys, Record** records, int num_records) {
    *offsets = (long*)malloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    *keys = (int*)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return;
    }

    *records = (Record*)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand();

        generate_random_string(&(*records)[i].string, MIN_STRING_LEN, MAX_STRING_LEN);
        if ((*records)[i].string == NULL) {
            for (int j = 0; j < i; ++j) {
                free((*records)[j].string);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            fprintf(stderr, "Memory allocation failed for record strings\n");
            return;
        }

        (*records)[i].value = rand();
    }
}

void free_memory(long* offsets, int* keys, Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].string);
    }
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long* offsets;
    int* keys;
    Record* records;

    manage_memory(&offsets, &keys, &records, MAX_RECORDS);

    // Use the allocated memory...

    free_memory(offsets, keys, records, MAX_RECORDS);

    return 0;
}
