record** efficientDataHandler(int numRecords, int minStringLen, int maxStringLen, const char* password) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static EVP_CIPHER_CTX *ctx = NULL;
    static int ivLength = 16; // AES block size
    static int keyLength = 32; // 256 bits

    pthread_mutex_lock(&mutex);

    if (ctx == NULL) {
        ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            fprintf(stderr, "Failed to create cipher context\n");
            return NULL;
        }

        unsigned char* key = (unsigned char*)malloc(keyLength);
        if (!key) {
            fprintf(stderr, "Failed to allocate memory for key\n");
            EVP_CIPHER_CTX_free(ctx);
            ctx = NULL;
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        if (!RAND_bytes(key, keyLength)) {
            fprintf(stderr, "Failed to generate random bytes for key\n");
            free(key);
            EVP_CIPHER_CTX_free(ctx);
            ctx = NULL;
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        unsigned char* iv = (unsigned char*)malloc(ivLength);
        if (!iv) {
            fprintf(stderr, "Failed to allocate memory for IV\n");
            free(key);
            EVP_CIPHER_CTX_free(ctx);
            ctx = NULL;
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        if (!RAND_bytes(iv, ivLength)) {
            fprintf(stderr, "Failed to generate random bytes for IV\n");
            free(key);
            free(iv);
            EVP_CIPHER_CTX_free(ctx);
            ctx = NULL;
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
            fprintf(stderr, "Failed to initialize cipher\n");
            free(key);
            free(iv);
            EVP_CIPHER_CTX_free(ctx);
