DataStructureManager manager;

void initialize_manager() {
    pthread_mutex_init(&manager.lock, NULL);
    memset(manager.offsets, 0, sizeof(long) * MAX_RECORDS);
    memset(manager.keys, 0, sizeof(int) * MAX_RECORDS);
}

void allocate_memory() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        manager.records[i].str = malloc(MAX_STRING_LEN);
        if (!manager.records[i].str) {
            // Log memory allocation failure
            continue;
        }
        manager.records[i].metadata = malloc(sizeof(Metadata));
        if (!manager.records[i].metadata) {
            free(manager.records[i].str); // Clean up previously allocated string
            // Log memory allocation failure
            continue;
        }
    }
}

void generate_random_string(char* str, int len) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < len; i++) {
        str[i] = charset[rand() % (sizeof(charset)-1)];
    }
    str[len] = '\0';
}

void populate_records(int start_key, int num_records, int string_len) {
    pthread_mutex_lock(&manager.lock);
    for (int i = 0; i < num_records && manager.keys[start_key + i] == 0; i++) {
        manager.offsets[start_key + i] = rand() % MAX_RECORDS;
        manager.keys[start_key + i] = start_key + i;
        generate_random_string(manager.records[start_key + i].str, string_len);
        manager.records[start_key + i].value = rand();
        // Initialize metadata
    }
    pthread_mutex_unlock(&manager.lock);
}

void delete_record(int key) {
    pthread_mutex_lock(&manager.lock);
    if (key >= 0 && key < MAX_RECORDS && manager.keys[key] == key) {
        free(manager.records[key].str);
        free(manager.records[key].metadata);
        manager.offsets[key] = 0;
        manager.keys[key] = 0;
    }
    pthread_mutex_unlock(&manager.lock);
}

void cleanup_manager() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (manager.records[i].str) free(manager.records[i].str);
        if (manager.records[i].metadata) free(manager.records[i].metadata);
    }
    pthread_mutex_destroy(&manager.lock);
}
