    double value;
    char name[NAME_LENGTH];
    Status status;
} Entry;

typedef struct metadata {
    Entry* entry_ptr;
    time_t timestamp;
    int access_flag;
} Metadata;

Entry* create_entries(int *num_entries) {
    srand(time(NULL));
    Entry* entries = (Entry*)malloc(*num_entries * sizeof(Entry));
    if (!entries) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    const char* names[] = {"Alice", "Bob", "Charlie", "David", "Eve"};
    for (int i = 0; i < *num_entries; ++i) {
        entries[i].value = (double)rand() / RAND_MAX;
        snprintf(entries[i].name, NAME_LENGTH, "%s%d", names[i % sizeof(names) / sizeof(names[0])], rand());
        entries[i].status = (rand() % 2 == 0) ? ACTIVE : INACTIVE;
    }

    *num_entries = MIN(*num_entries, MAX_ENTRIES);
    return entries;
}

Metadata* create_metadata(Entry* entries, int num_entries, Metadata** metadata_ptr) {
    time_t current_time = time(NULL);
    Metadata* metadata = (Metadata*)malloc(num_entries * sizeof(Metadata));
    if (!metadata) {
        printf("Memory allocation failed\n");
        free(entries);
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        metadata[i].entry_ptr = &entries[i];
        metadata[i].timestamp = current_time + i * 3600; // Each entry has a unique timestamp
        metadata[i].access_flag = (metadata[i].entry_ptr->status == ACTIVE) ? 1 : 0;
    }

    *metadata_ptr = metadata;
    return metadata;
}

void free_memory(Entry* entries, Metadata* metadata) {
    free(entries);
    free(metadata);
}

int main() {
    int num_entries = 5;
    Entry* entries = create_entries(&num_entries);
    if (!entries) return -1;

    Metadata* metadata = create_metadata(entries, num_entries, &metadata);
    if (!metadata) {
        free_memory(entries, NULL);
        return -1;
    }

    // Use the created entries and metadata as needed

    free_memory(entries, metadata);
    return 0;
}
