#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 1024
#define MAX_NAME_LEN 64
#define LOG_FILE "system.log"

typedef enum {
    ACTIVE,
    INACTIVE
} Status;

typedef struct {
    double value;
    char name[MAX_NAME_LEN];
    Status status;
} Entry;

typedef struct {
    Entry* entry;
    time_t timestamp;
    int access_flag;
} Metadata;

void log_message(const char* level, const char* message) {
    FILE* log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s: %s\n", level, message);
        fclose(log);
    }
}

Entry* create_entry(double value, const char* name, Status status) {
    Entry* entry = malloc(sizeof(Entry));
    if (entry) {
        log_message("INFO", "Created entry");
        entry->value = value;
        strncpy(entry->name, name, MAX_NAME_LEN);
        entry->status = status;
    } else {
        log_message("ERROR", "Failed to allocate memory for entry");
    }
    return entry;
}

Metadata* create_metadata(Entry* entry) {
    Metadata* metadata = malloc(sizeof(Metadata));
    if (metadata) {
        log_message("INFO", "Created metadata");
        metadata->entry = entry;
        metadata->timestamp = time(NULL);
        metadata->access_flag = (rand() % 2 == 0) ? 1 : 0; // Random access flag
    } else {
        log_message("ERROR", "Failed to allocate memory for metadata");
    }
    return metadata;
}

void free_entry(Entry* entry) {
    if (entry) {
        log_message("INFO", "Freed entry");
        free(entry);
    }
}

void free_metadata(Metadata* metadata) {
    if (metadata) {
        log_message("INFO", "Freed metadata");
        free(metadata->entry);
        free(metadata);
    }
}

Entry** create_entries(int count, const char* names[], Status status) {
    Entry** entries = malloc(count * sizeof(Entry*));
    if (entries) {
        for (int i = 0; i < count; i++) {
            double value = ((double)rand() / RAND_MAX) * 100.0;
            entries[i] = create_entry(value, names[i], status);
        }
    } else {
        log_message("ERROR", "Failed to allocate memory for entry array");
    }
    return entries;
}

Metadata** create_metadata_array(Entry** entries, int count) {
    Metadata** metadata_array = malloc(count * sizeof(Metadata*));
    if (metadata_array) {
        for (int i = 0; i < count; i++) {
            metadata_array[i] = create_metadata(entries[i]);
        }
    } else {
        log_message("ERROR", "Failed to allocate memory for metadata array");
    }
    return metadata_array;
}

void free_entries(Entry** entries, int count) {
    for (int i = 0; i < count; i++) {
        free_entry(entries[i]);
    }
    free(entries);
}

void free_metadata_array(Metadata** metadata_array, int count) {
    for (int i = 0; i < count; i++) {
        free_metadata(metadata_array[i]);
    }
    free(metadata_array);
}

int main() {
    const char* names[] = {"Alice", "Bob", "Charlie"};
    Entry** entries = create_entries(3, names, ACTIVE);
    if (entries) {
        Metadata** metadata_array = create_metadata_array(entries, 3);
        if (metadata_array) {
            // Use the arrays as needed
            free_metadata_array(metadata_array, 3);
        }
        free_entries(entries, 3);
    }
    return 0;
}
