#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MERCHANT_LEN 256
#define MAX_TRANSACTION_TYPE 10

typedef struct {
    long timestamp;
    int transaction_type;
    float amount;
    char merchant[MAX_MERCHANT_LEN];
} Transaction;

typedef struct {
    long date;
    float total_amount;
    int transaction_count;
} DailyTotal;

typedef struct {
    char merchant[MAX_MERCHANT_LEN];
    float total_amount;
    int transaction_count;
} MerchantSummary;

typedef struct {
    DailyTotal *daily_totals;
    MerchantSummary *merchant_summaries;
    int num_merchants;
} AggregationResult;

AggregationResult* process_transactions(Transaction* transactions, int num_transactions, long start_date, long end_date) {
    // Memory allocation and initialization
    AggregationResult *result = (AggregationResult*)malloc(sizeof(AggregationResult));
    result->daily_totals = (DailyTotal*)calloc((end_date - start_date + 1), sizeof(DailyTotal));
    result->merchant_summaries = (MerchantSummary*)calloc(num_transactions, sizeof(MerchantSummary));
    result->num_merchants = num_transactions;

    // Process transactions
    for(int i = 0; i < num_transactions; i++) {
        Transaction *transaction = &transactions[i];
        if(transaction->timestamp >= start_date && transaction->timestamp <= end_date) {
            long date_key = (transaction->timestamp / 86400) + 19700101L; // Simplified date key calculation
            DailyTotal *daily_total = &result->daily_totals[date_key - start_date];
            daily_total->total_amount += transaction->amount;
            daily_total->transaction_count++;

            strcpy(result->merchant_summaries[i].merchant, transaction->merchant);
            result->merchant_summaries[i].total_amount += transaction->amount;
            result->merchant_summaries[i].transaction_count++;
        }
    }

    // Calculate averages
    for(int i = 0; i < (end_date - start_date + 1); i++) {
        if(result->daily_totals[i].transaction_count > 0) {
            result->daily_totals[i].total_amount /= result->daily_totals[i].transaction_count;
        }
    }

    for(int i = 0; i < num_transactions; i++) {
        if(result->merchant_summaries[i].transaction_count > 0) {
            result->merchant_summaries[i].total_amount /= result->merchant_summaries[i].transaction_count;
        }
    }

    return result;
}

void free_aggregation_result(AggregationResult *result, int num_transactions) {
    free(result->daily_totals);
    free(result->merchant_summaries);
    free(result);
}
```

