typedef struct packet {
    long sequence_number;
    struct packet *next;
} Packet;

typedef struct {
    long *timestamps;
    short *port_numbers;
    Packet *packet_list;
    size_t capacity;
    size_t size;
} NetworkPacketMetadata;

NetworkPacketMetadata* create_packet_metadata(size_t initial_capacity) {
    NetworkPacketMetadata *metadata = (NetworkPacketMetadata*)malloc(sizeof(NetworkPacketMetadata));
    if (!metadata) return NULL;

    metadata->timestamps = (long*)calloc(initial_capacity, sizeof(long));
    metadata->port_numbers = (short*)calloc(initial_capacity, sizeof(short));
    metadata->packet_list = NULL;
    metadata->capacity = initial_capacity;
    metadata->size = 0;

    if (!metadata->timestamps || !metadata->port_numbers) {
        free(metadata->timestamps);
        free(metadata->port_numbers);
        free(metadata);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity - 1; ++i) {
        metadata->timestamps[i] = metadata->timestamps[i + 1];
        metadata->port_numbers[i] = metadata->port_numbers[i + 1];
    }

    metadata->timestamps[initial_capacity - 1] = 0;
    metadata->port_numbers[initial_capacity - 1] = 0;

    return metadata;
}

void destroy_packet_metadata(NetworkPacketMetadata *metadata) {
    Packet *current = metadata->packet_list;
    while (current) {
        Packet *next = current->next;
        free(current);
        current = next;
    }

    free(metadata->timestamps);
    free(metadata->port_numbers);
    free(metadata);
}

void append_packets(NetworkPacketMetadata *metadata, long start_sequence, size_t count) {
    if (metadata->size + count > metadata->capacity) {
        metadata->capacity *= 2;
        metadata->timestamps = (long*)realloc(metadata->timestamps, metadata->capacity * sizeof(long));
        metadata->port_numbers = (short*)realloc(metadata->port_numbers, metadata->capacity * sizeof(short));
        if (!metadata->timestamps || !metadata->port_numbers) {
            return; // Handle memory allocation failure
        }
    }

    for (size_t i = 0; i < count; ++i) {
        Packet *new_packet = (Packet*)malloc(sizeof(Packet));
        if (!new_packet) continue;

        new_packet->sequence_number = start_sequence + i;
        new_packet->next = metadata->packet_list;
        metadata->packet_list = new_packet;
    }

    metadata->size += count;
}

void verify_integrity(NetworkPacketMetadata *metadata) {
    Packet *current = metadata->packet_list;
    while (current) {
        if (!current->next) break; // End of list
        if (current == current->next) {
            // Handle self-referencing or circular linked list
            break;
        }
        current = current->next;
    }
}
