#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORD_LENGTH 100

typedef struct {
    int value;
    char* str;
    const char* metadata;
} record;

int generate_random_string(char* buffer, int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < length - 1; ++i) {
        buffer[i] = charset[rand() % sizeof(charset)];
    }
    buffer[length - 1] = '\0';
    return 0;
}

int manage_memory(long** offsets, int** keys, record** records, char** metadata, int num_records, int min_length, int max_length) {
    srand(time(NULL));

    *offsets = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)malloc(num_records * sizeof(int));
    *records = (record*)calloc(num_records, sizeof(record));
    *metadata = (char*)malloc(MAX_RECORD_LENGTH * sizeof(char));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *metadata == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    int successful_allocations = 0;

    for (int i = 0; i < num_records; ++i) {
        (*keys)[i] = rand();
        generate_random_string((*records)[i].str, rand() % (max_length - min_length + 1) + min_length);
        (*records)[i].metadata = *metadata;
        successful_allocations++;

        if ((successful_allocations > num_records / 2) && i == num_records - 1) {
            printf("Reducing number of records due to memory constraints.\n");
            break;
        }
    }

    sprintf(*metadata, "Records allocated: %d", successful_allocations);

    return 0;
}

void free_memory(long* offsets, int* keys, record* records, char* metadata) {
    if (records != NULL) {
        for (int i = 0; records[i].str != NULL; ++i) {
            free(records[i].str);
        }
        free(records);
    }

    free(offsets);
    free(keys);
    free(metadata);
}

int main() {
    long* offsets;
    int* keys;
    record* records;
    char* metadata;

    int num_records = 100;
    int min_length = 5;
    int max_length = 20;

    if (manage_memory(&offsets, &keys, &records, &metadata, num_records, min_length, max_length) == 0) {
        printf("Memory management successful. Metadata: %s\n", metadata);
        free_memory(offsets, keys, records, metadata);
    } else {
        printf("Memory management failed.\n");
    }

    return 0;
}
