public class EnhancedRandom
{
    private Random _random;

    public EnhancedRandom()
    {
        _random = new Random();
    }

    public float NextFloat(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value must be less than max value.");

        return (float)_random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int NextInt(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value must be less than max value.");

        return _random.Next(minValue, maxValue);
    }

    public T WeightedRandom<T>(Dictionary<T, float> weights) where T : notnull
    {
        if (weights == null || weights.Count == 0)
            throw new ArgumentException("Weights dictionary cannot be empty.");

        float totalWeight = 0;
        foreach (var weight in weights.Values)
        {
            if (weight < 0)
                throw new ArgumentException("Weights must be non-negative.");
            totalWeight += weight;
        }

        float randomValue = NextFloat(0, totalWeight);
        float cumulativeWeight = 0;

        foreach (var item in weights)
        {
            cumulativeWeight += item.Value;
            if (randomValue <= cumulativeWeight)
                return item.Key;
        }

        throw new InvalidOperationException("Failed to select a weighted value.");
    }
}

