        if (strcmp(current->user_name, user_name) == 0) {
            pthread_mutex_unlock(&data->ids_lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&data->ids_lock);
    return NULL; // Session not found
}

void remove_session(SessionData* data, long id) {
    pthread_mutex_lock(&data->ids_lock);

    // Remove session from the array, hash table, and binary tree
    // ...

    Session** current = &data->sessions;
    while (*current) {
        if ((*current)->id == id) {
            Session* to_remove = *current;
            *current = (*current)->next;

            free(to_remove->user_name);
            free(to_remove);

            break; // Remove only one session with the given ID
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&data->ids_lock);
}
