#include <string.h>
#include <pthread.h>

#define MAX_FILES 100
#define LOG_DIR "./logs/"

typedef struct {
    char* filename;
    int line_count;
} FileData;

void print_usage() {
    printf("Usage: %s [--manpage] -cs input_file [-o output_file]\n", argv[0]);
}

void* process_file(void* arg) {
    FileData* file_data = (FileData*)arg;
    FILE* file = fopen(file_data->filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", file_data->filename);
        return NULL;
    }

    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
    }
    fclose(file);

    file_data->line_count = line_count;
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        print_usage();
        return 1;
    }

    pthread_t threads[MAX_FILES];
    FileData file_data[MAX_FILES];
    int file_count = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            continue;
        }

        if (argv[i][0] == '-') {
            // Handle options
            if (strcmp(argv[i], "-cs") == 0 && i + 1 < argc) {
                // Process multiple files concurrently
                int start = file_count;
                for (int j = i + 1; j < argc && file_count < MAX_FILES; j++) {
                    file_data[file_count].filename = argv[j];
                    pthread_create(&threads[file_count], NULL, process_file, &file_data[file_count]);
                    file_count++;
                }
                i += file_count - start;
            } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
                // Handle output option
                char* output_dir = argv[++i];
                // Process output directory and handle logs
            } else {
                fprintf(stderr, "Unknown option: %s\n", argv[i]);
                print_usage();
                return 1;
            }
        } else {
            if (file_count >= MAX_FILES) {
                fprintf(stderr, "Too many files specified. Maximum limit is %d.\n", MAX_FILES);
                return 1;
            }
            file_data[file_count].filename = argv[i];
            pthread_create(&threads[file_count], NULL, process_file, &file_data[file_count]);
            file_count++;
        }
    }

    for (int i = 0; i < file_count; i++) {
        pthread_join(threads[i], NULL);
        printf("File: %s, Lines: %d\n", file_data[i].filename, file_data[i].line_count);
    }

    return 0;
}
