#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>

#define MAX_LOG_FILES 100
#define MAX_FILE_NAME_LENGTH 256

void process_logs(const char *directory_path);
void parse_log_file(const char *file_path, double *response_times, int *num_response_times);
double calculate_average(double *response_times, int num_response_times);
int detect_anomalies(double average_response_time, double threshold);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <directory_path>\n", argv[0]);
        return 1;
    }

    process_logs(argv[1]);

    return 0;
}

void process_logs(const char *directory_path) {
    DIR *dir;
    struct dirent *entry;
    double *response_times[MAX_LOG_FILES];
    int num_response_times[MAX_LOG_FILES] = {0};
    int total_num_files = 0;

    dir = opendir(directory_path);
    if (!dir) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        char file_path[MAX_FILE_NAME_LENGTH];
        snprintf(file_path, sizeof(file_path), "%s/%s", directory_path, entry->d_name);

        struct stat file_stat;
        if (stat(file_path, &file_stat) == -1 || !S_ISREG(file_stat.st_mode)) {
            continue;
        }

        response_times[total_num_files] = malloc(sizeof(double));
        if (!response_times[total_num_files]) {
            perror("malloc");
            return;
        }
        *response_times[total_num_files] = 0.0;

        parse_log_file(file_path, response_times[total_num_files], &num_response_times[total_num_files]);

        total_num_files++;
    }

    closedir(dir);

    for (int i = 0; i < total_num_files; i++) {
        double average_response_time = calculate_average(response_times[i], num_response_times[i]);
        int anomaly = detect_anomalies(average_response_time, 1.5); // Example threshold

        printf("Log file: %s\n", entry->d_name);
        printf("Average response time: %.2f ms\n", average_response_time);
        if (anomaly) {
            printf("Anomaly detected!\n");
        }

        free(response_times[i]);
    }
}

void parse_log_file(const char *file_path, double *response_times, int *num_response_times) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("fopen");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Assuming log lines contain response times in milliseconds
        double response_time;
        if (sscanf(line, "%lf", &response_time) == 1) {
            *num_response_times += 1;
            *response_times = realloc(*response_times, *num_response_times * sizeof(double));
            (*response_times)[*num_response_times - 1] = response_time;
        }
    }

    fclose(file);
}

double calculate_average(double *response_times, int num_response_times) {
    double sum = 0.0;
    for (int i = 0; i < num_response_times; i++) {
        sum += response_times[i];
    }
    return sum / num_response_times;
}

int detect_anomalies(double average_response_time, double threshold) {
    // Implement anomaly detection logic here
    return fabs(average_response_time - 100.0) > threshold; // Example condition
}
