#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

long parse_long(const char* str) {
    errno = 0;
    long result = strtol(str, NULL, 10);
    if (errno == ERANGE || (result == LONG_MIN || result == LONG_MAX)) {
        fprintf(stderr, "Invalid input for offset\n");
        exit(1);
    }
    return result;
}

int parse_int(const char* str) {
    errno = 0;
    int result = atoi(str);
    if (errno != 0) {
        fprintf(stderr, "Invalid input for key\n");
        exit(1);
    }
    return result;
}

void initialize_records(record** records, size_t num_records, long* offsets, int* keys) {
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].offset = offsets[i];
        (*records)[i].key = keys[i];
    }
}

void generate_unique_keys(int* keys, size_t num_keys, int min_value, int max_value) {
    for (size_t i = 0; i < num_keys; ++i) {
        int key;
        do {
            key = rand() % (max_value - min_value + 1) + min_value;
        } while (i > 0 && keys[i-1] == key);
        keys[i] = key;
    }
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

record** create_records(size_t num_offsets, size_t num_keys, int seed) {
    if (num_offsets > SIZE_MAX / sizeof(long)) {
        log_error("Offset array size exceeds system limit");
        return NULL;
    }
    if (num_keys > SIZE_MAX / sizeof(int)) {
        log_error("Key array size exceeds system limit");
        return NULL;
    }

    srand(seed);

    long* offsets = safe_malloc(num_offsets * sizeof(long));
    int* keys = safe_malloc(num_keys * sizeof(int));

    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = parse_long("123"); // Example input
    }

    generate_unique_keys(keys, num_keys, INT_MIN, INT_MAX);

    record** records = safe_malloc(num_records * sizeof(record*));
    for (size_t i = 0; i < num_records; ++i) {
        records[i] = safe_malloc(sizeof(record));
    }

    initialize_records(records, num_records, offsets, keys);

    free(offsets);
    free(keys);

    return records;
}

int main() {
    const char* input_offset_count = "10";
    const char* input_key_count = "5";
    int seed = 42;

    size_t num_offsets = parse_long(input_offset_count);
    size_t num_keys = parse_int(input_key_count);
    size_t num_records = (num_offsets > num_keys) ? num_offsets : num_keys;

    record** records = create_records(num_offsets, num_keys, seed);

    if (records) {
        for (size_t i = 0; i < num_records; ++i) {
            printf("Record %zu: Offset = %ld, Key = %d\n", i, records[i]->offset, records[i]->key);
            free(records[i]);
        }
        free(records);
    }

    return 0;
}
