#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

// Function to handle memory allocation with safety checks
void* safe_malloc(size_t size) {
    if (size > SIZE_MAX / 2) {
        fprintf(stderr, "Memory allocation too large.\n");
        exit(EXIT_FAILURE);
    }
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to dynamically allocate and initialize an array of offsets
long* allocate_offsets(int count) {
    if (count < 0) {
        fprintf(stderr, "Negative offset count not allowed.\n");
        exit(EXIT_FAILURE);
    }
    long* offsets = (long*)safe_malloc(count * sizeof(long));
    for (int i = 0; i < count; i++) {
        offsets[i] = (long)i * 100L; // Example initialization
    }
    return offsets;
}

// Function to dynamically allocate and initialize an array of keys with unique random values
int* allocate_keys(int count, int min_key, int max_key) {
    if (count < 0 || min_key > max_key) {
        fprintf(stderr, "Invalid key range.\n");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL)); // Seed for random number generation
    int* keys = (int*)safe_malloc(count * sizeof(int));
    for (int i = 0; i < count; i++) {
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }
    return keys;
}

// Function to allocate and initialize an array of records
record* allocate_records(int count, int min_key, int max_key) {
    if (count < 0 || min_key > max_key) {
        fprintf(stderr, "Invalid record parameters.\n");
        exit(EXIT_FAILURE);
    }
    record* records = (record*)safe_malloc(count * sizeof(record));
    for (int i = 0; i < count; i++) {
        records[i].offset = (long)i * 100L;
        records[i].key = allocate_keys(1, min_key, max_key)[0];
    }
    return records;
}

// Function to set a custom allocator
void* (*custom_allocator)(size_t) = NULL;

void* use_custom_allocator(size_t size) {
    if (custom_allocator != NULL) {
        return custom_allocator(size);
    } else {
        return safe_malloc(size);
    }
}
