    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

record* create_record_array(int size) {
    record* array = (record*)custom_allocator(sizeof(record) * size);
    for (int i = 0; i < size; i++) {
        array[i].offset = -1;
        array[i].key = -1;
    }
    return array;
}

void resize_record_array(record** array, int old_size, int new_size) {
    record* new_array = create_record_array(new_size);
    for (int i = 0; i < old_size && i < new_size; i++) {
        new_array[i] = (*array)[i];
    }
    free(*array);
    *array = new_array;
}

void thread_safe_access(record* array, int index, int value) {
    // Implement thread-safe access logic here
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < sizeof(array)/sizeof(record)) {
        array[index].offset = value;
    } else {
        fprintf(stderr, "Out-of-bounds access attempt\n");
    }
    pthread_mutex_unlock(&mutex);
}

