#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 50000

typedef struct {
    int* data;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DataArray;

void init_data_array(DataArray* arr) {
    arr->data = (int*)calloc(MAX_ELEMENTS, sizeof(int));
    if (arr->data == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    arr->count = 0;
    arr->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&arr->mutex, NULL);
}

void process_int(DataArray* arr, int value) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->count < arr->capacity) {
        arr->data[arr->count++] = value;
    } else {
        fprintf(stderr, "Error: Array is full\n");
    }
    pthread_mutex_unlock(&arr->mutex);
}

void* find_largest_integer(void* arg) {
    DataArray* arr = (DataArray*)arg;
    int largest = INT_MIN;
    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->data[i] > largest) {
            largest = arr->data[i];
        }
    }
    printf("Largest integer: %d\n", largest);
    return NULL;
}

void cleanup(DataArray* arr) {
    free(arr->data);
    pthread_mutex_destroy(&arr->mutex);
}
