        free(array->records);
        array->records = NULL;
        array->capacity = 0;
        array->size = 0;
        array->memory_usage = 0;
    }
    log_memory_usage(array);
}

int add_record(LTE_PHY_TX_ARRAY* array, LTE_PHY_TX_RECORD record) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
