typedef struct DynamicArray {
    void** data;
    size_t size;
    size_t capacity;
} DynamicArray;

void initDynamicArray(DynamicArray* array, size_t initialCapacity) {
    array->data = malloc(initialCapacity * sizeof(void*));
    if (array->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for dynamic array\n");
        exit(EXIT_FAILURE);
    }
    array->size = 0;
    array->capacity = initialCapacity;
}

void freeDynamicArray(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]);
    }
    free(array->data);
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
}

void resizeDynamicArray(DynamicArray* array, size_t newCapacity) {
    void** newData = realloc(array->data, newCapacity * sizeof(void*));
    if (newData == NULL) {
        fprintf(stderr, "Failed to reallocate memory for dynamic array\n");
        exit(EXIT_FAILURE);
    }
    array->data = newData;
    array->capacity = newCapacity;
}

void addToDynamicArray(DynamicArray* array, void* item) {
    if (array->size >= array->capacity) {
        resizeDynamicArray(array, array->capacity * 2);
    }
    array->data[array->size++] = item;
}

LTE_PHY_TX_RECORD* createLTEPHYTXRecord(int channel, long timestamp, const char* modulation) {
