            return "Invalid input: Pokemon object cannot be null";
        }

        String type = typeRetriever.getType(pokemon);
        switch (type) {
            case "Fire":
                return nameRetriever.getName(pokemon) + " is weak to Water, Rock, and Ground.";
            case "Water":
                return nameRetriever.getName(pokemon) + " is weak to Electric, Grass, and Ice.";
            case "Grass":
                return nameRetriever.getName(pokemon) + " is weak to Fire, Ice, Flying, Bug, Rock, and Steel.";
            // Add other cases
            default:
                return nameRetriever.getName(pokemon) + " has no specific weaknesses based on its type.";
        }
    }

