        // Additional management logic
    }

    public Record[] createRecords(int range, int count) {
        if (range < 1 || count <= 0) {
            throw new IllegalArgumentException("Invalid range or count for records");
        }

        Set<Integer> values = new HashSet<>();
        while (values.size() < count) {
            values.add(new Random().nextInt(range));
        }

        Record[] records = new Record[count];
        int index = 0;
        for (int value : values) {
            records[index++] = new Record(value);
        }

        return records;
    }
}
