        free(array->data);
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int append_to_array(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory for DynamicArray");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = new_element;

    pthread_mutex_unlock(&array->mutex);
    return 0;
