        for (int attempt = 1; attempt <= maxRetries; attempt++) {
            try {
                service.storeFile(file);
                return;
            } catch (IOException e) {
                if (attempt == maxRetries) throw new RuntimeException("Failed to store file after " + maxRetries + " attempts", e);
                long delay = initialDelay * (1 << (attempt - 1));
                try { Thread.sleep(delay); } catch (InterruptedException ie) {}
            }
        }
    }

