#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the cryptographic algorithm function pointers
typedef struct crypto_node {
    char* name;
    int (*init)(void*);
    void* (*operation)(void*, void*);
    void* params;
    struct crypto_node* left;
    struct crypto_node* right;
} crypto_node;

crypto_node* create_crypto_node(char* name, int (*init)(void*), void* (*operation)(void*, void*), void* params) {
    crypto_node* node = (crypto_node*)malloc(sizeof(crypto_node));
    if (node == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    node->name = strdup(name);
    node->init = init;
    node->operation = operation;
    node->params = params;
    node->left = node->right = NULL;
    return node;
}

crypto_node* insert_crypto_node(crypto_node* root, char* name, int (*init)(void*), void* (*operation)(void*, void*), void* params) {
    if (root == NULL) {
        return create_crypto_node(name, init, operation, params);
    }
    int cmp = strcmp(name, root->name);
    if (cmp < 0) {
        root->left = insert_crypto_node(root->left, name, init, operation, params);
    } else if (cmp > 0) {
        root->right = insert_crypto_node(root->right, name, init, operation, params);
    }
    return root;
}

crypto_node* search_crypto_node(crypto_node* root, char* name) {
    if (root == NULL || strcmp(name, root->name) == 0) {
        return root;
    }
    if (strcmp(name, root->name) < 0) {
        return search_crypto_node(root->left, name);
    } else {
        return search_crypto_node(root->right, name);
    }
}

void delete_crypto_node(crypto_node* node) {
    free(node->name);
    free(node);
}

void delete_crypto_tree(crypto_node* root) {
    if (root != NULL) {
        delete_crypto_tree(root->left);
        delete_crypto_tree(root->right);
        delete_crypto_node(root);
    }
}

int main() {
    crypto_node* root = NULL;
    // Example usage
    root = insert_crypto_node(root, "SHA-256", sha256_init, sha256_operation, NULL);
    root = insert_crypto_node(root, "AES-256-CBC", aes_256_cbc_init, aes_256_cbc_operation, NULL);

    crypto_node* node = search_crypto_node(root, "SHA-256");
    if (node != NULL) {
        printf("Algorithm found: %s\n", node->name);
    }

    delete_crypto_tree(root);
    return 0;
}
