#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define CONFIG_FILE "config.txt"
#define MAX_LINE_LENGTH 256

typedef struct {
    FILE *file;
    pthread_mutex_t mutex;
    int version;
} ConfigManager;

ConfigManager *init_config_manager() {
    ConfigManager *manager = (ConfigManager *)malloc(sizeof(ConfigManager));
    manager->file = fopen(CONFIG_FILE, "a+");
    if (!manager->file) {
        perror("Failed to open config file");
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->mutex, NULL);
    manager->version = 0;
    return manager;
}

void update_config(ConfigManager *manager, const char *key, const char *value) {
    pthread_mutex_lock(&manager->mutex);
    fseek(manager->file, 0, SEEK_END);
    fprintf(manager->file, "%s=%s\n", key, value);
    fflush(manager->file);
    manager->version++;
    pthread_mutex_unlock(&manager->mutex);
}

int get_config_value(ConfigManager *manager, const char *key, char *value, size_t max_length) {
    pthread_mutex_lock(&manager->mutex);
    rewind(manager->file);
    while (fgets(value, max_length, manager->file)) {
        value[strcspn(value, "\n")] = '\0';
        if (!strncmp(key, value, strlen(key))) {
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1;
}

int get_config_version(ConfigManager *manager) {
    int current_version = manager->version;
    pthread_mutex_lock(&manager->mutex);
    if (current_version != manager->version) {
        current_version = manager->version;
    }
    pthread_mutex_unlock(&manager->mutex);
    return current_version;
}

void log_config_change(ConfigManager *manager, const char *key, const char *old_value, const char *new_value) {
    pthread_mutex_lock(&manager->mutex);
    FILE *log_file = fopen("config_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "[%d] %s: %s -> %s\n", get_config_version(manager), key, old_value, new_value);
        fclose(log_file);
    }
    pthread_mutex_unlock(&manager->mutex);
}

void destroy_config_manager(ConfigManager *manager) {
    pthread_mutex_destroy(&manager->mutex);
    if (manager->file) {
        fclose(manager->file);
    }
    free(manager);
}
