void processFile(const std::string& fileName, std::forward_list<int>& myList, int insertBefore, int insertAfter, std::function<bool(int, int)> comp) {
    std::ifstream file(fileName);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << fileName << std::endl;
        return;
    }

    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        int num;
        std::vector<int> parsedNumbers;

        // Parse the line into integers
        while (iss >> num) {
            parsedNumbers.push_back(num);
        }

        for (int number : parsedNumbers) {
            auto it = myList.begin();
            while (it != myList.end() && !comp(*it, number)) {
                ++it;
            }
            myList.insert_after(it, number);
        }

        // Compute the average of the last two fields
        if (parsedNumbers.size() >= 2) {
            int average = (parsedNumbers.back() + parsedNumbers[static_cast<int>(parsedNumbers.size()) - 2]) / 2;
            auto it = myList.begin();
            while (it != myList.end() && !comp(*it, average)) {
                ++it;
            }
            myList.insert_after(it, average);
        }
    }

    // Insert after the first occurrence of insertAfter
    for (auto it = myList.begin(); it != myList.end(); ) {
        if (*it == insertAfter) {
            auto nextIt = std::next(it);
            myList.insert_after(it, insertBefore);
            it = nextIt;
        } else {
            ++it;
        }
    }

    // If not found, append at the end
    if (std::find(myList.begin(), myList.end(), insertAfter) == myList.end()) {
        myList.push_front(insertBefore);
    }

    file.close();
}
