class Logger {
public:
    enum Severity { INFO, WARNING, ERROR };

    void log(const std::string& message, Severity severity) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::ofstream file("logs.txt", std::ios_base::app);
        if (file.is_open()) {
            file << "[" << getCurrentTime() << "] " << getSeverityString(severity) << ": " << message << std::endl;
            file.close();
        }
    }

private:
    std::mutex mutex_;

    std::string getCurrentTime() {
        auto now = std::chrono::system_clock::now();
        std::time_t time = std::chrono::system_clock::to_time_t(now);
        return std::ctime(&time);
    }

    std::string getSeverityString(Severity severity) {
