#include <functional>
#include <string>

namespace RandomNumberGenerator {
    class RNG {
    public:
        RNG(size_t seed = std::random_device{}()) : gen(seed) {}

        ~RNG() {
            // Ensure all resources are properly released
        }

        template<typename T>
        static void initialize(std::vector<RNG>& rngs, size_t numThreads) {
            for (size_t i = 0; i < numThreads; ++i) {
                rngs.emplace_back(i);
            }
        }

        template<typename Distribution, typename ResultType>
        ResultType getNumber() {
            std::lock_guard<std::mutex> lock(mutex);
            return distribution(generator);
        }

    private:
        static thread_local std::mt19937 generator;
        std::uniform_int_distribution<> distribution;
        std::mutex mutex;
    };

    template<typename T>
    std::vector<RNG> RNG::rngs;

    class DistributionFactory {
    public:
        virtual ~DistributionFactory() = default;

        virtual void createDistributions(std::vector<std::function<void(RNG&)>>& creators) const = 0;
    };

    class UniformDistribution : public DistributionFactory {
    public:
        void createDistributions(std::vector<std::function<void(RNG&)>>& creators) const override {
            for (auto& creator : creators) {
                creator([](RNG& rng) { rng.distribution = std::uniform_int_distribution<>(0, 100); });
            }
        }
    };

    class NormalDistribution : public DistributionFactory {
    public:
        void createDistributions(std::vector<std::function<void(RNG&)>>& creators) const override {
            for (auto& creator : creators) {
                creator([](RNG& rng) { rng.distribution = std::normal_distribution<>(50, 10); });
            }
        }
    };
}

int main() {
    size_t numThreads = std::thread::hardware_concurrency();
    RandomNumberGenerator::RNG::initialize(RandomNumberGenerator::RNG::rngs, numThreads);

    std::vector<std::function<void(RNG&)>> creators;
    creators.emplace_back([](RNG& rng) { rng.distribution = std::uniform_int_distribution<>(0, 100); });
    RandomNumberGenerator::UniformDistribution uniformDist;
    uniformDist.createDistributions(creators);

    for (size_t i = 0; i < numThreads; ++i) {
        std::cout << "Thread " << i << " generated number: " 
                  << RandomNumberGenerator::RNG::rngs[i].getNumber<int>() << std::endl;
    }

    return 0;
}
