['```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class UserProfile
{
    public int UserId { get; set; }
    public string Name { get; set; }
    public string Email { get; set; }
}

public class SqlBulkInsertManager
{
    public static (int, List<string>) InsertUserProfiles(List<UserProfile> userProfiles, SqlConnection connection, string tableName, int maxBatchSize, IsolationLevel isolationLevel)
    {
        if (userProfiles == null || userProfiles.Count == 0) return (0, new List<string>());

        int totalInserted = 0;
        List<string> errorLog = new List<string>();

        using (SqlTransaction transaction = connection.BeginTransaction(isolationLevel))
        {
            try
            {
                foreach (var batch in GetBatches(userProfiles, maxBatchSize))
                {
                    using (SqlCommand command = new SqlCommand())
                    {
                        command.Connection = connection;
                        command.Transaction = transaction;

                        string sqlQuery = $"INSERT INTO {tableName} (UserId, Name, Email) VALUES (@UserId, @Name, @Email)";
                        command.CommandText = sqlQuery;

                        AddParameters(command, batch);

                        int affectedRows = command.ExecuteNonQuery();
                        totalInserted += affectedRows;
                    }
                }

                transaction.Commit();
            }
            catch (Exception ex)
            {
                errorLog.Add($"Error during insertion: {ex.Message}");
                try
                {
                    transaction.Rollback();
                }
                catch (Exception rollbackEx)
                {
                    errorLog.Add($"Rollback failed: {rollbackEx.Message}");
                }
            }
        }

        return (totalInserted, errorLog);
    }

    private static IEnumerable<List<UserProfile>> GetBatches(List<UserProfile> userProfiles, int batchSize)
    {
        for (int i = 0; i < userProfiles.Count; i += batchSize)
        {
            yield return userProfiles.GetRange(i, Math.Min(batchSize, userProfiles.Count - i));
        }
    }

    private static void AddParameters(SqlCommand command, List<UserProfile> batch)
    {
        foreach (var profile in batch)
        {
            command.Parameters.AddWithValue("@UserId", profile.UserId);
            command.Parameters.AddWithValue("@Name", profile.Name);
            command.Parameters.AddWithValue("@Email", profile.Email);
        }
    }
}
