const express = require('express');
const app = express();
app.use(express.json());

// Mock database for demonstration purposes
let resources = [
    { id: 1, name: 'Resource 1', version: 1, isActive: true },
    { id: 2, name: 'Resource 2', version: 2, isActive: false }
];

// Function to find a resource by ID
const findResourceById = (id) => resources.find(r => r.id === parseInt(id));

// PUT endpoint to update an existing resource
app.put('/api/resources/:id', (req, res) => {
    const { id } = req.params;
    const { name, version } = req.body;

    // Validate request body
    if (!name || !version) return res.status(400).send('Invalid request body');

    const resource = findResourceById(id);
    if (!resource) return res.status(404).send('Resource not found');

    if (resource.version !== version) return res.status(409).send('Conflict: Resource has been modified');

    // Update the resource
    resource.name = name;
    resource.version++;
    resources = [...resources.filter(r => r.id !== id), resource];

    res.status(200).send(resource);
});

// DELETE endpoint to delete a resource
app.delete('/api/resources/:id', (req, res) => {
    const { id } = req.params;

    const resource = findResourceById(id);
    if (!resource) return res.status(404).send('Resource not found');

    if (!resource.isActive) return res.status(400).send('Cannot delete an active resource');

    // Simulate deletion by marking it as inactive
    resource.isActive = false;

    const newResource = { id: resource.id, name: 'Default Resource', version: 1, isActive: true };
    resources.push(newResource);

    res.status(200).send(newResource);
});

app.listen(3000, () => console.log('Server is running on port 3000'));
