public class XmlParser
{
    private readonly object _lock = new object();
    private XmlDocument _xmlDocument;

    public void LoadXml(string xmlContent)
    {
        lock (_lock)
        {
            try
            {
                _xmlDocument = new XmlDocument();
                _xmlDocument.LoadXml(xmlContent);
            }
            catch (XmlException ex)
            {
                Log.Error("Invalid XML document", ex);
                throw;
            }
        }
    }

    public List<XmlNode> ParseElements(string xpathPattern, bool enableOptimizations)
    {
        lock (_lock)
        {
            try
            {
                var nodeList = _xmlDocument.SelectNodes(xpathPattern);

                if (nodeList == null || nodeList.Count == 0)
                    return new List<XmlNode>();

                return nodeList.Cast<XmlNode>().ToList();
            }
            catch (Exception ex)
            {
                Log.Error("Error parsing XML elements", ex);
                throw;
            }
        }
    }

    public void UpdateSchema(string schemaContent)
    {
        lock (_lock)
        {
            try
            {
                _xmlDocument.Schemas.Add(null, null, schemaContent);
            }
            catch (XmlSchemaValidationException ex)
            {
                Log.Error("Invalid XML schema", ex);
                throw;
            }
        }
    }

