import java.io.*;
import java.util.logging.Logger;

public class StateLoader {
    private static final Logger logger = Logger.getLogger(StateLoader.class.getName());
    private static final String CONFIG_FILE_PATH = "config.properties";
    private static int expectedVersion;

    static {
        loadExpectedVersion();
    }

    public static MoSTState loadState(String filePath) {
        File file = new File(filePath);
        ObjectInputStream ois = null;
        try (FileInputStream fis = new FileInputStream(file)) {
            ois = new ObjectInputStream(fis);
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                MoSTState state = (MoSTState) obj;
                validateVersion(state.getVersion());
                return state;
            }
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Failed to load state from file: " + filePath);
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException e) {
                    logger.warning("Failed to close ObjectInputStream");
                }
            }
        }
        return null;
    }

    private static void validateVersion(int version) {
        if (version != expectedVersion) {
            logger.warning("Loaded state is not at the expected version: " + version);
        } else {
            logger.info("Loaded state is at the expected version: " + version);
        }
    }

    private static void loadExpectedVersion() {
        try (InputStream input = new FileInputStream(CONFIG_FILE_PATH)) {
            Properties prop = new Properties();
            prop.load(input);
            expectedVersion = Integer.parseInt(prop.getProperty("expected.version", "-1"));
        } catch (IOException e) {
            logger.severe("Failed to load expected version from config file");
            expectedVersion = -1;
        }
    }
}
