      console.error(`Failed to load module at ${path}:`, error);
      throw error;
    }
  }

  async function runTestsInModule(module, testLabel) {
    for (const [testName, testFunction] of Object.entries(module)) {
      if (typeof testFunction === 'function') {
        const startTime = performance.now();
        await testFunction();
        const endTime = performance.now();
        console.log(`${label} - ${modulePath} - ${testLabel} - ${testName} - Duration: ${endTime - startTime}ms`);
        blueslip.reset();
      }
    }
  }

  async function runTestsForModules(paths) {
    for (const path of paths) {
      const module = await loadModule(path);
      await runTestsInModule(module, path.split('/').pop());
    }
  }

  return runTestsForModules(modulePath).catch(console.error);
}
