['```javascript
const eventRegexes = {
  Old Testament: /(?:Creation|Flood|Exodus)/gi,
  New Testament: /(?:Cross|Ascension)/gi
};

const punctuationToRemove = /[.,!?]/g;

function processDocuments(documents, config) {
  const results = {};
  const startTimes = {};

  async function processDocument(docId, text) {
    try {
      startTimes[docId] = Date.now();
      let matches = [];

      Object.keys(eventRegexes).forEach(testament => {
        let match;
        while ((match = eventRegexes[testament].exec(text)) !== null) {
          const exactText = match[0].replace(punctuationToRemove, '');
          if (config.ignoreWords.includes(exactText.toLowerCase())) continue;
          matches.push({
            documentId: docId,
            textSegment: exactText,
            timestamp: match.index
          });
        }
      });

      results[docId] = {
        events: matches,
        processingTime: Date.now() - startTimes[docId]
      };
    } catch (error) {
      console.error(`Error processing document ${docId}:`, error);
    }
  }

  const promises = documents.map((text, index) => processDocument(index, text));

  return Promise.all(promises).then(() => results);
}

// Example usage:
const config = {
  ignoreWords: ['and', 'but'],
  maxProcessingTime: 1000
};

const largeDocuments = [
  "In the beginning, God created the heavens and the earth.",
  "He brought water to a boil on the cross."
];

processDocuments(largeDocuments, config).then(results => {
  console.log(JSON.stringify(results, null, 2));
});
```

