// Configuration object structure
const menuConfig = [
  {
    text: 'Home',
    link: '/',
    iconClass: 'fas fa-home',
    role: 'navigation',
    state: 'active',
    subMenu: [
      { text: 'Sub1', link: '/sub1' },
      { text: 'Sub2', link: '/sub2' }
    ]
  },
  {
    text: 'About',
    link: '/about',
    iconClass: 'fas fa-info-circle',
    role: 'navigation'
  }
];

// Function to generate navigation menu
function generateNavigationMenu(config) {
  // Validate input
  if (!Array.isArray(config)) return '';

  // Initialize HTML string
  let html = `<nav role="navigation" aria-label="Main Menu">`;

  // Generate menu items
  config.forEach(item => {
    html += `
      <div class="menu-item">
        ${item.iconClass ? `<i class="${item.iconClass}"></i>` : ''}
        <a href="${item.link}" role="${item.role}" ${item.state ? `aria-current="${item.state}"` : ''}>
          ${item.text}
        </a>
        ${item.subMenu && item.subMenu.length > 0 ? `
          <button class="toggle-button" aria-label="Toggle Submenu">+</button>
          <div class="sub-menu">
            ${generateSubMenu(item.subMenu)}
          </div>
        ` : ''}
      </div>
    `;
  });

  html += '</nav>';

  return html;
}

// Helper function to generate submenu
function generateSubMenu(subMenuConfig) {
  let subHtml = '';
  subMenuConfig.forEach(subItem => {
    subHtml += `
      <a href="${subItem.link}" role="menuitem">
        ${subItem.text}
      </a>
    `;
  });
  return subHtml;
}

// Generate and log navigation menu HTML
console.log(generateNavigationMenu(menuConfig));
