    let totalBytesCopied = 0;

    for (const chunk of chunks) {
        if (totalBytesCopied >= numBytes) break;

        const bytesToCopy = Math.min(chunk.length, numBytes - totalBytesCopied);
        buffer.copy(chunk, totalBytesCopied, offset);
        totalBytesCopied += bytesToCopy;
        offset += bytesToCopy;
