    if (size > MAX_BUFFER_SIZE) throw new Error('Size exceeds maximum allowed');
    return Buffer.alloc(size * 4); // Assuming 32-bit integers
}

// Record structure definition
class Record {
    constructor(offset, key) {
        this.offset = offset;
        this.key = key;
    }
}

// Function to add a new record
function addRecord(offset, key) {
    if (recordArray.length === recordArray.maxSize) resizeRecordArray(RECORD_GROWTH_FACTOR);

    let existingKeyIndex = findRecordByOffset(offset);
    if (existingKeyIndex !== -1) {
        // Handle duplicate keys using retry mechanism
        return;
    }

    recordArray.push(new Record(offset, key));
}

// Function to find a record by its int key
function findRecordByKey(key) {
    for (let i = 0; i < recordArray.length; i++) {
        if (recordArray[i].key === key) {
            return recordArray[i].offset;
        }
    }

    return -1; // Special value indicating non-existent key
}

// Function to resize records array
function resizeRecordArray(factor) {
    const newSize = recordArray.length * factor;
    if (newSize > MAX_BUFFER_SIZE) throw new Error('Resized array exceeds maximum allowed');

    let newArray = Buffer.alloc(newSize * 12); // Adjust size based on Record structure

    for (let i = 0; i < recordArray.length; i++) {
        newArray[i * 12] = recordArray[i].offset;
        newArray[i * 12 + 8] = recordArray[i].key;
    }

    recordArray = newArray;
}

// Function to sort records based on offsets
function sortRecords() {
    recordArray.sort((a, b) => a.offset - b.offset);
}

// Sliding window approach for managing memory fragmentation
class SlidingWindow {
    constructor(initialSize) {
        this.size = initialSize;
        this.window = new Array(this.size).fill(null);
    }

    add(element) {
        if (this.window.every(x => x !== null)) {
            // Resize or handle overflow
        }

        for (let i = 0; i < this.size - 1; i++) {
            this.window[i] = this.window[i + 1];
        }

        this.window[this.size - 1] = element;
    }
}

// Function to monitor memory usage and detect leaks
