// LoadJSModule.js
const LoadJSModule = (function() {
    const scriptCache = {};
    const errorCount = 0;
    const maxErrors = 5;

    function loadScript(url, callback) {
        if (scriptCache[url]) {
            callback();
        } else {
            const script = document.createElement('script');
            script.src = url;
            script.onload = () => {
                scriptCache[url] = true;
                callback();
            };
            script.onerror = () => {
                errorCount++;
                console.error(`Failed to load script: ${url}`);
                if (errorCount >= maxErrors) {
                    alert('Maximum number of errors reached. Application may not function properly.');
                }
            };
            document.head.appendChild(script);
        }
    }

    return {
        loadModule: function(urls, callback) {
            let loadedScripts = 0;
            urls.forEach(url => {
                loadScript(url, () => {
                    loadedScripts++;
                    if (loadedScripts === urls.length) {
                        callback();
                    }
                });
            });
        },
        clearCache: function() {
            scriptCache = {};
        }
    };
})();

// Usage example
const moduleUrls = ['script1.js', 'script2.js', 'third-party-library.js'];
LoadJSModule.loadModule(moduleUrls, () => {
    console.log('All scripts loaded successfully.');
});
