#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/pem.h>
#include <openssl/rsa.h>
#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>
#include <random>
#include <chrono>

namespace CryptoNamespace {
    class CryptoRandomGenerator {
    private:
        EVP_CIPHER_CTX* aesCtx;
        EVP_CIPHER_CTX* camelliaCtx;
        MD5_CTX md5Ctx;
        SHA256_CTX sha256Ctx;
        RSA* rsa;
        std::mt19937 rng;

        void initCryptography() {
            // Initialize AES and Camellia contexts
            aesCtx = EVP_CIPHER_CTX_new();
            camelliaCtx = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(aesCtx, EVP_aes_256_cbc(), NULL, NULL, NULL);
            EVP_EncryptInit_ex(camelliaCtx, EVP_camellia_128_ecb(), NULL, NULL, NULL);

            // Initialize MD5 and SHA-256 contexts
            MD5_Init(&md5Ctx);
            SHA256_Init(&sha256Ctx);

            // Initialize RSA with SHA1
            rsa = RSA_new();
            RSA_set0_key(rsa, BN_new(), BN_new(), NULL);
            RSA_sign(NID_sha1, (const unsigned char*)"data", strlen("data"), NULL, 0, RSA_PKCS1_PADDING);
        }

    public:
        CryptoRandomGenerator() : rng(std::random_device{}()) {
            initCryptography();
        }

        ~CryptoRandomGenerator() {
            EVP_CIPHER_CTX_free(aesCtx);
            EVP_CIPHER_CTX_free(camelliaCtx);
            MD5_Init(&md5Ctx);
            SHA256_Init(&sha256Ctx);
            RSA_free(rsa);
        }

        float generateFloat(float minVal, float maxVal) {
            if (minVal > maxVal) std::swap(minVal, maxVal);
            return minVal + static_cast<float>(rng()) / RAND_MAX * (maxVal - minVal);
        }

        int generateInt(int minVal, int maxVal) {
            if (minVal > maxVal) std::swap(minVal, maxVal);
            return minVal + rng() % (maxVal - minVal);
        }

        bool areUnique(const std::vector<std::string>& strings) {
            std::set<std::string> uniqueStrings(strings.begin(), strings.end());
            return uniqueStrings.size() == strings.size();
        }
    };
}

int main() {
    CryptoNamespace::CryptoRandomGenerator cryptoGen;
    float randomFloat = cryptoGen.generateFloat(1.0f, 5.0f);
    int randomInt = cryptoGen.generateInt(10, 20);
    std::vector<std::string> strings = {"apple", "banana", "cherry"};
    bool areUnique = cryptoGen.areUnique(strings);

    std::cout << "Random Float: " << randomFloat << std::endl;
    std::cout << "Random Int: " << randomInt << std::endl;
    std::cout << "Are Strings Unique: " << (areUnique ? "Yes" : "No") << std::endl;

    return 0;
}
