class ThemeCache {
private:
    std::unordered_map<std::string, int> themeReferences;
    std::unordered_map<std::string, std::shared_ptr<Bitmap>> themeBitmaps;
    std::mutex cacheMutex;
    std::condition_variable purgeCondition;
    std::atomic<bool> running;

public:
    ThemeCache() : running(true) {
        // Initialize default configuration and start background purging thread
        initializeDefaultConfig();
        startPurgeThread();
    }

    ~ThemeCache() {
        running = false;
        purgeCondition.notify_all();
        purgeThread.join();
    }

    void loadTheme(const std::string& themePath) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (themeBitmaps.find(themePath) == themeBitmaps.end()) {
            auto bitmap = parsePNGFile(themePath);
            themeBitmaps[themePath] = bitmap;
            themeReferences[themePath] = 1;
        } else {
            ++themeReferences[themePath];
        }
    }

    void unloadTheme(const std::string& themePath) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (themeReferences.find(themePath) != themeReferences.end()) {
            --themeReferences[themePath];
            if (themeReferences[themePath] == 0) {
                themeBitmaps.erase(themePath);
                themeReferences.erase(themePath);
            }
        }
    }

    void startPurgeThread() {
        purgeThread = std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(cacheMutex);
                purgeCondition.wait_for(lock, std::chrono::minutes(10), [this] { return !running || themeBitmaps.empty(); });
                if (!themeBitmaps.empty()) {
                    for (auto it = themeBitmaps.begin(); it != themeBitmaps.end();) {
                        if (it->second.use_count() == 1) {
                            it = themeBitmaps.erase(it);
                        } else {
                            ++it;
                        }
                    }
                }
            }
        });
    }

private:
