fn compile_with_custom_logging(files: &[&str], log_level: &str, log_format: &str) -> i32 {
    let start_time = Instant::now();
    let before_memory = get_resident_set_size();

    let mut errors = Vec::new();
    for file in files {
        if !validate_file(file) {
            eprintln!("Error: Invalid file {}", file);
            continue;
        }

        let output = Command::new("rustc")
            .arg("-o")
            .arg(format!("{}.exe", file.replace(".rs", "")))
            .arg(file)
            .output()
            .expect("Failed to execute command");

        if !output.status.success() {
            errors.push(String::from_utf8_lossy(&output.stderr).to_string());
        }
    }

    let after_memory = get_resident_set_size();
    let duration = start_time.elapsed();

    install_ice_hook();

    let log_data = format!("Compilation time: {:?}", duration);
    if before_memory.is_some() && after_memory.is_some() {
        log_data.push_str(&format!("\nMemory usage: {} -> {}", before_memory.unwrap(), after_memory.unwrap()));
    }
    if !errors.is_empty() {
        log_data.push_str(&format!("\nErrors:\n{}", errors.join("\n")));
    }

    thread::spawn(move || {
        for _ in 0..3 {
            match send_log_to_service(&log_data) {
                Ok(_) => break,
                Err(e) => eprintln!("Error sending log: {}", e),
            }
        }
    });

    rustc_driver::catch_with_exit_code(|args| {
        if !errors.is_empty() {
            early_error(
                DiagnosticBuilder::new(E0001, SyntaxContext::empty())
                    .with_span(span)
                    .with_message("Compilation failed")
                    .with_note(format!("Errors:\n{}", errors.join("\n"))),
            );
        }
        0
    });

    log_data.push_str(&format!("\nFiles processed: {}", files.len()));
    if !errors.is_empty() {
        log_data.push_str(&format!("\nTotal errors: {}", errors.len()));
    }

    eprintln!("{}", log_data);

    0
}

