using System;
using System.Data;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class EmployeeService
{
    private readonly IDbConnection _connection;
    private readonly IMemoryCache _cache;
    private readonly ILogger<EmployeeService> _logger;
    private const int CacheDuration = 60; // in seconds

    public EmployeeService(IDbConnection connection, IMemoryCache cache, ILogger<EmployeeService> logger)
    {
        _connection = connection ?? throw new ArgumentNullException(nameof(connection));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<List<Employee>> GetEmployeeDetailsAsync(int supervisorId, int? departmentId, string jobTitle)
    {
        var cacheKey = $"Employees_{supervisorId}_{departmentId}_{jobTitle}";
        if (_cache.TryGetValue(cacheKey, out List<Employee> cachedEmployees))
        {
            _logger.LogInformation("Returning cached data for supervisor ID: {SupervisorId}", supervisorId);
            return cachedEmployees;
        }

        try
        {
            using (var command = _connection.CreateCommand())
            {
                var sql = @"
                    SELECT e.EmployeeID, e.Name, e.City, e.Address 
                    FROM Employees e
                    WHERE (@departmentId IS NULL OR e.DepartmentID = @departmentId)
                      AND (@jobTitle IS NULL OR e.JobTitle = @jobTitle)
                      AND EXISTS (SELECT 1 FROM EmployeeSupervisors es WHERE es.SupervisorID = @supervisorId AND es.EmployeeID = e.EmployeeID)";

                command.CommandText = sql;
                command.Parameters.AddWithValue("@supervisorId", supervisorId);
                command.Parameters.AddWithValue("@departmentId", departmentId.HasValue ? departmentId.Value : DBNull.Value);
                command.Parameters.AddWithValue("@jobTitle", string.IsNullOrEmpty(jobTitle) ? DBNull.Value : jobTitle);

                var employees = new List<Employee>();
                using (var reader = await command.ExecuteReaderAsync())
                {
                    while (await reader.ReadAsync())
                    {
                        employees.Add(new Employee
                        {
                            EmployeeID = reader.GetInt32(0),
                            Name = reader.GetString(1),
                            City = reader.GetString(2),
                            Address = reader.GetString(3)
                        });
                    }
                }

                if (employees.Count == 0)
                {
                    _logger.LogWarning("No matching records found for supervisor ID: {SupervisorId}", supervisorId);
                    return new List<Employee> { new Employee { Message = "No matching records" } };
                }

                _cache.Set(cacheKey, employees, new MemoryCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(CacheDuration)
                });

                return employees;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error retrieving employee details for supervisor ID: {SupervisorId}", supervisorId);
            throw;
        }
    }
}

public class Employee
{
    public int EmployeeID { get; set; }
    public string Name { get; set; }
    public string City { get; set; }
    public string Address { get; set; }
    public string Message { get; set; }
}
