<?php

class UtilityTool {
    private static $logger;
    private static $config;

    public static function setLogger($logger) {
        self::$logger = $logger;
    }

    public static function setConfig($config) {
        self::$config = $config;
    }

    public static function generateRandomString($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        $maxCharIndex = strlen($charset) - 1;
        $result = '';
        for ($i = 0; $i < $length; $i++) {
            $result .= $charset[random_int(0, $maxCharIndex)];
        }
        self::logUsage('generateRandomString', ['length' => $length, 'charset' => substr($charset, 0, 10)]);
        return $result;
    }

    public static function hashValue($value, $algorithm = 'sha256') {
        if (!in_array($algorithm, hash_algos())) {
            throw new Exception("Unsupported hashing algorithm: $algorithm");
        }
        $hash = hash($algorithm, $value);
        self::logUsage('hashValue', ['value' => substr($value, 0, 10), 'algorithm' => $algorithm]);
        return $hash;
    }

    private static function logUsage($method, $params) {
        if (self::$logger && self::$config['loggingEnabled']) {
            try {
                self::$logger->log([
                    'timestamp' => time(),
                    'class' => __CLASS__,
                    'method' => $method,
                    'params' => $params
                ]);
            } catch (Exception $e) {
                error_log("Logging failed: " . $e->getMessage());
            }
        }
    }

    public static function validateParameters($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        if (!is_int($length) || $length < 1) {
            throw new Exception('Length must be a positive integer.');
        }
        if (!is_string($charset) || strlen($charset) === 0) {
            throw new Exception('Charset must be a non-empty string.');
        }
    }

    public static function validateHashingAlgorithm($algorithm) {
        $supportedAlgorithms = ['sha256', 'md5', 'sha1'];
        if (!in_array($algorithm, $supportedAlgorithms)) {
            throw new Exception("Unsupported hashing algorithm: $algorithm. Supported algorithms are: " . implode(', ', $supportedAlgorithms));
        }
    }
}
