<?php

class OAuthManager {
    private $clients = [
        'google' => ['client_id' => 'your_google_client_id', 'client_secret' => 'your_google_client_secret'],
        'facebook' => ['client_id' => 'your_facebook_client_id', 'client_secret' => 'your_facebook_client_secret'],
        'linkedin' => ['client_id' => 'your_linkedin_client_id', 'client_secret' => 'your_linkedin_client_secret']
    ];

    private $refreshLocks = [];
    private $maxConcurrentRefreshes = 3;
    private $refreshWindow = 60;

    public function authenticate($provider, $accessToken) {
        if (!isset($this->clients[$provider])) {
            throw new Exception('Invalid provider');
        }

        try {
            $client = new GuzzleHttp\Client();
            $response = $client->get('https://graph.' . $provider . '.com/me', [
                'headers' => ['Authorization' => 'Bearer ' . $accessToken]
            ]);

            return json_decode($response->getBody(), true);
        } catch (GuzzleHttp\Exception\BadResponseException $e) {
            if ($e->getResponse()->getStatusCode() == 401) {
                return $this->refreshAccessToken($provider, $accessToken);
            }
            throw $e;
        }
    }

    private function refreshAccessToken($provider, $accessToken) {
        if (!isset($this->clients[$provider])) {
            throw new Exception('Invalid provider');
        }

        $clientId = $this->clients[$provider]['client_id'];
        $clientSecret = $this->clients[$provider]['client_secret'];

        if (isset($this->refreshLocks[$accessToken]) && count($this->refreshLocks[$accessToken]) >= $this->maxConcurrentRefreshes) {
            throw new Exception('Too many concurrent refresh attempts');
        }

        if (!isset($this->refreshLocks[$accessToken])) {
            $this->refreshLocks[$accessToken] = [];
        }

        $lockId = uniqid();
        array_push($this->refreshLocks[$accessToken], $lockId);

        try {
            sleep(1); // Simulate network delay

            $client = new GuzzleHttp\Client();
            $response = $client->post('https://graph.' . $provider . '.com/oauth2/v4/token', [
                'form_params' => [
                    'grant_type' => 'refresh_token',
                    'client_id' => $clientId,
                    'client_secret' => $clientSecret,
                    'refresh_token' => $accessToken
                ]
            ]);

            $data = json_decode($response->getBody(), true);
            return $data['access_token'];
        } catch (Exception $e) {
            unset($this->refreshLocks[$accessToken][$lockId]);
            throw $e;
        }
    }
}
