        // Other necessary fields
        Node* children[8];
        record** records;
        metadata* metadatas;
        size_t recordCount;
        size_t capacity;
    };

    Node* root;
    size_t leafCapacity;
    std::mutex memoryMutex;

public:
    Octree(size_t featureSize, size_t numLeafNodes) : root(nullptr), leafCapacity(numLeafNodes) {
        // Initialize octree with customizable parameters
        root = new Node();
        root->isLeaf = true;
        root->capacity = leafCapacity;
        root->records = new record*[leafCapacity];
        root->metadatas = new metadata[leafCapacity];
        for (size_t i = 0; i < leafCapacity; ++i) {
            root->records[i] = nullptr;
            root->metadatas[i].timestamp = 0;
            root->metadatas[i].flag = 0;
        }
    }

    ~Octree() {
        // Free all dynamically allocated memory
        delete[] root->records;
        delete[] root->metadatas;
        delete root;
    }

    void insert(int key, record* data) {
        std::lock_guard<std::mutex> lock(memoryMutex);
        if (root->recordCount >= root->capacity) {
            resizeLeaf();
        }
        root->records[root->recordCount] = data;
        root->metadatas[root->recordCount].timestamp = time(nullptr);
        ++root->recordCount;
    }

private:
    void resizeLeaf() {
        std::lock_guard<std::mutex> lock(memoryMutex);
        size_t newCapacity = root->capacity * 2;
        record** newRecords = new record*[newCapacity];
        metadata* newMetadatas = new metadata[newCapacity];

        for (size_t i = 0; i < root->recordCount; ++i) {
            newRecords[i] = root->records[i];
            newMetadatas[i] = root->metadatas[i];
        }

        delete[] root->records;
        delete[] root->metadatas;

        root->records = newRecords;
        root->metadatas = newMetadatas;
        root->capacity = newCapacity;
    }
};

int main() {
    Octree octree(10, 16);
    // Example usage
    return 0;
}
