#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000
#define TOP_METRICS 10

typedef struct {
    int id;
    double value;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    pthread_mutex_t lock;
} TransactionQueue;

typedef struct {
    double weights[TOP_METRICS];
    int ids[TOP_METRICS];
    pthread_mutex_t lock;
} MetricList;

void init_transaction_queue(TransactionQueue *queue) {
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void init_metric_list(MetricList *list) {
    for (int i = 0; i < TOP_METRICS; i++) {
        list->weights[i] = -1.0;
        list->ids[i] = -1;
    }
    pthread_mutex_init(&list->lock, NULL);
}

void add_transaction(TransactionQueue *queue, MetricList *list, Transaction transaction) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count >= MAX_TRANSACTIONS) {
        queue->count--;
        memmove(queue->transactions + 1, queue->transactions, sizeof(Transaction) * queue->count);
    }
    memcpy(&queue->transactions[0], &transaction, sizeof(Transaction));
    queue->count++;
    pthread_mutex_unlock(&queue->lock);

    pthread_mutex_lock(&list->lock);
    double weight = list->weights[TOP_METRICS - 1] + 1.0;
    for (int i = TOP_METRICS - 2; i >= 0; i--) {
        if (transaction.value * weight > list->weights[i]) {
            memmove(list->weights + i + 1, list->weights + i, sizeof(double) * (TOP_METRICS - i - 1));
            memmove(list->ids + i + 1, list->ids + i, sizeof(int) * (TOP_METRICS - i - 1));
            list->weights[i] = transaction.value * weight;
            list->ids[i] = transaction.id;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void* process_transactions(void *arg) {
    TransactionQueue *queue = (TransactionQueue*)arg;
    MetricList *list = (MetricList*)arg;

    while (1) {
        time_t now = time(NULL);
        for (int i = 0; i < queue->count; i++) {
            if (difftime(now, queue->transactions[i].timestamp) > 5) {
                pthread_mutex_lock(&queue->lock);
                memmove(queue->transactions + i, queue->transactions + i + 1, sizeof(Transaction) * (queue->count - i - 1));
                queue->count--;
                pthread_mutex_unlock(&queue->lock);
                i--;
            } else if (difftime(now, queue->transactions[i].timestamp) <= 3 && queue->count <= MAX_TRANSACTIONS) {
                add_transaction(queue, list, queue->transactions[i]);
            }
        }

        sleep(1); // Simulate processing time
    }

    return NULL;
}

int main() {
    TransactionQueue queue;
    MetricList list;

    init_transaction_queue(&queue);
    init_metric_list(&list);

    pthread_t thread;
    pthread_create(&thread, NULL, process_transactions, &queue);

    // Simulate adding transactions
    for (int i = 0; i < 1500; i++) {
        Transaction transaction = {i, rand() % 1000 / 100.0, time(NULL)};
        pthread_mutex_lock(&queue.lock);
        if (queue.count >= MAX_TRANSACTIONS) {
            queue.count--;
            memmove(queue.transactions + 1, queue.transactions, sizeof(Transaction) * queue->count);
        }
        memcpy(&queue.transactions[0], &transaction, sizeof(Transaction));
        queue.count++;
        pthread_mutex_unlock(&queue.lock);

        sleep(1); // Simulate transaction submission time
    }

    pthread_join(thread, NULL);

    return 0;
}
