const asyncReduce = (data, initialAcc, callback, errorHandler) => {
  let acc = initialAcc;
  let currentIndex = 0;

  const processNext = async () => {
    if (currentIndex >= data.length) {
      return acc;
    }

    try {
      const element = data[currentIndex++];
      const updatedAcc = await callback(acc, element);
      return updatedAcc;
    } catch (error) {
      errorHandler(error, { index: currentIndex - 1, element: data[currentIndex - 1] });
      return processNext();
    }
  };

  return processNext();
};

// Example usage
const data = [1, 2, 3, 4, 5];
const initialAcc = 0;
const callback = async (acc, element) => {
  if (typeof element === 'number') {
    return acc + element;
  } else {
    throw new Error('Invalid element type');
  }
};

const errorHandler = (error, context) => {
  console.error(`Error at index ${context.index}:`, error);
};

(async () => {
  try {
    const result = await asyncReduce(data, initialAcc, callback, errorHandler);
    console.log('Final accumulated value:', result);
  } catch (error) {
    console.error('Unhandled error:', error);
  }
})();
```

This code snippet defines an `asyncReduce` function that processes an array of mixed data types asynchronously. It uses a recursive approach to handle each element and calls the provided callback for updating the accumulator. Errors are caught and logged using the specified error handler, which can be customized by the user. The example usage demonstrates how to call this function with a sample dataset and handle errors gracefully."]

