#include <zip.h>

int create_zip_archive(const char* directory_path, const char* output_file_name, int compression_level, const char** exclusion_list, size_t exclusion_count) {
    zip_t *zip = zip_open(output_file_name, ZIP_CREATE | ZIP_TRUNCATE, NULL);
    if (!zip) {
        fprintf(stderr, "Failed to create zip archive: %s\n", zip_strerror(zip));
        return -1;
    }

    DIR *dir = opendir(directory_path);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", strerror(errno));
        zip_close(zip);
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char path[4096];
        snprintf(path, sizeof(path), "%s/%s", directory_path, entry->d_name);

        if (is_excluded(entry->d_name, exclusion_list, exclusion_count)) continue;

        struct stat file_stat;
        if (stat(path, &file_stat) != 0) {
            fprintf(stderr, "Failed to get file status: %s\n", strerror(errno));
            continue;
        }

        if (S_ISREG(file_stat.st_mode) && is_jpeg_file(entry->d_name)) {
            zip_source_t *source = zip_source_file(zip, path, 0, 0);
            if (!source) {
                fprintf(stderr, "Failed to create source for file: %s\n", strerror(errno));
                continue;
            }

            int err;
            if ((err = zip_file_add(zip, entry->d_name, source, ZIP_FL_ENC_GUESS | compression_level)) < 0) {
                fprintf(stderr, "Failed to add file to archive: %s\n", zip_strerror(err));
                zip_source_free(source);
                continue;
            }
        } else if (S_ISDIR(file_stat.st_mode)) {
            // Recursively process subdirectories
            char new_dir[4096];
            snprintf(new_dir, sizeof(new_dir), "%s/%s", directory_path, entry->d_name);
            create_zip_archive(new_dir, output_file_name, compression_level, exclusion_list, exclusion_count);
        }
    }

    closedir(dir);
    int err = zip_close(zip);
    if (err < 0) {
        fprintf(stderr, "Failed to close zip archive: %s\n", zip_strerror(err));
        return -1;
    }

    return 0;
}

int is_excluded(const char* name, const char** exclusion_list, size_t exclusion_count) {
    for (size_t i = 0; i < exclusion_count; ++i) {
        if (strcmp(name, exclusion_list[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

int is_jpeg_file(const char* name) {
    size_t len = strlen(name);
    if (len >= 4 && strcmp(&name[len - 4], ".jpg") == 0) {
        return 1;
    } else if (len >= 5 && strcmp(&name[len - 5], ".jpeg") == 0) {
        return 1;
    }
    return 0;
}

int main(int argc, char* argv[]) {
    // Parse command-line arguments
    const char* directory_path = "path/to/directory";
    const char* output_file_name = "output.zip";
    int compression_level = Z_DEFAULT_COMPRESSION;
    const char* exclusion_list[] = {"exclude1", "exclude2"};
    size_t exclusion_count = sizeof(exclusion_list) / sizeof(exclusion_list[0]);

    // Create zip archive
    if (create_zip_archive(directory_path, output_file_name, compression_level, exclusion_list, exclusion_count) != 0) {
        fprintf(stderr, "Failed to create zip archive\n");
        return -1;
    }

    return 0;
}
```

