#define MAX_COMMANDS 100
#define MAX_COMMAND_LENGTH 256
#define MAX_RETRIES 3
#define MAX_PROCESSES 5

typedef struct {
    int success;
    double execution_time;
} CommandResult;

int execute_commands_in_background(char **commands, int num_commands, FILE *log_file) {
    pid_t pids[MAX_PROCESSES] = {0};
    int completed_commands = 0;
    time_t start_time, end_time;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_NOCLDSTOP;
    if (sigaction(SIGCHLD, &sa, NULL) == -1) {
        perror("Failed to ignore SIGCHLD");
        return 0;
    }

    for (int i = 0; i < num_commands; i++) {
        int free_slot = -1;
        time(&start_time);

        for (int j = 0; j < MAX_PROCESSES; j++) {
            if (pids[j] == 0) {
                free_slot = j;
                break;
            }
        }

        if (free_slot != -1) {
            pids[free_slot] = fork();
            if (pids[free_slot] == -1) {
                perror("Fork failed");
                return 0;
            } else if (pids[free_slot] == 0) {
                execl("/bin/sh", "sh", "-c", commands[i], NULL);
                perror("Exec failed");
                _exit(EXIT_FAILURE);
            }
        }

        while (completed_commands < num_commands && free_slot == -1) {
            int status;
            pid_t pid = wait(&status);
            if (pid == -1) {
                perror("Wait failed");
                return 0;
            } else if (WIFEXITED(status)) {
                time(&end_time);
                completed_commands++;
                // Log completion time
                fprintf(log_file, "Command completed: %s at %ld\n", commands[completed_commands - 1], end_time);
            }
        }
    }

    while (completed_commands < num_commands) {
        int status;
        pid_t pid = wait(&status);
        if (pid == -1) {
            perror("Wait failed");
            return 0;
        } else if (WIFEXITED(status)) {
            time(&end_time);
            completed_commands++;
            // Log completion time
            fprintf(log_file, "Command completed: %s at %ld\n", commands[completed_commands - 1], end_time);
        }
    }

    int all_successful = 1;
    for (int i = 0; i < num_commands; i++) {
        // Simulate command result checking and logging
        if (rand() % 2 == 0) {
            fprintf(log_file, "Command %d failed\n", i);
            all_successful = 0;
        }
    }

    return all_successful;
}
