NFAPI_CRC_INDICATION_PDU_T** allocate_and_populate_array(int dimensions[], int* num_elements) {
    srand(time(NULL));
    *num_elements = 1;
    for (int i = 0; i < dimensions[0]; i++) {
        *num_elements *= dimensions[i];
    }

    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(dimensions[0] * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) return NULL;

    for (int i = 1; i < dimensions[0]; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(dimensions[i] * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            // Handle allocation failure
            for (int j = 0; j < i; j++) free(array[j]);
            free(array);
            return NULL;
        }
    }

    int tag = 1;
    for (int i = 0; i < *num_elements; i++) {
        array[dimensions[1] - 1][i].RX_UE_INFORMATION_TAG = tag++;
        array[dimensions[1] - 1][i].RNTI = rand() % 65536;
        array[dimensions[1] - 1][i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[dimensions[1] - 1][i].CRCFLAG = rand() % 2;
    }

    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T** array, int dimensions[]) {
    for (int i = dimensions[0] - 1; i >= 0; i--) {
        free(array[i]);
    }
    free(array);
}

