                   array[dimensions[1] - 1][i].CRC_INDICATION_REL8_TAG,
                   array[dimensions[1] - 1][i].CRCFLAG);
        }
        free_array(array, dimensions);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
