#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* initialize_records(const char* filename, int min_val, int max_val) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t num_entries = file_size / sizeof(long); // Assuming each line is a long value
    long* offsets = (long*)malloc(num_entries * sizeof(long));
    int* keys = (int*)malloc(num_entries * sizeof(int));

    if (!offsets || !keys) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        fread(&offsets[i], sizeof(long), 1, file);
        keys[i] = offsets[i]; // Assuming key is the same as offset for simplicity
    }
    fclose(file);

    int* unique_keys = NULL;
    size_t unique_count = 0;
    int* key_map = (int*)malloc(num_entries * sizeof(int));

    if (!key_map) {
        perror("Failed to allocate memory");
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        int key = keys[i];
        bool is_unique = true;
        for (size_t j = 0; j < unique_count; ++j) {
            if (unique_keys[j] == key) {
                is_unique = false;
                break;
            }
        }
        if (is_unique) {
            unique_keys = realloc(unique_keys, (unique_count + 1) * sizeof(int));
            unique_keys[unique_count++] = key;
            key_map[i] = unique_count - 1;
        } else {
            key_map[i] = -1; // Mark as non-unique
        }
    }

    record* records = (record*)malloc(unique_count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory");
        free(offsets);
        free(keys);
        free(key_map);
        free(unique_keys);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < unique_count; ++i) {
        records[i].value = min_val + rand() % (max_val - min_val + 1);
    }

    free(offsets);
    free(keys);
    free(key_map);
    return records;
}
