using System;
using System.Diagnostics;
using System.IO;
using System.Threading;

public class WebAppLauncher
{
    private static readonly object _lock = new object();

    public Process LaunchWebApplication(string directoryPath, string applicationName)
    {
        // Check for web.config file
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            return null;
        }

        lock (_lock)
        {
            try
            {
                // Ensure the directory exists
                Directory.CreateDirectory(directoryPath);

                // Start process using ProcessStartInfo
                ProcessStartInfo startInfo = new ProcessStartInfo
                {
                    FileName = Path.Combine(directoryPath, applicationName),
                    WorkingDirectory = directoryPath,
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                // Launch the process
                Process process = new Process { StartInfo = startInfo };
                process.Start();

                // Log successful launch
                Log($"Successfully launched application '{applicationName}' in directory '{directoryPath}'.");

                return process;
            }
            catch (Exception ex)
            {
                // Handle exceptions and log errors
                Log($"Failed to launch application '{applicationName}' in directory '{directoryPath}': {ex.Message}");
                return null;
            }
        }
    }

    private static void Log(string message)
    {
        // Implement logging logic here, e.g., writing to a file or console
        Console.WriteLine(message);
    }
}
