    if (settings->password == NULL || strlen(settings->password) == 0) return ERROR_INVALID_PASSWORD;
    return 0;
}

int validateNetworkConnection(NetworkConnection* connection, int maxRetries, double backoffFactor) {
    int retries = 0;
    while (!connection->active && retries < maxRetries) {
        // Simulate network connection attempt
        if (rand() % 2 == 0) {
            connection->active = 1;
            break;
        }
        retries++;
        double delay = pow(backoffFactor, retries);
        sleep(delay);
    }
    if (!connection->active) return ERROR_CONNECTION_FAILED;
    // Check load and resilience
    if (connection->load > 90 || connection->resilience < 2) {
        printf("Network over capacity or low resilience\n");
        return ERROR_CONNECTION_FAILED;
    }
    return 0;
}

