void evictCache();

NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateArray(int N) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    pthread_mutex_lock(&mutex);
    if (N > MAX_CACHE_SIZE) {
        evictCache();
    }
    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        // Handle allocation failure
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    RX_UE_INFORMATION_TAG *ueTags = (RX_UE_INFORMATION_TAG*)malloc(N * sizeof(RX_UE_INFORMATION_TAG));
    if (!ueTags) {
        free(array);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    int numTags = 0;
    if (fetchUEInfo(ueTags, &numTags) != 0) {
        free(array);
        free(ueTags);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    for (int i = 0; i < N; i++) {
        array[i].CRCFLAG = rand();
        // Populate other fields as per the structure definition
    }

    free(ueTags); // Free temporary buffer after use
    pthread_mutex_unlock(&mutex);
    return array;
}
