#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024

typedef struct {
    int id;
    time_t timestamp;
    unsigned char flags;
    unsigned char payload[256];
} Packet;

Packet *packet_pool[MAX_PACKETS];
int packet_count = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* custom_malloc(size_t size) {
    // Implement a custom allocator here
    return malloc(size);
}

void custom_free(void* ptr) {
    // Free memory using the appropriate method
    free(ptr);
}

Packet* allocate_packet(int id, time_t timestamp, unsigned char flags, const unsigned char* payload, size_t payload_size) {
    Packet* packet = (Packet*)custom_malloc(sizeof(Packet));
    if (!packet) return NULL;

    packet->id = id;
    packet->timestamp = timestamp;
    packet->flags = flags;
    memcpy(packet->payload, payload, payload_size);

    pthread_mutex_lock(&pool_mutex);
    if (packet_count < MAX_PACKETS) {
        packet_pool[packet_count++] = packet;
    } else {
        custom_free(packet);
    }
    pthread_mutex_unlock(&pool_mutex);

    return packet;
}

void free_packets() {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < packet_count; i++) {
        custom_free(packet_pool[i]);
    }
    packet_count = 0;
    pthread_mutex_unlock(&pool_mutex);
}

Packet* get_packet_by_index(int index) {
    if (index < 0 || index >= packet_count) return NULL;

    pthread_mutex_lock(&pool_mutex);
    Packet* packet = packet_pool[index];
    pthread_mutex_unlock(&pool_mutex);

    return packet;
}

int get_total_packets() {
    int count;
    pthread_mutex_lock(&pool_mutex);
    count = packet_count;
    pthread_mutex_unlock(&pool_mutex);
    return count;
}
