MessageBroker* create_message_broker(int max_queues) {
    if (max_queues <= 0) {
        fprintf(stderr, "Invalid max_queues value: %d\n", max_queues);
        return NULL;
    }

    MessageBroker *broker = malloc(sizeof(MessageBroker));
    if (!broker) {
        perror("Failed to allocate memory for message broker");
        return NULL;
    }

    broker->max_queues = max_queues;
    broker->current_size = INITIAL_QUEUE_SIZE < max_queues ? INITIAL_QUEUE_SIZE : max_queues;

    broker->queue_ids = malloc(broker->current_size * sizeof(char *));
    if (!broker->queue_ids) {
        perror("Failed to allocate memory for queue IDs");
        free(broker);
        return NULL;
    }

    memset(broker->queue_ids, 0, broker->current_size * sizeof(char *));

    broker->metadata = malloc(broker->current_size * sizeof(QueueMetadata));
    if (!broker->metadata) {
        perror("Failed to allocate memory for queue metadata");
        free(broker->queue_ids);
        free(broker);
        return NULL;
    }

    memset(broker->metadata, 0, broker->current_size * sizeof(QueueMetadata));

    pthread_mutex_init(&broker->lock, NULL);

    return broker;
}

void destroy_message_broker(MessageBroker *broker) {
    if (broker) {
        for (int i = 0; i < broker->max_queues; ++i) {
            free(broker->queue_ids[i]);
        }
        free(broker->queue_ids);
        free(broker->metadata);
        pthread_mutex_destroy(&broker->lock);
        free(broker);
    }
}

