#define DEFAULT_MAX_ENTRIES 100

typedef struct cache_entry {
    char *key;
    int key_id;
    double last_access_time;
} cache_entry;

typedef struct cache_system {
    cache_entry **entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} cache_system;

cache_system* create_cache_system(size_t max_entries) {
    if (max_entries <= 0) {
        max_entries = DEFAULT_MAX_ENTRIES;
    }

    cache_system *system = malloc(sizeof(cache_system));
    if (!system) {
        fprintf(stderr, "Failed to allocate memory for cache system\n");
        return NULL;
    }

    system->capacity = max_entries;
    system->size = 0;

    system->entries = calloc(system->capacity, sizeof(cache_entry *));
    if (!system->entries) {
        free(system);
        fprintf(stderr, "Failed to allocate memory for cache entries\n");
        return NULL;
    }

    pthread_mutex_init(&system->mutex, NULL);

    return system;
}

void destroy_cache_system(cache_system *system) {
    if (!system) {
        return;
    }

    for (size_t i = 0; i < system->capacity; ++i) {
        free(system->entries[i]);
    }

    free(system->entries);
    pthread_mutex_destroy(&system->mutex);
    free(system);
}

int add_to_cache(cache_system *system, const char *key, int key_id, double access_time) {
    if (!system || !key) {
        return -1;
    }

    pthread_mutex_lock(&system->mutex);

    // Resize the cache system if necessary
    if (system->size >= system->capacity) {
        size_t new_capacity = system->capacity * 2;
        cache_entry **new_entries = realloc(system->entries, new_capacity * sizeof(cache_entry *));
        if (!new_entries) {
            pthread_mutex_unlock(&system->mutex);
            fprintf(stderr, "Failed to resize cache entries\n");
            return -1;
        }
        system->entries = new_entries;
        system->capacity = new_capacity;
    }

    // Add the new entry
    size_t index = system->size++;
    system->entries[index] = malloc(sizeof(cache_entry));
    if (!system->entries[index]) {
        pthread_mutex_unlock(&system->mutex);
        fprintf(stderr, "Failed to allocate memory for cache entry\n");
        return -1;
    }
    system->entries[index]->key = strdup(key);
    system->entries[index]->key_id = key_id;
    system->entries[index]->last_access_time = access_time;

    pthread_mutex_unlock(&system->mutex);

    return 0;
}

// Implement other functions as needed for cache management, eviction policies,
// configuration management, thread safety, error handling, and optimization.

int main() {
    // Example usage of the cache system
    cache_system *cache = create_cache_system(10);
    if (!cache) {
        return -1;
    }

    int result = add_to_cache(cache, "key1", 1, 1633072800.0); // Example timestamp
    if (result != 0) {
        destroy_cache_system(cache);
        return -1;
    }

    // Add more cache entries and perform other operations

    destroy_cache_system(cache);

    return 0;
}
