#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct hash_table {
    int size;
    int capacity;
    Record **buckets;
} HashTable;

HashTable* create_hash_table(int initial_capacity) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->size = 0;
    ht->capacity = initial_capacity;
    ht->buckets = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    return ht;
}

void resize_hash_table(HashTable *ht) {
    int new_capacity = ht->capacity * 2;
    Record **new_buckets = (Record**)calloc(new_capacity, sizeof(Record*));
    if (!new_buckets) return;

    for (int i = 0; i < ht->capacity; ++i) {
        Record *bucket = ht->buckets[i];
        while (bucket) {
            Record *next = bucket->value;
            int hash = bucket->value % new_capacity;
            bucket->next = new_buckets[hash];
            new_buckets[hash] = bucket;
            bucket = next;
        }
    }

    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->capacity = new_capacity;
}

int insert_hash_table(HashTable *ht, int key) {
    if (ht->size >= ht->capacity * 0.7) resize_hash_table(ht);

    int hash = key % ht->capacity;
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return -1;
    new_record->value = key;

    Record *current = ht->buckets[hash];
    while (current) {
        if (current->value == key) return 0; // Key already exists
        current = current->next;
    }

    new_record->next = ht->buckets[hash];
    ht->buckets[hash] = new_record;
    ++ht->size;

    return 1;
}

Record** initialize_records(int n, int m, int low, int high) {
    Record **records = (Record**)malloc(m * sizeof(Record*));
    if (!records) return NULL;

    for (int i = 0; i < m; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            // Free previously allocated records
            for (int j = 0; j < i; ++j) free(records[j]);
            free(records);
            return NULL;
        }
        records[i]->value = low + rand() % (high - low + 1);
    }

    return records;
}

void init_data_structures(int n, int m, int low, int high) {
    if (n <= 0 || m <= 0) {
        fprintf(stderr, "Invalid input: n and m must be positive integers.\n");
        return;
    }

    long *offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets array.\n");
        return;
    }

    int *keys = (int*)malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys array.\n");
        return;
    }

    Record **records = initialize_records(n, m, low, high);
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records array.\n");
        return;
    }

    HashTable *hash_table = create_hash_table(m);
    if (!hash_table) {
        free(offsets);
        free(keys);
        for (int i = 0; i < m; ++i) free(records[i]);
        free(records);
        fprintf(stderr, "Memory allocation failed for hash table.\n");
        return;
    }

    int *indexes = (int*)calloc(m, sizeof(int));
    if (!indexes) {
        destroy_hash_table(hash_table);
        free(offsets);
        free(keys);
        for (int i = 0; i < m; ++i) free(records[i]);
        free(records);
        fprintf(stderr, "Memory allocation failed for indexes array.\n");
        return;
    }

    // Initialize offsets and keys with random values
    for (int i = 0; i < n; ++i) {
        offsets[i] = rand() % 1000L;
        keys[i] = rand() % m;
        insert_hash_table(hash_table, keys[i]);
    }

    // Assign records to hash table using indexes
    for (int i = 0; i < n; ++i) {
        while (indexes[keys[i]] != 0) {
            ++indexes[keys[i]];
        }
        records[indexes[keys[i]]]->value = keys[i];
        indexes[keys[i]]++;
    }

    // Example usage of the data structures
    printf("Offsets: ");
    for (int i = 0; i < n; ++i) printf("%ld ", offsets[i]);
    printf("\n");

    printf("Keys: ");
    for (int i = 0; i < n; ++i) printf("%d ", keys[i]);
    printf("\n");

    printf("Records: ");
    for (int i = 0; i < m; ++i) printf("%d ", records[i]->value);
    printf("\n");

    // Clean up
    destroy_hash_table(hash_table);
    free(offsets);
    free(keys);
    for (int i = 0; i < m; ++i) free(records[i]);
    free(records);
    free(indexes);
}

void destroy_hash_table(HashTable *ht) {
    if (!ht) return;

    for (int i = 0; i < ht->capacity; ++i) {
        Record *bucket = ht->buckets[i];
        while (bucket) {
            Record *next = bucket->next;
            free(bucket);
            bucket = next;
        }
    }

    free(ht->buckets);
    free(ht);
}
