typedef struct {
    char *key;
    int value;
} key_value_pair;

typedef enum { READ_LOCK, WRITE_LOCK } lock_state;

int hash_function(const char *key, int table_size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % table_size;
}

void initialize_data_store(int n, key_value_pair **kv_pairs, int **hash_table, int **timestamps, lock_state **lock_table, int **usage_statistics) {
