        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *hash_table = (int *)calloc(n, sizeof(int));
    if (*hash_table == NULL) {
        free(*kv_pairs);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *timestamps = (int *)malloc(n * sizeof(int));
    if (*timestamps == NULL) {
        free(*kv_pairs);
        free(*hash_table);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
