        free(*hash_table);
        free(*timestamps);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *usage_statistics = (int *)calloc(n, sizeof(int));
    if (*usage_statistics == NULL) {
        free(*kv_pairs);
        free(*hash_table);
        free(*timestamps);
        free(*lock_table);
