    for (int i = 0; i < n; i++) {
        (*kv_pairs)[i].key = NULL;
        (*kv_pairs)[i].value = 0;
        (*timestamps)[i] = 0;
        (*lock_table)[i] = READ_LOCK;
        (*usage_statistics)[i] = 0;
    }
}

void destroy_data_store(key_value_pair *kv_pairs, int *hash_table, int *timestamps, lock_state *lock_table, int *usage_statistics) {
    free(kv_pairs);
    free(hash_table);
    free(timestamps);
    free(lock_table);
    free(usage_statistics);
}

// Example usage
int main() {
