    key_value_pair *kv_pairs;
    int *hash_table, *timestamps;
    lock_state *lock_table;
    int *usage_statistics;

    initialize_data_store(n, &kv_pairs, &hash_table, &timestamps, &lock_table, &usage_statistics);

    // Store and retrieve values
    const char *key = "example_key";
    kv_pairs[hash_function(key, n)].value = 42;
    kv_pairs[hash_function(key, n)].key = strdup(key);

    int retrieved_value = kv_pairs[hash_function(key, n)].value;

    destroy_data_store(kv_pairs, hash_table, timestamps, lock_table, usage_statistics);

    return 0;
}
