#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t size;
    pthread_mutex_t lock;
} DataStruct;

void initialize_data_struct(DataStruct* ds, size_t size) {
    ds->size = size;
    ds->offsets = (long*)malloc(size * sizeof(long));
    ds->keys = (int*)malloc(size * sizeof(int));
    ds->records = (Record*)malloc(size * sizeof(Record));

    if (!ds->offsets || !ds->keys || !ds->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&ds->lock, NULL);
}

void set_random_values(DataStruct* ds, int range_start, int range_end, int use_hardware_rand) {
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->size; ++i) {
        if (use_hardware_rand && rand_r((unsigned int*)&time(NULL)) % 2 == 0) {
            // Use hardware-based random number generator
            ds->records[i].value = get_random_value_from_hardware(range_start, range_end);
        } else {
            // Use pseudo-random number generator
            ds->records[i].value = rand() % (range_end - range_start + 1) + range_start;
        }
    }

    pthread_mutex_unlock(&ds->lock);
}

void destroy_data_struct(DataStruct* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
}

int main() {
    DataStruct ds;
    initialize_data_struct(&ds, 1000); // Example size

    set_random_values(&ds, 0, 100, 1); // Use hardware-based random numbers if available

    destroy_data_struct(&ds);

    return 0;
}
