    double *doubles = (double *)calloc(array_size, sizeof(double));
    unsigned long *timestamps = (unsigned long *)calloc(array_size, sizeof(unsigned long));
    char **strings = (char **)malloc(array_size * sizeof(char *));
    if (!doubles || !timestamps || !strings) {
        custom_error_handler("Failed to allocate memory for arrays", perror);
        free(measurements);
        return;
    }

