int create_arrays(double **d_array, char ***s_array, data_point **dp_array, size_t size) {
    *d_array = (double *)malloc(size * sizeof(double));
    if (*d_array == NULL) return -1;

    *s_array = (char **)malloc(size * sizeof(char *));
    if (*s_array == NULL) {
        free(*d_array);
        return -1;
    }

    *dp_array = (data_point *)malloc(size * sizeof(data_point));
    if (*dp_array == NULL) {
        free(*d_array);
        free(*s_array);
        return -1;
    }

    for (size_t i = 0; i < size; ++i) {
        (*dp_array)[i].value = i * 1.1;
        (*dp_array)[i].flag = i % 2;

        // Allocate memory and copy string data
        char buffer[50];
        snprintf(buffer, sizeof(buffer), "String%d", i);
        (*s_array)[i] = (char *)malloc(strlen(buffer) + 1);
        if ((*s_array)[i] == NULL) {
            for (size_t j = 0; j < i; ++j) {
                free((*s_array)[j]);
            }
            free(*d_array);
            free(*s_array);
            free(*dp_array);
            return -1;
        }
        strcpy((*s_array)[i], buffer);

        (*dp_array)[i].str = (*s_array)[i];
    }

    return 0;
}

int main() {
    size_t size = 5;
    double *d_array;
    char **s_array;
    data_point *dp_array;

    int result = create_arrays(&d_array, &s_array, &dp_array, size);
    if (result != 0) {
        printf("Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Print out the contents for verification
    for (size_t i = 0; i < size; ++i) {
        printf("Data Point %zu: Value=%.1f, String=%s, Flag=%d\n", i, dp_array[i].value, dp_array[i].str, dp_array[i].flag);
        free(dp_array[i].str); // Don't forget to free the strings
    }

    // Free all allocated memory
    free(d_array);
    free(s_array);
    free(dp_array);

    return EXIT_SUCCESS;
}
