    long max_offset;
    long min_offset;
    double average_offset;
} metadata;

typedef struct {
    // Configuration fields
} config;

// Function to initialize the data structures
void init_data_structures(long num_records, record** records, long** offsets, int** keys, metadata* metadata, config* config) {
    // Allocate memory for records, offsets, keys, and metadata
    *records = (record*)malloc(num_records * sizeof(record));
    *offsets = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)malloc(num_records * sizeof(int));

    if (*records == NULL || *offsets == NULL || *keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize random seed
    srand(time(NULL));

    // Initialize records and offsets with random values
    for (long i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % 1000; // Example range: 0 to 999
        (*offsets)[i] = ((long)rand() << 32) | (rand() & 0xFFFFFFFF); // Large offset values
    }

    // Initialize keys with random values
    for (long i = 0; i < num_records; ++i) {
        (*keys)[i] = rand() % 1000; // Example range: 0 to 999
    }

    // Calculate metadata
    long sum_offset = 0;
    long min_offset = (*offsets)[0];
    long max_offset = (*offsets)[0];
    for (long i = 0; i < num_records; ++i) {
        sum_offset += (*offsets)[i];
        if ((*offsets)[i] < min_offset) {
            min_offset = (*offsets)[i];
        }
        if ((*offsets)[i] > max_offset) {
            max_offset = (*offsets)[i];
        }
    }

    metadata->max_offset = max_offset;
    metadata->min_offset = min_offset;
    metadata->average_offset = (double)sum_offset / num_records;
}

// Function to free allocated memory
void free_data_structures(record* records, long* offsets, int* keys) {
    free(records);
    free(offsets);
    free(keys);
