int allocate_arrays(size_t size, size_t preferred_size, data_point** dp_array, double** double_array, char*** string_array, int* error_flag) {
    *dp_array = (data_point*)malloc(preferred_size * sizeof(data_point));
    *double_array = (double*)malloc(preferred_size * sizeof(double));
    *string_array = (char**)malloc(preferred_size * sizeof(char*));

    if (*dp_array == NULL || *double_array == NULL || *string_array == NULL) {
        *error_flag = 1;
        return -1;
    }

    *error_flag = 0;
    return 0;
}

void populate_arrays(size_t size, data_point** dp_array, double** double_array, char*** string_array) {
    for (size_t i = 0; i < size; i++) {
        (*dp_array)[i].value = (*double_array)[i];
        (*string_array)[i] = strdup((*dp_array)[i].str);
        (*dp_array)[i].flag = i % 2;
    }
}

void free_arrays(data_point** dp_array, double** double_array, char*** string_array) {
    for (size_t i = 0; i < size; i++) {
        free((*string_array)[i]);
    }

    free(*dp_array);
    free(*double_array);
    free(*string_array);
}

void* manage_arrays(void* arg) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    data_point* dp_array;
    double* double_array;
    char** string_array;
    int error_flag;

    size_t size = 100; // Example size
    size_t preferred_size = 200; // Preferred size

    if (allocate_arrays(size, preferred_size, &dp_array, &double_array, &string_array, &error_flag) != 0) {
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    populate_arrays(size, &dp_array, &double_array, &string_array);
    pthread_mutex_unlock(&mutex);

    // Simulate usage
    for (size_t i = 0; i < size; i++) {
        // Access dp_array[i]
    }

    free_arrays(&dp_array, &double_array, &string_array);

    pthread_mutex_destroy(&mutex);
    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    if (pthread_create(&thread1, NULL, manage_arrays, NULL) != 0) {
        return -1;
    }

    if (pthread_create(&thread2, NULL, manage_arrays, NULL) != 0) {
        return -1;
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
