        if (existingNode) {
            // Overwrite existing data
            existingNode->value = doubleArray[i];
            accessCount[i]++;
        } else {
            // Handle duplicate entries and update access count
            nodeArray[i]->value = doubleArray[i];
            accessCount[i]++;
            hashTableInsert(&hashTable, &hashTableSize, filePathArray[i], *nodeArray[i]);
        }
    }

    // Sort nodes based on timestamp or file size
    sortNodes(nodeArray, NUM_FILES, 0, compareTimestamps); // 0 for timestamp, 1 for file size

