void initialize_structures(long *offsets, int *keys, record *records, metadata *meta, config *cfg) {
    srand(time(NULL));

    for (int i = 0; i < NUM_RECORDS; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
        records[i].value = rand() % 1000;

        // Update metadata
        if (i == 0 || offsets[i] > meta[0].max) meta[0].max = offsets[i];
        if (i == 0 || offsets[i] < meta[0].min) meta[0].min = offsets[i];
        meta[0].average += offsets[i];

        if (i == 0 || keys[i] > meta[1].max) meta[1].max = keys[i];
        if (i == 0 || keys[i] < meta[1].min) meta[1].min = keys[i];
        meta[1].average += keys[i];

        if (records[i].value > meta[2].max) meta[2].max = records[i].value;
        if (records[i].value < meta[2].min) meta[2].min = records[i].value;
        meta[2].average += records[i].value;
    }

    // Calculate average
    meta[0].average /= NUM_RECORDS;
    meta[1].average /= NUM_RECORDS;
    meta[2].average /= NUM_RECORDS;

    cfg->flag = 1; // Example configuration flag
}

int main() {
    long *offsets = (long *)malloc(NUM_RECORDS * sizeof(long));
    int *keys = (int *)malloc(NUM_RECORDS * sizeof(int));
    record *records = (record *)malloc(NUM_RECORDS * sizeof(record));
    metadata meta[3] = {{0, 0, 0}, {0, 0, 0}, {0, 0, 0}};
    config cfg;

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_structures(offsets, keys, records, meta, &cfg);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
