#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

typedef struct {
    double value;
    unsigned long timestamp;
    char *name;
} Measurement;

Measurement* createMeasurements(int size, unsigned long startTimestamp) {
    Measurement *measurements = (Measurement*)aligned_alloc(64, size * sizeof(Measurement));
    for (int i = 0; i < size; i++) {
        measurements[i].value = 0.0;
        measurements[i].timestamp = startTimestamp + i;
        measurements[i].name = (char*)malloc(256);
        snprintf(measurements[i].name, 256, "Measurement_%d", i);
    }
    return measurements;
}

void destroyMeasurements(Measurement *measurements, int size) {
    for (int i = 0; i < size; i++) {
        free(measurements[i].name);
    }
    free(measurements);
}

double computeValue(unsigned long timestamp, char *name) {
    return sin(timestamp) * exp(strlen(name));
}

void* processMeasurements(void *arg) {
    Measurement *measurements = (Measurement*)arg;
    int size = sizeof(measurements) / sizeof(Measurement);

    for (int i = 0; i < size; i++) {
        measurements[i].value = computeValue(measurements[i].timestamp, measurements[i].name);
    }

    return NULL;
}

void logPerformance() {
    // Implement logging mechanism here
}

void runComputation(double startTimestamp, double endTimestamp) {
    int size = (int)((endTimestamp - startTimestamp) * 10); // Example: 1 measurement per second
    Measurement *measurements = createMeasurements(size, (unsigned long)startTimestamp);

    pthread_t thread;
    if (pthread_create(&thread, NULL, processMeasurements, measurements) != 0) {
        perror("Failed to create thread");
        return;
    }

    pthread_join(thread, NULL);
    logPerformance();

    destroyMeasurements(measurements, size);
}

int main() {
    double startTimestamp = time(NULL);
    double endTimestamp = startTimestamp + 60; // 1 minute
    runComputation(startTimestamp, endTimestamp);
    return 0;
}
```

