typedef struct {
    int value;
} record;

record** initializeDataStructures(int n, int m, int low, int high, int* offsets, int* keys, record*** records, record*** duplicates, int* indexes) {
    if (n <= 0 || m <= 0) {
        return NULL; // Invalid input
    }

    srand(time(NULL)); // Seed for random number generation

    *offsets = (int*)malloc(n * sizeof(int));
    *keys = (int*)malloc(n * sizeof(int));
    *records = (record**)malloc(m * sizeof(record*));
    *duplicates = (record**)malloc(m * sizeof(record*));
    *indexes = (int*)calloc(m, sizeof(int));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *duplicates == NULL || *indexes == NULL) {
        // Handle memory allocation error
        free(*offsets);
        free(*keys);
        free(*records);
        free(*duplicates);
        free(*indexes);
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        (*offsets)[i] = rand() % m; // Random offset
        (*keys)[i] = rand() % m; // Random key
    }

    for (int i = 0; i < m; ++i) {
        (*records)[i] = (record*)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            // Handle memory allocation error
            for (int j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            free(*duplicates);
            free(*indexes);
            return NULL;
        }
        (*records)[i]->value = rand() % (high - low + 1) + low; // Random value within range [low, high]
    }

    for (int i = 0; i < m; ++i) {
        (*duplicates)[i] = NULL;
    }

    return *records;
}
