        mm->large_offsets[i] = rand() % 1000000000L;
        mm->keys[i] = rand() % 1000;
        // Initialize record, metadata, event, and status structures with random values
    }

    return mm;
}

void free_memory_manager(MemoryManager *mm) {
    if (!mm) return;

    for (size_t i = 0; i < sizeof(mm->records)/sizeof(record*); ++i) {
        free(mm->records[i]);
    }
    free(mm->records);
    free(mm->large_offsets);
    free(mm->keys);
    free(mm->metadata);

    // Free events and statuses if they are dynamically allocated

    free(mm);
}
