#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_data(long n, long m, int low, int high) {
    if (n <= 0 || m <= 0) {
        fprintf(stderr, "Error: 'n' and 'm' must be positive integers.\n");
        return;
    }

    long *offsets = malloc(n * sizeof(*offsets));
    if (!offsets) {
        perror("Failed to allocate memory for offsets.");
        exit(EXIT_FAILURE);
    }

    int *keys = malloc(n * sizeof(*keys));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    record *records = malloc(m * sizeof(*records));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    record *duplicate_records = malloc(m * sizeof(*duplicate_records));
    if (!duplicate_records) {
        fprintf(stderr, "Error: Failed to allocate memory for duplicate records.\n");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    int *indexes = malloc(m * sizeof(*indexes));
    if (!indexes) {
        fprintf(stderr, "Error: Failed to allocate memory for indexes.\n");
        free(offsets);
        free(keys);
        free(records);
        free(duplicate_records);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    // Initialize records with random values
    for (long i = 0; i < m; ++i) {
        records[i].value = low + rand() % (high - low + 1);
        indexes[i] = i;
    }

    // Simulate conflicts and store in duplicate_records
    for (long i = 0; i < m; ++i) {
        long index = rand() % m;
        if (index != i) {
            duplicate_records[index].value = records[i].value;
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(duplicate_records);
    free(indexes);

    printf("Data initialization complete.\n");
}

int main() {
    long n = 10;
    long m = 20;
    int low = 1;
    int high = 100;

    initialize_data(n, m, low, high);

    return 0;
}
```

