    int *keys = malloc(n * sizeof(int));
    record *records = malloc(m * sizeof(record));
    if (!offsets || !keys || !records) {
        fprintf(stderr, "Failed to allocate memory\n");
        free(offsets);
        free(keys);
        return EXIT_FAILURE;
    }

    // Initialize records
    initialize_records(records, m, low, high);

    // Secondary record array for conflicts
    int secondary_size = 10;
    record *secondary_records = malloc(secondary_size * sizeof(record));
    if (!secondary_records) {
        fprintf(stderr, "Failed to allocate memory\n");
        free(offsets);
        free(keys);
