    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data = data;
    new_node->next = new_node->prev = NULL;
    return new_node;
}

Record* create_record(int value) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    record->value = value;
    return record;
}

BSTNode* create_bst_node(int key, Record *record) {
