    n->next = NULL;
    n->prev = NULL;
    return n;
}

bst_node* create_bst_node(int key, record* value) {
    bst_node* bn = (bst_node*)malloc(sizeof(bst_node));
    bn->key = key;
    bn->value = value;
    bn->left = NULL;
    bn->right = NULL;
    return bn;
}

void insert_hash_table(hash_table* ht, int key, record* value) {
    int index = key % ht->size;
    while (ht->table[index] != NULL) {
        index = (index + 1) % ht->size;
    }
    ht->table[index] = value;
}

node* insert_doubly_linked_list(node** head, node* new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
    }
    return new_node;
}

bst_node* insert_bst(bst_node** root, int key, record* value) {
    if (*root == NULL) {
        *root = create_bst_node(key, value);
    } else {
        bst_node* current = *root;
        while (current != NULL) {
            if (key < current->key) {
                if (current->left == NULL) {
                    current->left = create_bst_node(key, value);
                    break;
                }
                current = current->left;
            } else {
                if (current->right == NULL) {
                    current->right = create_bst_node(key, value);
                    break;
                }
                current = current->right;
            }
        }
    }
    return *root;
}

node* insert_queue(node** front, node** rear, node* new_node) {
    if (*front == NULL) {
        *front = *rear = new_node;
    } else {
        (*rear)->next = new_node;
        new_node->prev = *rear;
        *rear = new_node;
    }
    return *front;
}

record** allocate_matrix(int rows, int cols) {
    record** matrix = (record**)malloc(rows * sizeof(record*));
    for (int i = 0; i < rows; i++) {
        matrix[i] = (record*)malloc(cols * sizeof(record));
    }
    return matrix;
}

composite* create_composite() {
    composite* c = (composite*)malloc(sizeof(composite));
    // Initialize fields of composite here
    return c;
}

void free_record(record* r) {
    free(r);
}

void free_node(node* n) {
    if (n != NULL) {
        free_node(n->next);
        free(n);
    }
}

void free_hash_table(hash_table* ht) {
    for (int i = 0; i < ht->size; i++) {
        free_record(ht->table[i]);
    }
    free(ht->table);
    free(ht);
}

void free_doubly_linked_list(node** head) {
    free_node(*head);
    *head = NULL;
}

void free_bst(bst_node* root) {
    if (root != NULL) {
        free_bst(root->left);
        free_bst(root->right);
        free_record(root->value);
        free(root);
    }
}

void free_queue(node** front, node** rear) {
    free_doubly_linked_list(front);
    *front = *rear = NULL;
}

void free_matrix(record*** matrix, int rows) {
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

void free_composite(composite* c) {
    // Free fields of composite here
    free(c);
}
