        fprintf(stderr, "Memory allocation failed for records\n");
        free(ds->offsets);
        free(ds->keys);
        exit(1);
    }
    ds->records_size = m;

    ds->duplicate_records = (record **)malloc(m * sizeof(record *));
    if (!ds->duplicate_records) {
        fprintf(stderr, "Memory allocation failed for duplicate records\n");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
