                free(ds->records[j]);
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            free(ds->duplicate_records);
            free(ds->indexes);
            exit(1);
        }
        ds->records[i]->value = low + rand() % (high - low + 1);

        if (i < m - 1) {
            ds->duplicate_records[i] = NULL;
        } else {
            ds->duplicate_records[i] = (record *)malloc(sizeof(record));
            if (!ds->duplicate_records[i]) {
                fprintf(stderr, "Memory allocation failed for duplicate record %d\n", i);
                for (int j = 0; j < m - 1; j++)
                    free(ds->duplicate_records[j]);
                for (int j = 0; j < m; j++)
                    free(ds->records[j]);
                free(ds->offsets);
                free(ds->keys);
                free(ds->records);
                free(ds->duplicate_records);
                free(ds->indexes);
                exit(1);
            }
        }
    }
}

void destroy_data_structures(data_structures *ds, int n, int m) {
    for (int i = 0; i < n; i++) {
        free(ds->offsets[i]);
        free(ds->keys[i]);
    }
    free(ds->offsets);
    free(ds->keys);

    for (int i = 0; i < m; i++) {
        free(ds->records[i]);
        if (ds->duplicate_records[i] != NULL)
            free(ds->duplicate_records[i]);
    }
    free(ds->records);
    free(ds->duplicate_records);
    free(ds->indexes);
}

