#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_RECORDS 10000000

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t offset_range_min, offset_range_max;
    size_t key_range_min, key_range_max;
    double avg_offset, avg_key;
} Metadata;

Metadata* init_memory(size_t num_records) {
    Metadata* metadata = (Metadata*)malloc(sizeof(Metadata));
    if (!metadata) {
        perror("Failed to allocate memory for metadata");
        return NULL;
    }

    metadata->offsets = (long*)aligned_alloc(64, num_records * sizeof(long));
    if (!metadata->offsets) {
        perror("Failed to allocate aligned memory for offsets");
        free(metadata);
        return NULL;
    }

    metadata->keys = (int*)malloc(num_records * sizeof(int));
    if (!metadata->keys) {
        perror("Failed to allocate memory for keys");
        free(metadata->offsets);
        free(metadata);
        return NULL;
    }

    metadata->records = (Record**)malloc(num_records * sizeof(Record*));
    if (!metadata->records) {
        perror("Failed to allocate memory for records pointers");
        free(metadata->keys);
        free(metadata->offsets);
        free(metadata);
        return NULL;
    }

    srand(time(NULL));

    long min_offset = 0, max_offset = 0;
    int min_key = 0, max_key = 0;

    for (size_t i = 0; i < num_records; ++i) {
        metadata->offsets[i] = rand();
        if (min_offset > metadata->offsets[i]) min_offset = metadata->offsets[i];
        if (max_offset < metadata->offsets[i]) max_offset = metadata->offsets[i];

        metadata->keys[i] = rand() % 1000; // Assuming keys are within [0, 999]
        if (min_key > metadata->keys[i]) min_key = metadata->keys[i];
        if (max_key < metadata->keys[i]) max_key = metadata->keys[i];

        metadata->records[i] = (Record*)malloc(sizeof(Record));
        if (!metadata->records[i]) {
            perror("Failed to allocate memory for record");
            // Free previously allocated memories
            free(metadata->records);
            for (size_t j = 0; j < i; ++j) free(metadata->records[j]);
            free(metadata->keys);
            free(metadata->offsets);
            free(metadata);
            return NULL;
        }
        metadata->records[i]->value = rand() % 1000; // Assuming record values are within [0, 999]
    }

    metadata->offset_range_min = min_offset;
    metadata->offset_range_max = max_offset;
    metadata->key_range_min = min_key;
    metadata->key_range_max = max_key;

    // Calculate averages
    long sum_offset = 0, sum_key = 0;
    for (size_t i = 0; i < num_records; ++i) {
        sum_offset += metadata->offsets[i];
        sum_key += metadata->keys[i];
    }
    metadata->avg_offset = (double)sum_offset / num_records;
    metadata->avg_key = (double)sum_key / num_records;

    return metadata;
}

void free_memory(Metadata* metadata, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) free(metadata->records[i]);
    free(metadata->records);
    free(metadata->keys);
    free(metadata->offsets);
    free(metadata);
}
