int manage_memory(long **offsets, int **keys, record **records, size_t size, int offset_range, int key_range, int record_min, int record_max) {
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (record *)malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize offset and key arrays
    for (size_t i = 0; i < size; i++) {
        (*offsets)[i] = i % offset_range;
        (*keys)[i] = i % key_range + 1;
    }

    // Initialize record array with random values within the specified range
    srand(time(0));
    int *record_values = (int *)malloc(size * sizeof(int));
    if (record_values == NULL) {
        fprintf(stderr, "Memory allocation failed for record values\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    size_t records_initialized = 0;
    while (records_initialized < size) {
        int random_value = rand() % (record_max - record_min + 1) + record_min;
        int duplicate = 0;
        for (size_t j = 0; j < records_initialized; j++) {
            if (record_values[j] == random_value) {
                duplicate = 1;
                break;
            }
        }
        if (!duplicate) {
            (*records)[records_initialized].value = random_value;
            record_values[records_initialized++] = random_value;
        }
    }

    free(record_values);

    return records_initialized;
}
