#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 * 1024 // 1GB

typedef struct {
    int value;
} record;

long* offset_array;
int* key_array;
record* record_array;

size_t array_size;
int key_range_start = 1;
int key_range_end = 1000;
int record_value_range_start = 0;
int record_value_range_end = 10000;
int max_records = 1000;
pthread_mutex_t memory_management_lock;

void* init_memory(void* arg) {
    size_t requested_size = *(size_t*)arg;
    if (requested_size > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Error: Requested memory exceeds maximum allowed usage.\n");
        return NULL;
    }

    // Simulate memory allocation
    void* allocated_memory = malloc(requested_size);
    if (!allocated_memory) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_lock(&memory_management_lock);
    // Log memory allocation details for auditing purposes
    printf("Memory allocated: %zu bytes\n", requested_size);
    pthread_mutex_unlock(&memory_management_lock);

    return allocated_memory;
}

void* allocate_record_array(size_t size) {
    size_t required_memory = sizeof(record) * size;
    void* memory = init_memory(required_memory);
    if (memory == NULL) {
        return NULL;
    }

    record_array = (record*)memory;
    array_size = size;

    // Initialize record array with random integer values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < array_size; ++i) {
        int value = rand() % (record_value_range_end - record_value_range_start + 1) + record_value_range_start;
        // Ensure no duplicate values in the record array
        while (value == record_array[i].value) {
            value = rand() % (record_value_range_end - record_value_range_start + 1) + record_value_range_start;
        }
        record_array[i].value = value;
    }

    return memory;
}

void update_offset_and_key_arrays(size_t new_size, int new_key_range_start, int new_key_range_end) {
    pthread_mutex_lock(&memory_management_lock);
    // Ensure that the updated values do not violate any integrity constraints
    if (new_size > array_size || new_key_range_start < 0 || new_key_range_end <= key_range_end) {
        fprintf(stderr, "Error: Invalid update values.\n");
        pthread_mutex_unlock(&memory_management_lock);
        return;
    }

    // Update offset and key arrays at runtime without reallocating memory
    for (size_t i = array_size; i < new_size; ++i) {
        offset_array[i] = i;
        key_array[i] = i + 1;
    }
    array_size = new_size;
    key_range_start = new_key_range_start;
    key_range_end = new_key_range_end;

    pthread_mutex_unlock(&memory_management_lock);
}

int main() {
    // Initialize memory management
    pthread_mutex_init(&memory_management_lock, NULL);

    // Allocate record array with 100 records
    void* allocated_memory = allocate_record_array(100);
    if (allocated_memory == NULL) {
        fprintf(stderr, "Error: Allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Update offset and key arrays at runtime
    update_offset_and_key_arrays(200, 500, 600);

    // Free allocated memory
    free(allocated_memory);
    pthread_mutex_destroy(&memory_management_lock);

    return EXIT_SUCCESS;
}
