void manageMemory(double **doubles, char **chars, item ***items, size_t size) {
    *doubles = (double *)malloc(size * sizeof(double));
    *chars = (char *)malloc(size * sizeof(char));
    *items = (item **)malloc(size * sizeof(item *));

    if (*doubles == NULL || *chars == NULL || *items == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        (*doubles)[i] = rand() / (double)RAND_MAX;
        (*chars)[i] = 'A' + (rand() % 26);

        (*items)[i] = (item *)malloc(sizeof(item));
        if ((*items)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for item\n");
            exit(1);
        }
        (*items)[i]->timestamp = time(NULL);
        (*items)[i]->identifier = rand() % 100;
        (*items)[i]->value = (*items)[i]->identifier * 2.5f + (*doubles)[i];
    }
}

int main() {
    size_t size = 10;
    double *doubles;
    char *chars;
    item **items;

    manageMemory(&doubles, &chars, &items, size);

    for (size_t i = 0; i < size; ++i) {
        printf("Double: %f, Char: %c, Item - Timestamp: %ld, Identifier: %d, Value: %f\n",
               doubles[i], chars[i], items[i]->timestamp, items[i]->identifier, items[i]->value);
    }

    for (size_t i = 0; i < size; ++i) {
        free(items[i]);
    }
    free(doubles);
    free(chars);

    return 0;
}
