        printf("Invalid size. Must be between 1 and %d.\n", MAX_SIZE);
        return NULL;
    }

    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i].offset = 0;
        records[i].key = i;
    }

    return records;
}

void freeRecords(Record* records) {
    if (records) {
        free(records);
    }
}

void resizeRecords(Record** records, int newSize) {
    Record* newRecords = allocateRecords(newSize);
    if (!newRecords) {
        printf("Failed to resize records.\n");
        return;
    }

    *records = newRecords;
}

int main() {
    srand(time(NULL));
    int size = 500;
    Record* records = allocateRecords(size);

    if (records) {
        // Use the records array
        for (int i = 0; i < size; i++) {
            printf("Record %d: Offset = %ld, Key = %d\n", i, records[i].offset, records[i].key);
        }

        resizeRecords(&records, 1000);

        if (records) {
            for (int i = 500; i < 1000; i++) {
                printf("Record %d: Offset = %ld, Key = %d\n", i, records[i].offset, records[i].key);
            }
        }

        freeRecords(records);
