#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    record* data;
    size_t size;
    size_t max_size;
    size_t allocated;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t initial_size, size_t max_size) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    pool->data = (record*)malloc(initial_size * sizeof(record));
    pool->size = initial_size;
    pool->max_size = max_size;
    pool->allocated = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool* pool) {
    free(pool->data);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

record* allocate_record(memory_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated == pool->size) {
        if (pool->allocated >= pool->max_size) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Out of memory
        }
        size_t new_size = pool->size * 2;
        record* new_data = (record*)realloc(pool->data, new_size * sizeof(record));
        if (!new_data) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Realloc failed
        }
        pool->data = new_data;
        pool->size = new_size;
    }
    record* rec = &pool->data[pool->allocated++];
    pthread_mutex_unlock(&pool->lock);
    return rec;
}

void free_record(memory_pool* pool, record* rec) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->allocated; ++i) {
        if (&pool->data[i] == rec) {
            memmove(&pool->data[i], &pool->data[i + 1], (pool->allocated - i - 1) * sizeof(record));
            pool->allocated--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void log_event(const char* message) {
    // Log the message to a file or system logs
    printf("%s\n", message);
}

unsigned long generate_random_number(unsigned int seed, long min, long max) {
    srand(seed);
    return (rand() % (max - min + 1)) + min;
}

void monitor_memory_usage(memory_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    printf("Current Memory Usage: %zu / %zu\n", pool->allocated * sizeof(record), pool->size * sizeof(record));
    pthread_mutex_unlock(&pool->lock);
}
