    int key;
} record;

#define MAX_STREAMS 10
#define DEFAULT_CACHE_SIZE 256

typedef struct {
    record *memory_pool[MAX_STREAMS];
    size_t pool_size[MAX_STREAMS];
    size_t used_memory[MAX_STREAMS];
    pthread_mutex_t lock;
    record **cache;
    int cache_size;
} memory_manager;

memory_manager manager;

void initialize_manager(int num_streams, int cache_size) {
    memset(&manager, 0, sizeof(manager));
    manager.cache_size = cache_size;
    manager.cache = (record **)malloc(cache_size * sizeof(record *));
    for (int i = 0; i < num_streams; ++i) {
        pthread_mutex_init(&manager.lock[i], NULL);
    }
}

