    *chars = malloc(*size * sizeof(char));
    *items = malloc(*size * sizeof(item*));
    for (int i = 0; i < *size; i++) {
        (*items)[i] = malloc(sizeof(item));
        (*items)[i]->timestamp = time(NULL);
        (*items)[i]->identifier = rand() % (*size);
        (*items)[i]->value = calculate_value((*items)[i]->identifier);
    }

    *offsets = malloc(*size * sizeof(long));
    *keys = malloc(*size * sizeof(int));

    for (int i = 0; i < *size; i++) {
        (*offsets)[i] = rand() % (*size) * 1024;
        (*keys)[i] = (*keys)[i-1] + 1; // Ensure uniqueness
    }
}

void resize_array(record **records, int *size, int new_size) {
    if (new_size > *size) {
        *records = realloc(*records, new_size * sizeof(record));
        *size = new_size;
    }
}

void custom_sort(record *records, int size) {
    for (int i = 1; i < size; i++) {
        record key = records[i];
        int j = i - 1;

        while (j >= 0 && records[j].offset > key.offset) {
            records[j + 1] = records[j];
            j--;
        }
        records[j + 1] = key;
    }
}

long find_record_by_key(record *records, int size, int key) {
    for (int i = 0; i < size; i++) {
        if (records[i].key == key) {
            return records[i].offset;
        }
    }
    return -1; // Key not found
}

void add_record(record **records, int *size, long offset, int key) {
    resize_array(records, size, *size + 1);
    (*records)[*size - 1].offset = offset;
    (*records)[*size - 1].key = key;
}

int main() {
