        logValidationAttempt(false, "Invalid JSON format");
        return false;
    }

    if (!isBearerTokenType(jsonToken)) {
        logValidationAttempt(false, "Token type must be 'Bearer'");
        return false;
    }

    int expiresIn = parseExpiresIn(jsonToken);
    if (expiresIn <= 0 || expires_in > 3600) {
        logValidationAttempt(false, "Invalid 'expires_in' value");
        return false;
    }

    const char* scope = getScopeFromToken(jsonToken);
    if (scope != NULL && strlen(scope) == 0) {
        logValidationAttempt(false, "'scope' must be a non-empty string");
        return false;
    }

    time_t issuedAt = parseIssuedAt(jsonToken);
    time_t now = time(NULL);
    if (issuedAt <= 0 || difftime(now, issuedAt) > 1800) {
        logValidationAttempt(false, "'issued_at' must be a valid timestamp within the last 30 minutes");
        return false;
    }

    const char* refreshToken = getRefreshTokenFromToken(jsonToken);
    if (refreshToken != NULL && !isRefreshTokenValid(refreshToken)) {
        logValidationAttempt(false, "Invalid 'refresh_token'");
        return false;
    }

    const char* clientId = getClientIdFromToken(jsonToken);
    if (!isInClientList(clientId)) {
        logValidationAttempt(false, "Unknown client ID");
        return false;
    }

    // Rate limiting logic here (not shown for brevity)

    logValidationAttempt(true, "Token validation successful");
    return true;
}
