using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class MessageProcessor
{
    private static readonly Dictionary<string, Tuple<byte[], byte[]>> cache = new Dictionary<string, Tuple<byte[], byte[]>>();
    private static readonly object cacheLock = new object();

    public string ProcessAndDecryptMessage(string base64EncodedMessage, bool skipHashing)
    {
        try
        {
            byte[] key = Encoding.UTF8.GetBytes("YourTripleDESKey123"); // Replace with actual key
            byte[] iv = Encoding.UTF8.GetBytes("YourIV12345"); // Replace with actual IV

            if (cache.ContainsKey($"{key}- {iv}"))
            {
                lock (cacheLock)
                {
                    if (cache.ContainsKey($"{key}- {iv}"))
                    {
                        key = cache[$"{key}- {iv}"].Item1;
                        iv = cache[$"{key}- {iv}"].Item2;
                    }
                }
            }
            else
            {
                lock (cacheLock)
                {
                    if (!cache.ContainsKey($"{key}- {iv}"))
                    {
                        cache.Add($"{key}- {iv}", new Tuple<byte[], byte[]>(key, iv));
                    }
                }
            }

            byte[] encryptedData = Convert.FromBase64String(base64EncodedMessage);
            using (TripleDESCryptoServiceProvider tdesAlg = new TripleDESCryptoServiceProvider())
            {
                tdesAlg.Key = key;
                tdesAlg.IV = iv;
                ICryptoTransform decryptor = tdesAlg.CreateDecryptor(tdesAlg.Key, tdesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            string decryptedMessage = srDecrypt.ReadToEnd();
                            if (decryptedMessage == ReverseString(decryptedMessage) && skipHashing)
                            {
                                return "PALINDROME_SKIP";
                            }
                            else
                            {
                                byte[] hashBytes = MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(decryptedMessage));
                                return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
            return null;
        }
    }

    private string ReverseString(string s)
    {
        char[] array = s.ToCharArray();
        Array.Reverse(array);
        return new string(array);
    }
