using System;
using System.IO;
using System.Security.Cryptography;

class LogHashProcessor
{
    private static readonly SHA256 _sha256 = SHA256.Create();
    private static readonly string _hashDelimiter = ";";

    public static void ProcessLogEntries(string filePath, string outputFilePath)
    {
        using (var reader = new StreamReader(filePath))
        using (var writer = new StreamWriter(outputFilePath))
        {
            string line;
            long currentLine = 0;

            if (File.Exists(outputFilePath))
            {
                // Find the last processed line to resume from
                var lines = File.ReadAllLines(outputFilePath);
                currentLine = int.Parse(lines[lines.Length - 1]);
                reader.BaseStream.Seek(currentLine * 1024, SeekOrigin.Begin); // Approximate seek based on line length
            }

            while ((line = reader.ReadLine()) != null)
            {
                if (string.IsNullOrEmpty(line) || line.Length > 1000)
                {
                    continue; // Skip empty or too long lines
                }

                var hashBytes = _sha256.ComputeHash(Encoding.UTF8.GetBytes(line));
                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

                writer.WriteLine($"{currentLine}{_hashDelimiter}{line}{_hashDelimiter}{hashString}");

                currentLine++;
            }
        }
    }
}
```

