['```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public class SecureFileProcessor
{
    private readonly byte[] _encryptionKey;
    private readonly byte[] _initializationVector;
    private readonly int _segmentSize;
    private readonly bool _enableHmacValidation;
    private HMACSHA256 _hmac;

    public SecureFileProcessor(byte[] encryptionKey, byte[] initializationVector, int segmentSize = 1024 * 1024, bool enableHmacValidation = true)
    {
        _encryptionKey = encryptionKey;
        _initializationVector = initializationVector;
        _segmentSize = segmentSize;
        _enableHmacValidation = enableHmacValidation;

        if (_enableHmacValidation)
        {
            _hmac = new HMACSHA256(_encryptionKey);
        }
    }

    public void ProcessFile(string inputFilePath, string outputFilePath)
    {
        using (var inputStream = new FileStream(inputFilePath, FileMode.Open, FileAccess.Read))
        using (var outputStream = new FileStream(outputFilePath, FileMode.Create, FileAccess.Write))
        {
            byte[] buffer = new byte[_segmentSize];
            int bytesRead;

            while ((bytesRead = inputStream.Read(buffer, 0, buffer.Length)) > 0)
            {
                if (_enableHmacValidation && !VerifySegmentIntegrity(buffer, bytesRead))
                {
                    Console.WriteLine("Skipping corrupted segment.");
                    continue;
                }

                try
                {
                    byte[] decryptedData = DecryptSegment(buffer, bytesRead);
                    outputStream.Write(decryptedData, 0, decryptedData.Length);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Decryption error: {ex.Message}");
                }
            }
        }
    }

    private bool VerifySegmentIntegrity(byte[] segment, int length)
    {
        byte[] hmacValue = _hmac.ComputeHash(segment, 0, length);
        // Assuming the HMAC value is appended at the end of each segment
        Array.Copy(hmacValue, 0, segment, length, hmacValue.Length);
        byte[] computedHmacValue = _hmac.ComputeHash(segment, 0, length + hmacValue.Length);

        return hmacValue.SequenceEqual(computedHmacValue);
    }

    private byte[] DecryptSegment(byte[] segment, int length)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = _encryptionKey;
            aes.IV = _initializationVector;
            aes.Mode = CipherMode.CBC;

            ICryptoTransform decryptor = aes.CreateDecryptor();
            byte[] decryptedData = decryptor.TransformFinalBlock(segment, 0, length);

            return decryptedData;
        }
    }

    public void ConfigureParameters(int segmentSize, bool enableHmacValidation)
    {
        _segmentSize = segmentSize;
        _enableHmacValidation = enableHmacValidation;

        if (_enableHmacValidation)
        {
            _hmac = new HMACSHA256(_encryptionKey);
        }
    }
}
