import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class BinaryFileProcessor {

    public static List<CustomData> processBinaryFile(String filePath) {
        List<CustomData> customDataList = new ArrayList<>();
        try (RandomAccessFile file = new RandomAccessFile(filePath, "r")) {
            long fileSize = file.length();
            byte[] buffer = new byte[4096]; // 4KB buffer for efficient reading

            while (file.getFilePointer() < fileSize) {
                int bytesRead = file.read(buffer);
                if (bytesRead == -1) break; // End of file

                ByteArrayInputStream bais = new ByteArrayInputStream(buffer, 0, bytesRead);
                ObjectInputStream ois = new ObjectInputStream(bais);

                try {
                    CustomData customData = (CustomData) ois.readObject();
                    customDataList.add(customData);
                } catch (ClassNotFoundException e) {
                    System.err.println("Class not found: " + e.getMessage());
                } catch (IOException e) {
                    System.err.println("I/O error during deserialization: " + e.getMessage());
                } finally {
                    ois.close();
                }
            }
        } catch (FileNotFoundException e) {
            System.err.println("File not found: " + filePath);
        } catch (IOException e) {
            System.err.println("Error opening file: " + e.getMessage());
        }

        return customDataList;
    }
}
