#include <vector>

// Function to validate if a string is numeric
bool isNumeric(const std::string& str) {
    return !str.empty() && std::all_of(str.begin(), str.end(), ::isdigit);
}

// Callback function for cURL to handle data received from the server
size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

// Function to upload and process a file using cURL
std::string uploadAndProcessFile(const std::string& url, const std::string& filename, const std::string& option) {
    CURL* curl = curl_easy_init();
    if(curl) {
        std::ifstream file(filename);
        if(!file.is_open()) {
            std::cerr << "Error opening file: " << filename << std::endl;
            return "";
        }

        std::vector<std::string> lines;
        std::string line;
        while(std::getline(file, line)) {
            std::istringstream iss(line);
            std::vector<std::string> fields((std::istream_iterator<std::string>(iss)),
                                             std::istream_iterator<std::string>());
            if(fields.size() >= 3 && isNumeric(fields[fields.size()-2]) && isNumeric(fields[fields.size()-1])) {
                double sum = std::stod(fields[fields.size()-2]) + std::stod(fields[fields.size()-1]);
                fields.push_back(std::to_string(sum / 2));
            }
            lines.push_back(std::accumulate(fields.begin(), fields.end(), std::string(),
                                            [](const std::string& a, const std::string& b) {
                                                return a.empty() ? b : a + "," + b;
                                            }));
        }

        std::ostringstream dataStream;
        for(const auto& line : lines) {
            dataStream << line << "\n";
        }

        struct curl_slist* headers = nullptr;
        headers = curl_slist_append(headers, "Content-Type: text/plain");

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, dataStream.str().c_str());
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);

        CURLcode res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
            return "";
        }

        std::string responseUrl;
        curl_easy_getinfo(curl, CURLINFO_EFFECTIVE_URL, &responseUrl);

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);

        return responseUrl;
    }
    return "";
}

int main() {
    // Example usage
    std::string url = "http://example.com/upload";
    std::string filename = "data.csv";
    std::string option = "--option";
    std::cout << "Uploaded URL: " << uploadAndProcessFile(url, filename, option) << std::endl;
    return 0;
}
