use std::env;
use std::fs::{create_dir_all, metadata};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

fn initialize_workspace_and_execute_commands(commands: Vec<&str>) -> Result<(), Box<dyn std::error::Error>> {
    let ws_path = env::var("WS_PATH").unwrap_or_else(|_| "workspace".to_string());
    let setup_log_path = PathBuf::from(&ws_path).join("setup.log");

    if Path::new(&ws_path).exists() {
        ensure_directory_permissions(&ws_path)?;
    } else {
        create_workspace(&ws_path, &setup_log_path)?;
    }

    let mut results = Vec::new();
    let max_concurrent_commands = 5;
    let semaphore = Arc::new(Mutex::new(0));

    for command in commands {
        loop {
            if *semaphore.lock().unwrap() < max_concurrent_commands {
                *semaphore.lock().unwrap() += 1;
                break;
            }
        }

        let result = execute_command_in_background(command, &setup_log_path)?;
        results.push(result);
        *semaphore.lock().unwrap() -= 1;
    }

    for result in results {
        match result {
            Ok(_) => println!("Command succeeded"),
            Err(e) => eprintln!("Command failed: {}", e),
        }
    }

    Ok(())
}

fn ensure_directory_permissions(path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let metadata = metadata(path)?;
    if !metadata.permissions().readonly() {
        // Implement permission validation logic here
        println!("Directory permissions are correct");
    } else {
        return Err("Invalid directory permissions".into());
    }
    Ok(())
}

fn create_workspace(ws_path: &str, setup_log_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    create_dir_all(&ws_path)?;
    log_operation(setup_log_path, "Workspace created")?;
    println!("New workspace directory created at {}", ws_path);
    Ok(())
}

fn execute_command_in_background(command: &str, setup_log_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(command)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()?;

    let start_time = SystemTime::now();
    if let Err(e) = child.wait() {
        log_failure(setup_log_path, command, &e)?;
        return Err(e.into());
    }

    let duration = start_time.elapsed().unwrap_or_default();
    println!("Command {} executed in {:?}", command, duration);
    Ok(())
}

fn log_operation(log_path: &Path, message: &str) -> Result<(), Box<dyn std::error::Error>> {
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .append(true)
        .create(true)
        .open(log_path)?;

    let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();
    writeln!(file, "{} - {}", timestamp, message)?;
    Ok(())
}

fn log_failure(log_path: &Path, command: &str, error: &std::io::Error) -> Result<(), Box<dyn std::error::Error>> {
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .append(true)
        .create(true)
        .open(log_path)?;

    let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();
    writeln!(file, "{} - Command {} failed: {}", timestamp, command, error)?;
    Ok(())
}
