        perror("Failed to allocate memory for RX frames");
        return NULL;
    }

    // Initialize each frame with default values
    for (int i = 0; i < num_frames; ++i) {
        frames[i].RX_FRAME_TAG = 0;
        frames[i].rx_antenna_index = -1;
        frames[i].rx_chain_index = -1;
        memset(frames[i].data_buffer, 0, N);
    }

    return frames;
}

void free_frames(NFAPI_RX_FRAME_T* frames) {
    if (frames) {
        free(frames);
    }
}

// Example usage
int main() {
    int num_frames = 100;
    NFAPI_RX_FRAME_T* rx_frames = initialize_frames(num_frames);

    if (rx_frames) {
        // Use the frames for processing
        free_frames(rx_frames); // Properly release memory when done
    }

    return 0;
}
