#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int DEVICE_ID;
    char IP_ADDRESS[16];
    int PORT_NUMBER;
    time_t LAST_HEARTBEAT_TIME;
    double CURRENT_LOAD;
    int STATUS_CODE;
} DEVICE_STATUS_RECORD_T;

typedef struct {
    DEVICE_STATUS_RECORD_T** records;
    size_t count;
    pthread_mutex_t mutex;
} DEVICE_STATUS_LIST_T;

DEVICE_STATUS_LIST_T* create_device_status_list(size_t initial_size) {
    DEVICE_STATUS_LIST_T* list = (DEVICE_STATUS_LIST_T*)malloc(sizeof(DEVICE_STATUS_LIST_T));
    if (!list) return NULL;

    list->records = (DEVICE_STATUS_RECORD_T**)calloc(initial_size, sizeof(DEVICE_STATUS_RECORD_T*));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->count = initial_size;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_device_status_list(DEVICE_STATUS_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i]);
    }
    free(list->records);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_device_status(DEVICE_STATUS_LIST_T* list, DEVICE_STATUS_RECORD_T* record) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i]->DEVICE_ID == record->DEVICE_ID ||
            strcmp(list->records[i]->IP_ADDRESS, record->IP_ADDRESS) == 0) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Duplicate device ID or IP address
        }
    }

    if (list->count == list->records_size) {
        size_t new_size = list->count * 2;
        DEVICE_STATUS_RECORD_T** new_records = realloc(list->records, new_size * sizeof(DEVICE_STATUS_RECORD_T*));
        if (!new_records) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failure
        }
        list->records = new_records;
        list->count = new_size;
    }

    list->records[list->count++] = record;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Additional functions for concurrent access, memory safety, performance optimizations,
// resource management, logging, file export, system monitoring, and future adaptability
