#define MAX_MEASUREMENTS 1000

typedef struct {
    double value;
    unsigned long timestamp;
    char* string;
    int flag;
} Measurement;

typedef struct {
    Measurement measurements[MAX_MEASUREMENTS];
    size_t count;
    pthread_mutex_t lock;
} MeasurementSystem;

void init_measurement_system(MeasurementSystem* system) {
    memset(system, 0, sizeof(MeasurementSystem));
    pthread_mutex_init(&system->lock, NULL);
}

void add_measurement(MeasurementSystem* system, double value, unsigned long timestamp, const char* string, int flag) {
    pthread_mutex_lock(&system->lock);
    if (system->count < MAX_MEASUREMENTS) {
        Measurement* m = &system->measurements[system->count];
        m->value = value;
        m->timestamp = timestamp;
        m->string = strdup(string); // Copy string
        m->flag = flag;
        system->count++;
    }
    pthread_mutex_unlock(&system->lock);
}

void compute_measurements(MeasurementSystem* system, double (*compute_func)(double, unsigned long, const char*, int)) {
    pthread_mutex_lock(&system->lock);
    for (size_t i = 0; i < system->count; i++) {
        Measurement* m = &system->measurements[i];
        m->value = compute_func(m->value, m->timestamp, m->string, m->flag);
    }
    pthread_mutex_unlock(&system->lock);
}

double compute_func(double value, unsigned long timestamp, const char* string, int flag) {
    // Example computation: Trigonometric function based on timestamp and string length
    return sin((double)timestamp * strlen(string) / 100.0) + flag;
}

void free_measurement_system(MeasurementSystem* system) {
    pthread_mutex_lock(&system->lock);
    for (size_t i = 0; i < system->count; i++) {
        free(system->measurements[i].string); // Free allocated string
    }
    memset(system, 0, sizeof(MeasurementSystem));
    pthread_mutex_unlock(&system->lock);
    pthread_mutex_destroy(&system->lock);
}

int main() {
    MeasurementSystem system;
    init_measurement_system(&system);

    // Add measurements dynamically
    add_measurement(&system, 1.0, 1633072800, "example", 1);
    add_measurement(&system, 2.0, 1633072900, "data", 0);

    // Compute measurements using a custom function
    compute_measurements(&system, compute_func);

    // Free resources
    free_measurement_system(&system);

    return 0;
}
