    }

    return ((float)rand() / RAND_MAX) * (maxValue - minValue) + minValue; // Using rand() for simplicity, should use UnityEngine.RandomValueGenerator in Unity context
}

float generateWeightedRandomFloat(float* weights, int size) {
    if (size <= 1 || !weights) {
        // Handle invalid input
        return 0.0f;
    }

    float totalWeight = 0.0f;
    for (int i = 0; i < size; ++i) {
        if (weights[i] < 0) {
            // Handle negative weight
            continue;
        }
        totalWeight += weights[i];
    }

    if (totalWeight <= 0) {
        // Handle zero or negative total weight
        return 0.0f;
    }

    float randomValue = generateRandomFloat(0, totalWeight);
    for (int i = 0; i < size; ++i) {
        if (randomValue < weights[i]) {
            return (float)i / (size - 1); // Simplified mapping to [0, 1] for demonstration
        }
        randomValue -= weights[i];
    }

    // Handle edge case
    return (float)(size - 1) / (size - 1);
}
