typedef struct Node {
    int value;
    char *str;
    struct Node *next;
} Node;

Node* create_node(int value, const char *str) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    node->value = value;
    node->str = strdup(str);
    node->next = NULL;
    return node;
}

void free_node(Node *node) {
    if (node != NULL) {
        free(node->str);
        free_node(node->next);
        free(node);
    }
}

Node* add_to_list(Node *head, int value, const char *str) {
    Node *new_node = create_node(value, str);
    new_node->next = head;
    return new_node;
}

void print_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        printf("Value: %d, String: %s\n", current->value, current->str);
        current = current->next;
    }
}

int main() {
    srand(time(NULL));

    int list_size = 5;
    Node *head = NULL;

    for (int i = 0; i < list_size; i++) {
        head = add_to_list(head, rand(), "Random String");
    }

    print_list(head);

    free_node(head);

    return 0;
}
