// Function to generate a random integer within a specified range
int random_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate a random float within a specified range
float random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

// Weighted random float method
float weighted_random_float(float* weights, int num_weights) {
    // Sum the weights to ensure they sum to 1.0
    float total_weight = 0.0f;
    for(int i = 0; i < num_weights; ++i) {
        if(weights[i] < 0.0f) {
            return -1.0f; // Invalid weight
        }
        total_weight += weights[i];
    }
    if(total_weight == 0.0f) {
        return -1.0f; // Sum of weights is zero
    }

    float rand_value = random_float(0.0f, total_weight);
    float cum_weight = 0.0f;
    for(int i = 0; i < num_weights; ++i) {
        cum_weight += weights[i];
        if(rand_value <= cum_weight) {
            return (float)i / (num_weights - 1);
        }
    }

    return -1.0f; // In case of floating point precision issues
}

// Initialize arrays and handle memory allocation failures
