    srand(time(NULL)); // Seed the random number generator

    keys = (int*)malloc(array_size * sizeof(int));
    offsets = (long*)malloc(array_size * sizeof(long));
    records = (Record**)malloc(array_size * sizeof(Record*));

    if(keys == NULL || offsets == NULL || records == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
