// Function to generate random float within specified range
float generateRandomFloat(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

// Weighted random float method that normalizes weights if they don't sum to 1.0
float weightedRandomFloat(float* weights, int size) {
    // Normalize weights if necessary
    float totalWeight = 0;
    for(int i = 0; i < size; i++) {
        totalWeight += weights[i];
    }
    if(totalWeight != 1.0) {
        for(int i = 0; i < size; i++) {
            weights[i] /= totalWeight;
        }
    }

    float randomValue = generateRandomFloat(0.0, 1.0);
    float cumulativeWeight = 0.0;
    for(int i = 0; i < size; i++) {
        cumulativeWeight += weights[i];
        if(randomValue <= cumulativeWeight) {
            return i + min; // Adjust as needed based on weight values
        }
    }
    return size - 1; // Fallback in case of precision issues
}

