#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_RECORDS 1000
#define MAX_NODES 500

typedef struct record {
    double value;
    char* buffer;
} Record;

typedef struct Node {
    int value;
    char* str;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    int size;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        fprintf(stderr, "Memory allocation failed for LinkedList.\n");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    return list;
}

Node* createNode(int value, const char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed for Node.\n");
        return NULL;
    }
    node->value = value;
    node->str = strdup(str);
    node->next = NULL;
    return node;
}

void addNode(LinkedList* list, int value, const char* str) {
    if (list == NULL) {
        fprintf(stderr, "Invalid LinkedList.\n");
        return;
    }
    Node* newNode = createNode(value, str);
    if (newNode == NULL) {
        return;
    }
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
}

void freeLinkedList(LinkedList* list) {
    if (list == NULL) {
        fprintf(stderr, "Invalid LinkedList.\n");
        return;
    }
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
    free(list);
}

int main() {
    // Example usage
    LinkedList* myList = createLinkedList();
    addNode(myList, 42, "Hello");
    printf("List size: %d\n", myList->size);
    freeLinkedList(myList);
    return 0;
}
