record* create_records(int num_records, const char** strings, int range_start, int range_end) {
    srand(time(0));

    record* records = (record*)malloc(num_records * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand();
        records[i].key = rand() % (range_end - range_start + 1) + range_start;
        records[i].value = ((double)rand()) / RAND_MAX;

        // Allocate memory for the string
        size_t len = strlen(strings[i]) + 1;
        records[i].string_ptr = (char*)malloc(len);
        if (records[i].string_ptr == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; j++) {
                free(records[j].string_ptr);
            }
            free(records);
            return NULL;
        }

        // Copy the string
        strcpy(records[i].string_ptr, strings[i]);
    }

    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].string_ptr);
    }
    free(records);
}
