#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a record
typedef struct {
    long offset;
    int key;
    double value;
    char *name;
    char **attributes;
} Record;

// Function to initialize a record with dynamic memory allocation
Record* init_record(long offset, int key, double value, const char *names[], int name_count, const char *attribute_list[], int attribute_count) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    record->offset = offset;
    record->key = key;
    record->value = value;

    // Allocate memory for the name
    record->name = (char *)malloc((strlen(names[key % name_count]) + 1) * sizeof(char));
    if (record->name == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(record);
        exit(1);
    }
    strcpy(record->name, names[key % name_count]);

    // Allocate memory for the attributes array
    record->attributes = (char **)malloc(attribute_count * sizeof(char *));
    if (record->attributes == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(record->name);
        free(record);
        exit(1);
    }

    // Initialize each attribute in the array
    for (int i = 0; i < attribute_count; i++) {
        record->attributes[i] = (char *)malloc((strlen(attribute_list[i]) + 1) * sizeof(char));
        if (record->attributes[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; j++) {
                free(record->attributes[j]);
            }
            free(record->name);
            free(record->attributes);
            free(record);
            exit(1);
        }
        strcpy(record->attributes[i], attribute_list[i]);
    }

    return record;
}

// Function to free the memory allocated for a record
void free_record(Record *record, int attribute_count) {
    if (record != NULL) {
        free(record->name);
        for (int i = 0; i < attribute_count; i++) {
            free(record->attributes[i]);
        }
        free(record->attributes);
        free(record);
    }
}

// Example usage
int main() {
    srand(time(NULL));

    // Define names and attributes
    const char *names[] = {"Alice", "Bob", "Charlie"};
    const char *attributes[] = {"Attribute1", "Attribute2", "Attribute3"};

    int name_count = sizeof(names) / sizeof(names[0]);
    int attribute_count = sizeof(attributes) / sizeof(attributes[0]);

    // Initialize a record
    Record *record = init_record(12345, 2, 3.14, names, name_count, attributes, attribute_count);

    // Free the allocated memory for the record
    free_record(record, attribute_count);

    return 0;
}
