        records[i]->key_ptr = &keys[i];
    }
}

void log_memory_allocation(void* ptr, size_t size) {
    printf("Allocated %zu bytes at address %p\n", size, ptr);
}

void initialize_arrays(int array_size, int min_value, int max_value, int** keys, struct record*** records, int enable_logging) {
    custom_malloc((void**)keys, array_size * sizeof(int));
    custom_malloc((void**)records, array_size * sizeof(struct record*));

    srand(time(NULL));

    for (int i = 0; i < array_size; i++) {
        keys[i] = i;
    }

    if (enable_logging) log_memory_allocation(keys, array_size * sizeof(int));
    initialize_record(*records, array_size, min_value, max_value, *keys);

    if (enable_logging) {
        for (int i = 0; i < array_size; i++) {
            printf("Record %d: Value = %d, Key Address = %p\n", i, (*records)[i]->value, (*records)[i]->key_ptr);
        }
    }
}

void deallocate_memory(int* keys, struct record** records, int array_size) {
    for (int i = 0; i < array_size; i++) {
        free(records[i]);
    }
    free(records);
