void sort_records(Record* records, int size) {
    // Simple bubble sort for demonstration purposes
    for (int i = 0; i < size - 1; ++i) {
        for (int j = 0; j < size - i - 1; ++j) {
            if (records[j].key > records[j + 1].key) {
                Record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

void update_records(Record* records, long* offsets, int size, int min_val, int max_val) {
    for (int i = 0; i < size; ++i) {
        long cumulative_sum = 0;
        for (int j = 0; j <= i; ++j) {
            cumulative_sum += offsets[j];
        }
        records[i].key = min_val + rand() % (max_val - min_val);
    }
}

void print_records(Record* records, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Key: %d, Offset: %ld\n", records[i].key, records[i].offset);
    }
}

