// Define a structure to hold cryptographic operations
typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *digest_ctx;
} CryptoContext;

// Function to initialize the cryptographic module
void init_crypto_module() {
    // Add AES, Camellia, MD5, SHA, and RSA with SHA1 algorithms
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_256_ecb());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest_alias("sha", "sha1");
}

// Function to create a new cryptographic context
CryptoContext* create_crypto_context() {
    CryptoContext *ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    ctx->cipher_ctx = EVP_CIPHER_CTX_new();
    ctx->digest_ctx = EVP_MD_CTX_create();
    return ctx;
}

// Function to free the cryptographic context
void free_crypto_context(CryptoContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->cipher_ctx);
    EVP_MD_CTX_destroy(ctx->digest_ctx);
    free(ctx);
}

// Function to perform encryption using AES
void encrypt_data(CryptoContext *ctx, const unsigned char *plaintext, int plaintext_len,
                   unsigned char *ciphertext, int *ciphertext_len) {
    EVP_EncryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx->cipher_ctx, ciphertext, ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx->cipher_ctx, ciphertext + *ciphertext_len, ciphertext_len);
}

// Function to perform decryption using AES
void decrypt_data(CryptoContext *ctx, const unsigned char *ciphertext, int ciphertext_len,
                   unsigned char *plaintext, int *plaintext_len) {
    EVP_DecryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_DecryptUpdate(ctx->cipher_ctx, plaintext, plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx->cipher_ctx, plaintext + *plaintext_len, plaintext_len);
}

// Function to perform MD5 hash
void md5_hash(const unsigned char *data, int data_len, unsigned char *md5_out) {
    EVP_MD_CTX_init(ctx->digest_ctx);
    EVP_DigestInit_ex(ctx->digest_ctx, EVP_md5(), NULL);
    EVP_DigestUpdate(ctx->digest_ctx, data, data_len);
    EVP_DigestFinal_ex(ctx->digest_ctx, md5_out, &md5_len);
    EVP_MD_CTX_cleanup(ctx->digest_ctx);
}

// Function to perform SHA1 hash
void sha1_hash(const unsigned char *data, int data_len, unsigned char *sha1_out) {
    EVP_MD_CTX_init(ctx->digest_ctx);
    EVP_DigestInit_ex(ctx->digest_ctx, EVP_sha1(), NULL);
    EVP_DigestUpdate(ctx->digest_ctx, data, data_len);
    EVP_DigestFinal_ex(ctx->digest_ctx, sha1_out, &sha1_len);
    EVP_MD_CTX_cleanup(ctx->digest_ctx);
}

// Function to resize memory allocations
void *resize_memory(void *ptr, size_t old_size, size_t new_size) {
    void *new_ptr = realloc(ptr, new_size);
    if (new_ptr == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return new_ptr;
}

// Function to sort records by key values
void sort_records_by_key(Record *records, int record_count) {
    qsort(records, record_count, sizeof(Record), compare_records_by_key);
}

// Function to calculate cumulative sum of offset values
void calculate_cumulative_sum(Record *records, int record_count) {
    for (int i = 1; i < record_count; i++) {
        records[i].offset += records[i - 1].offset;
    }
}

// Function to generate a random value within a specified range
unsigned int generate_random_value(unsigned int min, unsigned int max) {
