#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_HEAP_SIZE 1024 * 1024 * 10 // 10 MB
#define DEFERRED_INIT_THRESHOLD 512

typedef struct {
    int* data;
    size_t array_size;
    int min_value;
    int max_value;
    int enable_logging;
    size_t logging_max_size;
    FILE* log_file;
} RecordSet;

void custom_malloc(size_t size, void** ptr) {
    if (*ptr != NULL) free(*ptr);
    *ptr = malloc(size > MAX_HEAP_SIZE ? MAX_HEAP_SIZE : size);
}

RecordSet* create_record_set(size_t array_size, int min_value, int max_value, int enable_logging, size_t logging_max_size, const char* external_data_source) {
    RecordSet* rs = (RecordSet*)malloc(sizeof(RecordSet));
    rs->array_size = array_size;
    rs->min_value = min_value;
    rs->max_value = max_value;
    rs->enable_logging = enable_logging;
    rs->logging_max_size = logging_max_size;

    custom_malloc(array_size * sizeof(int), (void**)&rs->data);

    if (enable_logging) {
        rs->log_file = fopen("record_set.log", "w");
        if (!rs->log_file) return NULL;
        setvbuf(rs->log_file, NULL, _IOFBF, logging_max_size);
    }

    // Initialize data with random values between min_value and max_value
    for (size_t i = 0; i < array_size; i++) {
        rs->data[i] = rand() % (max_value - min_value + 1) + min_value;
        if (enable_logging) fprintf(rs->log_file, "Allocated memory address: %p, Value: %d\n", &rs->data[i], rs->data[i]);
    }

    return rs;
}

void destroy_record_set(RecordSet* rs) {
    if (rs->enable_logging && rs->log_file) fclose(rs->log_file);
    free(rs->data);
    free(rs);
}

int main() {
    RecordSet* rs = create_record_set(1000, 0, 100, 1, 1024 * 1024, "external_data_source");
    if (rs) {
        // Use the record set
        destroy_record_set(rs);
    }
    return 0;
}
