#include <pthread.h>

typedef struct {
    int timestamp;
    int status;
    // Add additional metadata fields here
} record;

typedef struct {
    int key;
    record *rec_ptr;
} hash_entry;

typedef struct {
    hash_entry **buckets;
    size_t size;
    size_t capacity;
    size_t initial_buckets;
    size_t max_heap_size;
    size_t current_memory_usage;
    pthread_mutex_t lock;
} hash_table;

typedef struct {
    void *(*malloc)(size_t);
    void (*free)(void *);
    size_t max_heap_size;
    size_t current_memory_usage;
    // Add other custom memory allocator functions here
} custom_allocator;

hash_table *create_hash_table(size_t initial_buckets, size_t max_heap_size) {
    hash_table *ht = (hash_table *)malloc(sizeof(hash_table));
    ht->buckets = (hash_entry **)calloc(initial_buckets, sizeof(hash_entry *));
    ht->size = 0;
    ht->capacity = initial_buckets;
    ht->initial_buckets = initial_buckets;
    ht->max_heap_size = max_heap_size;
    ht->current_memory_usage = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void free_hash_table(hash_table *ht) {
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->buckets[i] != NULL) {
            free(ht->buckets[i]->rec_ptr);
            free(ht->buckets[i]);
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void insert_into_hash_table(hash_table *ht, int key, record *rec_ptr) {
    pthread_mutex_lock(&ht->lock);
    size_t index = key % ht->capacity;
    while (ht->buckets[index] != NULL && ht->buckets[index]->key != key) {
        index = (index + 1) % ht->capacity;
    }
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = (hash_entry *)malloc(sizeof(hash_entry));
        ht->size++;
    }
    ht->buckets[index]->key = key;
    ht->buckets[index]->rec_ptr = rec_ptr;
    pthread_mutex_unlock(&ht->lock);
}

record *create_record(int status, // Additional parameters for metadata
                      custom_allocator *allocator) {
    record *rec = (record *)allocator->malloc(sizeof(record));
    if (rec != NULL) {
        rec->timestamp = time(NULL);
        rec->status = status;
        // Initialize additional metadata fields here
        allocator->current_memory_usage += sizeof(record);
        if (allocator->current_memory_usage > allocator->max_heap_size) {
            fprintf(stderr, "Memory allocation failed. Maximum heap size exceeded.\n");
            allocator->free(rec);
            return NULL;
        }
    }
    return rec;
}

void destroy_record(record *rec, custom_allocator *allocator) {
    // Destroy additional metadata fields here
    allocator->current_memory_usage -= sizeof(record);
    allocator->free(rec);
}

int main() {
    size_t record_count = 100;
    size_t initial_buckets = 16;
    size_t max_heap_size = 1024 * 1024; // 1 MB
    int start_key = 0;
    int step_value = 1;
    int enable_logging = 1;
    size_t log_rotate_size = 10 * 1024 * 1024; // 10 MB

    custom_allocator allocator;
    allocator.malloc = malloc;
    allocator.free = free;
    allocator.max_heap_size = max_heap_size;
    allocator.current_memory_usage = 0;

    hash_table *ht = create_hash_table(initial_buckets, max_heap_size);

    for (int i = start_key; i < record_count; i += step_value) {
        record *rec = create_record(/* Additional parameters for metadata */, &allocator);
        if (rec != NULL) {
            insert_into_hash_table(ht, i, rec);
        }
    }

    free_hash_table(ht);

    return 0;
}
