    for (int i = 0; i < size; i++) {
        array[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
}

void initializeCompoundRecordArray(CompoundRecord* array, int size, int minValue, int maxValue) {
    for (int i = 0; i < size; i++) {
        array[i].value1 = rand() % (maxValue - minValue + 1) + minValue;
        array[i].value2 = rand() % (maxValue - minValue + 1) + minValue;
    }
}

WeightedRecord* initializeWeightedRecordArray(int size, float* weights, int* floatValues) {
    WeightedRecord* array = allocateMemory(size * sizeof(WeightedRecord));
    for (int i = 0; i < size; i++) {
        array[i].floatValue = floatValues[i];
        array[i].weight = weights[i];
    }
    return array;
}

float weightedRandomFloat(float* weights, int size) {
    float totalWeight = 0.0f;
    for (int i = 0; i < size; i++) {
        totalWeight += weights[i];
    }
    if (totalWeight != 1.0f) {
        fprintf(stderr, "Weights must sum up to 1.0f\n");
        exit(1);
    }
    float randomValue = rand() / (float)RAND_MAX;
    float cumulativeWeight = 0.0f;
    for (int i = 0; i < size; i++) {
        cumulativeWeight += weights[i];
        if (randomValue <= cumulativeWeight) {
            return weights[i];
        }
    }
    return weights[size - 1];
}

float weightedAverage(float* values, float* weights, int size) {
    float totalWeight = 0.0f;
    for (int i = 0; i < size; i++) {
        totalWeight += weights[i];
    }
    if (totalWeight != 1.0f) {
        fprintf(stderr, "Weights must sum up to 1.0f\n");
        exit(1);
    }
    float weightedSum = 0.0f;
    for (int i = 0; i < size; i++) {
        weightedSum += values[i] * weights[i];
    }
    return weightedSum / totalWeight;
}

void setSeed(unsigned int seed) {
    srand(seed);
}

