        do {
            uniqueId = minId + rand() % (maxId - minId + 1);
        } while (isUniqueIdUsed(entities, i, uniqueId));

        entities[i].id = uniqueId;
        entities[i].priority = rand() % 10 + 1; // Priority level between 1 and 10
        entities[i].velocity = ((float)rand() / RAND_MAX) * 9.9f + 0.1f; // Velocity between 0.1f and 10.0f

        entities[i].position.x = ((float)rand() / RAND_MAX) * 2000.0f - 1000.0f; // Position coordinates between -1000.0f and 1000.0f
        entities[i].position.y = ((float)rand() / RAND_MAX) * 2000.0f - 1000.0f;
        entities[i].position.z = ((float)rand() / RAND_MAX) * 2000.0f - 1000.0f;

        List<float>* sensorReadings = createRandomFloatList(5, 0.0f, 1.0f);
        if (!sensorReadings) {
            free(entities); // Clean up allocated memory on error
            return NULL;
        }
        entities[i].sensorReadings = *sensorReadings;
    }

    return entities;
}

int isUniqueIdUsed(SimulationEntity* entities, int currentIndex, long id) {
    for (int i = 0; i < currentIndex; ++i) {
        if (entities[i].id == id) {
            return 1; // ID already used
        }
    }
    return 0;
}

List<float>* createRandomFloatList(int count, float minVal, float maxVal) {
    List<float>* list = malloc(count * sizeof(float));
    if (!list) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < count; ++i) {
        list[i] = ((float)rand() / RAND_MAX) * (maxVal - minVal) + minVal;
    }

    return list;
}

void freeSimulationEntities(SimulationEntity* entities, int count) {
    for (int i = 0; i < count; ++i) {
        freeList(entities[i].sensorReadings);
    }
    free(entities);
}

float calculateAverageVelocity(SimulationEntity* entities, int count) {
    float totalVelocity = 0.0f;
    for (int i = 0; i < count; ++i) {
        totalVelocity += entities[i].velocity;
    }
    return totalVelocity / count;
}

float calculateMedianSensorReading(SimulationEntity* entities, int count) {
    List<float> allReadings = createEmptyList();
    for (int i = 0; i < count; ++i) {
        concatenateLists(&allReadings, entities[i].sensorReadings);
    }
    float median = findMedian(allReadings);
    freeList(allReadings);
