            );
            entity.SensorReadings = new List<float>();
            for (int i = 0; i < 5; i++)
            {
                entity.SensorReadings.Add(randomValueGenerator.GetFloat(0.0f, 1.0f));
            }

            entities.Add(entity);
        }

        return entities;
    }

    public float ComputeAverageVelocity(List<SimulationEntity> entities)
    {
        if (entities == null || entities.Count == 0)
        {
            return 0.0f;
        }

        float totalVelocity = 0.0f;
        foreach (var entity in entities)
        {
            totalVelocity += entity.Velocity;
        }
        return totalVelocity / entities.Count;
    }

    public float ComputeMedianSensorReading(List<SimulationEntity> entities)
    {
        if (entities == null || entities.Count == 0)
        {
            return 0.0f;
        }

        List<float> sensorReadings = new List<float>();
        foreach (var entity in entities)
        {
            sensorReadings.AddRange(entity.SensorReadings);
        }

        sensorReadings.Sort();
        int count = sensorReadings.Count;
        if (count % 2 == 1)
        {
            return sensorReadings[count / 2];
        }
        else
        {
            return (sensorReadings[(count - 1) / 2] + sensorReadings[count / 2]) / 2.0f;
        }
    }
}

public class EncryptionManager
{
    public byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream decryptedData = new MemoryStream())
                    {
                        csDecrypt.CopyTo(decryptedData);
                        return decryptedData.ToArray();
                    }
                }
            }
        }
    }
}
