    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Record* create_records(int initial_size, int max_size, unsigned long seed) {
    srand(seed);

    Record* records = safe_malloc(max_size * sizeof(Record));
    for (int i = 0; i < initial_size; i++) {
        records[i].offset = rand();
        if (rand() % 2 == 0) {
            records[i].key = -1;
        } else {
            records[i].key = rand();
        }
    }

    return records;
}

void resize_records(Record** records, int* current_size, int new_size, int max_size) {
    if (new_size > max_size || new_size < 0) {
        fprintf(stderr, "Invalid size for resizing\n");
        return;
    }

    *records = realloc(*records, new_size * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = *current_size; i < new_size; i++) {
        (*records)[i].offset = rand();
        if (rand() % 2 == 0) {
            (*records)[i].key = -1;
        } else {
            (*records)[i].key = rand();
        }
    }

    *current_size = new_size;
}

void free_records(Record* records) {
    free(records);
}

int main() {
    int initial_size = 10;
    int max_size = 100;
    unsigned long seed = time(NULL);

    Record* records = create_records(initial_size, max_size, seed);

    // Example of resizing
    resize_records(&records, &initial_size, 20, max_size);

    free_records(records);

    return 0;
}
