    char *connection_string;
} network_connection;

config_struct* initialize_config(size_t initial_size, int seed) {
    if (seed < 0 || seed > INT_MAX) {
        fprintf(stderr, "Invalid seed value.\n");
        return NULL;
    }

    config_struct *cfg = malloc(sizeof(config_struct));
    if (!cfg) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    cfg->int_keys = malloc(initial_size * sizeof(int));
    cfg->long_offsets = malloc(initial_size * sizeof(long));
    if (!cfg->int_keys || !cfg->long_offsets) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(cfg);
        return NULL;
    }

    cfg->size = 0;
    cfg->capacity = initial_size;

    srand(seed);

    for (size_t i = 0; i < initial_size; ++i) {
        cfg->int_keys[i] = rand() % INT_MAX;
        cfg->long_offsets[i] = rand() % LONG_MAX;
    }

    return cfg;
}

void resize_arrays(config_struct *cfg, size_t new_capacity) {
    if (new_capacity <= cfg->capacity || new_capacity > SIZE_MAX / sizeof(int) || new_capacity > SIZE_MAX / sizeof(long)) {
        fprintf(stderr, "Invalid capacity value.\n");
        return;
    }

    int *new_int_keys = realloc(cfg->int_keys, new_capacity * sizeof(int));
    long *new_long_offsets = realloc(cfg->long_offsets, new_capacity * sizeof(long));

    if (!new_int_keys || !new_long_offsets) {
        fprintf(stderr, "Memory reallocation failed.\n");
        free(new_int_keys);
        free(new_long_offsets);
        return;
    }

    cfg->int_keys = new_int_keys;
    cfg->long_offsets = new_long_offsets;
    cfg->capacity = new_capacity;
}

void add_record(config_struct *cfg) {
    if (cfg->size >= cfg->capacity) {
        resize_arrays(cfg, cfg->capacity * 2);
    }

    cfg->int_keys[cfg->size] = rand() % INT_MAX;
    cfg->long_offsets[cfg->size] = rand() % LONG_MAX;
    ++cfg->size;
}

void cleanup_config(config_struct *cfg) {
    free(cfg->int_keys);
    free(cfg->long_offsets);
    free(cfg);
}
