#define INITIAL_SIZE 10

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    record *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} record_array;

void init_record_array(record_array *array) {
    array->capacity = INITIAL_SIZE;
    array->size = 0;
    array->data = (record *)malloc(array->capacity * sizeof(record));
    if (array->data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->mutex, NULL);
}

void resize_record_array(record_array *array, size_t new_capacity) {
    record *new_data = (record *)realloc(array->data, new_capacity * sizeof(record));
    if (new_data == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void add_record_to_array(record_array *array, long offset, int key) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        resize_record_array(array, array->capacity * 2);
    }
    array->data[array->size].offset = offset;
    array->data[array->size].key = key;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

void free_record_array(record_array *array) {
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
}
