typedef struct {
    size_t size;
    void* (*allocate)(size_t);
    void (*free)(void*);
} CustomAllocator;

// Define record structure
typedef struct {
    long offset;
    int key;
} Record;

// Function to dynamically load user settings, network parameters, and a custom event handler
int load_configuration(CustomAllocator* allocator, long* offsets, int* keys, size_t initial_size) {
    // Initialize arrays with given size
    offsets = (long*)allocator->allocate(initial_size * sizeof(long));
    keys = (int*)allocator->allocate(initial_size * sizeof(int));
    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize records with initial size
    Record* records = (Record*)allocator->allocate(initial_size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        allocator->free(offsets);
        allocator->free(keys);
        return -1;
    }

    // Populate records with default values or load from configuration
    for (size_t i = 0; i < initial_size; ++i) {
        offsets[i] = 0;
        keys[i] = 0;
        records[i].offset = 0;
        records[i].key = 0;
    }

    // Example function to resize arrays and records
    void resize(CustomAllocator* allocator, long** offsets, int** keys, Record** records, size_t new_size) {
        *offsets = (long*)allocator->allocate(new_size * sizeof(long));
        *keys = (int*)allocator->allocate(new_size * sizeof(int));
        *records = (Record*)allocator->allocate(new_size * sizeof(Record));

        if (!*offsets || !*keys || !*records) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        // Copy existing data and initialize new elements
        for (size_t i = 0; i < initial_size && i < new_size; ++i) {
            (*offsets)[i] = offsets[i];
            (*keys)[i] = keys[i];
            (*records)[i].offset = records[i].offset;
            (*records)[i].key = records[i].key;
        }

        // Free old memory
        allocator->free(offsets);
        allocator->free(keys);
        allocator->free(records);

        offsets = *offsets;
        keys = *keys;
        records = *records;
    }

    // Example usage of resize function
    size_t new_size = initial_size * 2;
    resize(allocator, &offsets, &keys, &records, new_size);

    // Clean up
    allocator->free(offsets);
    allocator->free(keys);
    allocator->free(records);

    return 0;
}

// Example usage of custom allocator
int main() {
    CustomAllocator allocator = {
        .size = 1024 * 1024,
        .allocate = malloc,
        .free = free
    };

    long* offsets;
    int* keys;
    size_t initial_size = 10;

    if (load_configuration(&allocator, &offsets, &keys, initial_size) == 0) {
        printf("Configuration loaded successfully\n");
    } else {
        printf("Failed to load configuration\n");
    }

    return 0;
}
