import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.regex.Pattern;

public class EmailValidator {

    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[a-zA-Z0-9_+&*-]+(?:\\.[a-zA-Z0-9_+&*-]+)*@" +
            "(?:[a-zA-Z0-9-]+\\.)+[a-zA-Z]{2,7}$");
    private static final int MAX_EMAIL_LENGTH = 256;
    private static final String PALINDROME_PLACEHOLDER = "palindrome";
    private static final boolean ENABLE_PALINDROME_CHECK = true; // Configuration option
    private static final boolean ENABLE_HASHING = true; // Configuration option

    public static void validateAndProcessEmails(String filePath) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(filePath)))) {
            String line;
            while ((line = reader.readLine()) != null) {
                processLine(line);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void processLine(String line) {
        for (String email : line.split("\\s+")) {
            if (email.length() > MAX_EMAIL_LENGTH) {
                continue;
            }
            if (ENABLE_PALINDROME_CHECK && isPalindrome(email)) {
                System.out.println(PALINDROME_PLACEHOLDER);
            } else if (isValidEmail(email)) {
                if (ENABLE_HASHING) {
                    try {
                        String md5Hash = getMD5Hash(email);
                        System.out.println("Valid Email: " + email + ", MD5 Hash: " + md5Hash);
                    } catch (NoSuchAlgorithmException e) {
                        e.printStackTrace();
                    }
                } else {
                    System.out.println("Valid Email: " + email);
                }
            }
        }
    }

    private static boolean isValidEmail(String email) {
        return EMAIL_PATTERN.matcher(email).matches();
    }

    private static boolean isPalindrome(String email) {
        String reversed = new StringBuilder(email).reverse().toString();
        return email.equalsIgnoreCase(reversed);
    }

    private static String getMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) {
        validateAndProcessEmails("path/to/your/emailfile.txt");
    }
}
