        int cell_id = cell_ids[i];
        if (cell_id <= 0) continue; // Skip invalid CELL_IDs

        records[i].CELL_ID = cell_id;
        records[i].MEASUREMENT_TIME = time(NULL);

        // Generate random RSSI and CQI values
        records[i].stats.RSSI = rand() % 100; // Random value between 0 and 99
        records[i].stats.CQI = rand() % 20; // Random value between 0 and 19
    }

