import json

class JSONSerializer:
    def __init__(self):
        self.factory_registry = {}

    def register_factory(self, type_name, factory_function):
        self.factory_registry[type_name] = factory_function

    def deserialize_from_json(self, json_string):
        data = json.loads(json_string)
        if 'type' in data:
            type_name = data['type']
            if type_name in self.factory_registry:
                return self.factory_registry[type_name](data)
        raise ValueError("Unknown type or no type specified in JSON")

    def serialize_to_json(self, obj):
        return json.dumps(obj)

# Example usage
serializer = JSONSerializer()
serializer.register_factory('example_type', lambda data: ExampleType(data['value']))
json_data = '{"type": "example_type", "value": 42}'
obj = serializer.deserialize_from_json(json_data)
