import json
from collections import defaultdict

class JSONSerializer:
    _registry = defaultdict(lambda: None)

    @staticmethod
    def register_type(type_name, deserialize_func):
        JSONSerializer._registry[type_name] = deserialize_func

    @staticmethod
    def serialize(obj):
        return json.dumps(obj, default=lambda o: o.__dict__)

    @staticmethod
    def deserialize(json_str):
        data = json.loads(json_str)
        if 'type' in data:
            type_name = data['type']
            deserialize_func = JSONSerializer._registry[type_name]
            if deserialize_func is not None:
                return deserialize_func(data)
        raise ValueError("Unsupported type or missing deserialization function")
