#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the Record structure
typedef struct {
    int value;
} Record;

// Function to calculate ceil division
int ceil_div(int a, int b) {
    return (a + b - 1) / b;
}

// Function to allocate memory and initialize data structures
void allocate_and_initialize(long numOffsets, int minVal, int maxVal) {
    if (numOffsets <= 0 || minVal > maxVal) {
        printf("Invalid input parameters.\n");
        return;
    }

    // Step 1: Allocate memory for offsets
    long *offsets = (long *)aligned_alloc(alignof(long), numOffsets * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return;
    }

    // Step 2: Allocate memory for keys with proper bounds checking
    int numKeys = ceil_div(numOffsets, 2);
    int *keys = (int *)aligned_alloc(alignof(int), numKeys * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return;
    }

    // Step 3: Allocate and initialize records with random values
    Record *records = (Record *)aligned_alloc(alignof(Record), numKeys * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return;
    }

    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < numKeys; ++i) {
        keys[i] = rand() % (maxVal - minVal + 1) + minVal;
        records[i].value = keys[i]; // Assuming Record value is initialized as key
    }

    // Step 4: Free allocated memory in a controlled manner
    free(offsets);
    free(keys);
    free(records);

    printf("Memory allocation and initialization completed successfully.\n");
}

// Main function to demonstrate usage
int main() {
    long numOffsets = 10;
    int minVal = -50, maxVal = 50;

    allocate_and_initialize(numOffsets, minVal, maxVal);

    return 0;
}
