#include <stdlib.h>
#include <pthread.h>

#define MAX_SSID_LENGTH 64

typedef struct {
    char SSID[MAX_SSID_LENGTH];
    char BSSID[18]; // MAC address format: XX:XX:XX:XX:XX:XX
    double RSSI;
    int CHANNEL_FREQUENCY;
    int LINK_QUALITY_INDEX;
} WIFI_SCAN_RESULT_RECORD_T;

void* allocate_offsets(size_t numOffsets) {
    if (numOffsets == 0) return NULL;
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    if (!offsets) {
        // Handle allocation failure
        return NULL;
    }
    for (size_t i = 0; i < numOffsets; ++i) {
        offsets[i] = i * sizeof(long);
    }
    return offsets;
}

void** allocate_matrix(size_t rows, size_t cols) {
    if (rows == 0 || cols == 0) return NULL;
    double** matrix = (double**)malloc(rows * sizeof(double*));
    if (!matrix) {
        // Handle allocation failure
        return NULL;
    }
    for (size_t i = 0; i < rows; ++i) {
        matrix[i] = (double*)malloc(cols * sizeof(double));
        if (!matrix[i]) {
            // Handle allocation failure
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(matrix[j]);
            }
            free(matrix);
            return NULL;
        }
    }
    return matrix;
}

void add_matrices(double** A, double** B, double** C, size_t rows, size_t cols) {
    pthread_t* threads = (pthread_t*)malloc(rows * sizeof(pthread_t));
    if (!threads) {
        // Handle allocation failure
        return;
    }

    for (size_t i = 0; i < rows; ++i) {
        pthread_create(&threads[i], NULL, add_matrix_row, (void*)(struct MatrixAdditionParams){A[i], B[i], C[i], cols});
    }
    for (size_t i = 0; i < rows; ++i) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
}

void* add_matrix_row(void* arg) {
    struct MatrixAdditionParams params = *(struct MatrixAdditionParams*)arg;
    double* A_row = params.A;
    double* B_row = params.B;
    double* C_row = params.C;
    size_t cols = params.cols;

    for (size_t j = 0; j < cols; ++j) {
        C_row[j] = A_row[j] + B_row[j];
    }

    return NULL;
}

WIFI_SCAN_RESULT_RECORD_T** allocate_wifi_scan_results(size_t numResults) {
    if (numResults == 0) return NULL;
    WIFI_SCAN_RESULT_RECORD_T** records = (WIFI_SCAN_RESULT_RECORD_T**)malloc(numResults * sizeof(WIFI_SCAN_RESULT_RECORD_T*));
    if (!records) {
        // Handle allocation failure
        return NULL;
    }
    for (size_t i = 0; i < numResults; ++i) {
        records[i] = (WIFI_SCAN_RESULT_RECORD_T*)malloc(sizeof(WIFI_SCAN_RESULT_RECORD_T));
        if (!records[i]) {
            // Handle allocation failure
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }
    }
    return records;
}

void validate_and_add_record(WIFI_SCAN_RESULT_RECORD_T** records, size_t* numRecords, WIFI_SCAN_RESULT_RECORD_T newRecord) {
    for (size_t i = 0; i < *numRecords; ++i) {
        if (strcmp(records[i]->SSID, newRecord.SSID) == 0 && strcmp(records[i]->BSSID, newRecord.BSSID) == 0) {
            return;
        }
    }
    records[*numRecords] = (WIFI_SCAN_RESULT_RECORD_T*)malloc(sizeof(WIFI_SCAN_RESULT_RECORD_T));
    if (!records[*numRecords]) {
        // Handle allocation failure
        return;
    }
    *records[*numRecords] = newRecord;
    (*numRecords)++;
}

void free_matrix(double** matrix, size_t rows) {
    for (size_t i = 0; i < rows; ++i) {
        free(matrix[i]);
    }
    free(matrix);
