#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

int** allocate_offsets(int numOffsets) {
    int** offsets = (int**)allocate_memory(numOffsets * sizeof(int*));
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = (int*)allocate_memory(sizeof(int));
    }
    return offsets;
}

void free_offsets(int** offsets, int numOffsets) {
    for (int i = 0; i < numOffsets; i++) {
        free(offsets[i]);
    }
    free(offsets);
}

int* allocate_keys(int numOffsets) {
    if (numOffsets % 2 != 0) {
        numOffsets++;
    }
    int size = numOffsets / 2;
    int* keys = (int*)allocate_memory(size * sizeof(int));
    return keys;
}

void free_keys(int* keys) {
    free(keys);
}

Record** allocate_records(int* keys, int numKeys) {
    Record** records = (Record**)allocate_memory(numKeys * sizeof(Record*));
    for (int i = 0; i < numKeys; i++) {
        records[i] = (Record*)allocate_memory(sizeof(Record));
        records[i]->value = rand() % keys[numKeys - 1];
    }
    return records;
}

void free_records(Record** records, int numKeys) {
    for (int i = 0; i < numKeys; i++) {
        free(records[i]);
    }
    free(records);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <numOffsets>\n", argv[0]);
        return EXIT_FAILURE;
