typedef struct {
    int value;
} Record;

int custom_round(double num) {
    return (int)(num + 0.5);
}

void allocate_and_initialize_memory(int numOffsets, long **offsets, int **keys, Record **records, int minValue, int maxValue) {
    if (numOffsets <= 0) {
        fprintf(stderr, "Invalid number of offsets\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offsets
    *offsets = aligned_alloc(64, numOffsets * sizeof(long));
    if (*offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for keys
    *keys = (int *)malloc(custom_round(numOffsets / 2.0) * sizeof(int));
    if (*keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for records
    *records = (Record *)calloc(custom_round(numOffsets / 2.0), sizeof(Record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    // Initialize offsets with random values
    srand(time(NULL));
    for (int i = 0; i < numOffsets; i++) {
        (*offsets)[i] = rand() % 1000;
    }

    // Initialize keys with unique values and records with random values
    int keySet[custom_round(numOffsets / 2.0)];
    memset(keySet, 0, custom_round(numOffsets / 2.0) * sizeof(int));
    for (int i = 0; i < custom_round(numOffsets / 2.0); i++) {
        do {
            (*keys)[i] = rand() % numOffsets;
        } while (keySet[(*keys)[i]] != 0);
        keySet[(*keys)[i]] = 1;
    }

    for (int i = 0; i < custom_round(numOffsets / 2.0); i++) {
        (*records)[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
}

void free_memory(long *offsets, int *keys, Record *records) {
    if (offsets != NULL) {
        aligned_free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
}
