#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_BUCKET_SIZE 16
#define LOAD_FACTOR 0.75

typedef struct CacheEntry {
    char *key;
    void *value;
    size_t value_size;
    time_t expiration_time;
    int ref_count;
    struct CacheEntry *next;
} CacheEntry;

typedef struct HashTable {
    CacheEntry **buckets;
    size_t bucket_count;
    size_t entry_count;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash_function(const char *key, size_t bucket_count) {
    unsigned int hash = 0;
    for (int i = 0; key[i] != '\0'; ++i) {
        hash = (hash * 31 + key[i]) % bucket_count;
    }
    return hash;
}

HashTable* create_hash_table(size_t initial_size) {
    if (initial_size == 0 || initial_size < 0) {
        fprintf(stderr, "Invalid initial size for hash table.\n");
        return NULL;
    }

    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    ht->buckets = (CacheEntry **)calloc(initial_size, sizeof(CacheEntry *));
    ht->bucket_count = initial_size;
    ht->entry_count = 0;
    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

void resize_hash_table(HashTable *ht) {
    size_t new_size = ht->bucket_count * 2;
    CacheEntry **new_buckets = (CacheEntry **)calloc(new_size, sizeof(CacheEntry *));
    for (size_t i = 0; i < ht->bucket_count; ++i) {
        CacheEntry *entry = ht->buckets[i];
        while (entry != NULL) {
            size_t new_index = hash_function(entry->key, new_size);
            CacheEntry *next_entry = entry->next;
            entry->next = new_buckets[new_index];
            new_buckets[new_index] = entry;
            entry = next_entry;
        }
    }

    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->bucket_count = new_size;
}

void insert_to_cache(HashTable *ht, const char *key, void *value, size_t value_size, time_t expiration_time) {
    pthread_mutex_lock(&ht->lock);

    if (ht->entry_count / (double)ht->bucket_count > LOAD_FACTOR) {
        resize_hash_table(ht);
    }

    unsigned int index = hash_function(key, ht->bucket_count);
    CacheEntry *new_entry = (CacheEntry *)malloc(sizeof(CacheEntry));
    new_entry->key = strdup(key);
    new_entry->value = malloc(value_size);
    memcpy(new_entry->value, value, value_size);
    new_entry->value_size = value_size;
    new_entry->expiration_time = expiration_time;
    new_entry->ref_count = 1;
    new_entry->next = ht->buckets[index];

    ht->buckets[index] = new_entry;
    ++ht->entry_count;

    pthread_mutex_unlock(&ht->lock);
}

void *retrieve_from_cache(HashTable *ht, const char *key) {
    pthread_mutex_lock(&ht->lock);

    unsigned int index = hash_function(key, ht->bucket_count);
    CacheEntry *entry = ht->buckets[index];
    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0 && time(NULL) < entry->expiration_time) {
            ++entry->ref_count;
            pthread_mutex_unlock(&ht->lock);
            return entry->value;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void release_from_cache(HashTable *ht, const char *key) {
    pthread_mutex_lock(&ht->lock);

    unsigned int index = hash_function(key, ht->bucket_count);
    CacheEntry **prev_ptr = &ht->buckets[index];
    CacheEntry *entry = *prev_ptr;
    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0 && time(NULL) < entry->expiration_time) {
            --entry->ref_count;
            if (entry->ref_count <= 0) {
                *prev_ptr = entry->next;
                free(entry->key);
                free(entry->value);
                free(entry);
                --ht->entry_count;
                if (ht->entry_count > 0 && ht->entry_count / (double)ht->bucket_count < 0.25) {
                    resize_hash_table(ht);
                }
            }
            pthread_mutex_unlock(&ht->lock);
            return;
        }
        prev_ptr = &entry->next;
        entry = *prev_ptr;
    }

    pthread_mutex_unlock(&ht->lock);
}

void free_cache(HashTable *ht) {
    for (size_t i = 0; i < ht->bucket_count; ++i) {
        CacheEntry *entry = ht->buckets[i];
        while (entry != NULL) {
            CacheEntry *next_entry = entry->next;
            free(entry->key);
            free(entry->value);
            free(entry);
            entry = next_entry;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}
