    int LINK_QUALITY_INDEX;
} WIFI_SCAN_RESULT_RECORD_T;

typedef struct {
    WIFI_SCAN_RESULT_RECORD_T *records;
    size_t count;
} WIFI_SCAN_LIST_T;

Matrix* createMatrix(size_t numOffsets) {
    Matrix *matrix = (Matrix*)malloc(sizeof(Matrix));
    if (!matrix) return NULL;

    matrix->offsets = (long*)calloc(numOffsets, sizeof(long));
    if (!matrix->offsets) {
        free(matrix);
        return NULL;
    }

    matrix->numOffsets = numOffsets;
    return matrix;
}

void destroyMatrix(Matrix *matrix) {
    if (matrix->offsets) free(matrix->offsets);
    free(matrix);
}

WIFI_SCAN_LIST_T* createScanList(size_t initialCapacity) {
    WIFI_SCAN_LIST_T *list = (WIFI_SCAN_LIST_T*)malloc(sizeof(WIFI_SCAN_LIST_T));
    if (!list) return NULL;

    list->records = (WIFI_SCAN_RESULT_RECORD_T*)calloc(initialCapacity, sizeof(WIFI_SCAN_RESULT_RECORD_T));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->count = 0;
    return list;
}

void destroyScanList(WIFI_SCAN_LIST_T *list) {
    if (list->records) free(list->records);
    free(list);
}

int addScanResult(WIFI_SCAN_LIST_T *list, WIFI_SCAN_RESULT_RECORD_T result) {
    if (list->count >= INITIAL_CAPACITY) {
        // Resize the list dynamically
        WIFI_SCAN_RESULT_RECORD_T *newRecords = (WIFI_SCAN_RESULT_RECORD_T*)realloc(list->records, list->count * 2 * sizeof(WIFI_SCAN_RESULT_RECORD_T));
        if (!newRecords) return -1;

        list->records = newRecords;
    }

    // Check for uniqueness of SSID and BSSID
    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->records[i].SSID, result.SSID) == 0 && strcmp(list->records[i].BSSID, result.BSSID) == 0) return -1;
    }

    list->records[list->count++] = result;
    return 0;
}

