#include <pthread.h>

typedef enum {
    ACTIVE,
    INACTIVE,
    DELETED
} status;

typedef struct object {
    float value;
    char* str;
    status state;
    int access_count;
    pthread_mutex_t lock;
} object;

typedef struct list {
    object** objects;
    size_t size;
    size_t capacity;
    size_t max_size;
    pthread_mutex_t lock;
} list;

list* create_list(size_t initial_capacity, size_t max_size) {
    list* l = (list*)malloc(sizeof(list));
    if (!l) return NULL;
    l->objects = (object**)malloc(initial_capacity * sizeof(object*));
    if (!l->objects) {
        free(l);
        return NULL;
    }
    l->size = 0;
    l->capacity = initial_capacity;
    l->max_size = max_size;
    pthread_mutex_init(&l->lock, NULL);
    return l;
}

void destroy_list(list* l) {
    for (size_t i = 0; i < l->size; ++i) {
        free(l->objects[i]->str);
        free(l->objects[i]);
    }
    free(l->objects);
    pthread_mutex_destroy(&l->lock);
    free(l);
}

int insert_object(list* l, float value, char* str, status state) {
    if (l->size == l->capacity && l->size >= l->max_size) return -1;
    object* o = (object*)malloc(sizeof(object));
    if (!o) return -1;
    pthread_mutex_init(&o->lock, NULL);
    o->value = value;
    o->str = strdup(str);
    o->state = state;
    o->access_count = 0;
    pthread_mutex_lock(&l->lock);
    l->objects[l->size++] = o;
    pthread_mutex_unlock(&l->lock);
    return 0;
}

int delete_object(list* l, size_t index) {
    if (index >= l->size) return -1;
    free(l->objects[index]->str);
    free(l->objects[index]);
    pthread_mutex_lock(&l->lock);
    for (size_t i = index; i < l->size - 1; ++i) {
        l->objects[i] = l->objects[i + 1];
    }
    l->size--;
    pthread_mutex_unlock(&l->lock);
    return 0;
}

void serialize_list(list* l, FILE* file) {
    pthread_mutex_lock(&l->lock);
    fwrite(&l->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < l->size; ++i) {
        object* o = l->objects[i];
        fwrite(&o->value, sizeof(float), 1, file);
        size_t len = strlen(o->str) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(o->str, 1, len, file);
        fwrite(&o->state, sizeof(status), 1, file);
    }
    pthread_mutex_unlock(&l->lock);
}

int deserialize_list(list* l, FILE* file) {
    size_t size;
    if (fread(&size, sizeof(size_t), 1, file) != 1 || size > l->max_size) return -1;
    pthread_mutex_lock(&l->lock);
    for (size_t i = 0; i < l->size; ++i) {
        free(l->objects[i]->str);
        free(l->objects[i]);
    }
    l->size = 0;
    for (size_t i = 0; i < size; ++i) {
        object* o = (object*)malloc(sizeof(object));
        if (!o) {
            pthread_mutex_unlock(&l->lock);
            return -1;
        }
        pthread_mutex_init(&o->lock, NULL);
        fread(&o->value, sizeof(float), 1, file);
        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        o->str = (char*)malloc(len * sizeof(char));
        if (!o->str) {
            free(o);
            pthread_mutex_unlock(&l->lock);
            return -1;
        }
        fread(o->str, 1, len, file);
        fread(&o->state, sizeof(status), 1, file);
        o->access_count = 0;
        l->objects[l->size++] = o;
    }
    pthread_mutex_unlock(&l->lock);
    return 0;
}

void* object_callback(void* arg) {
