        perror("Failed to allocate memory for records");
        return NULL;
    }
    memset(records, 0, size * sizeof(record));
    return records;
}

void set_random_keys(record* records, size_t size, int min_key, int max_key, unsigned long seed) {
    if (seed < 0 || seed > ULONG_MAX) {
        fprintf(stderr, "Error: Invalid seed value\n");
        return;
    }
    srand(seed);
    int key_frequency[100] = {0}; // Assuming keys are in the range [0, 99]
    for (size_t i = 0; i < size; ++i) {
        int random_key;
        do {
            random_key = rand() % (max_key - min_key + 1) + min_key;
        } while (key_frequency[random_key] > 0);
        records[i].key = random_key;
        key_frequency[random_key]++;
    }
}

void log_error(const char* message) {
    // Logging mechanism implementation
}

void serialize_records(record* records, size_t size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(records, sizeof(record), size, file);
    fclose(file);
}

record* deserialize_records(const char* filename, size_t* size) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return NULL;
    }
    fseek(file, 0, SEEK_END);
    *size = ftell(file) / sizeof(record);
    rewind(file);
    record* records = (record*)malloc(*size * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for deserialized records");
        fclose(file);
        return NULL;
    }
    fread(records, sizeof(record), *size, file);
    fclose(file);
    return records;
}

int main() {
    size_t size = 1000; // Example size
    record* records = allocate_and_initialize_records(size);
    if (records == NULL) {
        return EXIT_FAILURE;
    }

    set_random_keys(records, size, 0, 99, 42);

    serialize_records(records, size, "records.bin");

    free(records);
    return EXIT_SUCCESS;
}
