#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

void printManPage() {
    printf("Usage: program [--manpage] -cs input_file [-o output_file]\n");
}

int parseArgs(int argc, char *argv[], int *outputFile) {
    bool manpage = false, cs = false;
    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "--manpage")) {
            manpage = true;
            continue;
        }
        if (!strcmp(argv[i], "-cs")) {
            cs = true;
            continue;
        }
        if (!strcmp(argv[i], "-o") && i + 1 < argc) {
            *outputFile = open(argv[++i], O_WRONLY | O_CREAT, 0644);
            if (*outputFile == -1) {
                perror("Failed to open output file");
                return -1;
            }
        } else if (argv[i][0] != '-') {
            return i; // Return index of the first non-option argument
        }
    }
    return manpage || cs ? 0 : -1;
}

record* initRecords(int *count, int range) {
    record *records = malloc(sizeof(record) * MAX_RECORDS);
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    *count = rand() % MAX_RECORDS + 1;
    for (int i = 0; i < *count; ++i) {
        records[i].value = rand() % range + 1;
    }
    return records;
}

void readFileAndCountLines(const char *filename, int *lineCount) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open input file");
        exit(EXIT_FAILURE);
    }
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        (*lineCount)++;
    }
    fclose(file);
}

int main(int argc, char *argv[]) {
    int outputFile = STDOUT_FILENO;
    int optionIndex = parseArgs(argc, argv, &outputFile);
    if (optionIndex == 0) {
        printManPage();
        return EXIT_SUCCESS;
    } else if (optionIndex == -1) {
        fprintf(stderr, "Error parsing arguments\n");
        return EXIT_FAILURE;
    }

    const char *inputFile = argv[optionIndex];
    int recordsCount, range = 100; // Assuming default range for simplicity
    record *records = initRecords(&recordsCount, range);

    int lineCount = 0;
    readFileAndCountLines(inputFile, &lineCount);

    printf("Number of lines in %s: %d\n", inputFile, lineCount);

    free(records);
    if (outputFile != STDOUT_FILENO) {
        close(outputFile);
    }
    return EXIT_SUCCESS;
}
