void parse_command_line(int argc, char* argv[], int* flags, const char** input_file, const char** output_file) {
    *input_file = NULL;
    *output_file = NULL;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printf("Man page content here.\n");
            exit(0);
        } else if (strcmp(argv[i], "-cs") == 0) {
            *flags |= 1 << 0;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            *output_file = argv[++i];
        } else if (*input_file == NULL) {
            *input_file = argv[i];
