#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

Record* record_storage[MAX_RECORDS];
long* offset_values = NULL;
int* keys = NULL;
int record_count = 0;
int max_records = MAX_RECORDS;

void initialize_system() {
    offset_values = (long*)malloc(max_records * sizeof(long));
    keys = (int*)malloc(max_records * sizeof(int));
}

void add_record(int key, int value) {
    if (record_count >= max_records) {
        fprintf(stderr, "Error: Maximum records reached.\n");
        return;
    }

    for (int i = 0; i < record_count; i++) {
        if (keys[i] == key) {
            fprintf(stderr, "Error: Key already exists.\n");
            return;
        }
    }

    record_storage[record_count] = (Record*)malloc(sizeof(Record));
    record_storage[record_count]->value = value;

    offset_values[record_count] = rand();
    keys[record_count++] = key;
}

int retrieve_record(int key) {
    for (int i = 0; i < record_count; i++) {
        if (keys[i] == key) {
            return record_storage[i]->value;
        }
    }

    fprintf(stderr, "Error: Key not found.\n");
    return -1; // Assuming -1 as an error value
}

void free_system() {
    for (int i = 0; i < record_count; i++) {
        free(record_storage[i]);
    }

    free(offset_values);
    free(keys);
}

int main() {
    srand(time(NULL));
    initialize_system();

    add_record(1, 42);
    printf("Retrieved value: %d\n", retrieve_record(1));

    free_system();
    return 0;
}
