int offset_array[MAX_RECORDS];
int key_array[MAX_RECORDS];

int add_record(int key, int value) {
    if (key >= MAX_RECORDS || key < 0) {
        printf("Error: Key out of range\n");
        return -1;
    }

    if (offset_array[key] != -1) {
        printf("Error: Duplicate key detected\n");
        return -1;
    }

    records[key] = (Record*)malloc(sizeof(Record));
    if (!records[key]) {
        printf("Memory allocation failed\n");
        return -1;
    }

    records[key]->value = value;
    offset_array[key] = key;
    key_array[offset_array[key]] = key;

    return 0;
}

int get_record(int key) {
    if (key >= MAX_RECORDS || key < 0) {
        printf("Error: Key out of range\n");
        return -1;
    }

    if (offset_array[key] == -1) {
        printf("Error: Record not found\n");
        return -1;
    }

    return records[offset_array[key]]->value;
}

void init_system() {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i] = NULL;
        offset_array[i] = -1;
        key_array[i] = -1;
    }
}

void free_system() {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }
}

int main() {
    srand(time(NULL));
    init_system();

    for (int i = 0; i < 1000; ++i) {
        int key = rand() % MAX_RECORDS;
        int value = rand() % 100000;
        add_record(key, value);
    }

    for (int i = 0; i < 1000; ++i) {
        int key = rand() % MAX_RECORDS;
        printf("Value for key %d: %d\n", key, get_record(key));
    }

    free_system();
    return 0;
}
