CRC_INDICATION_PDU_T* allocate_and_populate_array(int *N, int thread_id) {
    static CRC_INDICATION_PDU_T *cache[CACHE_SIZE];
    static int cache_index = 0;
    static int last_used_thread_id = -1;

    if (last_used_thread_id != thread_id) {
        // Evict least recently used entry from cache
        if (cache_index >= CACHE_SIZE) {
            free(cache[0]);
            memmove(cache, cache + 1, sizeof(CRC_INDICATION_PDU_T*) * (CACHE_SIZE - 1));
            cache_index--;
        }
        last_used_thread_id = thread_id;
    }

    // Allocate and populate new entry if needed
    if (cache_index < CACHE_SIZE) {
        CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(CRC_INDICATION_PDU_T));
        if (new_entry == NULL) {
            return NULL; // Handle allocation failure
        }
        int ue_id;
        while (!fetch_ue_info(rand() % MAX_UE_TAGS, &ue_id)); // Ensure unique tag
        new_entry->ue_tag = ue_id;
        generate_crc_flag(&new_entry->crcflag);
        cache[cache_index++] = new_entry;
    }

    *N = cache_index;
    return cache[0];
}
