#define MAX_KEYS 1024
#define HASH_SIZE 128
#define MIN_TRANSACTION_AGE 60
#define MAX_CONCURRENT_REQUESTS 10

typedef struct {
    long offset;
    int key;
    double value;
} record;

int hash_function(int key) {
    return abs(key) % HASH_SIZE;
}

record* create_record(long offset, int key, double value) {
    record* r = malloc(sizeof(record));
    if (r != NULL) {
        r->offset = offset;
        r->key = key;
        r->value = value;
    }
