#define MAX_SENSORS 100

typedef struct {
    long offset;
    int key;
    double value;
    float humidity;
} record;

record records[MAX_SENSORS];
int sensor_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* process_sensor_data(void* arg) {
    // Simulate processing sensor data
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_SENSORS && sensor_count > 0; i++) {
        records[i].value += 1.0;
        records[i].humidity += 0.5;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void add_sensor_calibration(int key, double value) {
    if (sensor_count >= MAX_SENSORS) {
        printf("Sensor calibration limit reached\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    records[sensor_count].key = key;
    records[sensor_count].value = value;
    records[sensor_count].humidity = 0.0;
    sensor_count++;
    pthread_mutex_unlock(&mutex);

    printf("Calibration added: Key %d, Value %.2f\n", key, value);
}

int main() {
    pthread_t threads[MAX_SENSORS];

    for (int i = 0; i < MAX_SENSORS; i++) {
        pthread_create(&threads[i], NULL, process_sensor_data, NULL);
    }

    for (int i = 0; i < MAX_SENSORS; i++) {
        pthread_join(threads[i], NULL);
    }

    add_sensor_calibration(1, 10.5);

    return 0;
}
