#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

typedef struct MemoryManager {
    Record* records;
    size_t array_size;
    size_t allocated_size;
    size_t min_value;
    size_t max_value;
    int enable_logging;
    size_t logging_max_size;
    FILE* log_file;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_size, size_t min_value, size_t max_value, int enable_logging, size_t logging_max_size) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->records = (Record*)calloc(initial_size, sizeof(Record));
    manager->array_size = initial_size;
    manager->allocated_size = initial_size;
    manager->min_value = min_value;
    manager->max_value = max_value;
    manager->enable_logging = enable_logging;
    manager->logging_max_size = logging_max_size;

    if (enable_logging) {
        manager->log_file = fopen("memory_log.txt", "w");
    } else {
        manager->log_file = NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    if (manager->records != NULL) {
        free(manager->records);
    }
    if (manager->enable_logging && manager->log_file != NULL) {
        fclose(manager->log_file);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void resize_memory_manager(MemoryManager* manager, size_t new_size) {
    pthread_mutex_lock(&manager->lock);

    Record* new_records = (Record*)realloc(manager->records, new_size * sizeof(Record));
    if (new_records == NULL) {
        // Handle allocation failure
        perror("Failed to resize memory");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->records = new_records;
    manager->array_size = new_size;

    pthread_mutex_unlock(&manager->lock);

    if (manager->enable_logging && manager->log_file != NULL) {
        fprintf(manager->log_file, "Memory resized to %zu elements\n", new_size);
    }
}

void initialize_records(MemoryManager* manager) {
    for (size_t i = 0; i < manager->array_size; ++i) {
        if (manager->records[i].value == 0) {
            // Initialize with a random value between min_value and max_value
            manager->records[i].value = manager->min_value + rand() % (manager->max_value - manager->min_value + 1);
        }
    }

    if (manager->enable_logging && manager->log_file != NULL) {
        for (size_t i = 0; i < manager->array_size; ++i) {
            fprintf(manager->log_file, "Record %zu initialized with value %d\n", i, manager->records[i].value);
        }
    }
}

void* memory_manager_thread(void* arg) {
    MemoryManager* manager = (MemoryManager*)arg;

    initialize_records(manager);

    // Simulate dynamic changes in array size
    resize_memory_manager(manager, 1000);
    initialize_records(manager);
    resize_memory_manager(manager, 500);
    initialize_records(manager);

    return NULL;
}

int main() {
    srand(time(NULL));

    MemoryManager* manager = create_memory_manager(200, 10, 100, 1, 10000);
    pthread_t thread;

    if (pthread_create(&thread, NULL, memory_manager_thread, manager) != 0) {
        perror("Failed to create thread");
        destroy_memory_manager(manager);
        return 1;
    }

    pthread_join(thread, NULL);

    destroy_memory_manager(manager);

    return 0;
}
```

This code snippet provides a basic implementation of a memory management system in C. It includes dynamic array resizing, record initialization, logging, and synchronization mechanisms to ensure thread safety. The `resize_memory_manager` function handles dynamic changes in the size of the managed array, while `initialize_records` initializes new records with random values within a specified range. The `memory_manager_thread` demonstrates how to use these functions in a multi-threaded context.']

