    arr->count = 0;
    arr->max_size = initial_size;
    pthread_mutex_init(&arr->lock, NULL);
}

void add_element_to_array(ThreadSafeArray* arr, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return; // Handle memory allocation failure
    new_node->data = data;
    new_node->next = arr->head;
    arr->head = new_node;
    arr->count++;
}

void free_array(ThreadSafeArray* arr) {
    Node* current = arr->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&arr->lock);
}

