#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct hash_map_node {
    int key;
    long offset;
    struct hash_map_node *next;
} hash_map_node;

typedef struct {
    hash_map_node **buckets;
    size_t size;
} hash_map;

hash_map* create_hash_map(size_t size) {
    hash_map *map = (hash_map*)malloc(sizeof(hash_map));
    map->size = size;
    map->buckets = (hash_map_node**)calloc(size, sizeof(hash_map_node*));
    return map;
}

void insert_into_hash_map(hash_map *map, int key, long offset) {
    size_t index = key % map->size;
    hash_map_node *node = (hash_map_node*)malloc(sizeof(hash_map_node));
    node->key = key;
    node->offset = offset;
    node->next = map->buckets[index];
    map->buckets[index] = node;
}

long get_from_hash_map(hash_map *map, int key) {
    size_t index = key % map->size;
    hash_map_node *node = map->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            return node->offset;
        }
        node = node->next;
    }
    return -1; // Key not found
}

void free_hash_map(hash_map *map) {
    for (size_t i = 0; i < map->size; ++i) {
        hash_map_node *node = map->buckets[i];
        while (node != NULL) {
            hash_map_node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(map->buckets);
    free(map);
}

int* create_usage_tracker(size_t size) {
    return (int*)calloc(size, sizeof(int));
}

void initialize_records(record *records, size_t count, int low, int high) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (high - low + 1) + low;
    }
}

record* initialize_data_structures(size_t n, size_t m, int low, int high) {
    if (n == 0 || m == 0) {
        return NULL; // Invalid input
    }

    record *records = (record*)malloc(m * sizeof(record));
    long *offsets = (long*)malloc(n * sizeof(long));
    int *keys = (int*)malloc(n * sizeof(int));
    hash_map *hash_map = create_hash_map(n);
    int *indexes = create_usage_tracker(n);

    if (!records || !offsets || !keys || !hash_map || !indexes) {
        free(records);
        free(offsets);
        free(keys);
        free_hash_map(hash_map);
        free(indexes);
        return NULL; // Memory allocation failed
    }

    initialize_records(records, m, low, high);

    for (size_t i = 0; i < n; ++i) {
        offsets[i] = rand() % n;
        keys[i] = i;
        insert_into_hash_map(hash_map, keys[i], offsets[i]);
    }

    return records;
}

void free_data_structures(record *records, long *offsets, int *keys, hash_map *hash_map, int *indexes) {
    free(records);
    free(offsets);
    free(keys);
    free_hash_map(hash_map);
    free(indexes);
}
