        free(tx_map);
        free(tx_index->indices);
        free(tx_index);
        free(logs);
        return NULL;
    }
    pthread_mutex_init(&tx_map->lock, NULL);

    // Initialize pending_transactions
    pending_transactions *pending_tx = (pending_transactions *)malloc(sizeof(pending_transactions));
    if (!pending_tx) {
        perror("Failed to allocate memory for pending_tx");
        free(tx_map->buckets);
        free(tx_map);
        free(tx_index->indices);
        free(tx_index);
        free(logs);
        return NULL;
    }
    pthread_mutex_init(&pending_tx->lock, NULL);
    pending_tx->head = NULL;

    // Load cryptographic primitives
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_256_ecb());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest_alias("sha", "sha1");

    // Initialize other data structures as needed

    return (void *)tx_map;
}

// Function to free the allocated memory
void free_data_structures(void *data) {
    transaction_map *tx_map = (transaction_map *)data;

    pthread_mutex_lock(&tx_map->lock);
    for (size_t i = 0; i < tx_map->size; ++i) {
        transaction_map_entry *entry = tx_map->buckets[i];
        while (entry) {
            transaction_map_entry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    pthread_mutex_unlock(&tx_map->lock);

    pthread_mutex_destroy(&tx_map->lock);
    free(tx_map->buckets);
    free(tx_map);
}
