    pthread_mutex_t pending_tasks_lock;
};

void initialize_task_manager(struct task_manager *manager, size_t n) {
    manager->task_queue = malloc(n * sizeof(struct task));
    if (!manager->task_queue) {
        fprintf(stderr, "Failed to allocate memory for task queue\n");
        exit(1);
    }

    manager->task_index = calloc(n, sizeof(unsigned int));
    if (!manager->task_index) {
        fprintf(stderr, "Failed to allocate memory for task index\n");
        free(manager->task_queue);
        exit(1);
    }

    manager->task_map.num_buckets = n;
    manager->task_map.buckets = malloc(n * sizeof(struct task_map_entry *));
    if (!manager->task_map.buckets) {
        fprintf(stderr, "Failed to allocate memory for task map buckets\n");
        free(manager->task_index);
        free(manager->task_queue);
        exit(1);
    }
    for (size_t i = 0; i < n; ++i) {
        manager->task_map.buckets[i] = NULL;
    }

    pthread_mutex_init(&manager->task_map.lock, NULL);
    pthread_mutex_init(&manager->pending_tasks_lock, NULL);

    manager->pending_tasks = NULL;
}

void destroy_task_manager(struct task_manager *manager) {
    for (size_t i = 0; i < manager->task_map.num_buckets; ++i) {
        struct task_map_entry *entry = manager->task_map.buckets[i];
        while (entry) {
            struct task_map_entry *next = entry->next;
            free(entry);
            entry = next;
        }
    }

    pthread_mutex_destroy(&manager->task_map.lock);
    pthread_mutex_destroy(&manager->pending_tasks_lock);

    free(manager->task_queue);
    free(manager->task_index);
    free(manager->task_map.buckets);
}

void add_task_to_manager(struct task_manager *manager, struct task *task) {
    // Add the task to the task queue and update the task map
}

void remove_task_from_manager(struct task_manager *manager, unsigned int id) {
