#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Task {
    int id;
    int priority;
    char status[20];
} Task;

typedef struct Entry {
    Task *task;
    struct Entry *next;
} Entry;

int hash(int key, int size) {
    return abs(key % size);
}

void insertEntry(Entry **hashTable, int size, Task *newTask) {
    int index = hash(newTask->id, size);
    if (hashTable[index] == NULL) {
        hashTable[index] = malloc(sizeof(Entry));
        hashTable[index]->task = newTask;
        hashTable[index]->next = NULL;
    } else {
        Entry *temp = hashTable[index];
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = malloc(sizeof(Entry));
        temp->next->task = newTask;
        temp->next->next = NULL;
    }
}

Task* getTaskById(Entry **hashTable, int size, int taskId) {
    int index = hash(taskId, size);
    Entry *entry = hashTable[index];
    while (entry != NULL) {
        if (entry->task->id == taskId) {
            return entry->task;
        }
        entry = entry->next;
    }
    return NULL;
}

void updateTaskStatus(Entry **hashTable, int size, int taskId, const char *newStatus) {
    Task *task = getTaskById(hashTable, size, taskId);
    if (task != NULL) {
        strcpy(task->status, newStatus);
    } else {
        printf("Task with ID %d not found.\n", taskId);
    }
}

void initializeTasks(int n, int m, int lowPriority, int highPriority, Task **tasks, Entry ***hashTable, int **priorities) {
    srand(time(0));

    *tasks = malloc(n * sizeof(Task));
    if (*tasks == NULL) {
        fprintf(stderr, "Memory allocation failed for tasks.\n");
        exit(1);
    }

    *hashTable = malloc(m * sizeof(Entry *));
    if (*hashTable == NULL) {
        fprintf(stderr, "Memory allocation failed for hash table.\n");
        free(*tasks);
        exit(1);
    }
    for (int i = 0; i < m; ++i) {
        (*hashTable)[i] = NULL;
    }

    *priorities = malloc(n * sizeof(int));
    if (*priorities == NULL) {
        fprintf(stderr, "Memory allocation failed for priorities.\n");
        free(*tasks);
        free(*hashTable);
        exit(1);
    }

    for (int i = 0; i < n; ++i) {
        (*tasks)[i].id = i + 1;
        (*tasks)[i].priority = lowPriority + rand() % (highPriority - lowPriority + 1);
        strcpy((*tasks)[i].status, "pending");
        insertEntry(*hashTable, m, &(*tasks)[i]);
        (*priorities)[i] = (*tasks)[i].priority;
    }
}

// Example usage:
int main() {
    int n = 5;
    int m = 10;
    int lowPriority = 1;
    int highPriority = 10;

    Task *tasks;
    Entry **hashTable;
    int *priorities;

    initializeTasks(n, m, lowPriority, highPriority, &tasks, &hashTable, &priorities);

    // Example update
    updateTaskStatus(hashTable, m, 3, "completed");

    // Free allocated memory
    for (int i = 0; i < m; ++i) {
        Entry *entry = hashTable[i];
        while (entry != NULL) {
            Entry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(hashTable);
    free(tasks);
    free(priorities);

    return 0;
}
