#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TASKS 1000
#define MAX_ENTRIES 1000
#define DEFAULT_STATUS "pending"
#define RESIZE_THRESHOLD 0.75

typedef struct {
    int id;
    int priority;
    char status[20];
    char description[100];
    time_t completion_date;
} Task;

typedef struct {
    int key;
    Task *value;
} Entry;

typedef struct {
    Entry entries[MAX_ENTRIES];
    int size;
    pthread_mutex_t lock;
} HashTable;

Task *tasks[MAX_TASKS];
HashTable task_table;
int priorities[MAX_TASKS];
pthread_mutex_t priority_lock;

void init_task(Task *task, int id, int priority, const char *description) {
    task->id = id;
    task->priority = priority;
    strcpy(task->status, DEFAULT_STATUS);
    strncpy(task->description, description, sizeof(task->description));
    task->completion_date = time(NULL) - (rand() % 365);
}

void init_task_table(int m) {
    pthread_mutex_init(&task_table.lock, NULL);
    for (int i = 0; i < m; i++) {
        task_table.entries[i].value = NULL;
    }
}

void resize_task_table(HashTable *table, int new_size) {
    Entry *old_entries = table->entries;
    int old_size = table->size;

    pthread_mutex_init(&table->lock, NULL);
    table->entries = (Entry *)malloc(new_size * sizeof(Entry));
    table->size = new_size;

    for (int i = 0; i < new_size; i++) {
        table->entries[i].value = NULL;
    }

    for (int i = 0; i < old_size; i++) {
        if (old_entries[i].value != NULL) {
            int index = old_entries[i].key % new_size;
            pthread_mutex_lock(&table->lock);
            table->entries[index].value = old_entries[i].value;
            pthread_mutex_unlock(&table->lock);
        }
    }

    free(old_entries);
}

void insert_task_table(HashTable *table, Task *task) {
    int index = task->id % table->size;
    pthread_mutex_lock(&table->lock);
    table->entries[index].value = task;
    pthread_mutex_unlock(&table->lock);
}

Task *get_task_table(HashTable *table, int id) {
    int index = id % table->size;
    pthread_mutex_lock(&table->lock);
    Task *task = table->entries[index].value;
    pthread_mutex_unlock(&table->lock);
    return task;
}

void prune_old_tasks(HashTable *table, int x_days) {
    time_t cutoff_time = time(NULL) - (x_days * 86400);
    for (int i = 0; i < table->size; i++) {
        pthread_mutex_lock(&table->lock);
        Task *task = table->entries[i].value;
        if (task != NULL && strcmp(task->status, "completed") == 0) {
            time_t completion_time = task->completion_date;
            if (difftime(completion_time, cutoff_time) > 0) {
                table->entries[i].value = NULL;
            }
        }
        pthread_mutex_unlock(&table->lock);
    }
}

void update_task_status(int id, const char *new_status) {
    Task *task = get_task_table(&task_table, id);
    if (task != NULL) {
        pthread_mutex_lock(&priority_lock);
        // Update task status and handle versioning here
        pthread_mutex_unlock(&priority_lock);
    }
}

