#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
} record;

int allocate_arrays(long **offsets, int **keys, record **records, long num_records, const char *buffer_str, int min_value, int max_value) {
    *offsets = (long *)malloc(num_records * sizeof(long));
    if (*offsets == NULL) return -1;

    *keys = (int *)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        free(*keys);
        free(*offsets);
        return -1;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (long i = 0; i < num_records; ++i) {
        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
        strcpy((*records)[i].buffer, buffer_str);
    }

    pthread_mutex_destroy(&lock);

    return 0;
}

void free_arrays(long *offsets, int *keys, record *records) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}

void print_records(record *records, long num_records) {
    for (long i = 0; i < num_records; ++i) {
        printf("Record %ld: Value = %d, Buffer = %s\n", i, records[i].value, records[i].buffer);
    }
}
