#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum {
    ACTIVE,
    INACTIVE,
    PENDING
} State;

typedef struct {
    int value;
    char buffer[256];
    State *metadata;
} Record;

typedef struct {
    char *message;
    char **tags;
    size_t tag_count;
} Event;

typedef struct {
    State state;
    time_t timestamp;
    Event *event;
} Metadata;

typedef struct DataStore {
    Record **records;
    Metadata **metadatas;
    size_t record_count;
    size_t metadata_count;
} DataStore;

DataStore* init_data_store(size_t num_records, size_t buffer_size) {
    DataStore *store = (DataStore*)malloc(sizeof(DataStore));
    if (!store) {
        return NULL;
    }

    store->records = (Record**)malloc(num_records * sizeof(Record*));
    if (!store->records) {
        free(store);
        return NULL;
    }

    store->metadatas = (Metadata**)malloc(num_records * sizeof(Metadata*));
    if (!store->metadatas) {
        free(store->records);
        free(store);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        store->records[i] = (Record*)malloc(sizeof(Record));
        if (!store->records[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(store->records[j]);
            }
            free(store->records);
            free(store->metadatas);
            free(store);
            return NULL;
        }

        store->records[i]->buffer[0] = '\0';
        store->records[i]->value = rand() % buffer_size;

        store->metadatas[i] = (Metadata*)malloc(sizeof(Metadata));
        if (!store->metadatas[i]) {
            for (size_t j = 0; j <= i; ++j) {
                free(store->records[j]);
            }
            free(store->records);
            for (size_t j = 0; j < num_records; ++j) {
                free(store->metadatas[j]);
            }
            free(store->metadatas);
            free(store);
            return NULL;
        }

        store->metadatas[i]->state = ACTIVE;
        store->metadatas[i]->timestamp = time(NULL);
        store->metadatas[i]->event = (Event*)malloc(sizeof(Event));
        if (!store->metadatas[i]->event) {
            for (size_t j = 0; j <= i; ++j) {
                free(store->records[j]);
            }
            free(store->records);
            for (size_t j = 0; j < num_records; ++j) {
                free(store->metadatas[j]->event);
                free(store->metadatas[j]);
            }
            free(store->metadatas);
            free(store);
            return NULL;
        }

        store->metadatas[i]->event->message = (char*)malloc(1024 * sizeof(char));
        if (!store->metadatas[i]->event->message) {
            for (size_t j = 0; j <= i; ++j) {
                free(store->records[j]);
            }
            free(store->records);
            for (size_t j = 0; j < num_records; ++j) {
                free(store->metadatas[j]->event->message);
                free(store->metadatas[j]->event);
                free(store->metadatas[j]);
            }
            free(store->metadatas);
            free(store);
            return NULL;
        }

        store->metadatas[i]->event->tags = (char**)malloc(10 * sizeof(char*));
        if (!store->metadatas[i]->event->tags) {
            for (size_t j = 0; j <= i; ++j) {
                free(store->records[j]);
            }
            free(store->records);
            for (size_t j = 0; j < num_records; ++j) {
                free(store->metadatas[j]->event->message);
                free(store->metadatas[j]->event->tags);
                free(store->metadatas[j]->event);
                free(store->metadatas[j]);
            }
            free(store->metadatas);
            free(store);
            return NULL;
        }

        store->record_count = num_records;
        store->metadata_count = num_records;

    }

    return store;
}

void cleanup_data_store(DataStore *store) {
    if (!store) return;

    for (size_t i = 0; i < store->record_count; ++i) {
        free(store->records[i]);
    }
    free(store->records);

    for (size_t i = 0; i < store->metadata_count; ++i) {
        free(store->metadatas[i]->event->tags);
        free(store->metadatas[i]->event->message);
        free(store->metadatas[i]->event);
        free(store->metadatas[i]);
    }
    free(store->metadatas);

    free(store);
}

// Additional functions for thread safety, logging, state validation,
// concurrent read/write operations, external data store integration,
// notification API usage, buffer compression, record filtering,
// support for large numbers of records, and load balancing would be implemented here.
