        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memset(node->children, 0, sizeof(node->children));
    node->data = NULL;
    return node;
}

void insertDocument(TrieNode* root, Document* doc, int id) {
    TrieNode* current = root;
    for (int i = 0; title[i] != '\0'; i++) {
        if (!current->children[(unsigned char)title[i]]) {
            current->children[(unsigned char)title[i]] = createTrieNode();
        }
        current = current->children[(unsigned char)title[i]];
    }
    current->data = (void*)id;
}

int searchPrefix(TrieNode* root, const char* prefix) {
    TrieNode* current = root;
    for (int i = 0; prefix[i] != '\0'; i++) {
        if (!current->children[(unsigned char)prefix[i]]) {
            return -1;
        }
        current = current->children[(unsigned char)prefix[i]];
    }
    if (current->data != NULL) {
        return *(int*)current->data;
    }
    return -1;
}

Document* createDocuments(int n, int m, int** timestamps) {
    if (n <= 0 || m <= 0) {
        fprintf(stderr, "Invalid input: n and m must be positive integers\n");
        exit(EXIT_FAILURE);
    }

    Document* documents = (Document*)malloc(n * sizeof(Document));
    if (documents == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    *timestamps = (int*)malloc(n * sizeof(int));
    if (*timestamps == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(documents);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n; i++) {
        documents[i].id = i;
        strncpy(documents[i].title, "Untitled", MAX_TITLE_LENGTH);
        strcpy(documents[i].content, "");
        documents[i].last_modified = time(NULL);
        (*timestamps)[i] = (int)documents[i].last_modified;
    }

    TrieNode* root = createTrieNode();

    for (int i = 0; i < n; i++) {
        insertDocument(root, &documents[i], i);
    }

    return documents;
}

void updateDocument(Document* document, const char* newTitle, const char* newContent) {
    strncpy(document->title, newTitle, MAX_TITLE_LENGTH);
    strcpy(document->content, newContent);
    document->last_modified = time(NULL);
}

void printDocuments(Document* documents, int n, int* timestamps) {
    for (int i = 0; i < n; i++) {
        printf("ID: %d, Title: %s, Content: %s, Last Modified: %ld\n",
               documents[i].id, documents[i].title, documents[i].content, timestamps[i]);
    }
}

