impl MemoryManager {
    fn new(size: usize, initial_value_range: (u8, u8)) -> Self {
        let mut node_pool = Vec::with_capacity(size);
        for _ in 0..size {
            node_pool.extend_from_slice(&[0; std::mem::size_of::<TreeNode>()]);
        }
        MemoryManager {
            node_pool: Arc::new(Mutex::new(node_pool)),
            nodes: HashSet::new(),
            logger: Logger::new(),
        }
