#define MAX_STREAMS 100
#define RECORD_SIZE sizeof(struct record)
struct record {
    long offset;
    int key;
};

typedef struct {
    void* memory_pool;
    size_t pool_size;
    size_t used_memory;
} MemoryManager;

void init_memory_manager(MemoryManager* mm, size_t initial_size) {
    mm->memory_pool = malloc(initial_size);
    if (mm->memory_pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    mm->pool_size = initial_size;
    mm->used_memory = 0;
}

void* allocate_record(MemoryManager* mm, size_t num_records) {
    size_t required_memory = num_records * RECORD_SIZE;
    if (mm->used_memory + required_memory > mm->pool_size) {
        fprintf(stderr, "Memory allocation exceeds pool limit\n");
        return NULL;
    }
    void* new_records = mm->memory_pool + mm->used_memory;
    memset(new_records, 0, required_memory);
    mm->used_memory += required_memory;
    return new_records;
}

void resize_memory_manager(MemoryManager* mm, size_t new_size) {
    void* new_pool = realloc(mm->memory_pool, new_size);
    if (new_pool == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    mm->memory_pool = new_pool;
    mm->pool_size = new_size;
}

void free_memory_manager(MemoryManager* mm) {
    free(mm->memory_pool);
}

int main() {
    MemoryManager manager;
    init_memory_manager(&manager, 1024 * 1024); // 1 MB initial pool size

    struct record* records = allocate_record(&manager, 1000);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return EXIT_FAILURE;
    }

    // Initialize records...

    resize_memory_manager(&manager, manager.pool_size * 2); // Double the pool size

    free_memory_manager(&manager);

    return EXIT_SUCCESS;
}
