#define MAX_TRANSACTION_TIMEOUT 10

typedef enum {
    TRANSACTION_TYPE_TAG,
    TRANSACTION_STATUS_TAG,
    TRANSACTION_TIMEOUT_TAG
} TAG;

typedef struct {
    int type;
    int status;
    time_t timeout;
} MAC_TRANSACTION_T;

typedef struct {
    MAC_TRANSACTION_T* transactions;
    size_t capacity;
    size_t count;
} MAC_TRANSACTION_MANAGER_T;

void mac_transaction_manager_init(MAC_TRANSACTION_MANAGER_T* manager, size_t initial_capacity) {
    manager->transactions = (MAC_TRANSACTION_T*)malloc(initial_capacity * sizeof(MAC_TRANSACTION_T));
    if (!manager->transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
}

void mac_transaction_manager_add(MAC_TRANSACTION_MANAGER_T* manager, int type, int status, time_t timeout) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        MAC_TRANSACTION_T* new_transactions = (MAC_TRANSACTION_T*)realloc(manager->transactions, new_capacity * sizeof(MAC_TRANSACTION_T));
        if (!new_transactions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->transactions = new_transactions;
        manager->capacity = new_capacity;
    }
    manager->transactions[manager->count].type = type;
    manager->transactions[manager->count].status = status;
    manager->transactions[manager->count].timeout = timeout;
    manager->count++;
}

size_t mac_transaction_manager_count_timeouts(MAC_TRANSACTION_MANAGER_T* manager, time_t current_time) {
    size_t timeout_count = 0;
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->transactions[i].timeout <= current_time && manager->transactions[i].status != TRANSACTION_STATUS_TAG) {
            timeout_count++;
        }
    }
    return timeout_count;
}

void mac_transaction_manager_free(MAC_TRANSACTION_MANAGER_T* manager) {
    free(manager->transactions);
    manager->transactions = NULL;
    manager->capacity = 0;
    manager->count = 0;
}
