crypto_node* create_crypto_node(char *name, void (*init_func)(), void (*operation_func)(void*), void *params) {
    crypto_node *new_node = malloc(sizeof(crypto_node));
    if (new_node == NULL) {
        // Handle memory allocation error
        return NULL;
    }
    new_node->name = strdup(name);
    new_node->init_func = init_func;
    new_node->operation_func = operation_func;
    new_node->params = params;
    pthread_mutex_init(&new_node->lock, NULL);
    new_node->left = new_node->right = NULL;
    return new_node;
}

crypto_node* insert_crypto_node(crypto_node *root, char *name, void (*init_func)(), void (*operation_func)(void*), void *params) {
    if (root == NULL)
        return create_crypto_node(name, init_func, operation_func, params);

    pthread_mutex_lock(&root->lock);
    int comparison = strcmp(name, root->name);
    if (comparison < 0)
        root->left = insert_crypto_node(root->left, name, init_func, operation_func, params);
    else if (comparison > 0)
        root->right = insert_crypto_node(root->right, name, init_func, operation_func, params);

    pthread_mutex_unlock(&root->lock);
    return root;
}

