import json

class JSONSerializer:
    def __init__(self):
        self.registry = {}

    def register_type(self, type_name, deserializer):
        self.registry[type_name] = deserializer

    def deserialize(self, data):
        obj_data = json.loads(data)
        if '$type' in obj_data:
            type_name = obj_data['$type']
            deserializer = self.registry.get(type_name)
            if deserializer:
                return deserializer(obj_data)
            else:
                raise ValueError(f"Deserialization function not registered for type: {type_name}")
        return obj_data

    def serialize(self, obj):
        if isinstance(obj, dict):
            data = {'$type': 'dict', **obj}
        elif hasattr(obj, '__dict__'):
            data = {'$type': type(obj).__name__, **obj.__dict__}
        else:
            raise ValueError(f"Unsupported object type: {type(obj)}")
        return json.dumps(data)

# Example usage
serializer = JSONSerializer()
serializer.register_type('MyClass', lambda data: MyClass(**data))

my_obj = MyClass(a=1, b=2)
serialized = serializer.serialize(my_obj)
deserialized = serializer.deserialize(serialized)
