typedef struct {
    int value;
} record;

void log_memory_allocation(void *ptr, size_t size) {
    printf("Allocated memory at %p with size %zu\n", ptr, size);
}

void log_memory_deallocation(void *ptr) {
    printf("Deallocated memory at %p\n", ptr);
}

int initialize_arrays(const char *config_file, long **offsets, int **keys, record **records, int *record_count, int *max_sum) {
    json_object *parsed_json;
    json_object *json_config;
    struct json_object_iterator it, end;

    parsed_json = json_tokener_parse_file(config_file);
    if (!parsed_json) {
        fprintf(stderr, "Error parsing JSON file\n");
        return -1;
    }

    json_object_object_get_ex(parsed_json, "config", &json_config);
    json_object_object_foreach_begin(json_config, it) {
        const char *key = it.key;
        struct json_object *value;

        if (strcmp(key, "record_count") == 0) {
            json_object_object_get_ex(value, "value", &value);
            *record_count = json_object_get_int(value);
        } else if (strcmp(key, "max_sum") == 0) {
            json_object_object_get_ex(value, "value", &value);
            *max_sum = json_object_get_int(value);
        }
    }

    *offsets = (long *)malloc(*record_count * sizeof(long));
    log_memory_allocation(*offsets, *record_count * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        json_object_put(parsed_json);
        return -1;
    }

    *keys = (int *)malloc(*record_count * sizeof(int));
    log_memory_allocation(*keys, *record_count * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*offsets);
        log_memory_deallocation(*offsets);
        json_object_put(parsed_json);
        return -1;
    }

    *records = (record *)malloc(*record_count * sizeof(record));
    log_memory_allocation(*records, *record_count * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(*offsets);
        log_memory_deallocation(*offsets);
        free(*keys);
        log_memory_deallocation(*keys);
        json_object_put(parsed_json);
        return -1;
    }

    // Initialize records with random values within the specified range
    int total_sum = 0;
    for (int i = 0; i < *record_count; i++) {
        (*records)[i].value = rand() % *max_sum + 1;
        total_sum += (*records)[i].value;
    }

    if (total_sum > *max_sum) {
        fprintf(stderr, "Sum of record values exceeds max_sum\n");
        free(*offsets);
        log_memory_deallocation(*offsets);
        free(*keys);
        log_memory_deallocation(*keys);
        free(*records);
        log_memory_deallocation(*records);
        json_object_put(parsed_json);
        return -1;
    }

    json_object_put(parsed_json);
    return 0;
}

int main() {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    int record_count = 0;
    int max_sum = 0;

    if (initialize_arrays("config.json", &offsets, &keys, &records, &record_count, &max_sum) != 0) {
        return -1;
    }

    // Further processing...

    free(offsets);
    log_memory_deallocation(offsets);
    free(keys);
    log_memory_deallocation(keys);
    free(records);
    log_memory_deallocation(records);

    return 0;
}
