#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <json-c/json.h>

#define MIN_N 100
#define MAX_N 10000
#define RECORD_VALUE_THRESHOLD 1000000

typedef struct {
    int value;
    long weight;
    char status;
} record;

typedef struct {
    char username[256];
    char access_token[256];
} session;

long* offset_values;
int* keys;
record** records;
session** sessions;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populate_arrays(int N) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < N; i++) {
        offset_values[i] = rand();
        keys[i] = rand() % N;
        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = rand() % RECORD_VALUE_THRESHOLD;
        records[i]->weight = rand() % MAX_N;
        records[i]->status = 'A' + (rand() % 26);

        sessions[i] = (session*)malloc(sizeof(session));
        snprintf(sessions[i]->username, sizeof(sessions[i]->username), "user%d", i);
        snprintf(sessions[i]->access_token, sizeof(sessions[i]->access_token), "token%d", i);
    }
    pthread_mutex_unlock(&mutex);
}

void free_arrays(int N) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < N; i++) {
        free(records[i]);
        free(sessions[i]);
    }
    free(offset_values);
    free(keys);
    free(records);
    free(sessions);
    pthread_mutex_unlock(&mutex);
}

void* allocate_memory(void* arg) {
    int N = *(int*)arg;
    offset_values = (long*)malloc(N * sizeof(long));
    keys = (int*)malloc(N * sizeof(int));
    records = (record**)malloc(N * sizeof(record*));
    sessions = (session**)malloc(N * sizeof(session*));

    if (!offset_values || !keys || !records || !sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_exit(NULL);
    }

    populate_arrays(N);
    pthread_exit(NULL);
}

int main() {
    int N;
    json_object* config = json_object_from_file("config.json");
    if (!config) {
        fprintf(stderr, "Failed to parse JSON configuration file\n");
        return 1;
    }

    json_object* n_obj = json_object_object_get_ex(config, "N", &n_obj);
    if (!n_obj || !json_is_integer(n_obj)) {
        fprintf(stderr, "Invalid N value in configuration\n");
        json_object_put(config);
        return 1;
    }

    N = json_object_get_int(n_obj);
    if (N < MIN_N || N > MAX_N) {
        fprintf(stderr, "N is out of acceptable bounds\n");
        json_object_put(config);
        return 1;
    }

    pthread_t thread;
    int result = pthread_create(&thread, NULL, allocate_memory, &N);
    if (result != 0) {
        fprintf(stderr, "Failed to create thread\n");
        json_object_put(config);
        return 1;
    }

    pthread_join(thread, NULL);

    free_arrays(N);
    json_object_put(config);

    return 0;
}
