import json
import threading
import time
import random

class LTE_PHY_RX_INDICATION_PDU_T:
    def __init__(self):
        self.RX_CHANNEL_STATUS_TAG = None
        self.ANTENNA_ID = None
        self.PHY_LAYER_ERROR_REPORT_TAG = None
        self.ERROR_FLAG = None

class LogEntry:
    def __init__(self, component, message):
        self.component = component
        self.message = message

class JsonParser:
    _registry = {}

    @classmethod
    def register_factory(cls, name, factory):
        cls._registry[name] = factory

    @classmethod
    def create_instance(cls, name):
        if name in cls._registry:
            return cls._registry[name]()
        raise ValueError(f"Factory for {name} not registered")

    def __init__(self):
        self.log_entries = []
        self.lock = threading.Lock()

    def allocate_and_populate_rx_indications(self, count):
        if count > 10_000_000:
            raise ValueError("Cannot handle more than 10 million concurrent log entries")

        rx_indications = [LTE_PHY_RX_INDICATION_PDU_T() for _ in range(count)]

        for i in range(count):
            rx_indications[i].RX_CHANNEL_STATUS_TAG = self._get_random_channel_status()
            rx_indications[i].ANTENNA_ID = random.randint(1, 4)
            rx_indications[i].PHY_LAYER_ERROR_REPORT_TAG = "ERROR" if random.random() < 0.1 else "NO_ERROR"
            rx_indications[i].ERROR_FLAG = random.choice([True, False])

        return rx_indications

    def log(self, entry):
        with self.lock:
            self.log_entries.append(entry)

    @staticmethod
    def _get_random_channel_status():
        # Predefined whitelist of valid RX_CHANNEL_STATUS_TAG values
        status_whitelist = ["A", "B", "C"]
        return random.choice(status_whitelist)

# Example usage
class CustomJsonParser(JsonParser):
    pass

JsonParser.register_factory("CustomJsonParser", CustomJsonParser)
instance = JsonParser.create_instance("CustomJsonParser")
rx_indications = instance.allocate_and_populate_rx_indications(10)
for rx in rx_indications:
    print(f"RX Channel Status: {rx.RX_CHANNEL_STATUS_TAG}, Antenna ID: {rx.ANTENNA_ID}, Error Flag: {rx.ERROR_FLAG}")
