#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <locale.h>

#define MAX_SIZE 1024

typedef struct {
    char* (*append_delimiter)(char*, size_t, const char*);
} StringProcessor;

char* default_append_delimiter(char* str, size_t max_size, const char* delimiter) {
    if (str == NULL || delimiter == NULL) return NULL;

    size_t len = strlen(str);
    if (len >= max_size - 1) return NULL; // Not enough space for delimiter

    str[len++] = *delimiter;
    str[len] = '\0';
    return str;
}

char* locale_sensitive_append_delimiter(char* str, size_t max_size, const char* delimiter) {
    if (str == NULL || delimiter == NULL) return NULL;

    size_t len = strlen(str);
    if (len >= max_size - 1) return NULL; // Not enough space for delimiter

    setlocale(LC_CTYPE, "");
    str[len++] = *delimiter;
    str[len] = '\0';
    return str;
}

StringProcessor get_string_processor(int locale_sensitive) {
    StringProcessor processor;
    if (locale_sensitive) {
        processor.append_delimiter = locale_sensitive_append_delimiter;
    } else {
        processor.append_delimiter = default_append_delimiter;
    }
    return processor;
}

char* process_string(char* input, size_t max_size, int locale_sensitive, char* buffer) {
    if (input == NULL || max_size > MAX_SIZE) return NULL;

    StringProcessor processor = get_string_processor(locale_sensitive);
    if (processor.append_delimiter == NULL) return NULL;

    if (strlen(input) >= max_size - 1) return NULL; // Input string too long

    char* result = buffer != NULL ? buffer : malloc(max_size * sizeof(char));
    if (result == NULL) return NULL; // Memory allocation failed

    processor.append_delimiter(result, max_size, "/");

    if (buffer == NULL) {
        free(input); // Free original input since it's not needed anymore
    }

    return result;
}

int main() {
    setlocale(LC_ALL, "en_US.UTF-8");
    char input[] = "Hello";
    size_t max_size = 10;
    int locale_sensitive = 1;
    char buffer[12];

    char* result = process_string(input, max_size, locale_sensitive, buffer);
    if (result != NULL) {
        printf("Processed string: %s\n", result);
    } else {
        printf("Failed to process string.\n");
    }

    return 0;
}
