#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

void handle_signal(int signum) {
    // Terminate all child processes
    pid_t pid;
    while ((pid = wait(NULL)) > 0);
}

int* run_commands_in_background(const char *commands, const char **envp, FILE *log_file) {
    int *exit_statuses = NULL;
    size_t num_commands = 0;

    // Count the number of commands
    for (const char *cmd = commands; *cmd != '\0'; cmd++) {
        if (*cmd == ';') {
            num_commands++;
        }
    }
    num_commands++; // Account for the last command

    exit_statuses = malloc(num_commands * sizeof(int));
    if (!exit_statuses) {
        perror("Failed to allocate memory");
        return NULL;
    }

    pid_t pid;
    int status;
    const char *cmd_start = commands;

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    if (sigaction(SIGTERM, &sa, NULL) == -1 || sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        free(exit_statuses);
        return NULL;
    }

    for (size_t i = 0; i < num_commands; i++) {
        pid = fork();
        if (pid == -1) {
            perror("Fork failed");
            free(exit_statuses);
            return NULL;
        } else if (pid == 0) {
            // Child process
            char *cmd_end = strchr(cmd_start, ';');
            if (cmd_end) {
                *cmd_end = '\0';
            }

            // Execute the command
            execve("/bin/sh", (char *const[]){"/bin/sh", "-c", cmd_start, NULL}, envp);
            perror("Execve failed");
            exit(EXIT_FAILURE);

        } else {
            // Parent process
            if (cmd_end) {
                cmd_start = cmd_end + 1;
            }

            // Wait for the child to finish and log the status
            waitpid(pid, &status, 0);
            fprintf(log_file, "Command %zu exited with status %d\n", i, WEXITSTATUS(status));
            exit_statuses[i] = WEXITSTATUS(status);
        }
    }

    return exit_statuses;
}

int main() {
    const char *commands = "ls -l; echo Hello; false";
    const char *envp[] = {NULL};
    FILE *log_file = fopen("command_log.txt", "w");

    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    int *exit_statuses = run_commands_in_background(commands, envp, log_file);
    if (exit_statuses) {
        for (size_t i = 0; i < num_commands + 1; i++) {
            printf("Command %zu exited with status %d\n", i, exit_statuses[i]);
        }
        free(exit_statuses);
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}
