typedef struct {
    int value;
    char buffer[128];
    int *keyPtr;
} Record;

typedef struct {
    long *offsetArray;
    int *keyArray;
    Record **recordArray;
    int numCommands;
    int *commandStatuses;
    double *executionTimes;
} ResultStruct;

ResultStruct* initializeAndExecute(int numRecords, int minVal, int maxVal, const char** commands) {
    if (numRecords <= 0 || minVal >= maxVal) return NULL;

    ResultStruct *result = malloc(sizeof(ResultStruct));
    if (!result) return NULL;

    result->offsetArray = malloc(numRecords * sizeof(long));
    result->keyArray = malloc(numRecords * sizeof(int));
    result->recordArray = malloc(numRecords * sizeof(Record*));
    result->numCommands = numRecords;
    result->commandStatuses = calloc(numRecords, sizeof(int));
    result->executionTimes = malloc(numRecords * sizeof(double));

    if (!result->offsetArray || !result->keyArray || !result->recordArray || !result->commandStatuses || !result->executionTimes) {
        cleanup(result);
        return NULL;
    }

    for (int i = 0; i < numRecords; ++i) {
        result->offsetArray[i] = rand();
        result->keyArray[i] = rand() % (maxVal - minVal + 1) + minVal;

        Record *record = malloc(sizeof(Record));
        if (!record) {
            cleanup(result);
            return NULL;
        }

        record->value = rand() % (maxVal - minVal + 1) + minVal;
        snprintf(record->buffer, sizeof(record->buffer), "Buffer%d", i);
        record->keyPtr = &result->keyArray[i];
        result->recordArray[i] = record;

        pid_t pid = fork();
        if (pid == -1) {
            cleanup(result);
            return NULL;
        } else if (pid == 0) {
            execlp(commands[i], commands[i], NULL);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < numRecords; ++i) {
        pid_t pid = wait(NULL);
        clock_t start, end;
        double cpu_time_used;

        if (pid == -1) {
            result->commandStatuses[i] = -1;
            continue;
        }

        start = clock();
        // Simulate command execution time
        sleep(rand() % 2); // Random delay between 0 and 1 second
        end = clock();

        cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;

        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            result->commandStatuses[i] = 1;
            result->executionTimes[i] = cpu_time_used;
        } else {
            result->commandStatuses[i] = 0;
        }
    }

    return result;

void cleanup(ResultStruct *result) {
    if (result) {
        for (int i = 0; i < result->numCommands; ++i) {
            free(result->recordArray[i]);
        }
        free(result->offsetArray);
        free(result->keyArray);
        free(result->recordArray);
        free(result->commandStatuses);
        free(result->executionTimes);
    }
}
