#define MAX_SIZE_THRESHOLD 1024 * 1024 // 1MB

typedef struct {
    int value;
} record;

record* create_records(int* offsets, int* keys, int size) {
    if (size > MAX_SIZE_THRESHOLD / sizeof(record)) {
        printf("Error: Requested size exceeds maximum threshold.\n");
        return NULL;
    }

    record* records = malloc(size * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for records.\n");
        return NULL;
    }

    offsets = (int*)malloc(size * sizeof(int));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets.\n");
        free(records);
        return NULL;
    }

    keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys.\n");
        free(offsets);
        free(records);
        return NULL;
    }

    srand(time(0));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % (size * sizeof(record));
        keys[i] = rand();
        records[i].value = rand() % 100; // Random value between 0 and 99
    }

    return records;
}

void resize_records(record** records, int* size) {
    int new_size = *size + 10; // Increase by 10 for simplicity
    if (new_size > MAX_SIZE_THRESHOLD / sizeof(record)) {
        printf("Error: Requested size exceeds maximum threshold.\n");
        return;
    }

    record* new_records = realloc(*records, new_size * sizeof(record));
    if (!new_records) {
        printf("Error: Failed to reallocate memory for records.\n");
        return;
    }

    *records = new_records;
    *size = new_size;

    srand(time(0));
    int last_index = *size - 1;
    for (int i = *size - 1; i > *size - 11; i--) {
        (*records)[i].value = rand() % 100; // Random value between 0 and 99
    }
}

int main() {
    int size = 5;
    record* records = create_records(NULL, NULL, size);
    if (!records) {
        return 1;
    }

    printf("Initial records:\n");
    for (int i = 0; i < size; i++) {
        printf("Record %d: Value = %d\n", i, records[i].value);
    }

    resize_records(&records, &size);

    printf("Resized records:\n");
    for (int i = 0; i < size; i++) {
        printf("Record %d: Value = %d\n", i, records[i].value);
    }

    free(records);
    return 0;
}
