#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 100
#define MAX_DATA_POINTS 200
#define MAX_STRING_LENGTH 100
#define MAX_MEMORY_SIZE (1024 * 1024) // 1 MB

typedef struct {
    int value;
} record;

typedef struct {
    double number;
    char* str;
    int flag;
} data_point;

typedef struct {
    record* records;
    data_point* data_points;
    size_t records_size;
    size_t data_points_size;
    size_t memory_usage;
    int error_flag;
} system_state;

void init_system(system_state* sys) {
    sys->records = malloc(MAX_RECORDS * sizeof(record));
    sys->data_points = malloc(MAX_DATA_POINTS * sizeof(data_point));
    sys->records_size = 0;
    sys->data_points_size = 0;
    sys->memory_usage = 0;
    sys->error_flag = 0;
}

void resize_records(system_state* sys, size_t new_size) {
    record* new_records = realloc(sys->records, new_size * sizeof(record));
    if (new_records == NULL) {
        sys->error_flag = 1;
        return;
    }
    sys->records = new_records;
    sys->records_size = new_size;
}

void resize_data_points(system_state* sys, size_t new_size) {
    data_point* new_data_points = realloc(sys->data_points, new_size * sizeof(data_point));
    if (new_data_points == NULL) {
        sys->error_flag = 1;
        return;
    }
    sys->data_points = new_data_points;
    sys->data_points_size = new_size;
}

void add_record(system_state* sys, int value) {
    if (sys->records_size >= MAX_RECORDS) {
        resize_records(sys, sys->records_size * 2);
        if (sys->error_flag) return;
    }
    sys->records[sys->records_size].value = value;
    sys->records_size++;
}

void add_data_point(system_state* sys, double number, const char* str, int flag) {
    if (sys->data_points_size >= MAX_DATA_POINTS) {
        resize_data_points(sys, sys->data_points_size * 2);
        if (sys->error_flag) return;
    }
    data_point* dp = &sys->data_points[sys->data_points_size];
    dp->number = number;
    dp->str = malloc((strlen(str) + 1) * sizeof(char));
    if (dp->str == NULL) {
        sys->error_flag = 1;
        return;
    }
    strcpy(dp->str, str);
    dp->flag = flag;
    sys->data_points_size++;
}

void free_system(system_state* sys) {
    for (size_t i = 0; i < sys->data_points_size; i++) {
        free(sys->data_points[i].str);
    }
    free(sys->records);
    free(sys->data_points);
}

int main() {
    system_state sys;
    init_system(&sys);

    srand(time(NULL));

    for (size_t i = 0; i < MAX_RECORDS; i++) {
        add_record(&sys, rand() % 100);
    }

    for (size_t i = 0; i < MAX_DATA_POINTS; i++) {
        double num = static_cast<double>(rand()) / RAND_MAX * 100.0;
        const char* str = "example";
        int flag = rand() % 2;
        add_data_point(&sys, num, str, flag);
    }

    free_system(&sys);

    return 0;
}
