Event* create_event(float value, const char* description, bool completed) {
    Event* event = (Event*)malloc(sizeof(Event));
    if (!event) return NULL;
    event->value = value;
    event->description = strdup(description);
    if (!event->description) {
        free(event);
        return NULL;
