#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct Node {
    float data;
    char flag;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t count;
} DoublyLinkedList;

Node* create_node(float data, char flag) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->flag = flag;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

DoublyLinkedList* create_doubly_linked_list(size_t count) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (list == NULL) {
        perror("Failed to allocate memory for doubly linked list");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = count;
    return list;
}

void append_node(DoublyLinkedList* list, Node* node) {
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
}

void initialize_data_structures(size_t n, size_t m, int low, int high,
                               float min_float, float max_float,
                               char* log_file_path, size_t log_max_size,
                               bool enable_logging) {
