    long* offsets = (long*)malloc(n * sizeof(long));
    if (offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    int* keys = (int*)calloc(n, sizeof(int));
    if (keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    Record* records = (Record*)malloc(m * sizeof(Record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    Record* conflicting_records = (Record*)malloc(m * sizeof(Record));
    if (conflicting_records == NULL) {
        perror("Failed to allocate memory for conflicting records");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    int* indexes = (int*)calloc(m, sizeof(int));
    if (indexes == NULL) {
        perror("Failed to allocate memory for indexes");
        free(offsets);
        free(keys);
        free(records);
        free(conflicting_records);
        exit(EXIT_FAILURE);
    }

    DoublyLinkedList* list = create_doubly_linked_list(n);

    // Initialize offsets, keys, records, conflicting_records, and list
    // ...

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(conflicting_records);
    free(indexes);
    free(list->head);
    free(list);
}

int main() {
    size_t n = 10;
    size_t m = 20;
    int low = 50;
    int high = 150;
    float min_float = 1.0f;
    float max_float = 10.0f;
