void print_usage() {
    printf("Usage: %s [options] [directory]\n", argv[0]);
    printf("Options:\n");
    printf("  -f, --filter pattern   Filter log files by filename pattern\n");
    printf("  -l, --log-level level  Set logging level (DEBUG, INFO, WARNING, ERROR, CRITICAL)\n");
    printf("  -s, --severity level Set severity level for non-critical logs\n");
    printf("  -o, --output dir     Specify output directory for results\n");
    printf("  -m, --multi-machine  Enable distributed processing\n");
    printf("  -h, --help           Show this help message and exit\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return EXIT_FAILURE;
    }

    // Parse command line options
    int opt;
    while ((opt = getopt(argc, argv, "f:l:s:o:mh")) != -1) {
        switch (opt) {
            case 'f':
                printf("Filtering by pattern: %s\n", optarg);
                break;
            case 'l':
                printf("Logging level set to: %s\n", optarg);
                break;
            case 's':
                printf("Severity level set to: %s\n", optarg);
                break;
            case 'o':
