                break;
            case 'h':
                print_usage();
                return EXIT_SUCCESS;
            default:
                fprintf(stderr, "Unknown option: %c\n", optopt);
                print_usage();
                return EXIT_FAILURE;
        }
    }

    // Process the directory
    if (optind < argc) {
        char *directory = argv[optind];
        DIR *dir;
        struct dirent *ent;

        if ((dir = opendir(directory)) != NULL) {
            while ((ent = readdir(dir)) != NULL) {
                printf("Log file: %s\n", ent->d_name);
