#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

void print_usage() {
    printf("Usage: program_name [options] input_file [output_file]\n");
    printf("Options:\n");
    printf("  --manpage\tPrint detailed usage instructions\n");
    printf("  -cs pattern\tPerform case-sensitive string matching against pattern\n");
    printf("  -o output_file\tSpecify output file for line count and matches\n");
}

int main(int argc, char *argv[]) {
    const char *input_file = NULL;
    const char *output_file = NULL;
    const char *pattern = NULL;
    int line_count = 0;
    int match_count = 0;
    FILE *in_fp = NULL;
    FILE *out_fp = NULL;

    // Parse command line arguments
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0 && i + 1 < argc) {
            pattern = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (!input_file) {
            input_file = argv[i];
        } else if (!output_file) {
            output_file = argv[i];
        }
    }

    // Open input file
    if (input_file) {
        in_fp = fopen(input_file, "r");
        if (!in_fp) {
            perror("Error opening input file");
            return 1;
        }
    } else {
        print_usage();
        return 0;
    }

    // Open output file if specified
    if (output_file) {
        out_fp = fopen(output_file, "w");
        if (!out_fp) {
            perror("Error opening output file");
            fclose(in_fp);
            return 1;
        }
    }

    // Read and process input file
    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), in_fp)) {
        ++line_count;
        if (pattern && strstr(line, pattern) != NULL) {
            ++match_count;
            if (out_fp) {
                fprintf(out_fp, "%s", line);
            } else {
                printf("%s", line);
            }
        }
    }

    // Close files
    fclose(in_fp);
    if (out_fp) {
        fclose(out_fp);
    }

    // Write line count to output file if specified
    if (output_file && out_fp) {
        fprintf(out_fp, "Total lines: %d\n", line_count);
        fprintf(out_fp, "Matched lines: %d\n", match_count);
    } else if (!output_file) {
        printf("Total lines: %d\n", line_count);
        printf("Matched lines: %d\n", match_count);
    }

    return 0;
}
