#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024

typedef struct {
    long* data;
    size_t used;
    size_t capacity;
    pthread_mutex_t lock;
} offset_record_array;

void init_offset_record_array(offset_record_array* arr) {
    arr->data = (long*)malloc(INITIAL_CAPACITY * sizeof(long));
    if (!arr->data) {
        // Handle allocation failure
        exit(EXIT_FAILURE);
    }
    arr->used = 0;
    arr->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&arr->lock, NULL);
}

void insert_offset_record(offset_record_array* arr, long value) {
    pthread_mutex_lock(&arr->lock);
    if (arr->used == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        long* new_data = (long*)realloc(arr->data, new_capacity * sizeof(long));
        if (!new_data) {
            // Handle allocation failure
            pthread_mutex_unlock(&arr->lock);
            exit(EXIT_FAILURE);
        }
        arr->data = new_data;
        arr->capacity = new_capacity;
    }
    arr->data[arr->used++] = value;
    pthread_mutex_unlock(&arr->lock);
}

// Similar implementations for key_record_array, record_array, and garbage collection
