#include <time.h>

typedef struct record {
    double value;
} record;

typedef struct node {
    char data[10];
    bool flag;
    struct node* next;
} node;

typedef struct allocator {
    size_t heap_size;
    size_t current_usage;
    void* memory_pool;
} allocator;

void initialize_allocator(allocator* alloc, size_t size) {
    alloc->heap_size = size;
    alloc->current_usage = 0;
    alloc->memory_pool = malloc(size);
}

void* allocate_memory(allocator* alloc, size_t size) {
    if (alloc->current_usage + size > alloc->heap_size) {
        return NULL; // Out of memory
    }
    void* ptr = (char*)alloc->memory_pool + alloc->current_usage;
    alloc->current_usage += size;
    return ptr;
}

void deallocate_memory(allocator* alloc, void* ptr, size_t size) {
    if ((char*)ptr - (char*)alloc->memory_pool >= alloc->current_usage || 
        (char*)ptr - (char*)alloc->memory_pool < 0) {
        return; // Invalid pointer
    }
    alloc->current_usage -= size;
}

void initialize_log(bool enable_logging, FILE* log_file) {
    if (!enable_logging) {
        fclose(log_file);
    }
}

void log_event(const char* message, FILE* log_file) {
    fprintf(log_file, "%s\n", message);
}

void rotate_logs(size_t max_size, size_t current_size, FILE** log_files, int file_count) {
    for (int i = file_count - 1; i > 0; i--) {
        if (current_size + log_files[i-1]->size() < max_size) {
            fclose(log_files[i]);
            log_files[i] = fopen("log_file", "w");
            current_size += log_files[i-1]->size();
        } else {
            break;
        }
    }
}

void* read_binary_records(size_t m, double low, double high) {
    FILE* file = fopen("records.bin", "rb");
    if (!file) return NULL;

    record* records = malloc(m * sizeof(record));
    for (size_t i = 0; i < m; i++) {
        if (fread(&records[i].value, sizeof(double), 1, file) != 1) {
            records[i].value = low + (rand() / (RAND_MAX + 1.0)) * (high - low);
        }
    }
    fclose(file);
    return records;
}

void initialize_linked_list(allocator* alloc, node** head, size_t node_count) {
    *head = NULL;
    for (size_t i = 0; i < node_count; i++) {
        node* new_node = allocate_memory(alloc, sizeof(node));
        if (!new_node) break;

        snprintf(new_node->data, 10, "Node%d", i);
        new_node->flag = rand() % 2 == 0;
        new_node->next = *head;
        *head = new_node;
    }
}

int main() {
    size_t n, m, node_count;
    double low, high;
    bool enable_logging;

    // Get user inputs
    scanf("%zu %zu %zu %lf %lf %d", &n, &m, &node_count, &low, &high, &enable_logging);

    allocator alloc;
    initialize_allocator(&alloc, 1024 * 1024); // 1MB heap

    long* offsets = (long*)allocate_memory(&alloc, n * sizeof(long));
    int* keys = (int*)allocate_memory(&alloc, n * sizeof(int));

    record* records = (record*)read_binary_records(m, low, high);
    if (!records) {
        fprintf(stderr, "Failed to read records from file\n");
        return 1;
    }

    node* head;
    initialize_linked_list(&alloc, &head, node_count);

    FILE* log_file = fopen("init_log.txt", "w");
    initialize_log(enable_logging, log_file);
    if (enable_logging) {
        for (size_t i = 0; i < n; i++) {
            fprintf(log_file, "Offset %zu: %ld\nKey %zu: %d\n", i, offsets[i], i, keys[i]);
        }
        for (node* current = head; current != NULL; current = current->next) {
            fprintf(log_file, "Node Data: %s, Flag: %s\n", current->data, current->flag ? "true" : "false");
        }
    }

    fclose(log_file);
    deallocate_memory(&alloc, offsets, n * sizeof(long));
    deallocate_memory(&alloc, keys, n * sizeof(int));
    free(records);

    while (head != NULL) {
        node* temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
