    entry** buckets;
    size_t size;
    data_node** free_nodes;
    size_t free_count;
    size_t max_heap_size;
    size_t current_usage;
} hash_table;

hash_table* create_hash_table(size_t n, size_t m, size_t k) {
    // Allocate memory for the hash table
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    if (!ht) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }

    // Initialize hash table fields
    ht->buckets = (entry**)calloc(n, sizeof(entry*));
    ht->size = n;
    ht->free_nodes = (data_node**)malloc(m * sizeof(data_node*));
    if (!ht->free_nodes) {
        perror("Failed to allocate memory for free nodes");
        free(ht);
        return NULL;
    }
    ht->free_count = m;
    ht->max_heap_size = MAX_HEAP_SIZE;
    ht->current_usage = 0;

    // Allocate memory for ids and values arrays
    long* ids = (long*)malloc(n * sizeof(long));
    double* values = (double*)malloc(n * sizeof(double));
    if (!ids || !values) {
        perror("Failed to allocate memory for ids and values");
        free(ht->free_nodes);
        free(ht);
        return NULL;
    }

    // Initialize ids and values arrays
    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        ids[i] = rand();
        values[i] = (double)rand() / RAND_MAX * 100.0;
    }

    // Allocate memory for entries array
    entry* entries = (entry*)malloc(m * sizeof(entry));
    if (!entries) {
        perror("Failed to allocate memory for entries");
        free(ids);
        free(values);
        free(ht->free_nodes);
        free(ht);
        return NULL;
    }

    // Initialize entries array with random values and keys
    for (size_t i = 0; i < m; ++i) {
        entries[i].value = (double)rand() / RAND_MAX * (high - low) + low;
        entries[i].key = (char*)malloc(k * sizeof(char));
        if (!entries[i].key) {
            perror("Failed to allocate memory for entry key");
            free(entries);
            free(ids);
            free(values);
            free(ht->free_nodes);
            free(ht);
            return NULL;
        }
        for (size_t j = 0; j < k - 1; ++j) {
            entries[i].key[j] = 'a' + rand() % ('z' - 'a' + 1);
        }
        entries[i].key[k - 1] = '\0';
        entries[i].node = NULL;
    }

    // Initialize hash table with entries
    for (size_t i = 0; i < m; ++i) {
        size_t index = ids[entries[i].value % n];
        entry* new_entry = &entries[i];
        new_entry->next = ht->buckets[index];
        ht->buckets[index] = new_entry;
    }

    // Free temporary memory
    free(ids);
    free(values);

    return ht;
}

void destroy_hash_table(hash_table* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        entry* curr = ht->buckets[i];
        while (curr != NULL) {
            entry* next = curr->next;
            free(curr->key);
            if (curr->node) {
                data_node* node = curr->node;
                curr->node = node->next;
                free(node);
            }
            free(curr);
            curr = next;
        }
    }
    free(ht->buckets);
    for (size_t i = 0; i < ht->free_count; ++i) {
        if (ht->free_nodes[i]) {
            free(ht->free_nodes[i]);
        }
    }
    free(ht->free_nodes);
    free(ht);
}

int main() {
    // Example usage
    size_t n = 10;
    size_t m = 5;
    size_t k = 8;
    hash_table* ht = create_hash_table(n, m, k);
    if (ht) {
        destroy_hash_table(ht);
    }
    return 0;
}
