#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <unistd.h>

#define MAX_DIRS 100
#define MAX_LOG_FILES 1000
#define MAX_API_RESPONSE_TIME 10000

typedef struct {
    char directory[MAX_DIRS][256];
    int dir_count;
    char log_files[MAX_LOG_FILES][256];
    int log_count;
} LogData;

typedef struct {
    double api_response_times[MAX_API_RESPONSE_TIME];
    int count;
} ApiResponseTimes;

void validate_directory(const char *path, LogData *log_data) {
    DIR *dir = opendir(path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }
    closedir(dir);
    snprintf(log_data->directory[log_data->dir_count], sizeof(log_data->directory[log_data->dir_count]), "%s", path);
    log_data->dir_count++;
}

void process_log_files(LogData *log_data, ApiResponseTimes *api_times) {
    for (int i = 0; i < log_data->dir_count; i++) {
        DIR *dir = opendir(log_data->directory[i]);
        if (dir == NULL) {
            perror("Failed to open directory");
            continue;
        }
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG && strstr(entry->d_name, ".log") != NULL) {
                snprintf(log_data->log_files[log_data->log_count], sizeof(log_data->log_files[log_data->log_count]), "%s/%s", log_data->directory[i], entry->d_name);
                log_data->log_count++;
            }
        }
        closedir(dir);
    }
}

void extract_api_response_times(LogData *log_data, ApiResponseTimes *api_times) {
    for (int i = 0; i < log_data->log_count; i++) {
        FILE *file = fopen(log_data->log_files[i], "r");
        if (file == NULL) {
            perror("Failed to open file");
            continue;
        }
        char line[256];
        while (fgets(line, sizeof(line), file)) {
            if (strstr(line, "API_RESPONSE_TIME") != NULL) {
                double response_time = atof(strtok(line, " "));
                int found = 0;
                for (int j = 0; j < api_times->count; j++) {
                    if (api_times->api_response_times[j] == response_time) {
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    api_times->api_response_times[api_times->count++] = response_time;
                }
            }
        }
        fclose(file);
    }
}

void detect_anomalies(ApiResponseTimes *api_times) {
    double sum = 0, mean = 0, variance = 0;
    for (int i = 0; i < api_times->count; i++) {
        sum += api_times->api_response_times[i];
    }
    mean = sum / api_times->count;
    for (int i = 0; i < api_times->count; i++) {
        variance += pow(api_times->api_response_times[i] - mean, 2);
    }
    double std_deviation = sqrt(variance / api_times->count);
    double upper_threshold = mean + 3 * std_deviation;
    double lower_threshold = mean - 3 * std_deviation;
    for (int i = 0; i < api_times->count; i++) {
        if (api_times->api_response_times[i] > upper_threshold || api_times->api_response_times[i] < lower_threshold) {
            printf("Anomaly detected: API response time %f\n", api_times->api_response_times[i]);
        }
    }
}

int main(int argc, char *argv[]) {
    LogData log_data;
    ApiResponseTimes api_times = {0};

    if (argc < 2) {
        fprintf(stderr, "Usage: %s directory1 [directory2 ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    for (int i = 1; i < argc; i++) {
        validate_directory(argv[i], &log_data);
    }

    process_log_files(&log_data, &api_times);
    extract_api_response_times(&log_data, &api_times);
    detect_anomalies(&api_times);

    return EXIT_SUCCESS;
}
