#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

#define MAX_HEAP_SIZE 1024 * 1024 * 1024 // 1GB

typedef struct data_node {
    struct packet_header* header;
    struct data_node* next;
} data_node;

typedef struct packet_header {
    double value;
    char* metadata;
    struct data_node* chain;
} packet_header;

typedef struct hash_table {
    int size;
    data_node** buckets;
} hash_table;

void* custom_malloc(size_t size, const char* file, int line) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed at %s:%d\n", file, line);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

hash_table* create_hash_table(int size) {
    hash_table* table = custom_malloc(sizeof(hash_table), __FILE__, __LINE__);
    table->size = size;
    table->buckets = custom_malloc(size * sizeof(data_node*), __FILE__, __LINE__);
    for (int i = 0; i < size; i++) {
        table->buckets[i] = NULL;
    }
    return table;
}

data_node* create_data_node(packet_header* header) {
    data_node* node = custom_malloc(sizeof(data_node), __FILE__, __LINE__);
    node->header = header;
    node->next = NULL;
    return node;
}

packet_header* create_packet_header(double value, char* metadata, data_node* chain) {
    packet_header* header = custom_malloc(sizeof(packet_header), __FILE__, __LINE__);
    header->value = value;
    header->metadata = strdup(metadata);
    header->chain = chain;
    return header;
}

void insert_into_hash_table(hash_table* table, uint32_t id, packet_header* header) {
    int index = id % table->size;
    data_node* node = create_data_node(header);
    node->next = table->buckets[index];
    table->buckets[index] = node;
}

int main() {
    srand(time(NULL));

    uint32_t n, m, k;
    printf("Enter n (number of entries for ids and values): ");
    scanf("%u", &n);
    printf("Enter m (number of packet headers): ");
    scanf("%u", &m);
    printf("Enter k (length of metadata string): ");
    scanf("%u", &k);

    uint32_t* ids = custom_malloc(n * sizeof(uint32_t), __FILE__, __LINE__);
    double* values = custom_malloc(n * sizeof(double), __FILE__, __LINE__);

    hash_table* table = create_hash_table(m);
    char** metadata_strings = custom_malloc(m * sizeof(char*), __FILE__, __LINE__);

    for (int i = 0; i < n; i++) {
        ids[i] = rand();
        values[i] = ((double)rand() / RAND_MAX) * (high - low) + low;
        metadata_strings[i] = custom_malloc(k * sizeof(char), __FILE__, __LINE__);
        for (int j = 0; j < k; j++) {
            metadata_strings[i][j] = 'a' + rand() % 26;
        }
        metadata_strings[i][k] = '\0';
    }

    for (int i = 0; i < m; i++) {
        packet_header* header = create_packet_header(values[rand() % n], metadata_strings[rand() % m], NULL);
        insert_into_hash_table(table, ids[rand() % n], header);
    }

    // Free allocated memory
    free(ids);
    free(values);

    for (int i = 0; i < m; i++) {
        free(metadata_strings[i]);
    }
    free(metadata_strings);

    for (int i = 0; i < table->size; i++) {
        data_node* node = table->buckets[i];
        while (node != NULL) {
            packet_header* header = node->header;
            free(header->metadata);
            free(header);
            data_node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);
    free(table);

    return 0;
}
