#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} record;

typedef struct node {
    float data;
    char flag;
    struct node* prev;
    struct node* next;
} node;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    record** conflicting_records;
    int* indexes;
    node* list_head;
    node* list_tail;
    size_t total_allocated;
    size_t current_usage;
    size_t max_heap_size;
    char enable_logging;
} memory_context;

memory_context* create_memory_context(size_t n, size_t m, size_t node_count, int low, int high, float min_float, float max_float, size_t max_heap_size, char enable_logging) {
    // Initialize the context structure
    memory_context* ctx = (memory_context*)malloc(sizeof(memory_context));
    if (!ctx) return NULL;

    ctx->offsets = (long*)malloc(n * sizeof(long));
    ctx->keys = (int*)malloc(n * sizeof(int));
    ctx->records = (record**)malloc(m * sizeof(record*));
    ctx->conflicting_records = (record**)malloc(m * sizeof(record*));
    ctx->indexes = (int*)calloc(n, sizeof(int));
    ctx->list_head = NULL;
    ctx->list_tail = NULL;
    ctx->total_allocated = 0;
    ctx->current_usage = 0;
    ctx->max_heap_size = max_heap_size;
    ctx->enable_logging = enable_logging;

    if (!ctx->offsets || !ctx->keys || !ctx->records || !ctx->conflicting_records || !ctx->indexes) {
        free(ctx);
        return NULL;
    }

    // Initialize offsets and keys
    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        ctx->offsets[i] = rand();
        ctx->keys[i] = rand() % (high - low + 1) + low;
    }

    // Initialize records with random values and handle conflicts
    for (size_t i = 0; i < m; ++i) {
        record* new_record = (record*)malloc(sizeof(record));
        if (!new_record) break;
        new_record->value = rand() % (high - low + 1) + low;
        ctx->records[i] = new_record;

        // Simple conflict resolution
        while (ctx->indexes[new_record->value % n]) {
            record* conflicting_record = ctx->conflicting_records[ctx->indexes[new_record->value % n]];
            record* temp = conflicting_record;
            ctx->conflicting_records[ctx->indexes[new_record->value % n]] = new_record;
            new_record = temp;
        }
        ctx->indexes[new_record->value % n] = i;

        if (ctx->enable_logging) {
            printf("Allocated record at: %p with value: %d\n", (void*)new_record, new_record->value);
        }
    }

    // Initialize doubly linked list
    for (size_t i = 0; i < node_count; ++i) {
        node* new_node = (node*)malloc(sizeof(node));
        if (!new_node) break;
        new_node->data = ((float)(rand() % ((int)(max_float * 100) - (int)(min_float * 100))) / 100.0f + min_float);
        new_node->flag = rand() > 0.5 * RAND_MAX;
        new_node->prev = ctx->list_tail;
        new_node->next = NULL;

        if (ctx->list_tail) {
            ctx->list_tail->next = new_node;
        }
        if (!ctx->list_head) {
            ctx->list_head = new_node;
        }
        ctx->list_tail = new_node;

        ctx->current_usage += sizeof(node);
        if (ctx->enable_logging) {
            printf("Allocated node at: %p with data: %f and flag: %d\n", (void*)new_node, new_node->data, new_node->flag);
        }

        // Check memory usage
        if (ctx->current_usage > ctx->max_heap_size) {
            fprintf(stderr, "Memory limit exceeded!\n");
            return ctx;
        }
    }

    return ctx;
}

// Additional functions for logging, freeing memory, and adjusting deferred initialization threshold would be implemented here.

int main() {
    // Example usage
    memory_context* ctx = create_memory_context(100, 200, 300, 1, 1000, 0.0f, 1.0f, 10 * 1024 * 1024, 1);
    if (!ctx) {
        fprintf(stderr, "Failed to create memory context.\n");
        return -1;
    }

    // Cleanup
    free(ctx->offsets);
    free(ctx->keys);
    for (size_t i = 0; i < 200; ++i) {
        free(ctx->records[i]);
    }
    free(ctx->conflicting_records);
    free(ctx->indexes);
    while (ctx->list_head) {
        node* temp = ctx->list_head;
        ctx->list_head = ctx->list_head->next;
        free(temp);
    }

    return 0;
}
