void init_and_manage_records(int num_records, int min_key, int max_key, int min_string_len, int max_string_len) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&lock);
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].offset = rand();
        int string_len = rand() % (max_string_len - min_string_len + 1) + min_string_len;
        records[i].str = (char*)malloc((string_len + 1) * sizeof(char));
        if (records[i].str == NULL) {
            perror("Failed to allocate memory for string");
            pthread_mutex_unlock(&lock);
            continue;
        }
        char* chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        for (int j = 0; j < string_len; j++) {
            records[i].str[j] = chars[rand() % 62];
        }
        records[i].str[string_len] = '\0';
        pthread_mutex_unlock(&lock);

        printf("Initialized record %d: key=%d, offset=%ld, str=\"%s\"\n", i, records[i].key, records[i].offset, records[i].str);
    }

    for (int i = 0; i < num_records; i++) {
        free(records[i].str);
    }
    free(records);

    pthread_mutex_destroy(&lock);
}
