int initialize_data_structures(DataStructures* ds, size_t count) {
    pthread_mutex_init(&ds->mutex, NULL);
    ds->offsets = (long*)malloc(count * sizeof(long));
    ds->keys = (int*)malloc(count * sizeof(int));
    ds->records = (Record**)malloc(count * sizeof(Record*));
    ds->count = count;
    ds->log_file = fopen("error.log", "a");

