    for (size_t i = 0; i < ds->count; ++i) {
        pthread_mutex_lock(&ds->mutex);

        // Check memory usage
        if (malloc_usable_size(ds) > MEMORY_LIMIT) {
            fprintf(ds->log_file, "Memory limit exceeded: Reducing data size\n");
            ds->count /= 2;
            i = 0; // Restart the loop from the beginning
            pthread_mutex_unlock(&ds->mutex);
            continue;
        }

        ds->offsets[i] = i * sizeof(long); // Example initialization
        ds->keys[i] = rand() % 100; // Example initialization

        ds->records[i]->value = rand() % 100; // Random value within range
        size_t data_size = rand() % 1024 + 1; // Random string length between 1 and 1024 characters
        ds->records[i]->data = (char*)malloc(data_size * sizeof(char));
        if (!ds->records[i]->data) {
            fprintf(ds->log_file, "Out of memory: Failed to allocate record data at index %zu\n", i);
            pthread_mutex_unlock(&ds->mutex);
            continue;
        }
        snprintf(ds->records[i]->data, data_size, "%d", ds->records[i]->value); // Example string initialization

        pthread_mutex_unlock(&ds->mutex);
    }

    return NULL;
}

int main() {
