    size_t count = MAX_RECORDS;

    if (initialize_data_structures(&ds, count) != 0) {
        fprintf(stderr, "Failed to initialize data structures\n");
        free_data_structures(&ds);
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, initialize_records, &ds) != 0) {
        perror("Failed to create thread");
        free_data_structures(&ds);
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    // Simulate periodic updates
