            snprintf(ds.records[i]->data, strlen(ds.records[i]->data) + 5, "_%d", ds.records[i]->value);
        }
        pthread_mutex_unlock(&ds.mutex);
    }

    free_data_structures(&ds);
    return EXIT_SUCCESS;
}
