#define MAX_DOCS 100

typedef enum { PENDING, IN_PROGRESS, COMPLETED } Status;

typedef struct {
    unsigned long id;
    time_t timestamp;
    Status status;
} Document;

void init_documents(Document **docs, int *count) {
    FILE *file = fopen("documents.txt", "r");
    if (!file) return;

    *count = 0;
    while (*count < MAX_DOCS && fscanf(file, "%lu %ld %d", &(*docs)[*count].id, &(*docs)[*count].timestamp, (int *)&(*docs)[*count].status) == 3) {
        (*count)++;
    }
    fclose(file);
}

void print_most_recent(Document *docs, int count) {
    if (count == 0) return;
    Document *most_recent = docs;
    for (int i = 1; i < count; i++) {
        if (docs[i].timestamp > most_recent->timestamp) {
            most_recent = &docs[i];
        }
    }
    printf("ID: %lu, Timestamp: %ld, Status: %d\n", most_recent->id, most_recent->timestamp, most_recent->status);
}

void update_status(Document *docs, int count, unsigned long id, Status new_status) {
    for (int i = 0; i < count; i++) {
        if (docs[i].id == id) {
            docs[i].status = new_status;
            break;
        }
    }
}

void free_documents(Document *docs, int count) {
    // No need to free anything as we did not dynamically allocate memory for the structure itself
}
