    free(device->connected_services);
    memset(device, 0, sizeof(NetworkDevice));
}

void* manage_devices(void* arg) {
    while (1) {
        sem_wait(&mutex);

        for (int i = 0; i < device_count; i++) {
            if (total_memory_usage + sizeof(DeviceConfig) > memory_limit) {
                // Handle memory limit exceeded
                break;
            }

            NetworkDevice* device = &devices[i];
            initialize_device(&device->config);
            total_memory_usage += sizeof(NetworkDevice);
        }

        sem_post(&mutex);

        sleep(10); // Periodic check for updates and validation
    }
}

