#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB

typedef struct {
    int value;
} record;

void initialize_arrays(int num_records, long **offsets, int **keys, record **records) {
    size_t total_size = (sizeof(long) + sizeof(int) + sizeof(record)) * num_records;

    if (total_size > MAX_MEMORY) {
        fprintf(stderr, "Memory allocation exceeds 1 MB limit.\n");
        exit(1);
    }

    *offsets = malloc(num_records * sizeof(long));
    *keys = malloc(num_records * sizeof(int));
    *records = malloc(num_records * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = rand() % (MAX_MEMORY / sizeof(long));
        (*keys)[i] = rand() % 1000; // Random value between 0 and 999
        (*records)[i].value = rand() % 10000; // Random value between 0 and 9999
    }
}

int main() {
    int num_records = 1000;
    long *offsets;
    int *keys;
    record *records;

    initialize_arrays(num_records, &offsets, &keys, &records);

    printf("Offset array initialized with %d elements.\n", num_records);
    printf("Key array initialized with %d elements.\n", num_records);
    printf("Record array initialized with %d elements.\n", num_records);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
