            free(tasks);
            return NULL;
        }
        snprintf(tasks[i].description, 256, "Task %d", i + 1);
        tasks[i].timestamp = time(NULL); // Current timestamp
    }

    return tasks;
}

status* create_statuses(int num_statuses) {
    status* statuses = malloc(num_statuses * sizeof(status));
    if (statuses == NULL) {
        perror("Failed to allocate memory for statuses");
        return NULL;
    }

    for (int i = 0; i < num_statuses; ++i) {
        statuses[i].flag = (rand() % 2 == 0); // Random boolean flag
        statuses[i].progress = (double)(rand() % 101) / 100.0; // Random progress between 0 and 100%
