using System.Runtime.InteropServices;
using System.Threading;

public struct Task
{
    public int PriorityLevel;
    public IntPtr Description; // char*
    public long Timestamp; // time_t
}

public struct Status
{
    public bool Flag;
    public double ProgressPercentage;
}

public class ConfigLoader
{
    private List<Task> tasks = new List<Task>();
    private List<Status> statuses = new List<Status>();
    private object lockObject = new object();

    public void LoadConfig(string xmlFilePath)
    {
        try
        {
            if (!File.Exists(xmlFilePath))
            {
                throw new FileNotFoundException("XML file not found.");
            }

            // Parse the XML file and populate tasks and statuses
            // ...

            // Allocate memory for tasks
            lock (lockObject)
            {
                IntPtr taskArray = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(Task)) * tasks.Count);
                try
                {
                    for (int i = 0; i < tasks.Count; i++)
                    {
                        Marshal.StructureToPtr(tasks[i], new IntPtr((long)taskArray + (i * Marshal.SizeOf(typeof(Task)))), true);
                    }

                    // Use the allocated memory for tasks
                    // ...

                    Marshal.FreeHGlobal(taskArray);
                }
                catch (OutOfMemoryException)
                {
                    Marshal.FreeHGlobal(taskArray);
                    throw;
                }
            }

            // Allocate memory for statuses
            lock (lockObject)
            {
                IntPtr statusArray = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(Status)) * statuses.Count);
                try
                {
                    for (int i = 0; i < statuses.Count; i++)
                    {
                        Marshal.StructureToPtr(statuses[i], new IntPtr((long)statusArray + (i * Marshal.SizeOf(typeof(Status)))), true);
                    }

                    // Use the allocated memory for statuses
                    // ...

                    Marshal.FreeHGlobal(statusArray);
                }
                catch (OutOfMemoryException)
                {
                    Marshal.FreeHGlobal(statusArray);
                    throw;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error loading configuration: " + ex.Message);
        }
    }
}

public class Program
{
    public static void Main()
    {
        ConfigLoader configLoader = new ConfigLoader();
        string xmlFilePath = "path_to_your_xml_file.xml";
        configLoader.LoadConfig(xmlFilePath);

        // Use the loaded tasks and statuses
        // ...
    }
}
