['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* value;
} item;

typedef struct {
    int front, rear;
    int max_size;
    int* array;
} queue;

typedef struct {
    pthread_mutex_t lock;
    int last_used_status;
} status_tracker;

queue** create_queues(int m, int max_size) {
    queue** queues = (queue**)malloc(m * sizeof(queue*));
    if (!queues) return NULL;

    for (int i = 0; i < m; i++) {
        queues[i] = (queue*)malloc(sizeof(queue));
        if (!queues[i]) {
            for (int j = 0; j < i; j++) free(queues[j]);
            free(queues);
            return NULL;
        }
        queues[i]->front = queues[i]->rear = -1;
        queues[i]->max_size = max_size;
        queues[i]->array = (int*)malloc(max_size * sizeof(int));
        if (!queues[i]->array) {
            for (int j = 0; j <= i; j++) {
                free(queues[j]->array);
                free(queues[j]);
            }
            free(queues);
            return NULL;
        }
    }

    return queues;
}

item** create_items(int n, char* item_values[]) {
    item** items = (item**)malloc(n * sizeof(item*));
    if (!items) return NULL;

    for (int i = 0; i < n; i++) {
        items[i] = (item*)malloc(sizeof(item));
        if (!items[i]) {
            for (int j = 0; j < i; j++) free(items[j]);
            free(items);
            return NULL;
        }
        items[i]->value = strdup(item_values[i]);
        if (!items[i]->value) {
            for (int j = 0; j <= i; j++) {
                free(items[j]->value);
                free(items[j]);
            }
            free(items);
            return NULL;
        }
    }

    return items;
}

queue** create_conflict_queues(int n, int max_size) {
    queue** conflict_queues = (queue**)malloc(n * sizeof(queue*));
    if (!conflict_queues) return NULL;

    for (int i = 0; i < n; i++) {
        conflict_queues[i] = (queue*)malloc(sizeof(queue));
        if (!conflict_queues[i]) {
            for (int j = 0; j < i; j++) free(conflict_queues[j]);
            free(conflict_queues);
            return NULL;
        }
        conflict_queues[i]->front = conflict_queues[i]->rear = -1;
        conflict_queues[i]->max_size = max_size;
        conflict_queues[i]->array = (int*)malloc(max_size * sizeof(int));
        if (!conflict_queues[i]->array) {
            for (int j = 0; j <= i; j++) {
                free(conflict_queues[j]->array);
                free(conflict_queues[j]);
            }
            free(conflict_queues);
            return NULL;
        }
    }

    return conflict_queues;
}

status_tracker* create_status_trackers(int m) {
    status_tracker* statuses = (status_tracker*)malloc(m * sizeof(status_tracker));
    if (!statuses) return NULL;

    for (int i = 0; i < m; i++) {
        pthread_mutex_init(&statuses[i].lock, NULL);
        statuses[i].last_used_status = -1;
    }

    return statuses;
}

void free_queues(queue** queues, int m) {
    for (int i = 0; i < m; i++) {
        free(queues[i]->array);
        free(queues[i]);
    }
    free(queues);
}

void free_items(item** items, int n) {
    for (int i = 0; i < n; i++) {
        free(items[i]->value);
        free(items[i]);
    }
    free(items);
}

void free_conflict_queues(queue** conflict_queues, int n) {
    for (int i = 0; i < n; i++) {
        free(conflict_queues[i]->array);
        free(conflict_queues[i]);
    }
    free(conflict_queues);
}

void free_status_trackers(status_tracker* statuses, int m) {
    for (int i = 0; i < m; i++) {
        pthread_mutex_destroy(&statuses[i].lock);
    }
    free(statuses);
}
