typedef struct {
    int key;
    long offset;
    char *string;
} data;

typedef struct {
    pthread_mutex_t lock;
    data **data_array;
    int num_data;
    int max_num_conflicts;
    data **conflict_array;
    int *status;
    int next_unused_status;
} manager;

manager* create_manager(int min_key, int max_key, int min_string_len, int max_string_len) {
    manager *m = (manager*)malloc(sizeof(manager));
    m->data_array = (data**)malloc(num_data * sizeof(data*));
    m->conflict_array = (data**)malloc(max_num_conflicts * sizeof(data*));
    m->status = (int*)malloc(num_data * sizeof(int));
    pthread_mutex_init(&m->lock, NULL);
    // Initialize other members
    return m;
}

void destroy_manager(manager *m) {
    for (int i = 0; i < m->num_data; i++) {
        free(m->data_array[i]->string);
        free(m->data_array[i]);
    }
    for (int i = 0; i < m->max_num_conflicts; i++) {
        if (m->conflict_array[i]) {
            free(m->conflict_array[i]->string);
            free(m->conflict_array[i]);
        }
    }
    pthread_mutex_destroy(&m->lock);
    free(m->data_array);
    free(m->conflict_array);
    free(m->status);
    free(m);
}

void init_and_manage_data_structures(int num_data, int min_key, int max_key, int min_string_len, int max_string_len) {
    manager *m = create_manager(min_key, max_key, min_string_len, max_string_len);

    for (int i = 0; i < num_data; i++) {
        pthread_mutex_lock(&m->lock);
        m->data_array[i] = (data*)malloc(sizeof(data));
        m->data_array[i]->key = rand() % (max_key - min_key + 1) + min_key;
        m->data_array[i]->offset = random();

        int string_len = rand() % (max_string_len - min_string_len + 1) + min_string_len;
        m->data_array[i]->string = (char*)malloc((string_len + 1) * sizeof(char));
        // Initialize string
        pthread_mutex_unlock(&m->lock);
    }

    destroy_manager(m);
}
