typedef struct {
    int value;
} Record;

Record** initializeDataStructures(int n, int m, int low, int high, int* indexes, pthread_mutex_t* locks) {
    if (n <= 0 || m <= 0) {
        fprintf(stderr, "Invalid input sizes. Both n and m must be positive integers.\n");
        return NULL;
    }

    Record** records = (Record**)malloc(n * sizeof(Record*));
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));
    Record** conflictingRecords = (Record**)malloc(m * sizeof(Record*));

    if (!records || !offsets || !keys || !conflictingRecords) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(records);
        free(offsets);
        free(keys);
        free(conflictingRecords);
        return NULL;
    }

    pthread_mutex_t* localLocks = (pthread_mutex_t*)malloc(n * sizeof(pthread_mutex_t));
    if (!localLocks) {
        fprintf(stderr, "Memory allocation failed for locks.\n");
        free(records);
        free(offsets);
        free(keys);
        free(conflictingRecords);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            for (int j = 0; j < i; ++j)
                free(records[j]);
            free(records);
            free(offsets);
            free(keys);
            free(conflictingRecords);
            free(localLocks);
            return NULL;
        }
        records[i]->value = low + rand() % (high - low + 1);
        offsets[i] = i * 10; // Example offset calculation
        keys[i] = i;
        indexes[i] = i;
        pthread_mutex_init(&localLocks[i], NULL);
    }

    for (int i = 0; i < m; ++i) {
        conflictingRecords[i] = (Record*)malloc(sizeof(Record));
        if (!conflictingRecords[i]) {
            fprintf(stderr, "Memory allocation failed for conflicting record %d.\n", i);
            for (int j = 0; j <= i; ++j)
                free(conflictingRecords[j]);
            for (int j = 0; j < n; ++j) {
                free(records[j]);
                pthread_mutex_destroy(&localLocks[j]);
            }
            free(records);
            free(offsets);
            free(keys);
            free(localLocks);
            return NULL;
        }
    }

    *locks = localLocks;

    return records;
}

void cleanUp(Record** records, int n, Record** conflictingRecords, int m, pthread_mutex_t* locks) {
    for (int i = 0; i < n; ++i) {
        free(records[i]);
        pthread_mutex_destroy(&locks[i]);
    }
    for (int i = 0; i < m; ++i)
        free(conflictingRecords[i]);
    free(records);
    free(conflictingRecords);
    free(locks);
}

int main() {
    int n, m, low, high;
    printf("Enter the number of records and offsets (n): ");
    scanf("%d", &n);
    printf("Enter the number of conflicting records (m): ");
    scanf("%d", &m);
    printf("Enter the range for random record values (low to high): ");
    scanf("%d %d", &low, &high);

    int* indexes = (int*)malloc(n * sizeof(int));
    pthread_mutex_t locks;

    Record** records = initializeDataStructures(n, m, low, high, indexes, &locks);
    if (!records) {
        printf("Failed to initialize data structures.\n");
        return 1;
    }

    // Use the initialized arrays here

    cleanUp(records, n, NULL, 0, &locks); // Clean up the records array
    free(indexes);

    return 0;
}
