#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record** createDataStructures(int n, int m, int low, int high, long** offsets, int* keys, long** secondaryRecords, long** indexes) {
    if (n <= 0 || m <= 0) {
        return NULL; // Invalid input
    }

    // Allocate memory for offsets and keys
    *offsets = malloc(n * sizeof(long));
    *keys = malloc(n * sizeof(int));
    if (*offsets == NULL || *keys == NULL) {
        free(*offsets);
        free(*keys);
        return NULL; // Memory allocation failed
    }

    // Allocate memory for records and secondaryRecords
    record** records = malloc(m * sizeof(record*));
    *secondaryRecords = malloc(m * sizeof(long));
    *indexes = malloc(m * sizeof(long));
    if (records == NULL || *secondaryRecords == NULL || *indexes == NULL) {
        free(*offsets);
        free(*keys);
        free(records);
        free(*secondaryRecords);
        return NULL; // Memory allocation failed
    }

    // Initialize records and keys with random values and indices
    srand(time(NULL));
    for (int i = 0; i < m; i++) {
        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(records);
            free(*secondaryRecords);
            return NULL; // Memory allocation failed
        }
        records[i]->value = rand() % (high - low + 1) + low;
        (*indexes)[i] = i;
    }

    // Initialize offsets with default values
    for (int i = 0; i < n; i++) {
        (*offsets)[i] = i * m / n;
    }

    return records;
}
