#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <stdbool.h>

#define MAX_HEAP_SIZE 1024 * 1024 * 1024 // 1 GB

typedef struct packet_header {
    double value;
    char* metadata;
    struct packet_header* next;
} packet_header;

typedef struct {
    uint32_t id;
    packet_header* header;
} hash_table_entry;

typedef struct {
    hash_table_entry** buckets;
    size_t bucket_count;
    size_t size;
} hash_table;

hash_table* create_hash_table(size_t bucket_count) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    table->buckets = (hash_table_entry**)calloc(bucket_count, sizeof(hash_table_entry*));
    table->bucket_count = bucket_count;
    table->size = 0;
    return table;
}

void destroy_hash_table(hash_table* table) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        hash_table_entry* entry = table->buckets[i];
        while (entry != NULL) {
            hash_table_entry* next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    free(table);
}

void insert_into_hash_table(hash_table* table, uint32_t id, packet_header* header) {
    size_t index = id % table->bucket_count;
    hash_table_entry* entry = (hash_table_entry*)malloc(sizeof(hash_table_entry));
    entry->id = id;
    entry->header = header;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    ++table->size;
}

packet_header* create_packet_header(double value, const char* metadata) {
    packet_header* header = (packet_header*)malloc(sizeof(packet_header));
    header->value = value;
    header->metadata = strdup(metadata);
    header->next = NULL;
    return header;
}

void free_packet_header(packet_header* header) {
    free(header->metadata);
    free(header);
}

int main() {
    srand(time(NULL));

    size_t n, m, k;
    printf("Enter number of ids: ");
    scanf("%zu", &n);
    printf("Enter number of packet headers: ");
    scanf("%zu", &m);
    printf("Enter length of metadata string: ");
    scanf("%zu", &k);

    hash_table* table = create_hash_table(n);

    for (size_t i = 0; i < m; ++i) {
        double value = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
        char metadata[k + 1];
        for (size_t j = 0; j < k; ++j) {
            metadata[j] = 'a' + rand() % ('z' - 'a' + 1);
        }
        metadata[k] = '\0';
        packet_header* header = create_packet_header(value, metadata);
        insert_into_hash_table(table, i, header);
    }

    destroy_hash_table(table);

    return 0;
}
