#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_DIR_PATH 256
#define MAX_LOG_FILE_PATH 512
#define LOG_FILE_BUFFER_SIZE 4096

typedef struct {
    char directory[MAX_DIR_PATH];
    int log_level;
    FILE *log_file;
} Config;

void validate_directory(const char *dir_path) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        fprintf(stderr, "Error: Directory %s does not exist or is inaccessible.\n", dir_path);
        exit(EXIT_FAILURE);
    }
    closedir(dir);
}

void read_log_files(const Config *config) {
    DIR *dir;
    struct dirent *entry;
    char file_path[MAX_LOG_FILE_PATH];

    if ((dir = opendir(config->directory)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            snprintf(file_path, sizeof(file_path), "%s/%s", config->directory, entry->d_name);
            if (strstr(entry->d_name, ".log") != NULL) {
                // Process log file
                printf("Processing log file: %s\n", file_path);
            }
        }
        closedir(dir);
    } else {
        fprintf(stderr, "Error: Unable to open directory %s.\n", config->directory);
    }
}

void *process_log_files(void *arg) {
    Config *config = (Config *)arg;
    read_log_files(config);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    Config config = {.directory = argv[1], .log_level = INFO};
    validate_directory(config.directory);

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_log_files, &config) != 0) {
        fprintf(stderr, "Error: Failed to create thread.\n");
        exit(EXIT_FAILURE);
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Error: Failed to join thread.\n");
        exit(EXIT_FAILURE);
    }

    printf("Log processing completed.\n");

    return 0;
}
```

This code provides a basic structure for a C program that processes log files across multiple directories. It includes directory validation and basic log file reading functionality. Additional features such as anomaly detection, configuration flexibility, performance optimization, scalability, user interface, and output management would require extensive additions to this foundation.']

