#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct data_node {
    int id;
    double value;
    char metadata[128];
    struct data_node *next;
} data_node;

typedef struct entry {
    double value;
    char key[16];
    data_node *node;
    struct entry *next;
} entry;

typedef struct hash_table {
    size_t size;
    entry **buckets;
} hash_table;

hash_table* create_hash_table(size_t size) {
    hash_table *ht = malloc(sizeof(hash_table));
    ht->size = size;
    ht->buckets = calloc(size, sizeof(entry *));
    return ht;
}

entry* create_entry(double value, char *key, data_node *node) {
    entry *e = malloc(sizeof(entry));
    e->value = value;
    snprintf(e->key, sizeof(e->key), "%s", key);
    e->node = node;
    e->next = NULL;
    return e;
}

void insert_entry(hash_table *ht, double value, char *key, data_node *node) {
    size_t index = hash(key, ht->size);
    entry *e = create_entry(value, key, node);
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = e;
    } else {
        entry *temp = ht->buckets[index];
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = e;
    }
}

data_node* create_data_node(int id, double value, char *metadata) {
    data_node *node = malloc(sizeof(data_node));
    node->id = id;
    node->value = value;
    snprintf(node->metadata, sizeof(node->metadata), "%s", metadata);
    node->next = NULL;
    return node;
}

void initialize_system(size_t n, size_t m, size_t k, double low, double high, bool enable_logging) {
    long *ids = malloc(n * sizeof(long));
    double *values = malloc(n * sizeof(double));

    hash_table *ht = create_hash_table(m);

    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        ids[i] = rand() % m;
        values[i] = low + (double)rand() / RAND_MAX * (high - low);
    }

    for (size_t i = 0; i < m; ++i) {
        char key[16];
        snprintf(key, sizeof(key), "%04x", rand());
        data_node *node = create_data_node(ids[i], values[i % n], "metadata");
        insert_entry(ht, values[i % n], key, node);
    }

    if (enable_logging) {
        log_initialization(ids, values, m, key, node);
    }

    // Free allocated memory
    free(ids);
    free(values);
    destroy_hash_table(ht);
}

void log_initialization(long *ids, double *values, size_t count, char *key, data_node *node) {
    for (size_t i = 0; i < count; ++i) {
        printf("ID: %ld, Value: %f\n", ids[i], values[i]);
    }
    // Additional logging logic for key and node
}

void destroy_hash_table(hash_table *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        entry *temp = ht->buckets[i];
        while (temp != NULL) {
            entry *next = temp->next;
            free(temp);
            temp = next;
        }
    }
    free(ht->buckets);
    free(ht);
}
