#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/types.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_DIRS 100
#define MAX_LOG_FILES 500
#define MAX_LINE_LENGTH 2048

typedef struct {
    char path[MAX_LINE_LENGTH];
    int log_files_count;
} Directory;

typedef struct {
    char filename[MAX_LINE_LENGTH];
    char timestamp[MAX_LINE_LENGTH];
    double response_time;
} LogEntry;

void process_directory(Directory *dir) {
    DIR *dp;
    struct dirent *entry;

    dp = opendir(dir->path);
    if (dp == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dp)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".log")) {
            char full_path[MAX_LINE_LENGTH];
            snprintf(full_path, MAX_LINE_LENGTH, "%s/%s", dir->path, entry->d_name);
            process_log_file(full_path);
        }
    }

    closedir(dp);
}

void process_log_file(const char *file_path) {
    FILE *fp;
    LogEntry log_entry;

    fp = fopen(file_path, "r");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    while (fgets(log_entry.filename, MAX_LINE_LENGTH, fp) != NULL) {
        // Parse log entry
        sscanf(log_entry.filename, "%[^,],%[^,],%lf", log_entry.timestamp, log_entry.filename, &log_entry.response_time);
        store_log_entry(&log_entry);
    }

    fclose(fp);
}

void store_log_entry(LogEntry *entry) {
    // Store or analyze the log entry
}

int main() {
    Directory dirs[MAX_DIRS];
    int dir_count = 0;

    // Initialize directories
    dirs[dir_count].path = "/var/log/dir1";
    dirs[dir_count].log_files_count = 5;
    dir_count++;

    dirs[dir_count].path = "/var/log/dir2/*";
    dirs[dir_count].log_files_count = 3;
    dir_count++;

    for (int i = 0; i < dir_count; i++) {
        process_directory(&dirs[i]);
    }

    return 0;
}
