    float float_value;
    char flag;
    struct node *prev, *next;
} Node;

typedef struct log_entry {
    void* address;
    size_t size;
    char type[10];
    struct log_entry *next;
} LogEntry;

LogEntry* log_head = NULL;
size_t current_memory_usage = 0;
size_t max_heap_size = 1024 * 1024; // 1 MB
bool enable_logging = true;
size_t log_max_size = 1024;
FILE* log_file = fopen("log.txt", "w");

void* custom_malloc(size_t size, char* type) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    current_memory_usage += size;
    if (enable_logging) {
        LogEntry* new_entry = malloc(sizeof(LogEntry));
        new_entry->address = ptr;
        new_entry->size = size;
        strcpy(new_entry->type, type);
        new_entry->next = log_head;
        log_head = new_entry;
        fprintf(log_file, "Allocated %zu bytes at %p for %s\n", size, ptr, type);
    }
    return ptr;
}

void custom_free(void* ptr, char* type) {
    free(ptr);
    current_memory_usage -= size;
    if (enable_logging) {
        LogEntry* entry = log_head;
        while (entry != NULL) {
            if (entry->address == ptr && strcmp(entry->type, type) == 0) {
                LogEntry* temp = entry;
                log_head = entry->next;
                free(temp);
                fprintf(log_file, "Freed %zu bytes at %p for %s\n", size, ptr, type);
                break;
            }
            entry = entry->next;
        }
    }
}

