    Node* current = head;
    for (int i = 1; i < node_count; i++) {
        Node* new_node = custom_malloc(sizeof(Node), "node");
        new_node->float_value = min_float + ((double)rand() / RAND_MAX) * (max_float - min_float);
        new_node->flag = (rand() % 2 == 0) ? 'T' : 'F';
        current->next = new_node;
        new_node->prev = current;
        current = new_node;
    }
    current->next = NULL;
    return head;
}

void initialize_records(int m, int low, int high, Record* records) {
