#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/stat.h>
#include <openssl/sha.h>

#define MAX_THREADS 10
#define CHUNK_SIZE 4096

typedef struct {
    FILE *file;
    pthread_mutex_t lock;
    int unique_word_count;
    char **unique_words;
} ThreadData;

void *process_file(void *arg) {
    ThreadData *td = (ThreadData *)arg;
    char buffer[CHUNK_SIZE];
    size_t bytes_read;
    SHA256_CTX sha256_ctx;
    unsigned char digest[SHA256_DIGEST_LENGTH];

    pthread_mutex_lock(&td->lock);
    td->unique_word_count = 0;
    td->unique_words = NULL;
    pthread_mutex_unlock(&td->lock);

    while ((bytes_read = fread(buffer, 1, CHUNK_SIZE, td->file)) > 0) {
        SHA256_Init(&sha256_ctx);
        SHA256_Update(&sha256_ctx, buffer, bytes_read);
        SHA256_Final(digest, &sha256_ctx);

        // Process each chunk here
    }

    fclose(td->file);
    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    int opt;
    FILE *input_file = NULL;
    ThreadData td;
    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    while ((opt = getopt(argc, argv, ":mcs:o:")) != -1) {
        switch (opt) {
            case 'm':
                printf("Manpage:\n");
                // Print manpage
                break;
            case 'c':
                printf("Counting characters...\n");
                break;
            case 's':
                printf("Output file specified.\n");
                break;
            case 'o':
                printf("Output file: %s\n", optarg);
                break;
            case '?':
                fprintf(stderr, "Unknown option: -%c\n", optopt);
                return 1;
            default:
                abort();
        }
    }

    if (optind < argc) {
        input_file = fopen(argv[optind], "r");
        if (input_file == NULL) {
            perror("Error opening file");
            return 1;
        }
    } else {
        input_file = stdin;
    }

    pthread_mutex_init(&td.lock, NULL);
    td.file = input_file;

    while ((thread_count < MAX_THREADS) && (fgetc(td.file) != EOF)) {
        if (pthread_create(&threads[thread_count], NULL, process_file, &td) != 0) {
            perror("Error creating thread");
            break;
        }
        pthread_mutex_lock(&td.lock);
        td.unique_word_count++;
        pthread_mutex_unlock(&td.lock);
    }

    for (int i = 0; i < thread_count; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Error joining thread");
        }
    }

    printf("Total unique words: %d\n", td.unique_word_count);

    pthread_mutex_destroy(&td.lock);
    fclose(td.file);

    return 0;
}
