    if (argc < 2) {
        fprintf(stderr, "Usage: %s directory [priority]\n", argv[0]);
        return 1;
    }

    const char *dir_path = argv[1];
    int priority = argc > 2 ? atoi(argv[2]) : 0;

    add_directory(dir_path, priority);

    list_directories();

    return 0;
}
