void log_message(const char* message, const void* address, int value) {
    static FILE* log_file = fopen("log.txt", "a");
    if (enable_logging && log_file != NULL) {
        fprintf(log_file, "%s: Address=%p, Value=%d\n", message, address, value);
    }
}

void* custom_malloc(size_t size, const char* file, int line) {
    static void* heap_start = NULL;
    static size_t heap_size = 0;
    static size_t heap_used = 0;

    if (heap_start == NULL) {
        heap_start = malloc(1);
        heap_size = 1;
        heap_used = 0;
    }

    if (heap_used + size > heap_size) {
        fprintf(stderr, "Error: Memory allocation failed. Max heap size reached.\n");
        exit(EXIT_FAILURE);
    }

    void* address = (char*)heap_start + heap_used;
    heap_used += size;

    log_message("Allocated", address, 0);

    return address;
}

void custom_free(void* ptr) {
    // No-op implementation for simplicity
}

Node* create_linked_list(size_t node_count, float min_float, float max_float, int enable_logging) {
    Node* head = NULL;
    Node* tail = NULL;

    for (size_t i = 0; i < node_count; ++i) {
        Node* new_node = (Node*)custom_malloc(sizeof(Node), __FILE__, __LINE__);
        new_node->data = ((max_float - min_float) * rand() / RAND_MAX) + min_float;
        new_node->flag = (rand() % 100 < 50) ? 'A' : 'B';
        new_node->prev = tail;
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
        } else {
            tail->next = new_node;
        }
        tail = new_node;

        log_message("Node created", new_node, (int)new_node->data);
    }

    return head;
}

// Main function to demonstrate the usage
int main() {
    srand(time(NULL));

    size_t n = 10;
    size_t m = 20;
    size_t node_count = 5;

    int* offsets = (int*)custom_malloc(n * sizeof(int), __FILE__, __LINE__);
    int* keys = (int*)custom_malloc(n * sizeof(int), __FILE__, __LINE__);

    Record* records = (Record*)custom_malloc(m * sizeof(Record), __FILE__, __LINE__);
    Node* linked_list = create_linked_list(node_count, 0.0f, 1.0f, 1);

    // Initialize structures...

    custom_free(offsets);
    custom_free(keys);
    custom_free(records);
    while (linked_list != NULL) {
        Node* temp = linked_list;
        linked_list = linked_list->next;
        custom_free(temp);
    }

    return 0;
}
