void process_log_files(const char* pattern) {
    DIR* dir;
    struct dirent* ent;
    if ((dir = opendir(pattern)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            // Check for symlinks and validate existence
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", pattern, ent->d_name);
            struct stat st;
            if (lstat(path, &st) == 0 && S_ISLNK(st.st_mode)) {
                printf("Symlink detected: %s\n", path);
                // Follow symlink and process remote log files
            } else if (S_ISREG(st.st_mode)) {
                printf("Log file found: %s\n", path);
                // Process log file here
            }
        }
        closedir(dir);
    } else {
        perror("Error opening directory");
    }
}

void* allocate_memory(size_t size, const char* type) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory for %s\n", type);
        return NULL;
    }
    memset(ptr, 0, size);
    return ptr;
}

data_point* initialize_arrays(size_t* max_size) {
    data_point* doubles = (data_point*)allocate_memory(*max_size * sizeof(data_point), "doubles");
    char** strings = (char**)allocate_memory(*max_size * sizeof(char*), "strings");
    for (size_t i = 0; i < *max_size; ++i) {
        strings[i] = allocate_memory(256, "string");
    }
    data_point** points = (data_point**)allocate_memory(*max_size * sizeof(data_point*), "points");
    for (size_t i = 0; i < *max_size; ++i) {
        points[i] = &doubles[i];
    }
    return points;
}

void reallocate_memory(void** ptr, size_t old_size, size_t new_size, const char* type) {
    void* new_ptr = realloc(*ptr, new_size);
    if (new_ptr == NULL) {
        fprintf(stderr, "Failed to reallocate memory for %s\n", type);
        return;
    }
    *ptr = new_ptr;
}

void free_memory(data_point** points, char** strings, size_t max_size) {
    for (size_t i = 0; i < max_size; ++i) {
        free(strings[i]);
    }
    free(points);
    free(*points);
}

// Example usage
int main() {
    const char* pattern = "/path/to/logs/*";
    process_log_files(pattern);

    size_t max_size = 1024;
    data_point** points = initialize_arrays(&max_size);
    // Use points for processing
    free_memory(points, NULL, max_size); // Free strings separately if needed

    return 0;
}
