#include <json-c/json.h>

typedef struct {
    char id[256];
    json_object *metadata;
} ResourceItem;

typedef struct {
    int itemCount;
    ResourceItem **items;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filePath, size_t maxHeapSize) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filePath);
        return NULL;
    }

    char buffer[1024];
    size_t bytesRead = fread(buffer, 1, sizeof(buffer), file);
    fclose(file);

    json_error_t error;
    json_object *root = json_tokener_parse_ex(json_tokener_new(), buffer, bytesRead, &error);
    if (!root) {
        fprintf(stderr, "JSON parse error: %s at line %d, col %d\n", error.msg, error.line, error.col);
        return NULL;
    }

    if (json_object_type(root) != json_type_array) {
        fprintf(stderr, "Invalid JSON format - expected an array\n");
        json_object_put(root);
        return NULL;
    }

    size_t itemCount = json_object_array_length(root);
    ResourceBundle *bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    bundle->itemCount = itemCount;
    bundle->items = (ResourceItem**)calloc(itemCount, sizeof(ResourceItem*));

    for (size_t i = 0; i < itemCount; ++i) {
        json_object *itemObj = json_object_array_get_idx(root, i);
        if (!json_object_is_type(itemObj, json_type_object)) {
            fprintf(stderr, "Invalid JSON format - expected an object at index %zu\n", i);
            for (size_t j = 0; j < i; ++j) {
                free(bundle->items[j]);
            }
            free(bundle->items);
            free(bundle);
            json_object_put(root);
            return NULL;
        }

        ResourceItem *item = (ResourceItem*)malloc(sizeof(ResourceItem));
        memset(item, 0, sizeof(ResourceItem));

        item->id[0] = '\0';
        if (json_object_object_get_ex(itemObj, "id", &jsonId)) {
            const char *idStr = json_object_get_string(jsonId);
            strncpy(item->id, idStr, sizeof(item->id) - 1);
        } else {
            fprintf(stderr, "Invalid JSON format - missing 'id' field\n");
            free(item);
            for (size_t j = 0; j < i; ++j) {
                free(bundle->items[j]);
            }
            free(bundle->items);
            free(bundle);
            json_object_put(root);
            return NULL;
        }

        item->metadata = json_object_object_get_ex(itemObj, "metadata", &jsonMetadata) ? jsonMetadata : json_object_new_object();

        bundle->items[i] = item;
    }

    json_object_put(root);
    return bundle;
}

void freeResourceBundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->itemCount; ++i) {
        ResourceItem *item = bundle->items[i];
        if (item->id[0]) {
            free(item->id);
        }
        json_object_put(item->metadata);
        free(item);
    }
    free(bundle->items);
    free(bundle);
}

int main() {
    const char* filePath = "path_to_resource_file.json";
    ResourceBundle *bundle = loadResourceBundle(filePath, 1024 * 1024); // 1MB max heap size
    if (bundle) {
        printf("Loaded %zu items\n", bundle->itemCount);
        freeResourceBundle(bundle);
    }
    return 0;
}
