Node** createNodeArray(int size) {
    return (Node**)malloc(size * sizeof(Node*));
}

void insertNode(Node** array, int index, int key) {
    if (index >= 0 && index < size) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->key = key;
        newNode->next = NULL;
        newNode->ref_count = 1;

        array[index] = newNode;
    }
}

void freeNodeArray(Node** array, int size) {
    for (int i = 0; i < size; i++) {
        Node* node = array[i];
        while (node != NULL) {
            Node* nextNode = node->next;
            free(node);
            node = nextNode;
        }
    }
    free(array);
}

int main() {
    int size = 5;
    Node** nodes = createNodeArray(size);

    insertNode(nodes, 0, 10);
    insertNode(nodes, 1, 20);

    freeNodeArray(nodes, size);

    return 0;
}
