#include <sys/stat.h>

#define MAX_ENVIRONMENTS 10
#define MAX_FILES 100

typedef struct {
    char path[256];
    int exists;
} EnvironmentFile;

EnvironmentFile environments[MAX_ENVIRONMENTS][MAX_FILES];

void load_environments(const char *env_path) {
    DIR *dir;
    struct dirent *entry;
    dir = opendir(env_path);
    if (dir == NULL) {
        perror("opendir");
        return;
    }
    int env_index = 0, file_index = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        snprintf(environments[env_index][file_index].path, sizeof(environments[env_index][file_index].path), "%s/%s", env_path, entry->d_name);
        struct stat file_stat;
        if (stat(environments[env_index][file_index].path, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
            environments[env_index][file_index].exists = 1;
            file_index++;
        }
        if (file_index >= MAX_FILES) {
            env_index++;
            file_index = 0;
        }
    }
    closedir(dir);
}

void check_environment_files(const char *env_path) {
    load_environments(env_path);
    for (int env_index = 0; environments[env_index][0].path[0] != '\0'; env_index++) {
        printf("Environment: %s\n", env_path);
        for (int file_index = 0; environments[env_index][file_index].path[0] != '\0'; file_index++) {
            if (!environments[env_index][file_index].exists) {
                fprintf(stderr, "Error: File not found - %s\n", environments[env_index][file_index].path);
                // Implement fallback mechanism here
            }
        }
    }
}

int main() {
    const char *env_path = "/path/to/environments";
    check_environment_files(env_path);
    return 0;
}
