#define MAX_CONCURRENT_THREADS 100

typedef struct {
    int key;
    long offset;
    char* string;
} record;

record** init_and_manage_records(int num_records, int min_key, int max_key, int min_string_len, int max_string_len) {
    static pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;
    static record** records_pool[MAX_CONCURRENT_THREADS] = {0};
    static int pool_index = 0;

    pthread_mutex_lock(&records_lock);
    if (pool_index >= MAX_CONCURRENT_THREADS) {
        pthread_mutex_unlock(&records_lock);
        return NULL; // Pool overflow
    }

    records_pool[pool_index++] = malloc(num_records * sizeof(record*));
    if (!records_pool[pool_index - 1]) {
        pthread_mutex_unlock(&records_lock);
        return NULL; // Memory allocation failed
    }

    record** records = records_pool[pool_index - 1];
    srand(time(NULL) + getpid());

    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            // Handle partial allocation and cleanup
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records_pool[pool_index - 1]);
            records_pool[pool_index - 1] = NULL;
            pthread_mutex_unlock(&records_lock);
            return NULL; // Memory allocation failed
        }

        records[i]->key = rand() % (max_key - min_key + 1) + min_key;
        records[i]->offset = i * sizeof(record); // Example offset calculation

        int string_len = rand() % (max_string_len - min_string_len + 1) + min_string_len;
        records[i]->string = malloc((string_len + 1) * sizeof(char));
        if (!records[i]->string) {
            free(records[i]);
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records_pool[pool_index - 1]);
            records_pool[pool_index - 1] = NULL;
            pthread_mutex_unlock(&records_lock);
            return NULL; // Memory allocation failed
        }

        // Securely generate random alphanumeric string
        for (int j = 0; j < string_len; ++j) {
            records[i]->string[j] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"[rand() % 62];
        }
        records[i]->string[string_len] = '\0';
    }

    pthread_mutex_unlock(&records_lock);
    return records;
}

void free_records(record** records, int num_records) {
    static pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&records_lock);
    for (int i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->string);
            free(records[i]);
        }
    }

    // Assuming only one thread uses this pool
    static record** records_pool[MAX_CONCURRENT_THREADS];
    for (int i = 0; i < MAX_CONCURRENT_THREADS; ++i) {
        if (records_pool[i]) {
            free(records_pool[i]);
            records_pool[i] = NULL;
        }
    }

    pthread_mutex_unlock(&records_lock);
}
