            snprintf(file_path, sizeof(file_path), "%s/%s", image_dir, ent->d_name);

            if (fetch_remote) {
                // Fetch the image from remote source
            } else {
                // Load the image from local file
                images[i] = load_image(file_path);
                pthread_create(&threads[i], NULL, load_image, &images[i]);
                i++;
            }
        }
        closedir(dir);
    }

    for (int j = 0; j < num_images; j++) {
        pthread_join(threads[j], NULL);
    }

    // Store processed images in memory-mapped file
    int fd = open("processed_images.mmf", O_CREAT | O_RDWR, 0644);
    ftruncate(fd, sizeof(Image) * num_images);

    void* mmf = mmap(NULL, sizeof(Image) * num_images, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mmf == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    memcpy(mmf, images, sizeof(Image) * num_images);

    munmap(mmf, sizeof(Image) * num_images);
    close(fd);

    // Clean up resources
    for (int k = 0; k < num_images; k++) {
        free(images[k].data);
    }

    return 0;
}
