        if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            // Set log level based on command line argument
            const char *level = argv[++i];
            if (strcmp(level, "DEBUG") == 0) log_level = DEBUG;
            else if (strcmp(level, "INFO") == 0) log_level = INFO;
            else if (strcmp(level, "WARNING") == 0) log_level = WARNING;
            else if (strcmp(level, "ERROR") == 0) log_level = ERROR;
            else if (strcmp(level, "CRITICAL") == 0) log_level = CRITICAL;
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            // Set custom log directory
            log_dir = argv[++i];
        } else if (strcmp(argv[i], "-s") == 0) {
            // Add stop words from command line arguments
            ++i;
            while (i < argc && argv[i][0] != '-') {
                ++stop_word_count;
                i++;
            }
            stop_words = (const char **)realloc(stop_words, sizeof(const char *) * stop_word_count);
            for (size_t j = 0; j < stop_word_count; ++j) {
