#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit in bytes

typedef struct record {
    int value;
} Record;

typedef struct hash_entry {
    int key;
    Record *record;
    struct hash_entry *next;
} HashEntry;

typedef struct hash_table {
    HashEntry **buckets;
    int size;
    int count;
    pthread_mutex_t mutex;
} HashTable;

void* initialize_data_structures(int n, int m, int low, int high) {
    if (n <= 0 || m <= 0) {
        return NULL; // Handle invalid input
    }

    long *offsets = (long *)malloc(n * sizeof(long));
    int *keys = (int *)malloc(n * sizeof(int));
    Record **records = (Record **)malloc(m * sizeof(Record *));
    Record **conflicting_records = (Record **)malloc(m * sizeof(Record *));
    int *indexes = (int *)calloc(n, sizeof(int));

    if (!offsets || !keys || !records || !conflicting_records || !indexes) {
        // Handle memory allocation error
        free(offsets);
        free(keys);
        free(records);
        free(conflicting_records);
        free(indexes);
        return NULL;
    }

    HashTable *hash_table = (HashTable *)malloc(sizeof(HashTable));
    hash_table->size = 16; // Initial size of the hash table
    hash_table->count = 0;
    hash_table->buckets = (HashEntry **)calloc(hash_table->size, sizeof(HashEntry *));
    pthread_mutex_init(&hash_table->mutex, NULL);

    if (!hash_table || !hash_table->buckets) {
        // Handle memory allocation error
        free(offsets);
        free(keys);
        free(records);
        free(conflicting_records);
        free(indexes);
        free(hash_table->buckets);
        free(hash_table);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < m; i++) {
        Record *record = (Record *)malloc(sizeof(Record));
        record->value = rand() % (high - low + 1) + low;

        int key = rand() % n;
        HashEntry *entry = hash_table_find(hash_table, key);
        if (entry == NULL) {
            entry = (HashEntry *)malloc(sizeof(HashEntry));
            entry->key = key;
            entry->record = record;
            entry->next = NULL;

            int index = indexes[key];
            records[index] = record;
            conflicting_records[index] = NULL;
            indexes[key] = (indexes[key] + 1) % n;

            hash_table_insert(hash_table, entry);
        } else {
            // Handle conflict
            Record *conflicting_record = entry->record;
            conflicting_records[entry->key] = conflicting_record;
        }
    }

    return offsets;
}

// Helper functions for hash table operations (not shown)
