void insert_record(HashTable *table, int key, Record record) {
    pthread_mutex_lock(&table->mutex);
    if (table->size >= table->capacity - 1) {
        expand_hash_table(table);
    }

    size_t index = hash_function(key); // Assume a simple hash function for demonstration
    while (table->keys[index] != -1 && table->keys[index] != key) {
        index = (index + 1) % table->capacity;
    }

    if (table->keys[index] == -1) {
        table->offsets[table->size] = malloc(sizeof(Record));
        memcpy(table->offsets[table->size], &record, sizeof(Record));
        table->keys[index] = key;
        table->records[index] = table->offsets[table->size];
        table->size++;
    }

    pthread_mutex_unlock(&table->mutex);
}

void validate_records(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        if (table->keys[i] != -1 && !check_record(table->records[i])) {
            fprintf(stderr, "Record validation failed\n");
        }
    }
}

void set_random_value(HashTable *table, int key, int min, int max) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key); // Assume a simple hash function for demonstration
    while (index < table->capacity && table->keys[index] != key && table->keys[index] != -1) {
        index = (index + 1) % table->capacity;
    }

    if (table->keys[index] == key) {
        table->records[index]->value = min + rand() % (max - min + 1);
    } else {
        fprintf(stderr, "Key not found\n");
    }

    pthread_mutex_unlock(&table->mutex);
}

void reset_records(HashTable *table) {
    pthread_mutex_lock(&table->mutex);
    for (size_t i = 0; i < table->size; ++i) {
        if (table->keys[i] != -1) {
            table->records[i]->value = 0;
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

void free_all_memory(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        free(table->records[i]);
    }
    free(table->offsets);
    free(table->keys);
    free(table->records);
    pthread_mutex_destroy(&table->mutex);
}

int hash_function(int key) {
    // Implement a simple hash function
    return abs(key % 1024);
}

int check_record(Record *record) {
    // Implement record validation logic
    return (record != NULL && record->value >= 0);
}
