#define ERROR_VALUE -1

typedef struct {
    int value;
} record;

record** create_data_structures(int n, int m, int low, int high, double p) {
    if (n <= 0 || m <= 0) {
        return NULL; // Invalid input
    }

    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) {
        return NULL; // Memory allocation failed
    }

    int* keys = (int*)malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record** records = (record**)malloc(m * sizeof(record*));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    record** secondary_records = (record**)malloc(m * sizeof(record*));
    if (!secondary_records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    int* indexes = (int*)calloc(n, sizeof(int));
    if (!indexes) {
        free(offsets);
        free(keys);
        free(records);
        free(secondary_records);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < m; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            free(secondary_records);
            free(indexes);
            return NULL;
        }

        if ((double)rand() / RAND_MAX < p) {
            // Record generation failed
            records[i]->value = ERROR_VALUE;
        } else {
            records[i]->value = rand() % (high - low + 1) + low;
        }
    }

    for (int i = m; i < n * m; ++i) {
        secondary_records[i - m] = (record*)malloc(sizeof(record));
        if (!secondary_records[i - m]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) {
                free(secondary_records[j]);
            }
            for (int j = 0; j < m; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            free(secondary_records);
            free(indexes);
            return NULL;
        }

        secondary_records[i - m]->value = rand() % (high - low + 1) + low;
    }

    // Initialize offsets and keys
    for (int i = 0; i < n; ++i) {
        offsets[i] = i * m;
        keys[i] = rand() % (high - low + 1) + low;
    }

    return records;
}
