// Define custom memory pool allocator structure
typedef struct {
    void *pool;
    size_t block_size;
    size_t pool_size;
    int free_index;
    pthread_mutex_t mutex;
} MemoryPool;

// Function to initialize memory pool
MemoryPool* init_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->pool_size = pool_size;
    pool->free_index = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    pool->pool = malloc(block_size * pool_size);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

// Function to allocate memory from the custom pool
void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->free_index >= pool->pool_size) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL; // Pool full, cannot allocate
    }

    void *block = ((char*)pool->pool + pool->free_index * pool->block_size);
    pool->free_index++;
    pthread_mutex_unlock(&pool->mutex);
    return block;
}

// Function to free memory back to the custom pool (not used in this example)
void free_to_pool(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->mutex);
    size_t index = ((char*)block - (char*)pool->pool) / pool->block_size;
    if (index >= 0 && index < pool->free_index) {
        pool->free_index--;
    }
    pthread_mutex_unlock(&pool->mutex);
}

// Function to create and initialize a multi-dimensional data structure
float*** create_and_initialize_matrix(int rows, int cols, int depth, float min_val, float max_val, MemoryPool *pool) {
    if (rows <= 0 || cols <= 0 || depth <= 0) return NULL;

    // Allocate memory for the main matrix using custom pool
    float ***matrix = allocate_from_pool(pool);
    if (!matrix) return NULL;

    // Initialize matrix and handle conflicts
    // ...

    return matrix;
}

// Function to dynamically resize the 3D matrix
void* resize_matrix(void *matrix, int new_rows, int new_cols, int new_depth, MemoryPool *pool) {
    // Implement resizing logic using custom pool
    // ...
    return matrix;
}

// Function to query the current number of allocated elements
int get_allocated_elements_count(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    int count = pool->free_index;
    pthread_mutex_unlock(&pool->mutex);
    return count;
}

// Function to populate the matrix from an external data source
