    }
    for (int i = 0; i < n; i++) {
        ids[i] = rand(); // Initialize with random values
    }
    return ids;
}

double* create_weights(int n) {
    double* weights = (double*)malloc(n * sizeof(double));
    if (weights == NULL) {
        // Handle memory allocation error
        return NULL;
    }
    for (int i = 0; i < n; i++) {
        weights[i] = ((double)rand() / RAND_MAX) * 100.0; // Random values between 0 and 100
    }
    return weights;
}

operation* create_operations(int m, double low, double high, int* index_map) {
    operation* operations = (operation*)malloc(m * sizeof(operation));
    if (operations == NULL) {
        // Handle memory allocation error
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    operation* conflicts = NULL;
    int conflict_count = 0;

    for (int i = 0; i < m; i++) {
        operations[i].type = rand() % 3 + 1; // Randomly select operation type
        operations[i].value = low + ((double)rand() / RAND_MAX) * (high - low);

        int index = operations[i].type - 1;
        if (index_map[index] != i) {
            conflicts = realloc(conflicts, (conflict_count + 1) * sizeof(operation));
            if (conflicts == NULL) {
                // Handle memory allocation error
                free(operations);
                return NULL;
            }
            conflicts[conflict_count++] = operations[i];
        } else {
            index_map[index] = i;
        }
    }

    return operations;
}

operation* create_conflicting_operations(operation* conflicts, int conflict_count) {
    operation* conflicting_ops = (operation*)malloc(conflict_count * sizeof(operation));
    if (conflicting_ops == NULL) {
        // Handle memory allocation error
        return NULL;
    }
    for (int i = 0; i < conflict_count; i++) {
        conflicting_ops[i] = conflicts[i];
    }
    free(conflicts); // Free the temporary array
    return conflicting_ops;
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle memory allocation error
        return NULL;
    }
    return ptr;
}
