float*** create_3d_matrix(int rows, int cols, int depth) {
    if (rows <= 0 || cols <= 0 || depth <= 0) {
        fprintf(stderr, "Invalid dimensions.\n");
        return NULL;
    }

    float*** matrix = (float***)malloc(rows * sizeof(float**));
    if (!matrix) {
        perror("Failed to allocate memory for rows.");
        return NULL;
    }

    for (int i = 0; i < rows; ++i) {
        matrix[i] = (float**)malloc(cols * sizeof(float*));
        if (!matrix[i]) {
            fprintf(stderr, "Failed to allocate memory for cols at row %d.\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(matrix[j]);
            }
            free(matrix);
            return NULL;
        }

        for (int j = 0; j < cols; ++j) {
            matrix[i][j] = (float*)malloc(depth * sizeof(float));
            if (!matrix[i][j]) {
                fprintf(stderr, "Failed to allocate memory for depth at row %d, col %d.\n", i, j);
                // Free previously allocated memory
                for (int k = 0; k < j; ++k) {
                    free(matrix[i][k]);
                }
                for (int k = 0; k < i; ++k) {
                    free(matrix[k]);
                }
                free(matrix);
                return NULL;
            }

            // Initialize with random values
            matrix[i][j] = MIN_VAL + (float)(rand() / (RAND_MAX / (MAX_VAL - MIN_VAL)));
        }
    }

    return matrix;
}

void free_3d_matrix(float*** matrix, int rows, int cols) {
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            free(matrix[i][j]);
        }
        free(matrix[i]);
    }
    free(matrix);
}

int main() {
    srand(time(NULL));
    float*** matrix = create_3d_matrix(2, 3, 4);

    if (matrix) {
        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j < 3; ++j) {
                printf("matrix[%d][%d] = %f\n", i, j, matrix[i][j]);
            }
        }

        free_3d_matrix(matrix, 2, 3);
    }

    return 0;
}
