#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    size_t size;
    size_t capacity;
    record *data;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t initial_capacity) {
    memory_pool *pool = (memory_pool *)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->size = 0;
    pool->capacity = initial_capacity;
    pool->data = (record *)malloc(initial_capacity * sizeof(record));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->data);
    free(pool);
}

record* allocate_record(memory_pool *pool) {
    record *new_record = (record *)malloc(sizeof(record));
    if (!new_record) return NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->size < pool->capacity) {
        new_record->value = rand() % 100; // Random value for demonstration
        pool->data[pool->size++] = *new_record;
    } else {
        pthread_mutex_unlock(&pool->lock);
        free(new_record);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);

    return new_record;
}

void deallocate_record(memory_pool *pool, record *record) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; ++i) {
        if (&pool->data[i] == record) {
            pool->data[i].value = -1; // Mark as free
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

int main() {
    srand(time(NULL));

    memory_pool *pool = create_memory_pool(100);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    record **records = (record **)malloc(50 * sizeof(record *));
    if (!records) {
        fprintf(stderr, "Failed to allocate records array\n");
        destroy_memory_pool(pool);
        return 1;
    }

    for (int i = 0; i < 50; ++i) {
        records[i] = allocate_record(pool);
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate record %d\n", i);
            // Handle error or retry allocation
        }
    }

    for (int i = 0; i < 50; ++i) {
        deallocate_record(pool, records[i]);
    }

    free(records);
    destroy_memory_pool(pool);

    return 0;
}
