// Function to dynamically allocate memory for and initialize a 3D float matrix
float*** create_3d_matrix(int rows, int cols, int depth, float min_val, float max_val) {
    if (rows <= 0 || cols <= 0 || depth <= 0) {
        // Handle invalid input
        return NULL;
    }

    float*** matrix = (float***)malloc(rows * sizeof(float**));
    if (!matrix) {
        // Handle memory allocation error
        return NULL;
    }

    for (int i = 0; i < rows; ++i) {
        matrix[i] = (float**)malloc(cols * sizeof(float*));
        if (!matrix[i]) {
            // Free previously allocated memory and handle error
            for (int j = 0; j < i; ++j) {
                free(matrix[j]);
            }
            free(matrix);
            return NULL;
        }

        for (int j = 0; j < cols; ++j) {
            matrix[i][j] = (float*)malloc(depth * sizeof(float));
            if (!matrix[i][j]) {
                // Free previously allocated memory and handle error
                for (int k = 0; k < j; ++k) {
                    free(matrix[i][k]);
                }
                free(matrix[i]);
                for (int l = 0; l < i; ++l) {
                    free(matrix[l]);
                }
                free(matrix);
                return NULL;
            }

            // Initialize elements with random values
            matrix[i][j] = min_val + ((max_val - min_val) * (float)rand() / RAND_MAX);
        }
    }

    return matrix;
}

// Example usage
int main() {
    srand(time(NULL));
    int rows = 3, cols = 4, depth = 5;
    float** matrix = create_3d_matrix(rows, cols, depth, -1.0f, 1.0f);

    if (matrix) {
        // Use the matrix
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                for (int k = 0; k < depth; ++k) {
                    printf("%f ", matrix[i][j][k]);
                }
                printf("\n");
            }
            printf("\n");
        }

        // Free the allocated memory
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                free(matrix[i][j]);
            }
            free(matrix[i]);
        }
        free(matrix);
    } else {
        // Handle error
        printf("Failed to create matrix.\n");
    }

    return 0;
}
