#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1000
#define STRING_POOL_SIZE 100

typedef struct {
    int value;
    char* identifier;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    char* string_pool[STRING_POOL_SIZE];
    size_t pool_index;
} RecordManager;

RecordManager* create_record_manager() {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) {
        perror("Failed to allocate memory for RecordManager");
        return NULL;
    }

    for (size_t i = 0; i < STRING_POOL_SIZE; ++i) {
        manager->string_pool[i] = malloc(256); // Assuming max string length of 255
        if (!manager->string_pool[i]) {
            perror("Failed to allocate memory for string pool");
            free(manager);
            return NULL;
        }
    }

    manager->pool_index = 0;

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        manager->records[i].identifier = malloc(256); // Assuming max string length of 255
        if (!manager->records[i].identifier) {
            perror("Failed to allocate memory for record identifier");
            for (size_t j = 0; j < i; ++j) {
                free(manager->records[j].identifier);
            }
            free(manager);
            return NULL;
        }
    }

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        free(manager->records[i].identifier);
    }

    for (size_t i = 0; i < STRING_POOL_SIZE; ++i) {
        free(manager->string_pool[i]);
    }

    free(manager);
}

void insert_record(RecordManager* manager, int value, const char* identifier) {
    if (manager->pool_index >= STRING_POOL_SIZE || manager->records[manager->pool_index].identifier == NULL) {
        fprintf(stderr, "String pool or record allocation failed\n");
        return;
    }

    Record* record = &manager->records[manager->pool_index];
    record->value = value;
    strncpy(record->identifier, identifier, 255);
    manager->pool_index++;
}

void print_records(const RecordManager* manager) {
    for (size_t i = 0; i < manager->pool_index; ++i) {
        printf("Value: %d, Identifier: %s\n", manager->records[i].value, manager->records[i].identifier);
    }
}

int main() {
    RecordManager* manager = create_record_manager();
    if (!manager) {
        return 1;
    }

    insert_record(manager, 42, "example");
    insert_record(manager, 100, "test");

    print_records(manager);

    destroy_record_manager(manager);
    return 0;
}
```

