    }

    for (int j = 0; j < m; j++) {
        records[j].value = rand() % (high - low + 1) + low;
        records[j].weight = offsets[rand() % n];
        records[j].status = 'A'; // Example initialization
    }

    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_sha256());
