#include <pthread.h>

#define POOL_SIZE 1024

typedef struct node {
    int ref_count;
    int status_flag;
    struct node* next;
} Node;

typedef struct {
    double* values;
    char** labels;
    Node** nodes;
    size_t n;
    size_t pool_size;
    pthread_mutex_t lock;
} DataPipeline;

DataPipeline* create_data_pipeline(size_t n) {
    DataPipeline* pipeline = (DataPipeline*)malloc(sizeof(DataPipeline));
    if (!pipeline) return NULL;

    pipeline->values = (double*)malloc(n * sizeof(double));
    pipeline->labels = (char**)malloc(n * sizeof(char*));
    pipeline->nodes = (Node**)malloc(n * sizeof(Node*));
    pthread_mutex_init(&pipeline->lock, NULL);

    for (size_t i = 0; i < n; ++i) {
        pipeline->values[i] = 0.0;
        pipeline->labels[i] = (char*)malloc(256);
        pipeline->nodes[i] = (Node*)malloc(sizeof(Node));
        pipeline->nodes[i]->ref_count = 1;
        pipeline->nodes[i]->status_flag = 0;
        pipeline->nodes[i]->next = NULL;
    }

    return pipeline;
}

void destroy_data_pipeline(DataPipeline* pipeline, size_t n) {
    pthread_mutex_lock(&pipeline->lock);
    for (size_t i = 0; i < n; ++i) {
        free(pipeline->labels[i]);
        Node* current = pipeline->nodes[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_unlock(&pipeline->lock);

    free(pipeline->values);
    free(pipeline->labels);
    free(pipeline->nodes);
    pthread_mutex_destroy(&pipeline->lock);
    free(pipeline);
}
