    if (!cache) {
        free(offsets);
        free(keys);
        free(records);
        printf("Failed to allocate memory for cache.\n");
        return NULL;
    }

    // Initialize cache
    for (int i = 0; i < recordCount; ++i) {
        cache[i] = -1; // -1 indicates not cached
    }

    void* dataProcessingModule = malloc(sizeof(data_processing_module));
    if (!dataProcessingModule) {
        free(offsets);
        free(keys);
        free(records);
        free(cache);
        printf("Failed to allocate memory for data processing module.\n");
        return NULL;
    }

    // Initialize dataProcessingModule with offsets, keys, records, and cache
    ((data_processing_module*)dataProcessingModule)->offsets = offsets;
    ((data_processing_module*)dataProcessingModule)->keys = keys;
    ((data_processing_module*)dataProcessingModule)->records = records;
    ((data_processing_module*)dataProcessingModule)->cache = cache;

    return dataProcessingModule;
}

