#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define MIN_VALUE 10
#define MAX_VALUE 100

typedef struct {
    int value;
    char* metadata;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t allocated_size;
    size_t used_count;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t initial_size) {
    memory_pool* pool = malloc(sizeof(memory_pool));
    if (pool == NULL) return NULL;

    pool->offsets = malloc(initial_size * sizeof(long));
    pool->keys = malloc(initial_size * sizeof(int));
    pool->records = malloc(initial_size * sizeof(record*));
    if (pool->offsets == NULL || pool->keys == NULL || pool->records == NULL) {
        free(pool);
        return NULL;
    }

    memset(pool->offsets, 0, initial_size * sizeof(long));
    memset(pool->keys, 0, initial_size * sizeof(int));
    memset(pool->records, 0, initial_size * sizeof(record*));
    pool->allocated_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

record* allocate_record(memory_pool* pool) {
    if (pool->used_count == pool->allocated_size) {
        size_t new_size = pool->allocated_size * 2;
        long* new_offsets = realloc(pool->offsets, new_size * sizeof(long));
        int* new_keys = realloc(pool->keys, new_size * sizeof(int));
        record** new_records = realloc(pool->records, new_size * sizeof(record*));

        if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
            return NULL;
        }

        pool->offsets = new_offsets;
        pool->keys = new_keys;
        pool->records = new_records;
        pool->allocated_size = new_size;
    }

    record* rec = malloc(sizeof(record));
    if (rec == NULL) return NULL;

    rec->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    rec->metadata = malloc(20 * sizeof(char));
    sprintf(rec->metadata, "Metadata_%d", pool->used_count);

    pthread_mutex_lock(&pool->lock);
    pool->records[pool->used_count] = rec;
    pool->keys[pool->used_count] = rand();
    pool->offsets[pool->used_count] = (long)rec;
    pool->used_count++;
    pthread_mutex_unlock(&pool->lock);

    return rec;
}

void free_record(memory_pool* pool, record* rec) {
    for (size_t i = 0; i < pool->used_count; i++) {
        if (pool->records[i] == rec) {
            pthread_mutex_lock(&pool->lock);
            pool->records[i] = NULL;
            free(pool->keys[i]);
            free(pool->offsets[i]);
            free(rec);
            pool->used_count--;
            pthread_mutex_unlock(&pool->lock);
            break;
        }
    }
}

void destroy_memory_pool(memory_pool* pool) {
    for (size_t i = 0; i < pool->used_count; i++) {
        if (pool->records[i] != NULL) {
            free(pool->keys[i]);
            free(pool->offsets[i]);
            free(pool->records[i]);
        }
    }

    pthread_mutex_destroy(&pool->lock);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);
}

int main() {
    srand(time(NULL));
    memory_pool* pool = create_memory_pool(100);
    if (pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (size_t i = 0; i < MAX_RECORDS; i++) {
        record* rec = allocate_record(pool);
        if (rec == NULL) {
            printf("Failed to allocate record %zu\n", i);
        } else {
            printf("Allocated record with value: %d, metadata: %s\n", rec->value, rec->metadata);
        }
    }

    for (size_t i = 0; i < MAX_RECORDS / 2; i++) {
        free_record(pool, pool->records[i]);
    }

    destroy_memory_pool(pool);
    return 0;
}
