        fwrite(records[i]->string, 1, string_length, file);
        fwrite(&records[i]->metadata_count, sizeof(int), 1, file);
    }
}

void deserialize_module(record** records, int* count, FILE* file) {
    fread(count, sizeof(int), 1, file);

