        fread(&records[i]->value, sizeof(int), 1, file);
        size_t string_length;
        fread(&string_length, sizeof(size_t), 1, file);
        records[i]->string = malloc(string_length + 1);
        fread(records[i]->string, 1, string_length, file);
        records[i]->string[string_length] = '\0';
        fread(&records[i]->metadata_count, sizeof(int), 1, file);
    }
}

void log_memory_operation(char* operation, int time_taken, int memory_usage) {
