typedef struct {
    MetaData *metadataArray;
    Record **recordArray;
    int metadataSize;
    int recordSize;
} DataModule;

int initializeAndPopulateModule(DataModule *module, int metadataSize, int recordSize, int rangeMin, int rangeMax) {
    if (metadataSize < 0 || recordSize < 0 || rangeMin < 0 || rangeMax < 0 || rangeMin > rangeMax) {
        return -1; // Invalid input
    }

    module->metadataArray = malloc(metadataSize * sizeof(MetaData));
    module->recordArray = malloc(recordSize * sizeof(Record *));
    if (!module->metadataArray || !module->recordArray) {
        free(module->metadataArray);
        free(module->recordArray);
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < metadataSize; ++i) {
        module->metadataArray[i].offset = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        module->metadataArray[i].key = i; // Using index as key for simplicity
        module->recordArray[i] = malloc(sizeof(Record));
        if (!module->recordArray[i]) {
            for (int j = 0; j < i; ++j) {
                free(module->recordArray[j]);
            }
            free(module->metadataArray);
            free(module->recordArray);
            return -2; // Memory allocation failed
        }
        module->recordArray[i]->value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
    }

    module->metadataSize = metadataSize;
    module->recordSize = recordSize;

    return 0; // Success
}

void freeModule(DataModule *module) {
    for (int i = 0; i < module->recordSize; ++i) {
        free(module->recordArray[i]);
    }
    free(module->metadataArray);
    free(module->recordArray);
}
