MatrixModule* init_matrix_module(int rows, int cols, size_t pool_size, void *(*init_value_func)(double, double)) {
    MatrixModule *module = (MatrixModule*)custom_malloc(NULL, sizeof(MatrixModule));
    if (!module) return NULL;

    module->total_submatrices = 1; // For simplicity, assume one submatrix
    module->submatrices = (Submatrix*)custom_malloc(module, sizeof(Submatrix));
    if (!module->submatrices) {
