        return NULL;
    }

    Submatrix *submatrix = &module->submatrices[0];
    submatrix->rows = rows;
    submatrix->cols = cols;
    submatrix->data = (double**)custom_malloc(module, rows * sizeof(double*));
    if (!submatrix->data) {
