        submatrix->data[i] = (double*)custom_malloc(module, cols * sizeof(double));
        if (!submatrix->data[i]) {
            for (int j = 0; j < i; ++j) free(submatrix->data[j]);
            free(submatrix->data);
            free(submatrix);
            free(module->submatrices);
            free(module);
            return NULL;
        }
    }

    pthread_mutex_init(&submatrix->lock, NULL);

    module->memory_pool_size = pool_size;
    module->init_value_func = init_value_func;
    pthread_mutex_init(&module->global_lock, NULL);

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            submatrix->data[i][j] = module->init_value_func(i, j);
        }
    }

    return module;
}

// Function to destroy the matrix module
void destroy_matrix_module(MatrixModule *module) {
    if (!module) return;

    for (int i = 0; i < module->total_submatrices; ++i) {
        Submatrix *submatrix = &module->submatrices[i];
        for (int j = 0; j < submatrix->rows; ++j) free(submatrix->data[j]);
        free(submatrix->data);
        pthread_mutex_destroy(&submatrix->lock);
    }

    free(module->submatrices);
    pthread_mutex_destroy(&module->global_lock);
    free(module);
}

// Function to perform element-wise addition
void add_matrix(MatrixModule *module, double value) {
    pthread_mutex_lock(&module->global_lock);
    for (int i = 0; i < module->total_submatrices; ++i) {
        Submatrix *submatrix = &module->submatrices[i];
        pthread_mutex_lock(&submatrix->lock);
        for (int j = 0; j < submatrix->rows; ++j) {
            for (int k = 0; k < submatrix->cols; ++k) {
                submatrix->data[j][k] += value;
            }
        }
        pthread_mutex_unlock(&submatrix->lock);
