#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MIN_STRING_LENGTH 5
#define MAX_STRING_LENGTH 20

typedef struct {
    int value;
    char *str;
} record;

record* create_records(int num_records, int low, int high) {
    record *records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (high - low + 1) + low;
        int length = rand() % (MAX_STRING_LENGTH - MIN_STRING_LENGTH + 1) + MIN_STRING_LENGTH;
        records[i].str = malloc(length * sizeof(char));
        if (records[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            free_records(records, i);
            return NULL;
        }
        sprintf(records[i].str, "%d", rand());
    }

    return records;
}

void free_records(record *records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].str);
    }
    free(records);
}

void serialize_records(record *records, int num_records, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fwrite(&num_records, sizeof(int), 1, file);
    for (int i = 0; i < num_records; ++i) {
        fwrite(&records[i].value, sizeof(int), 1, file);
        int length = strlen(records[i].str);
        fwrite(&length, sizeof(int), 1, file);
        fwrite(records[i].str, sizeof(char), length, file);
    }

    fclose(file);
}

void deserialize_records(record *records, int *num_records, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    fread(num_records, sizeof(int), 1, file);
    records = realloc(records, (*num_records) * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        fclose(file);
        return;
    }

    for (int i = 0; i < *num_records; ++i) {
        fread(&records[i].value, sizeof(int), 1, file);
        int length;
        fread(&length, sizeof(int), 1, file);
        records[i].str = malloc(length * sizeof(char));
        if (records[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            free_records(records, i);
            fclose(file);
            return;
        }
        fread(records[i].str, sizeof(char), length, file);
    }

    fclose(file);
}

int main() {
    srand(time(NULL));
    int num_records = MAX_RECORDS;
    record *records = create_records(num_records, 10, 20);

    if (records != NULL) {
        serialize_records(records, num_records, "data.bin");
        free_records(records, num_records);
    }

    records = NULL;
    deserialize_records(records, &num_records, "data.bin");

    return 0;
}
