#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int event_id;
    long timestamp;
    void* payload;
} Event;

typedef struct {
    Event** events;
    int front, rear, size;
    sem_t items, spaces;
    pthread_mutex_t mutex;
} EventQueue;

void initializeEventQueue(EventQueue* queue, int capacity) {
    queue->events = (Event**)malloc(capacity * sizeof(Event*));
    queue->front = queue->rear = -1;
    queue->size = 0;
    queue->capacity = capacity;
    sem_init(&queue->items, 0, 0);
    sem_init(&queue->spaces, 0, capacity);
    pthread_mutex_init(&queue->mutex, NULL);
}

void enqueue(EventQueue* queue, Event* event) {
    sem_wait(&queue->spaces);
    pthread_mutex_lock(&queue->mutex);
    if (queue->rear == -1) {
        queue->front = 0;
    }
    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->events[queue->rear] = event;
    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->items);
}

Event* dequeue(EventQueue* queue) {
    Event* event;
    sem_wait(&queue->items);
    pthread_mutex_lock(&queue->mutex);
    if (queue->front == -1) {
        printf("Error: Queue is empty\n");
        return NULL;
    }
    event = queue->events[queue->front];
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % queue->capacity;
    }
    queue->size--;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->spaces);
    return event;
}

