}

void unsubscribe(SubscriptionManager* manager, int event_id) {
    // Unsubscribe from an event here
}

typedef struct {
    void (*handleEvent)(Event*);
} MessageHandler;

void initializeMessageHandler(MessageHandler* handler, void (*callback)(Event*)) {
    handler->handleEvent = callback;
}

void handleMessage(MessageHandler* handler, Event* event) {
    handler->handleEvent(event);
}

// Example usage
void processEvent(Event* event) {
    printf("Processing event ID: %d at timestamp: %ld\n", event->event_id, event->timestamp);
}

int main() {
    EventQueue queue;
    initializeEventQueue(&queue, 100);

    SubscriptionManager manager;
    initializeSubscriptionManager(&manager);

    MessageHandler handler;
    initializeMessageHandler(&handler, processEvent);

    // Simulate event processing
    for (int i = 0; i < 1000; i++) {
        Event* event = (Event*)malloc(sizeof(Event));
        event->event_id = i;
        event->timestamp = time(NULL);
        enqueue(&queue, event);
    }

    while (queue.size > 0) {
        Event* event = dequeue(&queue);
        if (event != NULL) {
            handleMessage(&handler, event);
            free(event); // Free the allocated memory for each event
        }
    }

    return 0;
}
