#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>

// Define event structure
typedef struct {
    int event_id;
    struct timeval timestamp;
    void* payload;
} Event;

// Event queue node
typedef struct EventNode {
    Event* event;
    struct EventNode* next;
} EventNode;

// Event queue structure
typedef struct EventQueue {
    EventNode* head;
    EventNode* tail;
    pthread_mutex_t lock;
} EventQueue;

// Subscription manager structure
typedef struct {
    // Implement subscription logic here
} SubscriptionManager;

// Message handler function signature
typedef void (*MessageHandler)(Event*);

// Initialize event queue
void init_event_queue(EventQueue* queue) {
    queue->head = queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
}

// Enqueue an event
void enqueue_event(EventQueue* queue, Event* event) {
    pthread_mutex_lock(&queue->lock);
    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    new_node->event = event;
    new_node->next = NULL;

    if (queue->tail == NULL) {
        queue->head = queue->tail = new_node;
    } else {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }
    pthread_mutex_unlock(&queue->lock);
}

// Dequeue an event
Event* dequeue_event(EventQueue* queue) {
    Event* event = NULL;
    pthread_mutex_lock(&queue->lock);
    if (queue->head != NULL) {
        EventNode* temp = queue->head;
        event = temp->event;
        queue->head = queue->head->next;

        if (queue->head == NULL) {
            queue->tail = NULL;
        }

        free(temp);
    }
    pthread_mutex_unlock(&queue->lock);
    return event;
}

// Message handler function
void handle_message(Event* event) {
    // Implement message handling logic here
    printf("Event ID: %d, Timestamp: %ld.%06ld\n", event->event_id, event->timestamp.tv_sec, event->timestamp.tv_usec);
}

// Main processing loop for event-driven framework
void* event_processing_loop(void* arg) {
    EventQueue* queue = (EventQueue*)arg;
    MessageHandler handler = handle_message;

    while (1) {
        Event* event = dequeue_event(queue);
        if (event != NULL) {
            handler(event);
        }
    }

    return NULL;
}

int main() {
    EventQueue event_queue;
    init_event_queue(&event_queue);

    // Simulate enqueuing events
    for (int i = 0; i < 10; i++) {
        Event* new_event = (Event*)malloc(sizeof(Event));
        new_event->event_id = i;
        gettimeofday(&new_event->timestamp, NULL);
        new_event->payload = NULL;

        enqueue_event(&event_queue, new_event);
    }

    // Start processing loop in a separate thread
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, event_processing_loop, &event_queue);

    // Wait for the processing loop to finish (never actually does)
    pthread_join(thread_id, NULL);

    return 0;
}
```

This code provides a basic framework for an event-driven system in C using a linked list for the event queue. It includes functions to enqueue and dequeue events, as well as a main processing loop that handles events. The `handle_message` function is a placeholder where you can implement specific logic for processing each event.

Remember to implement the subscription manager and caching mechanisms as needed, and consider adding additional features such as thread pooling and dynamic adjustment of worker threads based on load.']

