#define RECORD_POOL_SIZE 1024

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    record** secondary_records;
    int* indexes;
    pthread_mutex_t lock;
} data_structures;

data_structures* initialize_data_structures(int n, int m, int low, int high) {
    if (n <= 0 || m <= 0) {
        return NULL; // Error: Invalid input
    }

    data_structures* ds = malloc(sizeof(data_structures));
    if (!ds) {
        return NULL; // Memory allocation failed
    }

    ds->offsets = malloc(n * sizeof(long));
    ds->keys = malloc(n * sizeof(int));
    ds->records = malloc(m * sizeof(record*));
    ds->secondary_records = malloc(RECORD_POOL_SIZE * sizeof(record*));
    ds->indexes = malloc(m * sizeof(int));

    if (!ds->offsets || !ds->keys || !ds->records || !ds->secondary_records || !ds->indexes) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds->secondary_records);
        free(ds->indexes);
        free(ds);
        return NULL; // Memory allocation failed
    }

    pthread_mutex_init(&ds->lock, NULL);

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        ds->offsets[i] = rand() % 1000;
        ds->keys[i] = i;
        ds->records[i] = malloc(sizeof(record));
        if (!ds->records[i]) {
            // Handle partial allocation failure
            for (int j = 0; j < i; j++) {
                free(ds->records[j]);
            }
            pthread_mutex_destroy(&ds->lock);
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            free(ds->secondary_records);
            free(ds->indexes);
            free(ds);
            return NULL;
        }
        ds->records[i]->value = rand() % (high - low + 1) + low;
        ds->indexes[i] = -1; // Initialize all indexes to unused
    }

    for (int i = 0; i < RECORD_POOL_SIZE; i++) {
        ds->secondary_records[i] = malloc(sizeof(record));
        if (!ds->secondary_records[i]) {
            // Handle partial allocation failure
            for (int j = 0; j <= n; j++) {
                free(ds->records[j]);
            }
            for (int j = 0; j < RECORD_POOL_SIZE; j++) {
                free(ds->secondary_records[j]);
            }
            pthread_mutex_destroy(&ds->lock);
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            free(ds->secondary_records);
            free(ds->indexes);
            free(ds);
            return NULL;
        }
    }

    return ds;
}

