class PokemonTypeCache {
    private final Map<String, String> cache = new ConcurrentHashMap<>();
    private final long expirationTime = TimeUnit.HOURS.toMillis(2);

    public String get(String key, Callable<String> supplier) throws Exception {
        return cache.computeIfAbsent(key, k -> {
            try {
                String value = supplier.call();
                ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
                scheduler.schedule(() -> cache.remove(k), expirationTime, TimeUnit.MILLISECONDS);
                return value;
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }
}

