void fetch_weather_data(Pokemon *pokemon) {
    CURL *curl;
    CURLcode res;
    int retries = 0;

    do {
        curl = curl_easy_init();
        if(curl) {
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Accept: application/json");

            char url[256];
            snprintf(url, sizeof(url), "https://api.weatherapi.com/v1/current.json?key=YOUR_API_KEY&q=%s", pokemon->name);

            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);

            res = curl_easy_perform(curl);

            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            }

            curl_easy_cleanup(curl);
        }
    } while(res != CURLE_OK && retries++ < MAX_RETRIES);

    if(retries == MAX_RETRIES) {
        printf("Failed to fetch weather data after multiple attempts.\n");
    }
}

