        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

Record* createRecords(int numRecords, int seed, const char** stringList, int strCount) {
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(seed);
    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand();
        records[i].str = strdup(stringList[rand() % strCount]);
        records[i].value = ((double)rand()) / RAND_MAX;
    }

    return records;
}

void freeRecords(Record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i].str);
    }
    free(records);
}
