#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
} record;

// Custom memory allocator structure
typedef struct {
    void* pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} custom_allocator;

// Initialize the custom memory allocator
void init_custom_allocator(custom_allocator* alloc, size_t size) {
    alloc->pool = malloc(size);
    alloc->size = size;
    alloc->used = 0;
    pthread_mutex_init(&alloc->lock, NULL);
}

// Allocate memory from the custom memory allocator
void* custom_malloc(custom_allocator* alloc, size_t size) {
    pthread_mutex_lock(&alloc->lock);
    if (alloc->used + size > alloc->size) {
        printf("Out of memory\n");
        return NULL;
    }
    void* ptr = ((char*)alloc->pool) + alloc->used;
    alloc->used += size;
    pthread_mutex_unlock(&alloc->lock);
    return ptr;
}

// Free memory in the custom memory allocator
void custom_free(custom_allocator* alloc, void* ptr) {
    // No-op since we are using a fixed-size pool for simplicity
}

// Function to dynamically allocate and initialize data structures
int dynamic_allocation(int n, int m, int node_count, custom_allocator* offsets_alloc, custom_allocator* records_alloc) {
    long* offsets = (long*)custom_malloc(offsets_alloc, n * sizeof(long));
    if (!offsets) return -1;

    record* keys = (record*)custom_malloc(records_alloc, n * sizeof(record));
    if (!keys) {
        custom_free(offsets_alloc, offsets);
        return -1;
    }

    record* records = (record*)custom_malloc(records_alloc, m * sizeof(record));
    if (!records) {
        custom_free(records_alloc, keys);
        custom_free(offsets_alloc, offsets);
        return -1;
    }

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % 1000;
        keys[i].offset = rand() % 1000;
        keys[i].key = rand() % 1000;
    }

    // Initialize record array with random values
    for (int i = 0; i < m; i++) {
        records[i].offset = rand() % 1000;
        records[i].key = rand() % 1000;
    }

    // Initialize conflicting records and indexes
    record* conflicting_records = (record*)custom_malloc(records_alloc, node_count * sizeof(record));
    int* indexes = (int*)custom_malloc(records_alloc, node_count * sizeof(int));
    if (!conflicting_records || !indexes) {
        custom_free(records_alloc, records);
        custom_free(records_alloc, keys);
        custom_free(records_alloc, offsets);
        return -1;
    }

    // Clean up
    custom_free(records_alloc, conflicting_records);
    custom_free(records_alloc, indexes);

    return 0;
}

int main() {
    int n = 5;
    int m = 3;
    int node_count = 10;

    custom_allocator offsets_alloc;
    custom_allocator records_alloc;

    init_custom_allocator(&offsets_alloc, 1024 * sizeof(long));
    init_custom_allocator(&records_alloc, 1024 * sizeof(record));

    if (dynamic_allocation(n, m, node_count, &offsets_alloc, &records_alloc) != 0) {
        printf("Failed to allocate memory\n");
    }

    custom_free(&offsets_alloc, NULL);
    custom_free(&records_alloc, NULL);

    return 0;
}
