#define MAX_LINE_LENGTH 1024
#define CONFIG_FILE_PATH "config.txt"

typedef struct {
    char key[MAX_LINE_LENGTH];
    char value[MAX_LINE_LENGTH];
} ConfigSetting;

ConfigSetting config_settings[100]; // Assuming a maximum of 100 settings

int parse_config_file(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    int setting_count = 0;
    while (fgets(config_settings[setting_count].key, MAX_LINE_LENGTH, file)) {
        char *value = strchr(config_settings[setting_count].key, '=');
        if (!value) {
            fprintf(stderr, "Invalid entry in configuration file: %s", config_settings[setting_count].key);
            continue;
        }
        *value++ = '\0';
        strcpy(config_settings[setting_count].value, value);

        // Trim whitespace from key and value
        config_settings[setting_count].key[strcspn(config_settings[setting_count].key, " \t\n")] = 0;
        config_settings[setting_count].value[strcspn(config_settings[setting_count].value, " \t\n")] = 0;

        if (config_settings[setting_count].key[0] == '#') {
            // Skip comments
            setting_count--;
        }

        if (++setting_count >= 100) {
            fprintf(stderr, "Configuration file exceeds maximum settings limit");
            break;
        }
    }

    fclose(file);
    return setting_count;
}

void reload_config(const char *file_path) {
    int new_setting_count = parse_config_file(file_path);
    if (new_setting_count != -1) {
        printf("Configuration reloaded with %d new settings\n", new_setting_count);
        // Update or replace existing settings
    }
}

void *monitor_config(void *arg) {
    const char *file_path = arg;
    while (1) {
        sleep(5); // Check for changes every 5 seconds
        if (access(file_path, F_OK) == 0) {
            reload_config(file_path);
        } else {
            printf("Configuration file missing\n");
        }
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    int verbose = 0;
    const char *config_file = CONFIG_FILE_PATH;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-v] [-c custom_config_file]\n", argv[0]);
            return 0;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            config_file = argv[++i];
        }
    }

    int setting_count = parse_config_file(config_file);
    if (setting_count != -1) {
        printf("Loaded %d settings from configuration file\n", setting_count);

        pthread_t monitor_thread;
        pthread_create(&monitor_thread, NULL, monitor_config, (void *)config_file);
        pthread_detach(monitor_thread);

        // Main loop or further processing
        while (1) {
            sleep(1); // Placeholder for actual work
        }
    }

    return 0;
}
