        item->identifier = rand() % 1000 + 1;
        item->value = (double)item->identifier * 2.5; // Example calculation
        item_pointers[i] = item;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&lock);
        printf("Record %d: Cell ID - %d\n", i, records[i].cell_id);
        pthread_mutex_unlock(&lock);
    }

    free(records);
    free(float_array);
    free(status_array);

    for (int i = 0; i < num_records; i++) {
        free(item_pointers[i]);
    }
    free(item_pointers);

    pthread_mutex_destroy(&lock);

    return NULL;
}

int main() {
    allocate_and_populate_records(NUM_RECORDS);
    return 0;
}
