} NETWORK_EVENT_RECORD;

NETWORK_EVENT_RECORD *records[MAX_RECORDS];
pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

int add_record(const NETWORK_EVENT_RECORD *record) {
    pthread_mutex_lock(&records_mutex);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (records[i] == NULL) {
            records[i] = malloc(sizeof(NETWORK_EVENT_RECORD));
            if (records[i] == NULL) {
                pthread_mutex_unlock(&records_mutex);
                return -1;
            }
            *records[i] = *record;
            pthread_mutex_unlock(&records_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&records_mutex);
    return -1;
}

void free_records() {
    pthread_mutex_lock(&records_mutex);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
            records[i] = NULL;
