TX_PACKET_DATA_PDU_T** allocate_and_populate_packets(uint32_t min_payload_size, uint32_t max_payload_size, int *packet_count) {
    // Allocate memory for packet array
    TX_PACKET_DATA_PDU_T **packets = (TX_PACKET_DATA_PDU_T **)malloc(*packet_count * sizeof(TX_PACKET_DATA_PDU_T *));
