#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_PACKETS 10000
#define MIN_PAYLOAD_SIZE 1024
#define MAX_PAYLOAD_SIZE 10240

typedef enum {
    SUCCESS,
    FAILURE
} TRANSMISSION_STATUS;

typedef struct {
    int id;
    size_t payload_size;
    TRANSMISSION_STATUS status;
    pthread_mutex_t lock;
} PacketData;

PacketData packets[MAX_PACKETS];
int packet_count = 0;
pthread_mutex_t packet_lock;
pthread_cond_t packet_condition;

void initialize_packet_data() {
    srand(time(NULL));
    for (int i = 0; i < MAX_PACKETS; i++) {
        pthread_mutex_init(&packets[i].lock, NULL);
        packets[i].id = i + 1;
        packets[i].payload_size = MIN_PAYLOAD_SIZE + rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE);
        packets[i].status = FAILURE; // Assume all initially fail
    }
}

void* process_packet(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        pthread_mutex_lock(&packet_lock);
        while (packet_count == 0) {
            pthread_cond_wait(&packet_condition, &packet_lock);
        }

        int index = rand() % packet_count;
        if (packets[index].payload_size >= MIN_PAYLOAD_SIZE && packets[index].payload_size <= MAX_PAYLOAD_SIZE) {
            pthread_mutex_lock(&packets[index].lock);
            if (packets[index].status == FAILURE) {
                packets[index].status = SUCCESS;
                printf("Thread %d processed packet %d\n", thread_id, packets[index].id);
            }
            pthread_mutex_unlock(&packets[index].lock);
        }

        pthread_mutex_unlock(&packet_lock);
    }
}

int main() {
    initialize_packet_data();
    pthread_t threads[10];
    int thread_ids[10];

    for (int i = 0; i < 10; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, process_packet, &thread_ids[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

