} PacketMetadata;

typedef struct {
    PacketMetadata** nodes;
    int max_nodes;
    int current_nodes;
    pthread_mutex_t lock;
    FILE* log_file;
} CacheManager;

void init_cache_manager(CacheManager* manager, int max_nodes) {
    manager->nodes = (PacketMetadata**)malloc(max_nodes * sizeof(PacketMetadata*));
    for(int i = 0; i < max_nodes; i++) {
        manager->nodes[i] = NULL;
    }
    manager->max_nodes = max_nodes;
    manager->current_nodes = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen("cache_manager.log", "a");
}

void free_cache_manager(CacheManager* manager) {
    for(int i = 0; i < manager->max_nodes; i++) {
        if(manager->nodes[i] != NULL) {
            free(manager->nodes[i]->key);
            free(manager->nodes[i]);
        }
    }
    free(manager->nodes);
    pthread_mutex_destroy(&manager->lock);
    fclose(manager->log_file);
}

void log_event(CacheManager* manager, const char* message, int verbosity) {
    if(verbosity > 0) {
        fprintf(manager->log_file, "%s\n", message);
    }
}

PacketMetadata* create_packet_metadata(const char* key, size_t offset, size_t size) {
    PacketMetadata* metadata = (PacketMetadata*)malloc(sizeof(PacketMetadata));
    metadata->key = strdup(key);
    metadata->offset = offset;
    metadata->size = size;
    metadata->status = TRANSMISSION_SUCCESS;
    metadata->transmission_flag = rand() % 2 ? TRANSMISSION_SUCCESS : TRANSMISSION_FAILURE;
    return metadata;
}

void add_packet_metadata(CacheManager* manager, PacketMetadata* metadata) {
    pthread_mutex_lock(&manager->lock);
    if(manager->current_nodes < manager->max_nodes) {
        manager->nodes[manager->current_nodes++] = metadata;
    }
    pthread_mutex_unlock(&manager->lock);
}

void remove_packet_metadata(CacheManager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);
    if(index >= 0 && index < manager->current_nodes) {
        free(manager->nodes[index]->key);
        free(manager->nodes[index]);
        for(int i = index; i < manager->current_nodes - 1; i++) {
            manager->nodes[i] = manager->nodes[i + 1];
        }
        manager->current_nodes--;
    }
    pthread_mutex_unlock(&manager->lock);
}

void compress_data(CacheManager* manager) {
    // Implement compression logic here
}

void decompress_data(CacheManager* manager) {
    // Implement decompression logic here
}

