    init_cache_manager(&cache_manager, MAX_NODES);

    PacketMetadata* metadata = create_packet_metadata("example_key", 0, 128);
    add_packet_metadata(&cache_manager, metadata);

    remove_packet_metadata(&cache_manager, 0);

    free_cache_manager(&cache_manager);

    return 0;
}
