typedef struct {
    int SESSION_ID;
    time_t START_TIME;
    time_t END_TIME;
} CONNECTION_STATS;

typedef struct {
    int SESSION_ID;
    time_t START_TIME;
    time_t END_TIME;
    CONNECTION_STATS *CONNECTION_STATS;
} NETWORK_SESSION_RECORD;

NETWORK_SESSION_RECORD* create_network_session_records(int num_records, int max_id) {
    if (num_records <= 0 || max_id <= 0) {
        return NULL;
    }

    NETWORK_SESSION_RECORD* records = (NETWORK_SESSION_RECORD*)malloc(num_records * sizeof(NETWORK_SESSION_RECORD));
    if (records == NULL) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        int unique_id;
        do {
            unique_id = rand() % max_id + 1;
        } while (is_id_taken(records, i, unique_id));

        records[i].SESSION_ID = unique_id;
        records[i].START_TIME = time(NULL);
        records[i].END_TIME = records[i].START_TIME + rand() % 3600; // Random duration between 0 and 1 hour

        int num_stats = 5; // Example: 5 connection stats per session
        CONNECTION_STATS* stats = (CONNECTION_STATS*)malloc(num_stats * sizeof(CONNECTION_STATS));
        if (stats == NULL) {
            free(records);
            return NULL;
        }

        for (int j = 0; j < num_stats; ++j) {
            stats[j].LATENCY = rand() % 100 + 1; // Random latency between 1 and 100 ms
            stats[j].PACKLOSS = rand() % 101; // Random packet loss percentage between 0 and 100%
        }

        records[i].CONNECTION_STATS = stats;
    }

    return records;
}

bool is_id_taken(NETWORK_SESSION_RECORD* records, int index, int id) {
    for (int i = 0; i < index; ++i) {
        if (records[i].SESSION_ID == id) {
            return true;
        }
    }
    return false;
}
