#define MAX_USER_ID_LENGTH 50
#define MAX_ACTIVITY_LOGS 100

typedef struct USER_PROFILE {
    char user_id[MAX_USER_ID_LENGTH];
    time_t creation_date;
    time_t last_login;
    struct ACTIVITY_LOG {
        time_t timestamp;
        char event_type[50];
    } activity_logs[MAX_ACTIVITY_LOGS];
    int log_count;
} USER_PROFILE;

typedef struct NODE {
    USER_PROFILE profile;
    struct NODE *next;
} NODE;

NODE* create_user_profile_node(const char *user_id) {
    NODE *new_node = (NODE *)malloc(sizeof(NODE));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strncpy(new_node->profile.user_id, user_id, MAX_USER_ID_LENGTH);
    new_node->profile.creation_date = time(NULL);
    new_node->profile.last_login = 0;
    new_node->profile.log_count = 0;
    new_node->next = NULL;
    return new_node;
}

int add_activity_log(NODE *node, const char *event_type) {
    if (node == NULL || node->profile.log_count >= MAX_ACTIVITY_LOGS) {
        return -1; // Log addition failed
    }
    time_t current_time = time(NULL);
    strncpy(node->profile.activity_logs[node->profile.log_count].event_type, event_type, 50);
    node->profile.activity_logs[node->profile.log_count].timestamp = current_time;
    node->profile.log_count++;
    return 0; // Log added successfully
}

void update_last_login(NODE *node) {
    if (node != NULL) {
        node->profile.last_login = time(NULL);
    }
}

NODE* find_user_profile_by_id(NODE *head, const char *user_id) {
    NODE *current = head;
    while (current != NULL) {
        if (strcmp(current->profile.user_id, user_id) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL; // User not found
}

void free_user_profile_list(NODE *head) {
    NODE *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
