    int priority;
    char message[256];
} Event;

typedef struct {
    Event* events;
    size_t capacity;
    size_t count;
    int maxTimestamp;
    int minTimestamp;
    size_t maxSizeThreshold;
} EventCollection;

EventCollection* create_event_collection(int initialCapacity, int maxTimestamp, int minTimestamp, size_t maxSizeThreshold) {
    EventCollection* collection = (EventCollection*)malloc(sizeof(EventCollection));
    if (!collection) return NULL;

    collection->events = (Event*)malloc(initialCapacity * sizeof(Event));
    if (!collection->events) {
        free(collection);
        return NULL;
    }

    collection->capacity = initialCapacity;
    collection->count = 0;
    collection->maxTimestamp = maxTimestamp;
    collection->minTimestamp = minTimestamp;
    collection->maxSizeThreshold = maxSizeThreshold;

    return collection;
}

int add_event(EventCollection* collection, Event newEvent) {
    if (collection->count >= collection->capacity || newEvent.timestamp > collection->maxTimestamp || newEvent.timestamp < collection->minTimestamp) {
        // Handle error: event cannot be added due to capacity or timestamp range
        return -1;
    }

    if ((collection->count + 1) * sizeof(Event) > collection->maxSizeThreshold) {
        // Resize the collection
        Event* newEvents = (Event*)realloc(collection->events, (collection->capacity + 1) * sizeof(Event));
        if (!newEvents) return -1;

        collection->events = newEvents;
        collection->capacity++;
    }

    collection->events[collection->count++] = newEvent;
    return 0;
}

void iterate_events_reverse(EventCollection* collection, void (*callback)(Event*)) {
    for (size_t i = collection->count; i > 0; i--) {
        callback(collection->events[i - 1]);
    }
}

void destroy_event_collection(EventCollection* collection) {
    free(collection->events);
    free(collection);
}
