} LogCollection;

LogCollection* create_log_collection(size_t max_size) {
    LogCollection* collection = (LogCollection*)malloc(sizeof(LogCollection));
    collection->entries = (LogEntry*)calloc(INITIAL_CAPACITY, sizeof(LogEntry));
    collection->count = 0;
    collection->capacity = INITIAL_CAPACITY;
    collection->max_size = max_size;
    return collection;
}

void destroy_log_collection(LogCollection* collection) {
    free(collection->entries);
    free(collection);
}

int add_log_entry(LogCollection* collection, time_t timestamp, const char* source, LogLevel severity, const char* message) {
    if (collection->count >= collection->capacity || total_size(collection) + sizeof(LogEntry) > collection->max_size) {
        // Resize the collection
        size_t new_capacity = collection->capacity * 2;
        LogEntry* new_entries = (LogEntry*)realloc(collection->entries, new_capacity * sizeof(LogEntry));
        if (!new_entries) return -1; // Memory allocation failed
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }
    if (timestamp < time(NULL) - 24 * 60 * 60 || timestamp > time(NULL)) return -2; // Timestamp out of range

    LogEntry* entry = &collection->entries[collection->count++];
    entry->timestamp = timestamp;
    strncpy(entry->source, source, sizeof(entry->source));
    entry->severity = severity;
    strncpy(entry->message, message, sizeof(entry->message));
    return 0;
}

size_t total_size(LogCollection* collection) {
    size_t size = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        size += sizeof(LogEntry);
    }
    return size;
}

void iterate_reverseChrono(LogCollection* collection, void (*callback)(LogEntry*)) {
    for (int i = collection->count - 1; i >= 0; --i) {
        callback(&collection->entries[i]);
    }
}

void filter_logs_by_sourceAndSeverity(LogCollection* collection, const char* source, LogLevel severity, void (*callback)(LogEntry*)) {
    for (size_t i = 0; i < collection->count; ++i) {
        LogEntry* entry = &collection->entries[i];
        if (strcmp(entry->source, source) == 0 && entry->severity >= severity) {
            callback(entry);
        }
    }
}

void set_logging_level(LogLevel level) {
    // Implementation of setting logging level
}

