#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <dlfcn.h>

// Define a struct to hold information about each algorithm
typedef struct {
    char name[256];
    void (*implementation)();
    void* init_params;
} AlgorithmInfo;

// Function to dynamically load and check for available algorithms
AlgorithmInfo** get_available_algorithms(size_t* count) {
    DIR* dir;
    struct dirent* ent;
    AlgorithmInfo** algorithms = NULL;
    size_t algo_count = 0;

    // Open the directory containing cryptographic libraries (e.g., /usr/lib/crypto)
    if ((dir = opendir("/usr/lib/crypto")) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

            // Construct the full path to the library
            char lib_path[512];
            snprintf(lib_path, sizeof(lib_path), "/usr/lib/crypto/%s", ent->d_name);

            // Open the shared library
            void* handle = dlopen(lib_path, RTLD_LAZY);
            if (handle == NULL) continue;

            // Get function pointers and check for availability
            void (*func)();
            func = (void (*)())dlsym(handle, "algorithm_function");
            if (func != NULL) {
                // Allocate memory for the algorithm information
                AlgorithmInfo* algo = malloc(sizeof(AlgorithmInfo));
                snprintf(algo->name, sizeof(algo->name), "%s", ent->d_name);
                algo->implementation = func;
                algo->init_params = NULL; // Initialize parameters as needed

                // Add the algorithm to the list
                algorithms = realloc(algorithms, (algo_count + 1) * sizeof(AlgorithmInfo*));
                algorithms[algo_count++] = algo;
            }

            // Close the library
            dlclose(handle);
        }

        closedir(dir);
    }

    // Return the list of available algorithms and their count
    *count = algo_count;
    return algorithms;
}

// Example usage of the function
int main() {
    size_t algo_count;
    AlgorithmInfo** algorithms = get_available_algorithms(&algo_count);

    if (algorithms == NULL) {
        printf("No algorithms found.\n");
        return 1;
    }

    // Print the available algorithms
    for (size_t i = 0; i < algo_count; i++) {
        printf("Algorithm: %s\n", algorithms[i]->name);
    }

    // Clean up allocated memory
    for (size_t i = 0; i < algo_count; i++) {
        free(algorithms[i]);
    }
    free(algorithms);

    return 0;
}
