#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_NODES 1024

typedef enum {
    SUCCESS,
    FAILURE
} TRANSMISSION_STATUS;

typedef struct {
    char* key;
    size_t offset;
    size_t length;
    TRANSMISSION_STATUS status;
} CacheNode;

CacheNode cache[MAX_NODES];
int node_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_cache() {
    for (int i = 0; i < MAX_NODES; i++) {
        cache[i].key = NULL;
        cache[i].offset = 0;
        cache[i].length = 0;
        cache[i].status = FAILURE;
    }
}

void* process_packet(void* arg) {
    int node_index = *(int*)arg;
    pthread_mutex_lock(&cache_lock);
    if (node_index >= 0 && node_index < MAX_NODES) {
        CacheNode* node = &cache[node_index];
        // Simulate packet processing
        node->status = (rand() % 2 == 0) ? SUCCESS : FAILURE;
        printf("Processed packet with key: %s, status: %s\n", node->key, node->status == SUCCESS ? "SUCCESS" : "FAILURE");
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void configure_cache(int max_nodes) {
    if (max_nodes > 0 && max_nodes <= MAX_NODES) {
        pthread_mutex_lock(&cache_lock);
        node_count = max_nodes;
        pthread_mutex_unlock(&cache_lock);
    } else {
        printf("Invalid max_nodes value: %d\n", max_nodes);
    }
}

int main() {
    srand(time(NULL));
    initialize_cache();
    configure_cache(10);

    int node_indices[MAX_NODES];
    for (int i = 0; i < node_count; i++) {
        cache[i].key = strdup("packet_key");
        pthread_create(&cache[i].offset, NULL, process_packet, &node_indices[i]);
    }

    for (int i = 0; i < node_count; i++) {
        pthread_join(cache[i].offset, NULL);
    }

    return 0;
}
