#include <stdlib.h>
#include <stdio.h>

#define MAX_DIM 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryBlock {
    void* data;
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

typedef struct MemoryPool {
    MemoryBlock* freeList;
    size_t blockSize;
    size_t alignment;
    void* poolStart;
    size_t poolSize;
    int blockCount;
} MemoryPool;

MemoryPool pools[MAX_DIM];
int poolCount = 0;

void init_memory_pool(size_t blockSize, size_t alignment, size_t poolSize) {
    if (poolCount >= MAX_DIM) return; // Limit to avoid overflow
    MemoryPool* pool = &pools[poolCount++];
    pool->blockSize = blockSize;
    pool->alignment = alignment;
    pool->poolStart = malloc(poolSize);
    pool->poolSize = poolSize;
    pool->freeList = (MemoryBlock*)(((size_t)pool->poolStart + alignment - 1) & ~(alignment - 1));
    pool->blockCount = poolSize / blockSize;
    MemoryBlock* block = pool->freeList;
    for (int i = 0; i < pool->blockCount - 1; ++i) {
        block->data = (void*)((char*)block + blockSize);
        block->size = blockSize;
        block->next = (MemoryBlock*)((char*)block->data + alignment);
        block = block->next;
    }
    block->data = NULL;
    block->size = 0;
    block->next = NULL;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (!pool || !pool->freeList) return NULL; // No memory available
    void* data = pool->freeList->data;
    MemoryBlock* oldFreeList = pool->freeList;
    pool->freeList = oldFreeList->next;
    oldFreeList->next = NULL;
    return data;
}

void deallocate_to_pool(MemoryPool* pool, void* data) {
    if (!pool || !data) return; // No data to deallocate
    MemoryBlock* block = (MemoryBlock*)((char*)data - offsetof(MemoryBlock, data));
    block->next = pool->freeList;
    pool->freeList = block;
}

NFAPI_CRC_INDICATION_PDU_T** allocate_multi_dimensional_array(int dimensions, int sizes[], size_t alignment) {
    if (dimensions <= 0 || dimensions > MAX_DIM) return NULL; // Invalid dimensions
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)allocate_from_pool(&pools[0]);
    if (!array) return NULL;
    for (int i = 1; i <= dimensions; ++i) {
        void* data = allocate_from_pool(&pools[i]);
        if (!data) {
            deallocate_to_pool(&pools[0], array);
            for (int j = 1; j < i; ++j) deallocate_to_pool(&pools[j], ((char*)array + sizes[0] * sizeof(NFAPI_CRC_INDICATION_PDU_T*)) / sizeof(void*));
            return NULL;
        }
        array[i - 1] = (NFAPI_CRC_INDICATION_PDU_T*)data;
    }
    for (int i = 0; i < dimensions; ++i) {
        NFAPI_CRC_INDICATION_PDU_T** subarray = array + i * sizes[i];
        for (int j = 0; j < sizes[i]; ++j) {
            NFAPI_CRC_INDICATION_PDU_T* element = allocate_from_pool(&pools[dimensions]);
            if (!element) {
                deallocate_to_pool(&pools[0], array);
                for (int k = i - 1; k >= 0; --k) {
                    NFAPI_CRC_INDICATION_PDU_T** subarray = array + k * sizes[k];
                    for (int l = 0; l < sizes[k]; ++l) deallocate_to_pool(&pools[dimensions], subarray[l]);
                }
                return NULL;
            }
            subarray[j] = element;
        }
    }
    return array;
}

void free_multi_dimensional_array(NFAPI_CRC_INDICATION_PDU_T** array, int dimensions, int sizes[]) {
    if (!array) return; // Nothing to free
    for (int i = 0; i < dimensions; ++i) {
        NFAPI_CRC_INDICATION_PDU_T** subarray = array + i * sizes[i];
        for (int j = 0; j < sizes[i]; ++j) deallocate_to_pool(&pools[dimensions], subarray[j]);
    }
    for (int i = 1; i <= dimensions; ++i) deallocate_to_pool(&pools[i], array[i - 1]);
    deallocate_to_pool(&pools[0], array);
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T** array, int dimensions, int sizes[]) {
    for (int i = 0; i < dimensions; ++i) {
        NFAPI_CRC_INDICATION_PDU_T** subarray = array + i * sizes[i];
        for (int j = 0; j < sizes[i]; ++j) {
            NFAPI_CRC_INDICATION_PDU_T* element = subarray[j];
            // Populate element with random values and valid RX_UE_INFORMATION_TAG
            element->RX_UE_INFORMATION_TAG = rand() % 1000;
            element->RNTI = rand() % 65536;
            element->CRC_INDICATION_REL8_TAG = rand() % 256;
            element->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        }
    }
}

int main() {
    int dimensions = 2;
    int sizes[dimensions] = {10, 20};
    size_t alignment = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    init_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), alignment, 10 * 20 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_CRC_INDICATION_PDU_T** array = allocate_multi_dimensional_array(dimensions, sizes, alignment);
    if (array) {
        populate_array(array, dimensions, sizes);
        free_multi_dimensional_array(array, dimensions, sizes);
    }
    return 0;
}
