#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryBlock {
    void* data;
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

typedef struct MemoryPool {
    MemoryBlock* freeList;
    size_t blockSize;
    size_t poolSize;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize, size_t poolSize) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->freeList = NULL;
    pool->blockSize = blockSize;
    pool->poolSize = poolSize;
    for (size_t i = 0; i < poolSize; ++i) {
        MemoryBlock* block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
        if (!block) {
            destroyMemoryPool(pool);
            return NULL;
        }
        block->data = malloc(blockSize);
        if (!block->data) {
            free(block);
            destroyMemoryPool(pool);
            return NULL;
        }
        block->size = blockSize;
        block->next = pool->freeList;
        pool->freeList = block;
    }
    return pool;
}

void destroyMemoryPool(MemoryPool* pool) {
    MemoryBlock* current = pool->freeList;
    while (current) {
        free(current->data);
        MemoryBlock* next = current->next;
        free(current);
        current = next;
    }
    free(pool);
}

void* allocateFromPool(MemoryPool* pool) {
    if (!pool || !pool->freeList) return NULL;
    MemoryBlock* block = pool->freeList;
    pool->freeList = block->next;
    return block->data;
}

void deallocateToPool(MemoryPool* pool, void* ptr) {
    if (!pool || !ptr) return;
    MemoryBlock* block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    if (!block) return;
    block->data = ptr;
    block->size = pool->blockSize;
    block->next = pool->freeList;
    pool->freeList = block;
}

NFAPI_CRC_INDICATION_PDU_T** createAndPopulateArray(size_t* dimensions, size_t dimensionCount, MemoryPool* pool) {
    if (!dimensions || !dimensionCount || !pool) return NULL;
    NFAPI_CRC_INDICATION_PDU_T*** array = (NFAPI_CRC_INDICATION_PDU_T***)allocateFromPool(pool);
    if (!array) return NULL;

    for (size_t i = 0; i < dimensionCount; ++i) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T**)allocateFromPool(pool);
        if (!array[i]) {
            destroyArray(array, dimensions, dimensionCount - 1, pool);
            return NULL;
        }
    }

    for (size_t i = 0; i < dimensions[dimensionCount - 1]; ++i) {
        array[dimensionCount - 1][i] = (NFAPI_CRC_INDICATION_PDU_T*)allocateFromPool(pool);
        if (!array[dimensionCount - 1][i]) {
            destroyArray(array, dimensions, dimensionCount, pool);
            return NULL;
        }
    }

    // Populate array with random data and validate RX_UE_INFORMATION_TAG
    for (size_t i = 0; i < dimensions[dimensionCount - 1]; ++i) {
