#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct VersionedHistory {
    ListNode* head;
    struct VersionedHistory* previousVersion;
} VersionedHistory;

VersionedHistory* createVersionedHistory() {
    VersionedHistory* history = (VersionedHistory*)malloc(sizeof(VersionedHistory));
    if (!history) {
        return NULL; // Memory allocation failed
    }
    history->head = NULL;
    history->previousVersion = NULL;
    return history;
}

void freeList(ListNode* head) {
    while (head) {
        ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

void freeVersionedHistory(VersionedHistory* history) {
    freeList(history->head);
    if (history->previousVersion) {
        freeVersionedHistory(history->previousVersion);
    }
    free(history);
}

int randomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void addRandomItemToList(ListNode** head, VersionedHistory* history) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        freeVersionedHistory(history);
        exit(1); // Memory allocation failed
    }
    newNode->data.RX_UE_INFORMATION_TAG = randomInt(0, 100);
    newNode->data.RNTI = randomInt(1, 1000);
    newNode->data.CRC_INDICATION_REL8_TAG = randomInt(0, 1);
    newNode->data.CRCFLAG = randomInt(0, 1);
    newNode->next = *head;
    *head = newNode;
}

void filterList(ListNode** head, int minRNTI, int maxRNTI) {
    ListNode* current = *head;
    ListNode* prev = NULL;

    while (current) {
        if (current->data.RNTI < minRNTI || current->data.RNTI > maxRNTI) {
            ListNode* temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

ListNode* getPreviousVersion(VersionedHistory* history, int versionNumber) {
    VersionedHistory* current = history;
    for (int i = 0; i < versionNumber; i++) {
        if (!current->previousVersion) {
            return NULL; // Requested version number is out of bounds
        }
        current = current->previousVersion;
    }
    return current->head;
}

void saveCurrentState(VersionedHistory* history) {
    VersionedHistory* newVersion = createVersionedHistory();
    ListNode* current = history->head;
    while (current) {
        ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
        if (!newNode) {
            freeVersionedHistory(newVersion);
            return; // Memory allocation failed
        }
        newNode->data = current->data;
        newNode->next = newVersion->head;
        newVersion->head = newNode;
        current = current->next;
    }
    newVersion->previousVersion = history;
    *history = *newVersion;
}

void addRandomItemsToHistory(VersionedHistory* history, int numItems) {
    for (int i = 0; i < numItems; i++) {
        saveCurrentState(history);
        addRandomItemToList(&history->head, history);
    }
}
