LTE_NAS_Message_T* initialize_and_populate_messages(int *num_messages, pthread_mutex_t *mutex) {
    // Simulated network load and available resources
    static int current_load = 0;
    static int max_load = 100;

    LTE_NAS_Message_T *messages = (LTE_NAS_Message_T *)malloc(*num_messages * sizeof(LTE_NAS_Message_T));
    if (!messages) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_lock(mutex);
    for (int i = 0; i < *num_messages; ++i) {
        messages[i].type = NAS_PDU_TYPE_ATTACH;
        messages[i].EPS_BEARER_ID = rand() % 10 + 1; // Random bearer ID from 1 to 10
        current_load += messages[i].EPS_BEARER_ID;
    }
    pthread_mutex_unlock(mutex);

    if (current_load > max_load) {
        // Handle network load exceeding maximum threshold
        for (int i = *num_messages - 1; i >= 0; --i) {
            free(&messages[i]);
        }
        free(messages);
        return NULL;
    }

    return messages;
}

Bearer_Information_T* select_bearer(LTE_NAS_Message_T *messages, int num_messages, int *selected_bearer_id) {
