    if (!bearers) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_messages; ++i) {
        bearers[i].bearerID = messages[i].EPS_BEARER_ID;
        bearers[i].priorityLevel = rand() % 3 + 1; // Random priority level from 1 to 3
        bearers[i].activeConnections = rand() % 5 + 1; // Random active connections from 0 to 4
    }

    int max_priority = -1;
    for (int i = 0; i < num_messages; ++i) {
        if (bearers[i].priorityLevel > max_priority || 
            (bearers[i].priorityLevel == max_priority && bearers[i].activeConnections < bearers[*selected_bearer_id].activeConnections)) {
            *selected_bearer_id = i;
            max_priority = bearers[i].priorityLevel;
        }
    }

    return bearers;
}
