typedef struct NFAPI_CRC_INDICATION_PDU_T {
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
    int RNTI;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_new_crc_indication(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    new_pdu->RNTI = RNTI;
    new_pdu->timestamp = time(NULL);
    new_pdu->prev = NULL;
    new_pdu->next = NULL;
    return new_pdu;
}

NFAPI_CRC_INDICATION_PDU_T* add_crc_indication(NFAPI_CRC_INDICATION_PDU_T** head, int RNTI) {
    if (*head == NULL || (*head)->RNTI > RNTI) {
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = create_new_crc_indication(RNTI);
        if (new_pdu != NULL) {
            new_pdu->next = *head;
            if (*head != NULL) {
                (*head)->prev = new_pdu;
            }
            *head = new_pdu;
        }
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head;
        while (current->next != NULL && current->next->RNTI < RNTI) {
            current = current->next;
        }
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = create_new_crc_indication(RNTI);
        if (new_pdu != NULL) {
            new_pdu->prev = current;
            new_pdu->next = current->next;
            if (current->next != NULL) {
                current->next->prev = new_pdu;
            }
            current->next = new_pdu;
        }
    }
    return *head;
}

NFAPI_CRC_INDICATION_PDU_T* find_crc_indication(NFAPI_CRC_INDICATION_PDU_T* head, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL && current->RNTI < RNTI) {
        current = current->next;
    }
    if (current != NULL && current->RNTI == RNTI) {
        return current;
    } else {
        return NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* delete_crc_indication(NFAPI_CRC_INDICATION_PDU_T** head, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* to_delete = find_crc_indication(*head, RNTI);
    if (to_delete != NULL) {
        if (to_delete->prev != NULL) {
            to_delete->prev->next = to_delete->next;
        } else {
            *head = to_delete->next;
        }
        if (to_delete->next != NULL) {
            to_delete->next->prev = to_delete->prev;
        }
        free(to_delete);
    }
    return *head;
}

void print_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        printf("RNTI: %d, Timestamp: %ld\n", current->RNTI, current->timestamp);
        current = current->next;
    }
}
