        return NULL;
    }
    if (!list->head) {
        list->head = new_pdu;
        list->tail = new_pdu;
    } else {
        list->tail->next = new_pdu;
        new_pdu->prev = list->tail;
        list->tail = new_pdu;
    }
    list->size++;
    log_operation(list, "CRC PDU inserted");
