}

Record** allocateRecords(int m) {
    return (Record**)malloc(m * sizeof(Record*));
}

void initializeRecords(Record** records, int m, int low, int high) {
    for (int i = 0; i < m; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        records[i]->value = low + rand() % (high - low + 1);
    }
}

void handleConflicts(Record** records, Record** secondaryRecords, int* indexes, int m) {
    for (int i = 0; i < m; i++) {
        if (indexes[records[i]->value] != i) {
            secondaryRecords[indexes[records[i]->value]] = records[i];
            records[i] = NULL;
        }
    }
}

void freeMemory(Record** records, Record** secondaryRecords, int* offsets, int* keys, int m) {
    for (int i = 0; i < m; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }
    for (int i = 0; i < m; i++) {
        if (secondaryRecords[i]) {
            free(secondaryRecords[i]);
        }
    }
    free(offsets);
    free(keys);
    free(*records);
    free(*secondaryRecords);
}

