    Record** records = allocateRecords(m);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    Record** secondaryRecords = allocateRecords(m);
    if (!secondaryRecords) {
        free(records);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    int* offsets = allocateOffsets(n);
    if (!offsets) {
        free(records);
        free(secondaryRecords);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    int* keys = allocateKeys(n);
    if (!keys) {
        free(records);
        free(secondaryRecords);
        free(offsets);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));
    initializeRecords(records, m, low, high);

    int* indexes = (int*)calloc(m, sizeof(int));
    if (!indexes) {
        free(records);
        free(secondaryRecords);
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < m; i++) {
        indexes[records[i]->value] = i;
    }

    handleConflicts(records, secondaryRecords, indexes, m);

    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % m;
    }

    for (int i = 0; i < n; i++) {
        keys[i] = rand() % m;
    }

    return records;
}
