#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

long* allocate_offsets(int n) {
    long* offsets = (long*)malloc(n * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(1);
    }
    return offsets;
}

int* allocate_keys(int n) {
    int* keys = (int*)malloc(n * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        exit(1);
    }
    return keys;
}

record* allocate_records(int m) {
    record* records = (record*)malloc(m * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(1);
    }
    return records;
}

record** allocate_conflict_records(int m) {
    record** conflict_records = (record**)malloc(m * sizeof(record*));
    if (conflict_records == NULL) {
        fprintf(stderr, "Memory allocation failed for conflict records\n");
        exit(1);
    }
    for (int i = 0; i < m; i++) {
        conflict_records[i] = NULL;
    }
    return conflict_records;
}

int* allocate_indexes(int n) {
    int* indexes = (int*)malloc(n * sizeof(int));
    if (indexes == NULL) {
        fprintf(stderr, "Memory allocation failed for indexes\n");
        exit(1);
    }
    for (int i = 0; i < n; i++) {
        indexes[i] = -1;
    }
    return indexes;
}

void initialize_records(record* records, int m, int low, int high) {
    srand(time(NULL));
    for (int i = 0; i < m; i++) {
        int value = rand() % (high - low + 1) + low;
        records[i].value = value;
    }
}

void resolve_conflicts(record* records, record** conflict_records, int* indexes, int n, int m) {
    for (int i = 0; i < m; i++) {
        int key = records[i].value % n;
        if (indexes[key] == -1) {
            indexes[key] = i;
        } else {
            record** conflict_records = allocate_conflict_records(m);
            conflict_records[indexes[key]] = &records[i];
            free(records);
            records = allocate_records(m);
            initialize_records(records, m, low, high);
            resolve_conflicts(records, conflict_records, indexes, n, m);
            break;
        }
    }
}

int* create_indexes(int n) {
    int* indexes = (int*)malloc(n * sizeof(int));
    if (indexes == NULL) {
        fprintf(stderr, "Memory allocation failed for indexes\n");
        exit(1);
    }
    for (int i = 0; i < n; i++) {
        indexes[i] = -1;
    }
    return indexes;
}

record* initialize_data_structures(int n, int m, int low, int high) {
    if (n <= 0 || m <= 0) {
        fprintf(stderr, "Invalid input: n and m must be positive integers\n");
        exit(1);
    }

    long* offsets = allocate_offsets(n);
    int* keys = allocate_keys(n);
    record* records = allocate_records(m);
    record** conflict_records = allocate_conflict_records(m);
    int* indexes = create_indexes(n);

    initialize_records(records, m, low, high);
    resolve_conflicts(records, conflict_records, indexes, n, m);

    return records;
}
