    return node;
}

void free_data_record_node(DATA_RECORD_NODE_T* node) {
    if (!node) return;

    pthread_mutex_lock(&node->lock);

    while (node->segments) {
        DATA_SEGMENT_T* temp = node->segments;
        node->segments = node->segments->next;
        free(temp->data);
        free(temp);
    }

    pthread_mutex_unlock(&node->lock);
    pthread_mutex_destroy(&node->lock);
    free(node);
}

void add_data_segment(DATA_RECORD_NODE_T* node, void* data, size_t length) {
    if (!node || !data || !length) return;

    pthread_mutex_lock(&node->lock);

    if (node->segment_count >= node->segment_capacity) {
        size_t new_capacity = node->segment_capacity ? node->segment_capacity * 2 : 16;
        DATA_SEGMENT_T** new_segments = realloc(node->segments, sizeof(DATA_SEGMENT_T*) * new_capacity);
        if (!new_segments) {
            pthread_mutex_unlock(&node->lock);
            return;
        }
        node->segments = new_segments;
        node->segment_capacity = new_capacity;
    }

    DATA_SEGMENT_T* segment = (DATA_SEGMENT_T*)malloc(sizeof(DATA_SEGMENT_T));
    if (!segment) {
        pthread_mutex_unlock(&node->lock);
        return;
    }

    segment->data = malloc(length);
    if (!segment->data) {
        free(segment);
        pthread_mutex_unlock(&node->lock);
        return;
    }

    memcpy(segment->data, data, length);
    segment->length = length;
    segment->next = NULL;

    node->segments[node->segment_count] = segment;
    node->segment_count++;

    pthread_mutex_unlock(&node->lock);
}

void process_data_record_node(DATA_RECORD_NODE_T* node) {
    if (!node) return;

    pthread_mutex_lock(&node->lock);

    // Process the data record here
    for (size_t i = 0; i < node->segment_count; i++) {
        DATA_SEGMENT_T* segment = node->segments[i];
        // Process each segment's data
    }

    pthread_mutex_unlock(&node->lock);
}
