// Define the node structure for the dynamic tree
typedef struct TreeNode {
    double value;
    struct TreeNode *parent, *child, *sibling;
} TreeNode;

// Function to create and initialize a dynamic tree
TreeNode* create_tree(double root_value) {
    TreeNode *root = (TreeNode *)malloc(sizeof(TreeNode));
    root->value = root_value;
    root->parent = NULL;
    root->child = NULL;
    root->sibling = NULL;
    return root;
}

// Function to traverse the tree in pre-order
void pre_order_traversal(TreeNode *node) {
    if (node != NULL) {
        printf("%f ", node->value);
        pre_order_traversal(node->child);
        pre_order_traversal(node->sibling);
    }
}

// Function to perform in-order traversal
void in_order_traversal(TreeNode *node) {
    if (node != NULL) {
        in_order_traversal(node->child);
        printf("%f ", node->value);
        in_order_traversal(node->sibling);
    }
}

// Function to perform post-order traversal
void post_order_traversal(TreeNode *node) {
    if (node != NULL) {
        post_order_traversal(node->child);
        post_order_traversal(node->sibling);
        printf("%f ", node->value);
    }
}

// Function to search for a specific value in the tree
TreeNode* search_tree(TreeNode *node, double target) {
    if (node == NULL) return NULL;
    if (node->value == target) return node;
    TreeNode *child = search_tree(node->child, target);
    if (child != NULL) return child;
    return search_tree(node->sibling, target);
}

// Function to insert a new node into the tree
void insert_node(TreeNode *parent, double value) {
    TreeNode *new_node = create_tree(value);
    new_node->parent = parent;
    new_node->child = parent->child;
    parent->child = new_node;
}

// Function to delete a node from the tree
void delete_node(TreeNode *node) {
    if (node == NULL) return;

    // Remove node from its parent's child list
    if (node->parent != NULL) {
        if (node->parent->child == node) {
            node->parent->child = node->sibling;
        } else {
            TreeNode *current = node->parent->child;
            while (current->sibling != node) {
                current = current->sibling;
            }
            current->sibling = node->sibling;
        }
    }

    // Free the memory
    free(node);
}

int main(int argc, char *argv[]) {
    initialize_data(argc, argv);

    TreeNode *root = create_tree(0.5);
    insert_node(root, 1.2);
    insert_node(root, -0.8);
    insert_node(root->child, 3.4);

    printf("Pre-order traversal: ");
    pre_order_traversal(root);
    printf("\n");

    printf("In-order traversal: ");
    in_order_traversal(root);
    printf("\n");

    printf("Post-order traversal: ");
    post_order_traversal(root);
    printf("\n");

    TreeNode *found_node = search_tree(root, 1.2);
    if (found_node) {
        printf("Found node with value: %f\n", found_node->value);
    } else {
        printf("Node not found.\n");
    }

    delete_node(found_node);

    return 0;
}
```

This code block demonstrates the implementation of a simple linked list and a basic tree structure in C, along with functions to initialize data, traverse the tree, search for values, insert new nodes, and delete existing nodes. The `initialize_data` function handles command-line arguments, file reading, and dynamic memory allocation for arrays and linked lists. The `create_tree` function sets up a dynamic tree structure, and various traversal and manipulation functions are provided to interact with the tree.']

