typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_NUM_STRUCTURES];
    int count;
    pthread_mutex_t mutex;
} ArrayManager;

ArrayManager* createArrayManager() {
    ArrayManager* manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    if (!manager) {
        return NULL; // Handle memory allocation failure
    }
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroyArrayManager(ArrayManager* manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->array[i]);
    }
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int insertStructure(ArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T* newStruct, int index) {
    pthread_mutex_lock(&manager->mutex);
    if (index < 0 || index > manager->count || manager->count >= MAX_NUM_STRUCTURES) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Handle out-of-bounds access
    }
    for (int i = manager->count; i > index; i--) {
        manager->array[i] = manager->array[i-1];
    }
    manager->array[index] = newStruct;
    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int removeStructure(ArrayManager* manager, int index) {
    pthread_mutex_lock(&manager->mutex);
    if (index < 0 || index >= manager->count) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Handle out-of-bounds access
    }
    for (int i = index; i < manager->count-1; i++) {
        manager->array[i] = manager->array[i+1];
    }
    free(manager->array[manager->count-1]);
    manager->count--;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void iterateForward(ArrayManager* manager, int startIndex, int endIndex) {
