typedef struct Node {
    Item *item;
    struct Node *next;
} Node;

typedef struct Bucket {
    Node *head;
} Bucket;

Item* create_item(int key, float value) {
    Item *new_item = (Item *)malloc(sizeof(Item));
    if (new_item == NULL) {
        printf("Memory allocation failed for item.\n");
        exit(EXIT_FAILURE);
    }
    new_item->key = key;
    new_item->value = value;
    return new_item;
}

Node* create_node(Item *item) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed for node.\n");
        exit(EXIT_FAILURE);
    }
    new_node->item = item;
    new_node->next = NULL;
    return new_node;
}

Bucket* create_bucket() {
    Bucket *new_bucket = (Bucket *)malloc(sizeof(Bucket));
    if (new_bucket == NULL) {
        printf("Memory allocation failed for bucket.\n");
        exit(EXIT_FAILURE);
    }
    new_bucket->head = NULL;
    return new_bucket;
}

void insert_item_to_bucket(Item *item, Bucket *bucket) {
    Node *new_node = create_node(item);
    new_node->next = bucket->head;
    bucket->head = new_node;
}

Bucket** init_buckets(int m) {
    if (m <= 0) {
        printf("Invalid number of buckets.\n");
        exit(EXIT_FAILURE);
    }
    Bucket **buckets = (Bucket **)malloc(m * sizeof(Bucket *));
    if (buckets == NULL) {
        printf("Memory allocation failed for buckets array.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < m; i++) {
        buckets[i] = create_bucket();
    }
    return buckets;
}

Item** init_items(int n, float min_val, float max_val) {
    if (n <= 0) {
        printf("Invalid number of items.\n");
        exit(EXIT_FAILURE);
    }
    Item **items = (Item **)malloc(n * sizeof(Item *));
    if (items == NULL) {
        printf("Memory allocation failed for items array.\n");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        float value = min_val + (float)(rand()) / RAND_MAX * (max_val - min_val);
        items[i] = create_item(i, value);
    }
    return items;
}

int* init_last_used_index(int n) {
    if (n <= 0) {
        printf("Invalid number of last used indices.\n");
        exit(EXIT_FAILURE);
    }
    int *last_used_index = (int *)malloc(n * sizeof(int));
    if (last_used_index == NULL) {
        printf("Memory allocation failed for last used index array.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < n; i++) {
        last_used_index[i] = -1;
    }
    return last_used_index;
}

Bucket** init_conflicting_buckets(int m) {
    Bucket **conflicting_buckets = (Bucket **)malloc(m * sizeof(Bucket *));
    if (conflicting_buckets == NULL) {
        printf("Memory allocation failed for conflicting buckets array.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < m; i++) {
        conflicting_buckets[i] = create_bucket();
    }
    return conflicting_buckets;
}

