struct TransactionLogEntry {
    int transactionID;
    std::time_t timestamp;
    char* messageBuffer;
};

class TransactionLogger {
private:
    std::vector<TransactionLogEntry*> logEntries;
    std::mutex mutex;
    bool enableLogging;

public:
    TransactionLogger(bool logging = false) : enableLogging(logging) {}

    ~TransactionLogger() {
        for (auto entry : logEntries) {
            delete[] entry->messageBuffer;
            delete entry;
        }
    }

    void addLogEntry(size_t maxMessageSize) {
        std::lock_guard<std::mutex> lock(mutex);
        TransactionLogEntry* newEntry = new TransactionLogEntry();
        newEntry->transactionID = generateRandomTransactionID();
        newEntry->timestamp = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        newEntry->messageBuffer = new char[maxMessageSize];
        logEntries.push_back(newEntry);

        if (enableLogging) {
            logMemoryAllocation(maxMessageSize);
        }
    }

    void enableLogger() {
        enableLogging = true;
    }

    void disableLogger() {
        enableLogging = false;
    }

private:
    int generateRandomTransactionID() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1000, 10000);
        return dis(gen);
    }

    void logMemoryAllocation(size_t size) {
        // Implement memory allocation logging logic here
        std::cout << "Allocated " << size << " bytes for message buffer" << std::endl;
    }
};

int main() {
    TransactionLogger logger(true);

    logger.addLogEntry(1024);
    logger.addLogEntry(2048);

    logger.disableLogger();

    return 0;
}
