#define MAX_FILE_PATH 256

typedef struct {
    char *file_path;
    int line_count;
} FileData;

void print_usage() {
    printf("Usage: program [options] input_files...\n");
    printf("Options:\n");
    printf("  --manpage          Display this manual page\n");
    printf("  -cs                Enable case-sensitive search\n");
    printf("  -o output_file     Specify the output file\n");
    printf("  input_files         Input files or directories to process\n");
}

void *process_file(void *arg) {
    FileData *file_data = (FileData *)arg;
    FILE *fp = fopen(file_data->file_path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening file: %s\n", file_data->file_path);
        return NULL;
    }

    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp)) {
        line_count++;
    }
    fclose(fp);

    file_data->line_count = line_count;
    return arg;
}

void process_directory(const char *dir_path) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        fprintf(stderr, "Error opening directory: %s\n", dir_path);
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            char file_path[MAX_FILE_PATH];
            snprintf(file_path, sizeof(file_path), "%s/%s", dir_path, entry->d_name);
            process_file(file_path);
        }
    }

    closedir(dir);
}

void compress_output(const char *input_file, const char *output_file) {
    gzFile out = gzdopen(open(output_file, O_WRONLY | O_CREAT | O_TRUNC), "wb");
    if (!out) {
        fprintf(stderr, "Error opening output file for compression: %s\n", output_file);
        return;
    }

    FILE *in = fopen(input_file, "r");
    if (!in) {
        fprintf(stderr, "Error opening input file for compression: %s\n", input_file);
        gzclose(out);
        return;
    }

    char buffer[1024];
    size_t nread;
    while ((nread = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        if (gzwrite(out, buffer, nread) != nread) {
            fprintf(stderr, "Error writing to compressed file: %s\n", output_file);
            break;
        }
    }

    fclose(in);
    gzclose(out);
}

