#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int init_data_structures(long offset_count, int key_count, int min_value, int max_value,
                          long **offsets, int **keys, record ***records) {
    *offsets = (long *)calloc(offset_count, sizeof(long));
    if (*offsets == NULL) {
        return -1; // Memory allocation failed
    }

    *keys = (int *)aligned_alloc(64, key_count * sizeof(int)); // Aligned for cache efficiency
    if (*keys == NULL) {
        free(*offsets);
        return -2; // Memory allocation failed
    }

    *records = (record **)malloc(key_count * sizeof(record *));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -3; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < key_count; i++) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            for (int j = 0; j < i; j++) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            return -4; // Memory allocation failed
        }

        int unique_value;
        do {
            unique_value = rand() % (max_value - min_value + 1) + min_value;
        } while (*records[i] != NULL && (*records[i])->value == unique_value);

        (*records)[i]->value = unique_value;
    }

    return 0; // Success
}

void free_data_structures(long *offsets, int *keys, record **records, int key_count) {
    for (int i = 0; i < key_count; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}
