    long *offsets = (long *)malloc(NUM_RECORDS * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    int *keys = (int *)malloc(NUM_RECORDS * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    double *values = (double *)malloc(NUM_RECORDS * sizeof(double));
    if (!values) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for values");
        return NULL;
    }

    record *records = (record *)malloc(NUM_RECORDS * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        free(values);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < NUM_RECORDS; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 100 + 1; // Random between 1 and 100
        values[i] = ((double)rand() / RAND_MAX) * 100.0; // Random between 0.0 and 100.0
        snprintf(records[i].buffer, BUFFER_SIZE, "Record %d", i);
    }

    for (int i = 0; i < NUM_RECORDS; ++i) {
        printf("Offset: %ld, Key: %d, Value: %.2f, Buffer: %s\n",
               offsets[i], keys[i], values[i], records[i].buffer);
    }

    free(offsets);
    free(keys);
    free(values);
    free(records);

    return NULL;
}

void cleanup() {
    // Implement cleanup logic here if needed
}

int main() {
    pthread_t thread;
    int result = pthread_create(&thread, NULL, initialize_records, NULL);
    if (result != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    cleanup();

    return EXIT_SUCCESS;
}
