    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} dynamicFileCollection;

// Function to initialize the dynamic file collection
dynamicFileCollection* initDynamicFileCollection(size_t initialCapacity) {
    dynamicFileCollection *col = (dynamicFileCollection*)malloc(sizeof(dynamicFileCollection));
    if (!col) return NULL;

    col->entries = (fileMetadata**)calloc(initialCapacity, sizeof(fileMetadata*));
    if (!col->entries) {
        free(col);
        return NULL;
    }

    col->count = 0;
    col->capacity = initialCapacity;
    pthread_mutex_init(&col->mutex, NULL);

    return col;
}

// Function to add a new file metadata entry
int addFileMetadata(dynamicFileCollection *col, const char *fileName, off_t fileSize) {
    pthread_mutex_lock(&col->mutex);
    if (col->count >= col->capacity) {
        size_t newCapacity = col->capacity ? col->capacity * 2 : 1;
        fileMetadata **newEntries = realloc(col->entries, newCapacity * sizeof(fileMetadata*));
        if (!newEntries) {
            pthread_mutex_unlock(&col->mutex);
            return -1; // Memory allocation failed
        }
        col->entries = newEntries;
        col->capacity = newCapacity;
    }

    fileMetadata *entry = (fileMetadata*)malloc(sizeof(fileMetadata));
    if (!entry) {
        pthread_mutex_unlock(&col->mutex);
        return -2; // Memory allocation failed
    }

    entry->fileName = strdup(fileName);
    entry->lastModified = time(NULL);
    entry->fileSize = fileSize;

    col->entries[col->count++] = entry;
    pthread_mutex_unlock(&col->mutex);

    return 0; // Success
}

// Function to update an existing file metadata entry
int updateFileMetadata(dynamicFileCollection *col, const char *fileName, off_t newSize) {
    pthread_mutex_lock(&col->mutex);
    for (size_t i = 0; i < col->count; ++i) {
        if (strcmp(col->entries[i]->fileName, fileName) == 0) {
            free(col->entries[i]->fileName);
            col->entries[i]->fileName = strdup(fileName);
            col->entries[i]->fileSize = newSize;
            pthread_mutex_unlock(&col->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&col->mutex);
    return -1; // Entry not found
}

// Function to remove a file metadata entry
int removeFileMetadata(dynamicFileCollection *col, const char *fileName) {
    pthread_mutex_lock(&col->mutex);
    for (size_t i = 0; i < col->count; ++i) {
        if (strcmp(col->entries[i]->fileName, fileName) == 0) {
            free(col->entries[i]->fileName);
            free(col->entries[i]);
            memmove(&col->entries[i], &col->entries[i + 1], (col->count - i - 1) * sizeof(fileMetadata*));
            --col->count;
            pthread_mutex_unlock(&col->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&col->mutex);
    return -1; // Entry not found
}

// Function to iterate over entries and print their contents
void printFileMetadata(dynamicFileCollection *col) {
    pthread_mutex_lock(&col->mutex);
    for (size_t i = 0; i < col->count; ++i) {
        printf("File Name: %s, Last Modified: %ld, File Size: %ld\n", 
               col->entries[i]->fileName, col->entries[i]->lastModified, col->entries[i]->fileSize);
    }
    pthread_mutex_unlock(&col->mutex);
}

// Function to cleanup and free all allocated memory
void cleanupDynamicFileCollection(dynamicFileCollection *col) {
    for (size_t i = 0; i < col->count; ++i) {
        free(col->entries[i]->fileName);
        free(col->entries[i]);
    }
    free(col->entries);
    pthread_mutex_destroy(&col->mutex);
    free(col);
}

// Function to serialize the dynamic file collection
int serializeDynamicFileCollection(dynamicFileCollection *col, FILE *stream) {
    // Implementation of serialization logic here
    return 0; // Success
}

// Function to deserialize the dynamic file collection
dynamicFileCollection* deserializeDynamicFileCollection(FILE *stream) {
