#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char *fileName;
    time_t lastModified;
    off_t fileSize;
} fileMetadata;

typedef struct {
    fileMetadata **data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} metadataCollection;

metadataCollection* createCollection() {
    metadataCollection *col = (metadataCollection*)malloc(sizeof(metadataCollection));
    if (!col) return NULL;
    col->data = NULL;
    col->count = 0;
    col->capacity = 0;
    pthread_mutex_init(&col->lock, NULL);
    return col;
}

int addEntry(metadataCollection *col, const char *fileName, off_t fileSize) {
    pthread_mutex_lock(&col->lock);
    if (col->count == col->capacity) {
        size_t newCapacity = col->capacity ? col->capacity * 2 : 16;
        fileMetadata **newData = (fileMetadata**)realloc(col->data, newCapacity * sizeof(fileMetadata*));
        if (!newData) {
            pthread_mutex_unlock(&col->lock);
            return -1; // Memory allocation failed
        }
        col->data = newData;
        col->capacity = newCapacity;
    }
    col->data[col->count] = (fileMetadata*)malloc(sizeof(fileMetadata));
    if (!col->data[col->count]) {
        pthread_mutex_unlock(&col->lock);
        return -1; // Memory allocation failed
    }
    col->data[col->count]->fileName = strdup(fileName);
    if (!col->data[col->count]->fileName) {
        free(col->data[col->count]);
        pthread_mutex_unlock(&col->lock);
        return -1; // Memory allocation failed
    }
    col->data[col->count]->lastModified = time(NULL);
    col->data[col->count]->fileSize = fileSize;
    col->count++;
    pthread_mutex_unlock(&col->lock);
    return 0;
}

void freeCollection(metadataCollection *col) {
    if (col) {
        for (size_t i = 0; i < col->count; i++) {
            free(col->data[i]->fileName);
            free(col->data[i]);
        }
        free(col->data);
        pthread_mutex_destroy(&col->lock);
        free(col);
    }
}

void printEntries(metadataCollection *col) {
    pthread_mutex_lock(&col->lock);
    for (size_t i = 0; i < col->count; i++) {
        printf("File: %s, Last Modified: %s, Size: %ld\n", 
               col->data[i]->fileName, ctime(&col->data[i]->lastModified), col->data[i]->fileSize);
    }
    pthread_mutex_unlock(&col->lock);
}

// Additional functions for updating and removing entries can be implemented similarly
