NFAPI_CRC_INDICATION_POOL_T* nfapi_crc_indication_pool_init(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_POOL_T *pool = (NFAPI_CRC_INDICATION_POOL_T*)malloc(sizeof(NFAPI_CRC_INDICATION_POOL_T));
    pool->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void nfapi_crc_indication_pool_free(NFAPI_CRC_INDICATION_POOL_T *pool) {
    free(pool->array);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int nfapi_crc_indication_pool_add(NFAPI_CRC_INDICATION_POOL_T *pool, int RNTI, const char *RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        pool->capacity *= 2;
        pool->array = realloc(pool->array, pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pool->array[pool->size].RNTI = RNTI;
    strncpy(pool->array[pool->size].RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG, 64);
    pool->size++;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int nfapi_crc_indication_pool_contains(NFAPI_CRC_INDICATION_POOL_T *pool, const char *RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; i++) {
        if (strcmp(pool->array[i].RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG) == 0) {
            pthread_mutex_unlock(&pool->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int nfapi_crc_indication_pool_get_size(NFAPI_CRC_INDICATION_POOL_T *pool) {
    int size = -1;
    pthread_mutex_lock(&pool->lock);
    size = pool->size;
    pthread_mutex_unlock(&pool->lock);
    return size;
}
