#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <zlib.h>

#define MAX_FILES 1000
#define LOG_FILE "error_log.txt"

typedef struct {
    char* filename;
    int processed;
} FileEntry;

FileEntry file_entries[MAX_FILES];
int num_files = 0;
pthread_mutex_t lock;

void log_error(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void* process_file(void* arg) {
    int index = *(int*)arg;
    FileEntry* entry = &file_entries[index];
    FILE* file = fopen(entry->filename, "r");

    if (file == NULL) {
        log_error("Failed to open file: ");
        free(arg);
        return NULL;
    }

    // Process the file
    printf("Processing %s...\n", entry->filename);
    // Add your file processing logic here

    fclose(file);
    pthread_mutex_lock(&lock);
    entry->processed = 1;
    pthread_mutex_unlock(&lock);

    free(arg);
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file or directory>\n", argv[0]);
        return 1;
    }

    // Initialize shared resources
    pthread_mutex_init(&lock, NULL);

    DIR* dir = opendir(argv[1]);
    if (dir != NULL) {
        struct dirent* ent;
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;

            if (num_files >= MAX_FILES) {
                log_error("Too many files");
                break;
            }

            file_entries[num_files].filename = strdup(ent->d_name);
            file_entries[num_files].processed = 0;
            num_files++;
        }
        closedir(dir);
    } else {
        // Process a single file
        if (num_files >= MAX_FILES) {
            log_error("Too many files");
            return 1;
        }

        file_entries[0].filename = strdup(argv[1]);
        file_entries[0].processed = 0;
        num_files++;
    }

    pthread_t threads[num_files];
    int thread_args[num_files];

    for (int i = 0; i < num_files; i++) {
        thread_args[i] = i;
        if (pthread_create(&threads[i], NULL, process_file, &thread_args[i]) != 0) {
            log_error("Failed to create thread");
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    // Output report
    printf("Processing complete. %d files processed.\n", num_files);

    // Clean up
    pthread_mutex_destroy(&lock);
    for (int i = 0; i < num_files; i++) {
        free(file_entries[i].filename);
    }

    return 0;
}
