        if (!new_entry) {
            fprintf(stderr, "Failed to create entry\n");
            free(ids);
            free(values);
            free(entries);
            destroy_hash_table(table);
            return;
        }
        insert_into_hash_table(table, ids[i], new_entry);
    }

    for (int i = 0; i < m; ++i) {
        log_message("Allocated memory for entry with id: %ld and value: %.2f", entries[i]->id, entries[i]->value), LOG_FILE_PATH);
    }

    // Clean up allocated memory
    free(ids);
    free(values);
    for (int i = 0; i < m; ++i) {
        free(entries[i]->string);
        free(entries[i]);
    }
    free(entries);
    destroy_hash_table(table);
}

int main() {
    initialize_data_structures(10, 5, 0.0, 1.0, 8, true);
    return 0;
}
