    history_entry *log;
    size_t log_size, log_capacity;
    size_t head, tail;
} history;

metadata* init_metadata(size_t size) {
    metadata *m = malloc(sizeof(metadata));
    m->offsets = (long*)calloc(size, sizeof(long));
    m->keys = (int*)malloc(size * sizeof(int));
    m->records = (record*)malloc(size * sizeof(record));
    m->offset_size = size * sizeof(long);
    m->key_size = size * sizeof(int);
    m->record_size = size * sizeof(record);
    return m;
}

history* init_history(size_t capacity) {
    history *h = malloc(sizeof(history));
    h->log = (history_entry*)malloc(capacity * sizeof(history_entry));
    h->log_capacity = capacity;
    h->head = 0;
    h->tail = 0;
    return h;
}

void log_operation(history *h, const char *operation_details) {
    time_t now = time(NULL);
    if (h->tail >= h->log_capacity - 1) {
        h->tail = 0;
    }
    h->log[h->tail].timestamp = now;
    h->log[h->tail].operation_details = strdup(operation_details);
    h->tail++;
}

void free_metadata(metadata *m, history *h) {
    for (size_t i = 0; i < m->record_size / sizeof(record); i++) {
        free(m->records[i].value);
    }
    free(m->offsets);
    free(m->keys);
    free(m->records);
    for (size_t i = h->head; i != h->tail; i = (i + 1) % h->log_capacity) {
        free(h->log[i].operation_details);
    }
    free(h->log);
    free(m);
    free(h);
}

