void init_data_structures() {
    pthread_mutex_init(&dataMutex, NULL);
}

void add_record(long offset, int key) {
    pthread_mutex_lock(&dataMutex);
    if (numRecords >= MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum number of records reached\n");
        pthread_mutex_unlock(&dataMutex);
        return;
    }
    dataStructures[numRecords] = malloc(sizeof(DataStructure));
    dataStructures[numRecords]->offset = offset;
    dataStructures[numRecords]->key = key;
    if (RAND_bytes((unsigned char *)&dataStructures[numRecords]->record.value, sizeof(int)) != 1) {
        fprintf(stderr, "Error: Failed to generate random number\n");
        free(dataStructures[numRecords]);
        pthread_mutex_unlock(&dataMutex);
        return;
    }
    numRecords++;
    pthread_mutex_unlock(&dataMutex);
}

