        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    // Continue with loading other primitives
    pthread_exit(NULL);
}

void run_concurrent_operations() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, load_cryptographic_primitives, NULL) != 0) {
        fprintf(stderr, "Error: Failed to create thread\n");
        return;
    }
    pthread_join(thread, NULL);
}

