#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

#define NUM_OFFSETS 1001
#define MAX_KEYS 500
#define MIN_VALUE 0
#define MAX_VALUE 10000

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
} OffsetKeyPair;

typedef struct {
    OffsetKeyPair* pairs;
    size_t capacity;
    size_t count;
} HashTable;

HashTable* hash_table_init(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->pairs = (OffsetKeyPair*)calloc(initial_capacity, sizeof(OffsetKeyPair));
    table->capacity = initial_capacity;
    table->count = 0;
    return table;
}

void hash_table_insert(HashTable* table, long offset, int key) {
    // Hash function and collision resolution strategy
    size_t index = (offset * key) % table->capacity;
    while (table->pairs[index].key != -1 && table->pairs[index].key != key) {
        if (++index == table->capacity)
            index = 0;
    }
    table->pairs[index] = (OffsetKeyPair){offset, key};
    table->count++;
}

void hash_table_free(HashTable* table) {
    free(table->pairs);
    free(table);
}

Record* allocate_records(size_t count) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }
    memset(records, 0, count * sizeof(Record));
    return records;
}

void free_records(Record* records, size_t count) {
    free(records);
}

void set_record_values(Record* records, int minValue, int maxValue) {
    srand(time(NULL)); // Seed for reproducibility
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        // Check for overflow condition
        if (records[i].value < minValue || records[i].value > maxValue) {
            fprintf(stderr, "Overflow condition encountered\n");
            exit(EXIT_FAILURE);
        }
    }
}

void print_data(OffsetKeyPair* offsets, int* keys, Record* records, size_t count) {
    printf("Offsets and Keys:\n");
    for (size_t i = 0; i < count; ++i)
        printf("%ld %d\n", offsets[i].offset, offsets[i].key);

    printf("Records:\n");
    for (size_t i = 0; i < count; ++i)
        printf("%d\n", records[i].value);
}

void serialize_to_json(OffsetKeyPair* offsets, int* keys, Record* records, size_t count) {
    printf("{\"offsets\": [");
    for (size_t i = 0; i < count; ++i) {
        if (i != 0) printf(", ");
        printf("{\"offset\": %ld, \"key\": %d}", offsets[i].offset, offsets[i].key);
    }
    printf("],\n\"records\": [");
    for (size_t i = 0; i < count; ++i) {
        if (i != 0) printf(", ");
        printf("%d", records[i].value);
    }
    printf("]}\n");
}

void* worker_thread(void* arg) {
    // Thread-specific code here
    return NULL;
}

int main() {
    HashTable* table = hash_table_init(MAX_KEYS);
    OffsetKeyPair* offsets = (OffsetKeyPair*)malloc(NUM_OFFSETS * sizeof(OffsetKeyPair));
    int* keys = (int*)malloc(MAX_KEYS * sizeof(int));

    // Initialize arrays and data structures
    for (size_t i = 0; i < NUM_OFFSETS; ++i) {
        offsets[i].offset = i;
        hash_table_insert(table, i, rand() % MAX_KEYS);
        if (table->count > table->capacity - 100) { // Dynamic resizing condition
            HashTable* new_table = hash_table_init(table->capacity * 2);
            for (size_t j = 0; j < table->count; ++j)
                hash_table_insert(new_table, table->pairs[j].offset, table->pairs[j].key);
            free(table->pairs);
            table->pairs = new_table->pairs;
            table->capacity = new_table->capacity;
            free(new_table);
        }
    }

    Record* records = allocate_records(table->count);

    set_record_values(records, MIN_VALUE, MAX_VALUE);
    print_data(offsets, keys, records, table->count);
    serialize_to_json(offsets, keys, records, table->count);

    // Free allocated memory
    hash_table_free(table);
    free(offsets);
    free(keys);
    free_records(records, table->count);

    return 0;
}
