#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_POOL_SIZE 1024 * 1024 * 10 // 10 MB
#define RECORD_SIZE sizeof(struct record)

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t lock;
    char pool[MAX_MEMORY_POOL_SIZE];
    size_t free_space;
} memory_pool;

memory_pool* create_memory_pool() {
    memory_pool* mp = (memory_pool*)malloc(sizeof(memory_pool));
    if (!mp) return NULL;
    pthread_mutex_init(&mp->lock, NULL);
    mp->free_space = MAX_MEMORY_POOL_SIZE;
    memset(mp->pool, 0, MAX_MEMORY_POOL_SIZE);
    return mp;
}

void destroy_memory_pool(memory_pool* mp) {
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

void* allocate_from_pool(memory_pool* mp, size_t size) {
    if (size > mp->free_space) return NULL;

    void* ptr = &mp->pool[mp->free_space - size];
    mp->free_space -= size;
    return ptr;
}

record* create_record(int value) {
    record* r = (record*)allocate_from_pool(memory_pool, RECORD_SIZE);
    if (!r) return NULL;
    r->value = value;
    return r;
}

void init_data_structures(long* offsets, int* keys, record** records, size_t count, long offset_range, int key_range, memory_pool* pool) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;

        records[i] = create_record(rand());
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_data_structures(long* offsets, int* keys, record** records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i]);
    }
}

int main() {
    const size_t num_elements = 1000;
    long offsets[num_elements];
    int keys[num_elements];
    record* records[num_elements];

    memory_pool* pool = create_memory_pool();
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return EXIT_FAILURE;
    }

    init_data_structures(offsets, keys, records, num_elements, 1000000L, 1000, pool);

    // Use data structures here

    cleanup_data_structures(offsets, keys, records, num_elements);
    destroy_memory_pool(pool);

    return EXIT_SUCCESS;
}
