#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offset;
    int ref_count;
} record;

typedef struct {
    int total_records;
    int max_key;
    int min_key;
    double avg_offset;
} metadata;

void initialize_data_structures(long *offsets, int *keys, record **records, metadata *meta, int num_records) {
    pthread_t threads[num_records];
    int thread_ids[num_records];

    for (int i = 0; i < num_records; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, init_record, &thread_ids[i]) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Initialize metadata
    meta->total_records = num_records;
    meta->max_key = keys[0];
    meta->min_key = keys[0];
    meta->avg_offset = 0.0;

    for (int i = 1; i < num_records; ++i) {
        if (keys[i] > meta->max_key) {
            meta->max_key = keys[i];
        }
        if (keys[i] < meta->min_key) {
            meta->min_key = keys[i];
        }
        meta->avg_offset += offsets[keys[i]];
    }

    meta->avg_offset /= num_records;
}

void *init_record(void *arg) {
    int index = *(int *)arg;

    record *rec = (record *)malloc(sizeof(record));
    if (!rec) {
        perror("Failed to allocate memory for record");
        pthread_exit(NULL);
    }

    rec->value = index; // Example initialization
    rec->offset = (long *)malloc(sizeof(long));
    if (!rec->offset) {
        free(rec);
        perror("Failed to allocate memory for offset");
        pthread_exit(NULL);
    }
    *rec->offset = 0; // Initialize to zero or appropriate value

    rec->ref_count = 1;

    record[index] = *rec;
    free(rec);

    pthread_exit(NULL);
}

void free_data_structures(record **records, metadata *meta) {
    for (int i = 0; i < meta->total_records; ++i) {
        if (records[i]->offset) {
            free(records[i]->offset);
        }
        records[i] = NULL;
    }

    free(meta);
}

// Example usage
int main() {
    int num_records = 1000;
    long offsets[num_records];
    int keys[num_records];
    record *records[num_records];
    metadata meta;

    // Initialize offsets and keys here

    initialize_data_structures(offsets, keys, records, &meta, num_records);

    // Use the data structures...

    free_data_structures(records, &meta);

    return 0;
}
