    Item *data;
    struct node *next;
    struct node *prev;
} Node;

Node* create_node(Item *item) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = item;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void initialize_arrays(int n, double **double_arr, char **char_arr, Node ***struct_arr) {
    *double_arr = (double *)malloc(n * sizeof(double));
    *char_arr = (char *)malloc(n * sizeof(char));
    *struct_arr = (Node **)malloc(n * sizeof(Node *));
}

void build_linked_list(int n, double *double_arr, char *char_arr, Node **head, Node **tail) {
    for (int i = 0; i < n; i++) {
        Item *item = (Item *)malloc(sizeof(Item));
        item->id = i;
        item->value = double_arr[i];
        Node *node = create_node(item);
        if (i == 0) {
            *head = node;
            *tail = node;
        } else {
            (*tail)->next = node;
            node->prev = *tail;
            *tail = node;
        }
    }
}

void update_linked_list(Node *head, float (*func)(float)) {
    while (head != NULL) {
        head->data->value = func(head->data->value);
        head = head->next;
    }
}

void free_memory(Node **head) {
    Node *current = *head;
    Node *next;
    while (current != NULL) {
        next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}
