#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_LOAD_FACTOR 0.75

typedef struct {
    int *data;
    size_t capacity;
} Array;

typedef struct record {
    int value;
} Record;

typedef struct node {
    int key;
    Record *record;
    struct node *next;
} Node;

typedef struct hash_table {
    Node **buckets;
    size_t size;
    size_t capacity;
    Array indexes;
} HashTable;

HashTable* create_hash_table(size_t n) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->buckets = (Node**)calloc(INITIAL_CAPACITY, sizeof(Node*));
    ht->size = 0;
    ht->capacity = INITIAL_CAPACITY;
    init_array(&ht->indexes, n);
    return ht;
}

void free_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Node *node = ht->buckets[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->buckets);
    free_array(&ht->indexes);
    free(ht);
}

void resize_hash_table(HashTable *ht, size_t new_capacity) {
    Node **old_buckets = ht->buckets;
    size_t old_size = ht->size;

    ht->buckets = (Node**)calloc(new_capacity, sizeof(Node*));
    ht->capacity = new_capacity;
    ht->size = 0;

    for (size_t i = 0; i < old_size; ++i) {
        Node *node = old_buckets[i];
        while (node != NULL) {
            Record *record = node->record;
            insert_hash_table(ht, record, node->key);
            Node *next = node->next;
            free(node);
            node = next;
        }
    }

    free(old_buckets);
}

size_t hash_function(int key, size_t capacity) {
    return (size_t)(key % capacity);
}

void insert_hash_table(HashTable *ht, Record *record, int key) {
    if ((double)ht->size / ht->capacity >= MAX_LOAD_FACTOR) {
        resize_hash_table(ht, ht->capacity * 2);
    }

    size_t index = hash_function(key, ht->capacity);

    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->key = key;
    new_node->record = record;
    new_node->next = ht->buckets[index];

    ht->buckets[index] = new_node;
    ++ht->size;

    // Update indexes array
    update_index(ht, record, index);
}

Record* get_record_by_key(HashTable *ht, int key) {
    size_t index = hash_function(key, ht->capacity);

    Node *node = ht->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            return node->record;
        }
        node = node->next;
    }

    return NULL;
}

void init_array(Array *arr, size_t n) {
    arr->data = (int*)malloc(n * sizeof(int));
    arr->capacity = n;
}

void free_array(Array *arr) {
    free(arr->data);
}

void update_index(HashTable *ht, Record *record, size_t index) {
    int record_index = find_record_index(ht->indexes.data, ht->records->data, record, ht->records->size);
    if (record_index != -1) {
        ht->indexes.data[record_index] = index;
    }
}

int find_record_index(int *indexes, Record *records, Record *target, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (records[i].value == target->value) {
            return (int)i;
        }
    }
    return -1;
}
