#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1000000

typedef struct {
    int value;
} Record;

int hash(int key, int size) {
    return abs(key % size);
}

void resize(Record** table, int* size, int factor) {
    int new_size = *size * factor;
    Record* new_table = realloc(*table, new_size * sizeof(Record));
    if (!new_table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = *size; i < new_size; ++i) {
        new_table[i].value = -1; // Mark as empty
    }
    *table = new_table;
    *size = new_size;
}

void insert(Record** table, int* size, int* count, int key, int value) {
    if (*count >= *size / 2) {
        resize(table, size, 2);
    }
    int index = hash(key, *size);
    while (table[index]->value != -1 && table[index]->value != key) {
        index = (index + 1) % *size;
    }
    if (table[index]->value == -1) {
        (*count)++;
    }
    table[index]->value = value;
}

void findLargest(int* arr, int size) {
    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    printf("Largest value: %d\n", largest);
}

void sortArray(int* arr, int size) {
    qsort(arr, size, sizeof(int), (int (*)(const void *, const void *))strcmp);
}

void freeResources(Record** table, int* offsets, int* keys, int* indexes, int n, int m) {
    for (int i = 0; i < m; ++i) {
        free(table[i]);
    }
    free(table);
    free(offsets);
    free(keys);
    free(indexes);
}

