    scanf("%d", &n);
    if (n <= 0 || n > MAX_SIZE) {
        fprintf(stderr, "Invalid record count\n");
        return EXIT_FAILURE;
    }

    printf("Enter the range for values (low-high): ");
    scanf("%d %d", &low, &high);
    if (low < 0 || high > INT_MAX) {
        fprintf(stderr, "Invalid value range\n");
        return EXIT_FAILURE;
    }

    printf("Enter the number of keys (1-%d): ", MAX_SIZE);
    scanf("%d", &m);
    if (m <= 0 || m > MAX_SIZE) {
        fprintf(stderr, "Invalid key count\n");
        return EXIT_FAILURE;
    }

    Record** table = malloc(m * sizeof(Record*));
    int* offsets = malloc(n * sizeof(int));
    int* keys = malloc(n * sizeof(int));
    int* indexes = malloc(n * sizeof(int));

    if (!table || !offsets || !keys || !indexes) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        offsets[i] = rand() % (m + 1);
        keys[i] = rand() % (high - low + 1) + low;
        indexes[i] = -1;

        table[i] = malloc(sizeof(Record));
        if (!table[i]) {
            fprintf(stderr, "Memory allocation failed\n");
