} image_segment;

struct image_processor {
    uint32_t n_images;
    uint32_t m_segments_per_image;
    image_segment** images;
    float* dimensions;
    float* intensities;
    float** segment_cache;
    EVP_CIPHER_CTX* cipher_ctx;
};

struct image_processor* efficientImageProcessor(uint32_t n, uint32_t m, const char* password) {
    struct image_processor* processor = (struct image_processor*)malloc(sizeof(struct image_processor));
    if (!processor) return NULL;

    processor->n_images = n;
    processor->m_segments_per_image = m;

    processor->images = (image_segment**)malloc(n * sizeof(image_segment*));
    processor->dimensions = (float*)malloc(n * sizeof(float));
    processor->intensities = (float*)malloc(m * sizeof(float));
    processor->segment_cache = (float**)malloc(m * sizeof(float*));

    if (!processor->images || !processor->dimensions || !processor->intensities || !processor->segment_cache) {
        free(processor);
        return NULL;
    }

    for (uint32_t i = 0; i < n; ++i) {
        processor->images[i] = (image_segment*)malloc(m * sizeof(image_segment));
        if (!processor->images[i]) {
            // Handle memory allocation error
        }
        for (uint32_t j = 0; j < m; ++j) {
            processor->images[i][j].width = rand() % 100 + 1;
            processor->images[i][j].height = rand() % 100 + 1;
            processor->images[i][j].pixel_data = (float*)malloc(processor->images[i][j].width * processor->images[i][j].height * sizeof(float));
            if (!processor->images[i][j].pixel_data) {
                // Handle memory allocation error
            }
            for (uint32_t k = 0; k < processor->images[i][j].width * processor->images[i][j].height; ++k) {
                processor->images[i][j].pixel_data[k] = ((float)rand() / RAND_MAX);
            }
        }
    }

    // Initialize AES-256-CBC cipher with OpenSSL
    processor->cipher_ctx = EVP_CIPHER_CTX_new();
    if (!processor->cipher_ctx) return NULL;
    EVP_EncryptInit_ex(processor->cipher_ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)password, NULL);

    return processor;
}

// Cleanup function to disable the cipher and free resources
void cleanupImageProcessor(struct image_processor* processor) {
    for (uint32_t i = 0; i < processor->n_images; ++i) {
        for (uint32_t j = 0; j < processor->m_segments_per_image; ++j) {
            free(processor->images[i][j].pixel_data);
        }
        free(processor->images[i]);
    }
    free(processor->images);
    free(processor->dimensions);
    free(processor->intensities);
    free(processor->segment_cache);
    EVP_CIPHER_CTX_free(processor->cipher_ctx);
    free(processor);
}
