#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFAPDUList;

void initNFAPDUList(NFAPDUList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addNFAPDU(NFAPDUList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        return; // Handle memory allocation failure
    }
    newNode->data = pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void removeNFAPDU(NFAPDUList* list, int rnti) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {
        if (prev == NULL) {
            list->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
}

void processNFAPDUs(NFAPDUList* list, void (*process)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        process(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void retrieveNFAPDUsWithCRCFlagSet(NFAPDUList* list, void (*process)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.CRCFLAG) {
            process(current->data);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void updateNFAPDUFlag(NFAPDUList* list, int rnti, int newCRCFlag) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            current->data.CRCFLAG = newCRCFlag;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
