void *memory_pool[NUM_STRUCTS][RECORD_POOL_SIZE];
pthread_mutex_t pool_lock[NUM_STRUCTS] = { PTHREAD_MUTEX_INITIALIZER };
char **string_pool[RECORD_POOL_SIZE];
pthread_mutex_t string_pool_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

int init_memory() {
    // Initialize memory structures and pools
    for (int i = 0; i < NUM_STRUCTS; ++i) {
        for (int j = 0; j < RECORD_POOL_SIZE; ++j) {
            memory_pool[i][j] = malloc(sizeof(Record));
            if (!memory_pool[i][j]) {
                fprintf(log_file, "Memory allocation failed for type %d\n", i);
                return -1;
            }
        }
    }

    for (int j = 0; j < RECORD_POOL_SIZE; ++j) {
        string_pool[j] = malloc(256 * sizeof(char));
        if (!string_pool[j]) {
