            return -1;
        }
    }

    return 0;
}

void free_memory() {
    // Free all allocated memory
    for (int i = 0; i < NUM_STRUCTS; ++i) {
        for (int j = 0; j < RECORD_POOL_SIZE; ++j) {
            free(memory_pool[i][j]);
        }
    }

    for (int j = 0; j < RECORD_POOL_SIZE; ++j) {
