        fprintf(log_file, "Failed to create cipher context\n");
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL,
                            (unsigned char *)password, (unsigned char *)"0123456789ABCDEF") != 1) {
        fprintf(log_file, "Failed to initialize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Perform encryption and handle any errors
    unsigned char *encrypted_data = malloc(256);
    int len, ciphertext_len;

    if (EVP_EncryptUpdate(ctx, encrypted_data, &len, (unsigned char *)"Hello, world!", 13) != 1 ||
        EVP_EncryptFinal_ex(ctx, encrypted_data + len, &ciphertext_len) != 1) {
        fprintf(log_file, "Failed to encrypt data\n");
        free(encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    ciphertext_len += len;

    // Cleanup
    EVP_CIPHER_CTX_free(ctx);

    return encrypted_data;
}

