#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 1000000

typedef struct {
    char* str;
    float value;
} Event;

typedef struct {
    Event* events;
    int* indexes;
    size_t count;
    size_t capacity;
} PriorityQueue;

PriorityQueue* create_priority_queue(size_t initial_capacity) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (!pq) return NULL;

    pq->events = (Event*)malloc(initial_capacity * sizeof(Event));
    pq->indexes = (int*)malloc(initial_capacity * sizeof(int));
    if (!pq->events || !pq->indexes) {
        free(pq);
        return NULL;
    }

    pq->count = 0;
    pq->capacity = initial_capacity;
    return pq;
}

void destroy_priority_queue(PriorityQueue* pq) {
    for (size_t i = 0; i < pq->count; ++i) {
        free(pq->events[i].str);
    }
    free(pq->events);
    free(pq->indexes);
    free(pq);
}

void resize_priority_queue(PriorityQueue* pq, size_t new_capacity) {
    Event* new_events = (Event*)realloc(pq->events, new_capacity * sizeof(Event));
    int* new_indexes = (int*)realloc(pq->indexes, new_capacity * sizeof(int));

    if (!new_events || !new_indexes) return;

    pq->events = new_events;
    pq->indexes = new_indexes;
    pq->capacity = new_capacity;
}

void insert_event(PriorityQueue* pq, char* str, float value) {
    if (pq->count == pq->capacity) resize_priority_queue(pq, pq->capacity * 2);

    size_t index = pq->count++;
    pq->events[index].str = strdup(str);
    pq->events[index].value = value;
    pq->indexes[index] = index;

    while (index > 0 && pq->events[(index - 1) / 2].value < pq->events[index].value) {
        Event temp = pq->events[index];
        pq->events[index] = pq->events[(index - 1) / 2];
        pq->events[(index - 1) / 2] = temp;

        int temp_index = pq->indexes[index];
        pq->indexes[index] = pq->indexes[(index - 1) / 2];
        pq->indexes[(index - 1) / 2] = temp_index;

        index = (index - 1) / 2;
    }
}

Event* extract_max(PriorityQueue* pq) {
    if (pq->count == 0) return NULL;

    Event* max_event = &pq->events[0];
    size_t last_index = --pq->count;

    size_t index = 0;
    while ((index * 2 + 1 < pq->count && pq->events[index].value < pq->events[index * 2 + 1].value) ||
           (index * 2 + 2 < pq->count && pq->events[index].value < pq->events[index * 2 + 2].value)) {
        size_t max_child = index * 2 + 1;
        if (index * 2 + 2 < pq->count && pq->events[index * 2 + 2].value > pq->events[max_child].value) {
            max_child = index * 2 + 2;
        }

        Event temp = pq->events[index];
        pq->events[index] = pq->events[max_child];
        pq->events[max_child] = temp;

        int temp_index = pq->indexes[index];
        pq->indexes[index] = pq->indexes[max_child];
        pq->indexes[max_child] = temp_index;

        index = max_child;
    }

    free(pq->events[last_index].str);
    return max_event;
}

