    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indications == NULL) {
        printf("Memory allocation failed for CRC indications\n");
        return;
    }

    long* offsets = (long*)malloc(n * sizeof(long));
    if (offsets == NULL) {
        printf("Memory allocation failed for offsets\n");
        free(crc_indications);
        return;
    }

    int* keys = (int*)malloc(n * sizeof(int));
    if (keys == NULL) {
        printf("Memory allocation failed for keys\n");
        free(crc_indications);
        free(offsets);
        return;
    }

    record* records = (record*)malloc(m * sizeof(record));
    if (records == NULL) {
        printf("Memory allocation failed for records\n");
        free(crc_indications);
        free(offsets);
        free(keys);
        return;
    }

    int** matrix = (int**)malloc(p * sizeof(int*));
    if (matrix == NULL) {
        printf("Memory allocation failed for matrix rows\n");
        free(crc_indications);
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    for (int i = 0; i < p; ++i) {
        matrix[i] = (int*)malloc(q * sizeof(int));
        if (matrix[i] == NULL) {
            printf("Memory allocation failed for matrix row %d\n", i);
            for (int j = 0; j < i; ++j) {
                free(matrix[j]);
            }
            free(matrix);
            free(crc_indications);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
    }

    index* vector = (index*)malloc(m * sizeof(index));
    if (vector == NULL) {
        printf("Memory allocation failed for vector\n");
        for (int i = 0; i < p; ++i) {
            free(matrix[i]);
        }
        free(matrix);
        free(crc_indications);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    double*** cube = (double***)malloc(r * sizeof(double**));
    if (cube == NULL) {
        printf("Memory allocation failed for cube layers\n");
        free(vector);
        for (int i = 0; i < p; ++i) {
            free(matrix[i]);
        }
        free(matrix);
        free(crc_indications);
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    for (int i = 0; i < r; ++i) {
        cube[i] = (double**)malloc(r * sizeof(double*));
        if (cube[i] == NULL) {
            printf("Memory allocation failed for cube layer %d\n", i);
            for (int j = 0; j < i; ++j) {
                free(cube[j]);
            }
            free(cube);
            free(vector);
            for (int k = 0; k < p; ++k) {
                free(matrix[k]);
            }
            free(matrix);
            free(crc_indications);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        for (int j = 0; j < r; ++j) {
            cube[i][j] = (double*)malloc(r * sizeof(double));
            if (cube[i][j] == NULL) {
                printf("Memory allocation failed for cube element %d,%d\n", i, j);
                for (int k = 0; k <= j; ++k) {
                    free(cube[i][k]);
                }
                free(cube[i]);
                for (int l = 0; l < i; ++l) {
                    free(cube[l]);
                }
                free(cube);
                free(vector);
                for (int m = 0; m < p; ++m) {
                    free(matrix[m]);
                }
                free(matrix);
                free(crc_indications);
                free(offsets);
                free(keys);
                free(records);
                return;
            }
        }
    }

    int* indexes = (int*)malloc(m * sizeof(int));
    if (indexes == NULL) {
        printf("Memory allocation failed for indexes\n");
        for (int i = 0; i < r; ++i) {
            for (int j = 0; j < r; ++j) {
                free(cube[i][j]);
            }
            free(cube[i]);
        }
        free(cube);
        free(vector);
        for (int k = 0; k < p; ++k) {
            free(matrix[k]);
        }
        free(matrix);
        free(crc_indications);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        crc_indications[i].CRCFLAG = rand() % 2;
        offsets[i] = i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        keys[i] = rand();
    }

    for (int i = 0; i < m; ++i) {
        records[i].value = rand();
        vector[i].index = i;
        vector[i].used = false;
        indexes[i] = -1;
    }

    for (int i = 0; i < p; ++i) {
        for (int j = 0; j < q; ++j) {
            matrix[i][j] = rand() % (high - low + 1) + low;
        }
    }

    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < r; ++j) {
            for (int k = 0; k < r; ++k) {
                cube[i][j][k] = pow(k, 3);
            }
        }
    }

    // Use the allocated structures here

    free(crc_indications);
    free(offsets);
    free(keys);
    free(records);
    for (int i = 0; i < p; ++i) {
        free(matrix[i]);
    }
    free(matrix);
