#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *interest;
} Preference;

typedef struct {
    char *name;
    char *email;
    char *date_of_birth;
    Preference **preferences;
    int preference_count;
} UserProfile;

typedef struct {
    UserProfile **profiles;
    int size;
    int count;
    double load_factor_threshold;
} UserProfileHashTable;

typedef struct {
    UserProfileHashTable *table;
    pthread_mutex_t mutex;
} ThreadSafeUserProfileManager;

unsigned long hash_email(const char *email) {
    unsigned long hash = 5381;
    int c;
    while ((c = *email++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

ThreadSafeUserProfileManager* create_user_profile_manager() {
    ThreadSafeUserProfileManager *manager = (ThreadSafeUserProfileManager*)malloc(sizeof(ThreadSafeUserProfileManager));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        exit(EXIT_FAILURE);
    }

    manager->table = (UserProfileHashTable*)malloc(sizeof(UserProfileHashTable));
    if (!manager->table) {
        perror("Failed to allocate memory for table");
        free(manager);
        exit(EXIT_FAILURE);
    }

    manager->table->size = 16;
    manager->table->count = 0;
    manager->table->load_factor_threshold = 0.75;
    manager->table->profiles = (UserProfile**)calloc(manager->table->size, sizeof(UserProfile*));
    if (!manager->table->profiles) {
        perror("Failed to allocate memory for profiles");
        free(manager->table);
        free(manager);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_user_profile_manager(ThreadSafeUserProfileManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->table->size; ++i) {
        if (manager->table->profiles[i]) {
            UserProfile *profile = manager->table->profiles[i];
            free(profile->name);
            free(profile->email);
            free(profile->date_of_birth);
            for (int j = 0; j < profile->preference_count; ++j) {
                free(profile->preferences[j]->interest);
                free(profile->preferences[j]);
            }
            free(profile->preferences);
            free(profile);
        }
    }

    free(manager->table->profiles);
    free(manager->table);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_user_profile(ThreadSafeUserProfileManager *manager, UserProfile *profile) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->table->count >= manager->table->size * manager->table->load_factor_threshold) {
        int new_size = manager->table->size * 2;
        UserProfile **new_profiles = (UserProfile**)realloc(manager->table->profiles, new_size * sizeof(UserProfile*));
        if (!new_profiles) {
            perror("Failed to reallocate memory for profiles");
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->table->size = new_size;
        memset(new_profiles + manager->table->count, 0, (manager->table->size - manager->table->count) * sizeof(UserProfile*));
        manager->table->profiles = new_profiles;
    }

    unsigned long index = hash_email(profile->email) % manager->table->size;
    while (manager->table->profiles[index]) {
        if (strcmp(manager->table->profiles[index]->email, profile->email) == 0) {
            fprintf(stderr, "Email already exists: %s\n", profile->email);
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        index = (index + 1) % manager->table->size;
    }

    manager->table->profiles[index] = profile;
    ++manager->table->count;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

UserProfile* get_user_profile(ThreadSafeUserProfileManager *manager, const char *email) {
    pthread_mutex_lock(&manager->mutex);

    unsigned long index = hash_email(email) % manager->table->size;
    while (manager->table->profiles[index]) {
        if (strcmp(manager->table->profiles[index]->email, email) == 0) {
            UserProfile *profile = manager->table->profiles[index];
            pthread_mutex_unlock(&manager->mutex);
            return profile;
        }
        index = (index + 1) % manager->table->size;
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

int main() {
    ThreadSafeUserProfileManager *manager = create_user_profile_manager();

    UserProfile *profile = (UserProfile*)malloc(sizeof(UserProfile));
    profile->name = strdup("John Doe");
    profile->email = strdup("john.doe@example.com");
    profile->date_of_birth = strdup("1990-01-01");
    profile->preferences = NULL;
    profile->preference_count = 0;

    if (add_user_profile(manager, profile) == 0) {
        UserProfile *retrieved_profile = get_user_profile(manager, "john.doe@example.com");
        if (retrieved_profile) {
            printf("Retrieved Profile: %s, %s\n", retrieved_profile->name, retrieved_profile->email);
        }
    }

    destroy_user_profile_manager(manager);

    return 0;
}
