#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

long* allocateOffsets(int size) {
    if (size <= 0) return NULL;
    return (long*)calloc(size, sizeof(long));
}

int* allocateKeys(int size) {
    if (size <= 0) return NULL;
    return (int*)calloc(size, sizeof(int));
}

Record* allocateRecords(int size) {
    if (size <= 0) return NULL;
    Record* records = (Record*)calloc(size, sizeof(Record));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
    }
    return records;
}

float generateRandomFloat(int min, int max) {
    if (min > max) return -1.0f; // Error handling for invalid range
    return ((float)(rand() % (max - min + 1)) + min) / 100.0f; // Random float between min and max
}

int generateRandomInt(int min, int max) {
    if (min > max) return -1; // Error handling for invalid range
    return rand() % (max - min + 1) + min; // Random integer between min and max
}

float weightedRandomFloat(float* weights, float* values, int size) {
    if (size <= 0 || !weights || !values) return -1.0f;

    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += weights[i];
    }
    if (!sum == 1.0f) return -1.0f; // Error handling for invalid weights

    float randVal = (float)rand() / RAND_MAX * sum;
    float cumulativeWeight = 0.0f;

    for (int i = 0; i < size; i++) {
        cumulativeWeight += weights[i];
        if (randVal <= cumulativeWeight) {
            return values[i];
        }
    }

    return -1.0f; // Fallback in case of error
}

void initializeSimulation(int size, long** offsets, int** keys, Record** records) {
    *offsets = allocateOffsets(size);
    *keys = allocateKeys(size);
    *records = allocateRecords(size);
}

void cleanupSimulation(long* offsets, int* keys, Record* records, int size) {
    free(offsets);
    free(keys);
    for (int i = 0; i < size; i++) {
        records[i].value = 0; // Reset record values to ensure no dangling pointers
    }
    free(records);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int size = 10;
    long* offsets;
    int* keys;
    Record* records;

    initializeSimulation(size, &offsets, &keys, &records);

    for (int i = 0; i < size; i++) {
        printf("Offset: %ld, Key: %d, Value: %d\n", offsets[i], keys[i], records[i].value);

        float randomFloat = generateRandomFloat(1.0f, 100.0f);
        int randomInt = generateRandomInt(1, 100);
        float weightedValue = weightedRandomFloat((float[3]){0.2f, 0.3f, 0.5f}, (int[3]){10, 20, 30}, 3);

        printf("Random Float: %.2f, Random Int: %d, Weighted Value: %d\n", randomFloat, randomInt, weightedValue);
    }

    cleanupSimulation(offsets, keys, records, size);

    return 0;
}
