#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int value;
} record;

float random_float(float min, float max) {
    return min + (max - min) * ((float)rand() / RAND_MAX);
}

int random_int(int min, int max) {
    if (min > max || (min == max && rand() % 2)) {
        int temp = min;
        min = max;
        max = temp;
    }
    return min + rand() % (max - min + 1);
}

float weighted_random_float(float weights[], float values[], int count) {
    float sum = 0.0f;
    for (int i = 0; i < count; i++) {
        sum += weights[i];
    }

    if (sum != 1.0f) {
        fprintf(stderr, "Error: Weights must sum to 1.0f\n");
        exit(EXIT_FAILURE);
    }

    float rand_value = random_float(0.0f, sum);
    for (int i = 0; i < count; i++) {
        if (rand_value <= weights[i]) {
            return values[i];
        }
        rand_value -= weights[i];
    }

    fprintf(stderr, "Error: Failed to select a value from weights\n");
    exit(EXIT_FAILURE);
}

void initialize_data_structures(int size, long** offsets, int** keys, record** records) {
    if (size <= 0) {
        fprintf(stderr, "Error: Invalid input size\n");
        return;
    }

    *offsets = malloc(size * sizeof(long));
    *keys = malloc(size * sizeof(int));
    *records = malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = random_int(0, 100);
        (*keys)[i] = random_int(0, 100);
        (*records)[i].value = random_int(-100, 100);
    }
}

void free_data_structures(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}
