#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Function to generate random integers within a specified range
int randomInt(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate random floats within a specified range
float randomFloat(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

// Weighted random float method based on provided weights
float weightedRandomFloat(float weights[], int size) {
    float r = randomFloat(0.0f, 1.0f);
    float cumulative_weight = 0.0f;

    for (int i = 0; i < size; i++) {
        cumulative_weight += weights[i];
        if (r <= cumulative_weight) {
            return i;
        }
    }

    // Fallback in case of floating-point precision issues
    return size - 1;
}

// Function to manage and initialize data structures
void initializeSimulationData(int numRecords, int minVal, int maxVal, char* filename) {
    if (numRecords <= 0 || minVal > maxVal) {
        fprintf(stderr, "Invalid input. Ensure numRecords > 0 and minVal <= maxVal.\n");
        return;
    }

    srand(time(NULL));

    // Allocate memory for arrays
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    record* records = (record*)malloc(numRecords * sizeof(record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Initialize arrays
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = randomInt(minVal, maxVal);
        keys[i] = randomInt(minVal, maxVal);

        // Random integer value for each record
        records[i].value = randomInt(minVal, maxVal);
    }

    // Modify filename and append extension
    char* newFilename = (char*)malloc(strlen(filename) + 10); // Assuming space for digits and file type
    if (newFilename == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    strcpy(newFilename, filename);
    char extension[5];
    int numDigits = 1;

    // Determine number of digits and file type from original filename
    for (int i = strlen(filename) - 1; i >= 0 && filename[i] != '.'; i--) {
        if (isdigit(filename[i])) {
            numDigits++;
        }
    }

    // Append new extension with digits and file type
    sprintf(extension, "_%d.txt", numDigits);
    strcat(newFilename, extension);

    printf("New Filename: %s\n", newFilename);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(newFilename);
}

int main() {
    int numRecords = 10;
    int minVal = 0;
    int maxVal = 100;
    char filename[] = "datafile";

    initializeSimulationData(numRecords, minVal, maxVal, filename);

    return 0;
}
